@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap");

/* =========================================================
   NOVADENT DENTAL CARE
   GLOBAL CSS
========================================================= */

:root {
  --ink: #0b2545;
  --ink-dark: #061a31;
  --primary: #1f8a8a;
  --primary-dark: #146b6b;
  --accent: #55b8b0;

  --cream: #f7fafc;
  --soft-bg: #eef6f6;
  --light-teal: #eaf5f4;

  --text: #183b56;
  --muted: #64748b;

  --border: #dce8eb;
  --white: #ffffff;

  --shadow-sm: 0 8px 25px rgba(11, 37, 69, 0.06);
  --shadow-md: 0 15px 40px rgba(11, 37, 69, 0.10);
  --shadow-lg: 0 25px 65px rgba(11, 37, 69, 0.14);

  --radius-sm: 10px;
  --radius-md: 18px;
  --radius-lg: 28px;

  --container: 1240px;
}

/* =========================================================
   RESET
========================================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  overflow-x: hidden;
}

body {
  margin: 0;
  padding: 0;

  font-family: "DM Sans", Arial, sans-serif;
  color: var(--text);
  background: var(--cream);

  line-height: 1.6;

  overflow-x: hidden;

  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body,
button,
input,
textarea,
select {
  font-family: "DM Sans", Arial, sans-serif;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

ul,
ol {
  margin: 0;
  padding: 0;
}

p,
h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

::selection {
  background: var(--accent);
  color: var(--ink-dark);
}

/* =========================================================
   COMMON
========================================================= */

.container {
  width: min(var(--container), calc(100% - 60px));
  margin: 0 auto;
}

.section {
  padding: 100px 0;
}

.miniLabel {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  color: var(--primary);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2.2px;
  line-height: 1.3;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  color: var(--accent);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2.2px;
}

.center {
  text-align: center;
}

.textLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  color: var(--primary);

  font-size: 12px;
  font-weight: 800;

  transition: gap 0.3s ease, color 0.3s ease;
}

.textLink:hover {
  gap: 13px;
  color: var(--primary-dark);
}

/* =========================================================
   BUTTONS
========================================================= */

.btn {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 9px;

  min-height: 48px;
  padding: 13px 22px;

  border: 0;
  border-radius: 999px;

  background: var(--primary);
  color: #ffffff !important;

  font-size: 12px;
  font-weight: 800;
  line-height: 1;

  cursor: pointer;

  box-shadow: 0 10px 25px rgba(31, 138, 138, 0.20);

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.btn:hover {
  background: var(--primary-dark);
  transform: translateY(-3px);
  box-shadow: 0 15px 32px rgba(31, 138, 138, 0.28);
}

.btn.ghost {
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.40);
  color: #ffffff !important;
  box-shadow: none;
}

.btn.ghost:hover {
  background: #ffffff;
  color: var(--ink) !important;
}

/* =========================================================
   NAVBAR
========================================================= */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.98);
  border-bottom: 1px solid rgba(220, 232, 235, 0.85);
  box-shadow: 0 5px 25px rgba(11, 37, 69, 0.06);
}
.navin {
  width: min(1400px, calc(100% - 50px));
  min-height: 82px;

  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 25px;
}

/* BRAND */

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;

  flex-shrink: 0;

  color: var(--ink);

  text-decoration: none;
}

.logo {
  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  background: var(--ink);
  color: #ffffff;

  box-shadow: 0 8px 22px rgba(11, 37, 69, 0.15);
}

.toothLogo {
  transition:
    transform 0.35s ease,
    background 0.35s ease;
}

.brand:hover .toothLogo {
  transform: translateY(-2px) rotate(-3deg);
  background: var(--primary);
}

.brandText {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brandText strong {
  color: var(--ink);

  font-size: 19px;
  font-weight: 800;
  letter-spacing: 2px;
  line-height: 1;
}

.brandText small {
  color: var(--primary);

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 3px;
  line-height: 1;

  text-transform: uppercase;
}

/* NAVIGATION */

.nav nav {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 28px;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 27px;
}

.navLinks a {
  position: relative;

  padding: 31px 0;

  color: #53677c;

  font-size: 13px;
  font-weight: 700;

  white-space: nowrap;

  transition: color 0.25s ease;
}

.navLinks a::after {
  content: "";

  position: absolute;
  left: 0;
  right: 0;
  bottom: 21px;

  height: 2px;

  border-radius: 10px;

  background: var(--primary);

  transform: scaleX(0);
  transform-origin: center;

  transition: transform 0.3s ease;
}

.navLinks a:hover,
.navLinks a.active {
  color: var(--primary);
}

.navLinks a:hover::after,
.navLinks a.active::after {
  transform: scaleX(1);
}

.navAppointment {
  min-height: 48px;
  padding: 12px 20px;
  white-space: nowrap;
}

/* HAMBURGER */

.hamb {
  display: none;

  width: 44px;
  height: 44px;

  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: #ffffff;
  color: var(--ink);

  cursor: pointer;
}

/* MOBILE CALL BAR */

.mobileCallBar {
  display: none;
}

/* =========================================================
   HERO
========================================================= */

.hero {
  position: relative;

  min-height: 820px;
  height: 100vh;
  max-height: 920px;

  overflow: hidden;

  background: var(--ink);
  color: #ffffff;
}

.heroSlides {
  position: absolute;
  inset: 0;

  overflow: hidden;
}

.heroSlide {
  position: absolute;
  inset: 0;

  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;

  opacity: 0;
  transform: scale(1.04);

  transition:
    opacity 0.9s ease,
    transform 7s ease;
}

.heroSlideActive {
  opacity: 1;
  transform: scale(1);
}

.heroContainer {
  position: relative;

  z-index: 5;

  width: min(1240px, calc(100% - 60px));
  height: 100%;
  min-height: 820px;

  margin: 0 auto;

  display: flex;
  align-items: center;
}

.heroContent {
  width: 100%;
  max-width: 790px;

  padding-top: 30px;
  padding-bottom: 100px;
}

.heroEyebrow {
  display: flex;
  align-items: center;
  gap: 12px;

  margin-bottom: 24px;

  color: #9ee1dc;

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2.5px;
}

.heroEyebrowLine {
  width: 42px;
  height: 1px;

  background: var(--accent);
}

.heroTitle {
  max-width: 800px;

  margin: 0;

  color: #ffffff;

  font-family: "Playfair Display", Georgia, serif;

  font-size: clamp(58px, 7vw, 96px);
  font-weight: 600;
  line-height: 0.98;

  letter-spacing: -3px;
}

.heroTitle span {
  color: #61c6be;

  font-style: italic;
}

.heroText {
  max-width: 600px;

  margin: 28px 0 0;

  color: rgba(255, 255, 255, 0.78);

  font-size: 16px;
  line-height: 1.75;
}

.heroActions {
  display: flex;
  align-items: center;
  gap: 18px;

  margin-top: 34px;
}

.heroPrimaryBtn {
  min-height: 52px;
}

.heroSecondaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;

  color: #ffffff;

  font-size: 12px;
  font-weight: 800;

  transition:
    gap 0.3s ease,
    color 0.3s ease;
}

.heroSecondaryBtn:hover {
  gap: 14px;
  color: var(--accent);
}

/* HERO TRUST */

.heroTrust {
  display: flex;
  align-items: center;
  gap: 23px;

  margin-top: 42px;
}

.heroTrustItem {
  display: flex;
  align-items: center;
  gap: 10px;
}

.heroTrustIcon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;

  color: var(--accent);

  background: rgba(255, 255, 255, 0.05);
}

.heroTrustItem div {
  display: flex;
  flex-direction: column;
}

.heroTrustItem strong {
  color: #ffffff;

  font-size: 11px;
  font-weight: 800;
}

.heroTrustItem small {
  color: rgba(255, 255, 255, 0.55);

  font-size: 9px;
}

.heroTrustDivider {
  width: 1px;
  height: 30px;

  background: rgba(255, 255, 255, 0.18);
}

/* HERO CONTROLS */

.heroControls {
  position: absolute;

  z-index: 10;

  left: 50%;
  bottom: 40px;

  transform: translateX(-50%);

  display: flex;
  align-items: center;
  gap: 18px;
}

.heroArrow {
  width: 49px;
  height: 49px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;

  background: rgba(255, 255, 255, 0.07);

  color: #ffffff;

  cursor: pointer;

  backdrop-filter: blur(10px);

  transition:
    background 0.3s ease,
    transform 0.3s ease,
    border-color 0.3s ease;
}

.heroArrow:hover {
  background: var(--primary);
  border-color: var(--primary);

  transform: scale(1.08);
}

.heroDots {
  display: flex;
  align-items: center;
  gap: 8px;
}

.heroDot {
  width: 8px;
  height: 8px;

  padding: 0;

  border: 0;
  border-radius: 50%;

  background: rgba(255, 255, 255, 0.42);

  cursor: pointer;

  transition:
    width 0.3s ease,
    background 0.3s ease;
}

.heroDot.active {
  width: 32px;

  border-radius: 20px;

  background: var(--accent);
}

.heroSlideNumber {
  margin-left: 5px;

  color: rgba(255, 255, 255, 0.65);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
}

.heroScroll {
  position: absolute;

  left: 0;
  bottom: 47px;

  display: flex;
  align-items: center;
  gap: 12px;

  color: rgba(255, 255, 255, 0.58);

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 2px;
}

.heroScrollLine {
  width: 50px;
  height: 1px;

  background: rgba(255, 255, 255, 0.4);
}

/* HERO ANIMATION */

.heroContentIn {
  animation: heroContentIn 0.7s ease both;
}

@keyframes heroContentIn {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   HOME INTRO
========================================================= */

.homeIntro {
  background: var(--cream);
}

.homeIntroGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;

  gap: 100px;

  align-items: center;
}

.homeIntroHeading h2,
.homeServices h2,
.homeWhy h2,
.homeDoctors h2,
.homeTestimonial h2 {
  margin: 13px 0 0;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: clamp(42px, 5vw, 64px);
  font-weight: 600;

  line-height: 1.04;

  letter-spacing: -1.8px;
}

.homeIntroHeading h2 span,
.homeServices h2 span,
.homeWhy h2 span,
.homeDoctors h2 span,
.homeTestimonial h2 span {
  color: var(--primary);

  font-style: italic;
}

.homeIntroContent {
  max-width: 570px;
}

.homeIntroContent p {
  margin: 0 0 17px;

  color: var(--muted);

  font-size: 14px;
  line-height: 1.8;
}

/* =========================================================
   HOME STATS
========================================================= */

.homeStats {
  background: var(--ink);

  color: #ffffff;
}

.homeStatsGrid {
  min-height: 145px;

  display: grid;
  grid-template-columns: repeat(4, 1fr);
  align-items: center;
}

.homeStat {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  min-height: 75px;

  border-right: 1px solid rgba(255, 255, 255, 0.14);

  text-align: center;
}

.homeStat:last-child {
  border-right: 0;
}

.homeStat strong {
  color: #ffffff;

  font-family: "Playfair Display", Georgia, serif;

  font-size: 38px;
  font-weight: 600;
  line-height: 1;
}

.homeStat span {
  margin-top: 8px;

  color: rgba(255, 255, 255, 0.56);

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}

/* =========================================================
   HOME SERVICES
========================================================= */

.homeServices {
  background: #ffffff;
}

.sectionTop {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 60px;

  margin-bottom: 55px;
}

.sectionTopRight {
  max-width: 410px;
}

.sectionTopRight p {
  margin: 0 0 17px;

  color: var(--muted);

  font-size: 13px;
  line-height: 1.75;
}

.serviceGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);

  gap: 24px;
}

/* =========================================================
   SERVICE CARD
========================================================= */

.serviceCard {
  position: relative;

  overflow: hidden;

  border: 1px solid var(--border);
  border-radius: 22px;

  background: #ffffff;

  box-shadow: var(--shadow-sm);

  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease,
    border-color 0.45s ease;
}

.serviceCard:hover {
  transform: translateY(-10px);

  border-color: rgba(31, 138, 138, 0.35);

  box-shadow: var(--shadow-lg);
}

.serviceCardImage {
  position: relative;

  height: 245px;

  overflow: hidden;

  background: var(--soft-bg);
}

.serviceCardImage img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition:
    transform 0.8s cubic-bezier(0.2, 0.7, 0.2, 1);
}

.serviceCard:hover .serviceCardImage img {
  transform: scale(1.08);
}

.serviceCardOverlay {
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      180deg,
      rgba(3, 25, 42, 0.45),
      transparent 45%,
      rgba(3, 25, 42, 0.42)
    );
}

.serviceCardBadge {
  position: absolute;

  top: 16px;
  left: 16px;

  display: flex;
  align-items: center;
  gap: 8px;

  padding: 8px 11px;

  border: 1px solid rgba(255, 255, 255, 0.20);
  border-radius: 30px;

  background: rgba(255, 255, 255, 0.12);

  color: #ffffff;

  backdrop-filter: blur(12px);
}

.serviceCardBadge span {
  color: var(--accent);
}

.serviceCardBadge small {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.3px;
}

.serviceCardView {
  position: absolute;

  right: 16px;
  bottom: 16px;

  width: 45px;
  height: 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #ffffff;
  color: var(--ink);

  opacity: 0;
  transform: translateY(12px);

  transition:
    opacity 0.35s ease,
    transform 0.35s ease,
    background 0.3s ease,
    color 0.3s ease;
}

.serviceCard:hover .serviceCardView {
  opacity: 1;
  transform: translateY(0);
}

.serviceCardView:hover {
  background: var(--primary);
  color: #ffffff;
}

.serviceCardContent {
  padding: 25px 23px 23px;
}

.serviceCardTop {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 15px;
}

.serviceCardIcon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: var(--light-teal);
  color: var(--primary);

  font-size: 17px;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease;
}

.serviceCard:hover .serviceCardIcon {
  transform: rotate(8deg) scale(1.08);

  background: var(--primary);
  color: #ffffff;
}

.serviceCardNumber {
  color: #94a3b8;

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
}

.serviceCardContent h3 {
  margin: 0;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: 23px;
  font-weight: 600;
  line-height: 1.2;
}

.serviceCardContent p {
  min-height: 65px;

  margin: 12px 0 20px;

  color: var(--muted);

  font-size: 12px;
  line-height: 1.7;
}

.serviceCardLink {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding-top: 17px;

  border-top: 1px solid var(--border);

  color: var(--ink);

  font-size: 11px;
  font-weight: 800;

  transition: color 0.3s ease;
}

.serviceCardLink:hover {
  color: var(--primary);
}

.serviceCardArrow {
  width: 31px;
  height: 31px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);
  border-radius: 50%;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease;
}

.serviceCardLink:hover .serviceCardArrow {
  transform: rotate(45deg);

  background: var(--primary);
  border-color: var(--primary);

  color: #ffffff;
}

/* =========================================================
   HOME WHY
========================================================= */

.homeWhy {
  background: var(--soft-bg);
}

.homeWhyGrid {
  display: grid;
  grid-template-columns: 1fr 0.95fr;

  gap: 90px;

  align-items: center;
}

.homeWhyImage {
  position: relative;

  min-height: 620px;

  border-radius: 30px;

  overflow: hidden;
}

.homeWhyImage > img {
  width: 100%;
  height: 100%;

  min-height: 620px;

  object-fit: cover;

  transition: transform 0.8s ease;
}

.homeWhyImage:hover > img {
  transform: scale(1.04);
}

.homeWhyFloating {
  position: absolute;

  left: 25px;
  bottom: 25px;

  display: flex;
  align-items: center;
  gap: 12px;

  padding: 15px 18px;

  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 15px;

  background: rgba(7, 30, 48, 0.78);

  color: #ffffff;

  backdrop-filter: blur(14px);
}

.homeWhyFloating svg {
  color: var(--accent);
}

.homeWhyFloating div {
  display: flex;
  flex-direction: column;
}

.homeWhyFloating strong {
  font-size: 11px;
}

.homeWhyFloating span {
  color: rgba(255, 255, 255, 0.58);

  font-size: 9px;
}

.homeWhyContent h2 {
  margin-bottom: 22px;
}

.homeWhyLead {
  max-width: 520px;

  color: var(--muted);

  font-size: 14px;
  line-height: 1.8;
}

.homeFeatureList {
  display: grid;

  gap: 20px;

  margin: 30px 0;
}

.homeFeature {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.homeFeature > span {
  width: 42px;
  height: 42px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background: #ffffff;
  color: var(--primary);

  box-shadow: var(--shadow-sm);
}

.homeFeature strong {
  color: var(--ink);

  font-size: 12px;
}

.homeFeature p {
  margin: 4px 0 0;

  color: var(--muted);

  font-size: 11px;
  line-height: 1.6;
}

.homeWhyButton {
  margin-top: 5px;
}

/* =========================================================
   DOCTOR CARDS
========================================================= */

.doctorGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 25px;
}

.doctorCard {
  overflow: hidden;

  border: 1px solid var(--border);
  border-radius: 24px;

  background: #ffffff;

  box-shadow: var(--shadow-sm);

  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.doctorCard:hover {
  transform: translateY(-9px);
  box-shadow: var(--shadow-lg);
}

.doctorImage {
  position: relative;

  height: 370px;

  overflow: hidden;

  background: var(--soft-bg);
}

.doctorImage img {
  width: 100%;
  height: 100%;

  object-fit: cover;

