  min-height: 390px;
}

.galleryItem img {
  width: 100%;
  height: 100%;

  position: absolute;
  inset: 0;

  object-fit: cover;

  transition: transform 0.7s ease;
}

.galleryItem:hover img {
  transform: scale(1.07);
}

.galleryItemOverlay {
  position: absolute;
  inset: 0;

  display: flex;
  align-items: flex-end;

  padding: 22px;

  background: linear-gradient(
    transparent 35%,
    rgba(3,25,42,0.78)
  );

  color: #ffffff;
}

.galleryItemOverlay div {
  display: flex;
  flex-direction: column;
}

.galleryItemOverlay strong {
  font-family: "Playfair Display", Georgia, serif;

  font-size: 21px;
}

.galleryItemOverlay span {
  margin-top: 3px;

  color: rgba(255,255,255,0.60);

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 1.5px;
}

.galleryExperience {
  margin-top: 45px;

  padding: 30px;

  border-radius: 20px;

  background: var(--soft-bg);

  text-align: center;
}

.galleryExperience h3 {
  margin: 0 0 7px;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: 25px;
}

.galleryExperience p {
  margin: 0;

  color: var(--muted);

  font-size: 11px;
}

/* LIGHTBOX */

.galleryLightbox {
  position: fixed;
  inset: 0;

  z-index: 2000;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 35px;

  background: rgba(3, 18, 30, 0.94);

  backdrop-filter: blur(10px);
}

.galleryLightbox img {
  max-width: 92vw;
  max-height: 88vh;

  border-radius: 18px;

  box-shadow: 0 30px 100px rgba(0,0,0,0.35);
}

.galleryLightboxClose {
  position: absolute;

  top: 25px;
  right: 25px;

  width: 45px;
  height: 45px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255,255,255,0.25);
  border-radius: 50%;

  background: rgba(255,255,255,0.08);

  color: #ffffff;

  cursor: pointer;
}

/* =========================================================
   REVIEWS
========================================================= */

.reviewGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 22px;
}

.reviewCard {
  padding: 30px;

  border: 1px solid var(--border);
  border-radius: 22px;

  background: #ffffff;

  box-shadow: var(--shadow-sm);

  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.reviewCard:hover {
  transform: translateY(-7px);
  box-shadow: var(--shadow-md);
}

.reviewCard .stars {
  display: flex;
  gap: 3px;

  color: #e8b13a;
}

.reviewCard blockquote {
  margin: 20px 0;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: 19px;
  line-height: 1.5;
}

.reviewPerson {
  display: flex;
  align-items: center;
  gap: 10px;

  padding-top: 16px;

  border-top: 1px solid var(--border);
}

.reviewAvatar {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: var(--ink);
  color: #ffffff;

  font-size: 9px;
  font-weight: 800;
}

.reviewPerson div {
  display: flex;
  flex-direction: column;
}

.reviewPerson strong {
  color: var(--ink);

  font-size: 10px;
}

.reviewPerson span {
  color: var(--muted);

  font-size: 8px;
}

.reviewStats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);

  margin: 55px 0 0;

  padding: 35px;

  border-radius: 22px;

  background: var(--ink);
}

.reviewStats > div {
  text-align: center;

  border-right: 1px solid rgba(255,255,255,0.15);
}

.reviewStats > div:last-child {
  border: 0;
}

.reviewStats strong {
  display: block;

  color: #ffffff;

  font-family: "Playfair Display", Georgia, serif;

  font-size: 35px;
}

.reviewStats span {
  color: rgba(255,255,255,0.55);

  font-size: 9px;
}

/* =========================================================
   APPOINTMENT
========================================================= */

.appointmentGrid {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;

  gap: 65px;

  align-items: start;
}

.appointmentInfo {
  position: sticky;
  top: 110px;
}

.appointmentInfo h2 {
  margin: 14px 0;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: clamp(40px, 4vw, 55px);

  line-height: 1.05;
}

.appointmentInfo h2 span {
  color: var(--primary);
  font-style: italic;
}

.appointmentInfo > p {
  color: var(--muted);

  font-size: 12px;
  line-height: 1.8;
}

.bookingInfoList {
  display: grid;
  gap: 13px;

  margin-top: 28px;
}

.bookingInfo {
  display: flex;
  align-items: center;
  gap: 12px;

  padding: 15px;

  border: 1px solid var(--border);
  border-radius: 15px;

  background: #ffffff;
}

.bookingInfoIcon {
  width: 39px;
  height: 39px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--light-teal);
  color: var(--primary);
}

.bookingInfo div {
  display: flex;
  flex-direction: column;
}

.bookingInfo strong {
  color: var(--ink);

  font-size: 10px;
}

.bookingInfo span {
  color: var(--muted);

  font-size: 9px;
}

.appointmentForm {
  padding: 38px;

  border: 1px solid var(--border);
  border-radius: 25px;

  background: #ffffff;

  box-shadow: var(--shadow-md);
}

.appointmentFormGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;

  gap: 18px;
}

.formGroup {
  display: flex;
  flex-direction: column;
}

.formGroup.full {
  grid-column: 1 / -1;
}

.formGroup label {
  color: var(--ink);

  font-size: 10px;
  font-weight: 800;
}

.formGroup input,
.formGroup select,
.formGroup textarea {
  width: 100%;

  margin-top: 7px;
  padding: 13px 14px;

  border: 1px solid var(--border);
  border-radius: 11px;

  background: #ffffff;

  color: var(--text);

  font-size: 11px;

  outline: none;

  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.formGroup input:focus,
.formGroup select:focus,
.formGroup textarea:focus {
  border-color: var(--primary);

  box-shadow: 0 0 0 3px rgba(31,138,138,0.09);
}

.formGroup textarea {
  min-height: 120px;

  resize: vertical;
}

.appointmentSubmit {
  margin-top: 8px;
}

.appointmentSuccess {
  padding: 35px;

  border-radius: 20px;

  background: var(--light-teal);

  text-align: center;
}

.appointmentSuccess svg {
  color: var(--primary);
}

.appointmentSuccess h3 {
  margin: 12px 0 5px;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: 28px;
}

.appointmentSuccess p {
  color: var(--muted);

  font-size: 11px;
}

/* =========================================================
   CONTACT
========================================================= */

.contactGrid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;

  gap: 75px;

  align-items: start;
}

.contactInfo h2 {
  margin: 13px 0 20px;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;

  font-size: clamp(42px, 5vw, 60px);

  line-height: 1;
}

.contactInfo h2 span {
  color: var(--primary);
  font-style: italic;
}

.contactInfo > p {
  color: var(--muted);

  font-size: 12px;
  line-height: 1.8;
}

.contactItems {
  display: grid;
  gap: 12px;

  margin-top: 30px;
}

.contactItem {
  display: flex;
  align-items: center;
  gap: 13px;

  padding: 14px;

  border: 1px solid var(--border);
  border-radius: 14px;

  background: #ffffff;
}

.contactItemIcon {
  width: 40px;
  height: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 11px;

  background: var(--light-teal);
  color: var(--primary);
}

.contactItem div {
  display: flex;
  flex-direction: column;
}

.contactItem strong {
  color: var(--ink);

  font-size: 10px;
}

.contactItem span {
  color: var(--muted);

  font-size: 9px;
}

.contactForm {
  padding: 38px;

  border: 1px solid var(--border);
  border-radius: 25px;

  background: #ffffff;

  box-shadow: var(--shadow-md);
}

.contactFormGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;

  gap: 18px;
}

.contactForm .full {
  grid-column: 1 / -1;
}

.contactForm label {
  display: flex;
  flex-direction: column;

  color: var(--ink);

  font-size: 10px;
  font-weight: 800;
}

.contactForm input,
.contactForm textarea {
  margin-top: 7px;
  padding: 13px 14px;

  border: 1px solid var(--border);
  border-radius: 11px;

  outline: none;

  font-size: 11px;

  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.contactForm input:focus,
.contactForm textarea:focus {
  border-color: var(--primary);

  box-shadow: 0 0 0 3px rgba(31,138,138,0.09);
}

.contactForm textarea {
  min-height: 140px;
  resize: vertical;
}

.contactSuccess {
  padding: 35px;

  border-radius: 20px;

  background: var(--light-teal);

  text-align: center;
}

.contactSuccess svg {
  color: var(--primary);
}

.contactSuccess h3 {
  margin: 12px 0 5px;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;
}

.contactSuccess p {
  color: var(--muted);

  font-size: 11px;
}

.mapSection {
  margin-top: 55px;
}

.mapBox {
  min-height: 300px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 25px;

  background:
    linear-gradient(
      rgba(234,245,244,0.88),
      rgba(234,245,244,0.88)
    ),
    url("https://images.unsplash.com/photo-1449824913935-59a10b8d2000?auto=format&fit=crop&w=1600&q=80")
    center/cover;

  text-align: center;
}

.mapBoxContent {
  padding: 30px;
}

.mapBoxContent svg {
  color: var(--primary);
}

.mapBoxContent h3 {
  margin: 10px 0 4px;

  color: var(--ink);

  font-family: "Playfair Display", Georgia, serif;
}

.mapBoxContent p {
  color: var(--muted);

  font-size: 10px;
}

/* =========================================================
   FOOTER
========================================================= */

.siteFooter {
  padding: 75px 0 22px;

  background: #061f35;

  color: rgba(255,255,255,0.60);
}

.footerMain {
  display: grid;
  grid-template-columns: 1.5fr 0.8fr 0.8fr 1fr;

  gap: 55px;
}

.footerBrand {
  max-width: 300px;
}

.footerBrand .brand {
  color: #ffffff;
}

.footerBrand .brandText strong {
  color: #ffffff;
}

.footerBrand p {
  margin-top: 20px;

  color: rgba(255,255,255,0.52);

  font-size: 11px;
  line-height: 1.8;
}

.footerColumn h4 {
  margin: 0 0 17px;

  color: #ffffff;

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.5px;
}

.footerColumn a {
  display: flex;
  align-items: center;
  gap: 7px;

  margin-bottom: 11px;

  color: rgba(255,255,255,0.55);

  font-size: 10px;

  transition: color 0.25s ease;
}

.footerColumn a:hover {
  color: var(--accent);
}

.footerContactItem {
  display: flex;
  align-items: flex-start;
  gap: 9px;

  margin-bottom: 13px;

  color: rgba(255,255,255,0.55);

  font-size: 10px;
}

.footerContactItem svg {
  flex-shrink: 0;

  color: var(--accent);
}

.footerCTA {
  margin-top: 60px;

  padding: 27px;

  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 20px;

  background: rgba(255,255,255,0.04);

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 25px;
}

.footerCTA h3 {
  margin: 0 0 4px;

  color: #ffffff;

  font-family: "Playfair Display", Georgia, serif;

  font-size: 24px;
}

.footerCTA p {
  margin: 0;

  color: rgba(255,255,255,0.48);

  font-size: 10px;
}

.footerBottom {
  margin-top: 45px;
  padding-top: 18px;

  border-top: 1px solid rgba(255,255,255,0.10);

  display: flex;
  align-items: center;
  justify-content: space-between;

  color: rgba(255,255,255,0.35);

  font-size: 8px;
}

/* =========================================================
   GENERAL FORMS
========================================================= */

input,
textarea,
select {
  font-family: "DM Sans", sans-serif;
}

input::placeholder,
textarea::placeholder {
  color: #9aa8b5;
}

/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1100px) {

  .container {
    width: min(100% - 45px, 1000px);
  }

  .navLinks {
    gap: 16px;
  }

  .navLinks a {
    font-size: 11px;
  }

  .navAppointment {
    padding: 11px 15px;
  }

  .serviceGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .homeIntroGrid,
  .homeWhyGrid,
  .homeTestimonialGrid,
  .aboutIntroGrid,
  .technologyGrid,
  .treatmentWhyGrid,
  .contactGrid {
    gap: 55px;
  }

  .processGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footerMain {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* =========================================================
   TABLET / MOBILE NAV
========================================================= */

@media (max-width: 900px) {

  .navin {
    min-height: 74px;
  }

  .hamb {
    display: flex;
  }

  .nav nav {
    position: absolute;

    top: 74px;
    left: 0;
    right: 0;

    display: none;

    padding: 20px;

    background: #ffffff;

    border-top: 1px solid var(--border);

    box-shadow: 0 20px 35px rgba(11,37,69,0.10);

    flex-direction: column;
    align-items: stretch;

    gap: 5px;
  }

  .nav nav.open {
    display: flex;
  }

  .navLinks {
    display: flex;

    flex-direction: column;
    align-items: stretch;

    gap: 0;
  }

  .navLinks a {
    padding: 13px 5px;

    border-bottom: 1px solid var(--border);

    font-size: 13px;
  }

  .navLinks a::after {
    display: none;
  }

  .navAppointment {
    width: 100%;

    margin-top: 10px;
  }

  .mobileCallBar {
    position: fixed;

    z-index: 999;

    left: 12px;
    right: 12px;
    bottom: 12px;

    display: grid;
    grid-template-columns: 1fr 1fr;

    overflow: hidden;

    border-radius: 15px;

    background: var(--ink);

    box-shadow: 0 15px 35px rgba(0,0,0,0.20);
  }

  .mobileCallBar a {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;

    min-height: 48px;

    color: #ffffff;

    font-size: 10px;
    font-weight: 800;
  }

  .mobileCallBar a + a {
    background: var(--primary);
  }

  .hero {
    min-height: 750px;
    height: 780px;
  }

  .heroContainer {
    min-height: 750px;

    align-items: center;
  }

  .heroContent {
    max-width: 700px;

    padding-bottom: 90px;
  }

  .heroTitle {
    font-size: clamp(52px, 8vw, 76px);
  }

  .heroScroll {
    display: none;
  }

  .homeIntroGrid,
  .homeWhyGrid,
  .homeTestimonialGrid,
  .aboutIntroGrid,
  .technologyGrid,
  .treatmentIntroGrid,
  .treatmentWhyGrid,
  .contactGrid,
  .appointmentGrid {
    grid-template-columns: 1fr;
  }

  .homeWhyImage,
  .aboutIntroImage,
  .technologyImage,
  .treatmentWhyImage {
    min-height: 500px;
  }

  .homeWhyImage > img,
  .aboutIntroImage img,
  .technologyImage img,
  .treatmentWhyImage img {
    min-height: 500px;
  }

  .appointmentInfo {
    position: static;
  }

  .treatmentReviewInner {
    flex-direction: column;
    align-items: flex-start;
  }

  .treatmentReviewStats {
    width: 100%;
  }
}

/* =========================================================
   MOBILE
========================================================= */

