  }

  .sectionTop {
    display: block;

    margin-bottom: 35px;
  }

  .sectionTopRight {
    margin-top: 20px;
  }

  .serviceGrid {
    grid-template-columns: 1fr;
  }

  .serviceCardImage {
    height: 225px;
  }

  .serviceCardView {
    width: 41px;
    height: 41px;

    opacity: 1;
    transform: translateY(0);
  }

  .homeWhyImage,
  .aboutIntroImage,
  .technologyImage,
  .treatmentWhyImage {
    min-height: 390px;
  }

  .homeWhyImage > img,
  .aboutIntroImage img,
  .technologyImage img,
  .treatmentWhyImage img {
    min-height: 390px;
  }

  .doctorGrid {
    grid-template-columns: 1fr;
  }

  .doctorImage {
    height: 330px;
  }

  .homeSmileBanner {
