  }

  .homeQuoteCard > p {
    font-size: 22px;
  }

  .homeCTA {
    padding: 40px 25px;
  }

  .homeCTAContent {
    display: block;
  }

  .homeCTAActions {
    flex-wrap: wrap;

    margin-top: 28px;
  }

  /* ABOUT */

  .valueGrid {
    grid-template-columns: 1fr;
  }

  .aboutStatsGrid {
    grid-template-columns: repeat(2, 1fr);

    gap: 20px;
  }

  .aboutStatsGrid > div {
