  .treatmentIntroGrid {
    gap: 30px;
  }

  .treatmentSectionHeading {
    display: block;
  }

  .treatmentSectionHeading > p {
    margin-top: 20px;
  }

  .treatmentGrid {
    grid-template-columns: 1fr;
  }

  .treatmentImage {
