  .reviewGrid {
    grid-template-columns: 1fr;
  }

  .reviewStats {
    grid-template-columns: repeat(2, 1fr);

    gap: 20px;

    padding: 25px;
  }

  .reviewStats > div {
    border: 0;
  }

  /* APPOINTMENT */

  .appointmentForm {
    padding: 25px 20px;
  }

  .appointmentFormGrid {
    grid-template-columns: 1fr;
  }

  .formGroup.full {
    grid-column: auto;
  }

  /* CONTACT */

  .contactForm {
    padding: 25px 20px;
  }

  .contactFormGrid {
    grid-template-columns: 1fr;
  }

  .contactForm .full {
    grid-column: auto;
  }

  /* FOOTER */

  .footerMain {
    grid-template-columns: 1fr;

    gap: 30px;
  }

  .footerCTA {
    display: block;
  }

  .footerCTA .btn {
    margin-top: 18px;
  }

  .footerBottom {
    display: block;

    text-align: center;
  }
}

