}

/* =========================================================
   NOVADENT HERO - CENTERED & RESPONSIVE FIX
   ========================================================= */

.hero {
  position: relative;
  width: 100%;
  min-height: calc(100vh - 82px);
  height: 820px;
  max-height: 900px;
  overflow: hidden;
  background: #061b2d;
  color: #ffffff;
}

.heroSlide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center center;
  background-repeat: no-repeat;
  opacity: 0;
  transform: scale(1.04);
  transition:
    opacity 0.9s ease,
    transform 6s ease;
}

/* Main container */
.heroContainer {
  position: relative;
  z-index: 3;
  width: min(1180px, calc(100% - 48px));
  height: 100%;
  margin: 0 auto;
  display: flex;
  align-items: center;
}

/* Content */
.heroContent {
  width: 100%;
  max-width: 760px;
  padding-top: 35px;
  margin-left: auto;
  margin-right: auto;
}

.heroEyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
  color: #78d0c9;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2.5px;
}

.heroEyebrowLine {
  width: 42px;
  height: 2px;
  background: #55b8b0;
  border-radius: 10px;
}

/* IMPORTANT: Heading now stays inside screen */
.heroTitle {
  width: 100%;
  margin: 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(56px, 6vw, 88px);
  line-height: 0.98;
  font-weight: 600;
  letter-spacing: -2.5px;
  color: #ffffff;
}

.heroTitle span {
  color: #64c8c1;
  font-style: italic;
}

.heroText {
  max-width: 620px;
  margin: 30px 0 0;
  font-family: "DM Sans", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.78);
}

/* Buttons */
.heroActions {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-top: 34px;
}

.heroPrimaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
}

.heroSecondaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  text-decoration: none;
  transition: gap 0.25s ease, color 0.25s ease;
}

.heroSecondaryBtn:hover {
  gap: 14px;
  color: #64c8c1;
}

/* Trust */
.heroTrust {
  display: flex;
  align-items: center;
  gap: 25px;
  margin-top: 55px;
}

.heroTrustIcon {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  color: #65c9c1;
  background: rgba(255, 255, 255, 0.06);
}

.heroTrustItem div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.heroTrustItem strong {
  font-size: 13px;
  color: #ffffff;
}

.heroTrustItem small {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.58);
}

.heroTrustDivider {
  width: 1px;
  height: 35px;
  background: rgba(255, 255, 255, 0.16);
}

/* Slider controls */
.heroControls {
  position: absolute;
  bottom: 54px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  z-index: 5;
}

.heroArrow {
  width: 48px;
  height: 48px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(10px);
  cursor: pointer;
  transition: all 0.25s ease;
}

.heroArrow:hover {
  background: #55b8b0;
  border-color: #55b8b0;
  transform: translateY(-2px);
}

.heroDot {
  width: 8px;
  height: 8px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.4);
  cursor: pointer;
  transition: all 0.3s ease;
}

.heroDot.active {
  width: 34px;
  border-radius: 20px;
  background: #55b8b0;
}

.heroSlideNumber {
  margin-left: 12px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 2px;
}

/* Scroll */
.heroScroll {
  position: absolute;
  left: 0;
  bottom: 65px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
}

.heroScrollLine {
  width: 55px;
  height: 1px;
  background: rgba(255, 255, 255, 0.35);
}

/* Animation */
.heroContentIn {
  animation: heroContentIn 0.8s ease both;
}

@keyframes heroContentIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

