/* =========================================================
   NOVADENT NAVBAR
   ========================================================= */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: 82px;
  background: rgba(255, 255, 255, 0.96);
  border-bottom: 1px solid rgba(11, 37, 69, 0.08);
  box-shadow: 0 5px 25px rgba(11, 37, 69, 0.06);
  backdrop-filter: blur(16px);
}

.navin {
  width: min(1380px, calc(100% - 48px));
  height: 100%;
  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

/* Logo */

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  flex-shrink: 0;
  color: var(--ink);
  text-decoration: none;
}

.logo {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;

  color: var(--primary);
  background: var(--light-teal);
  border: 1px solid rgba(31, 138, 138, 0.15);
  border-radius: 13px;

  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.brand:hover .logo {
  transform: rotate(-4deg) scale(1.04);
  background: #dff1ef;
}

.toothLogo svg {
  display: block;
}

.brandText {
  display: flex;
  flex-direction: column;
  line-height: 1;
  gap: 5px;
}

.brandText strong {
  font-family: "DM Sans", Arial, sans-serif;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: 1.5px;
  color: var(--ink);
}

.brandText small {
  font-family: "DM Sans", Arial, sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2.2px;
  text-transform: uppercase;
  color: var(--primary);
}

/* Navigation */

.nav nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 28px;
  margin-left: auto;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 24px;
}

.navLinks a {
  position: relative;
  padding: 31px 0;

  color: #52657a;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;

  transition:
    color 0.25s ease,
    transform 0.25s ease;
}

.navLinks a::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 21px;

  width: 0;
  height: 2px;

  background: var(--primary);
  border-radius: 10px;

  transform: translateX(-50%);
  transition: width 0.25s ease;
}

.navLinks a:hover {
  color: var(--primary);
}

.navLinks a:hover::after,
.navLinks a.active::after {
  width: 20px;
}

.navLinks a.active {
  color: var(--ink);
}

/* Appointment */

.navAppointment {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;

  min-height: 43px;
  padding: 0 18px;

  font-size: 12px;
  white-space: nowrap;
}

/* Hamburger */

.hamb {
  display: none;
  width: 44px;
  height: 44px;

  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);
  border-radius: 10px;

  background: #ffffff;
  color: var(--ink);
  cursor: pointer;
}

/* Mobile Call Bar */

.mobileCallBar {
  display: none;
}

/* =========================================================
   NAVBAR TABLET
   ========================================================= */

@media (max-width: 1100px) {
  .navin {
    width: calc(100% - 32px);
  }

  .navLinks {
    gap: 15px;
  }

  .nav nav {
    gap: 18px;
  }

  .navLinks a {
    font-size: 12px;
  }

  .navAppointment {
    padding: 0 13px;
  }
}

/* =========================================================
   NAVBAR MOBILE
   ========================================================= */

@media (max-width: 900px) {
  .nav {
    height: 74px;
  }

  .navin {
    width: calc(100% - 28px);
  }

  .brandText strong {
    font-size: 17px;
  }

  .brandText small {
    font-size: 8px;
  }

  .logo {
    width: 42px;
    height: 42px;
  }

  .hamb {
    display: flex;
  }

  .nav nav {
    position: fixed;
    top: 74px;
    left: 14px;
    right: 14px;

    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 18px;

    padding: 20px;

    background: rgba(255, 255, 255, 0.98);
    border: 1px solid var(--border);
    border-radius: 18px;
    box-shadow: 0 20px 50px rgba(11, 37, 69, 0.14);

    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);

    transition:
      opacity 0.25s ease,
      visibility 0.25s ease,
      transform 0.25s ease;
  }

  .nav nav.open {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }

  .navLinks {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
  }

  .navLinks a {
    padding: 13px 12px;
    border-radius: 9px;
  }

  .navLinks a::after {
