    grid-template-columns: 1fr 1fr;

    background: #ffffff;
    border-top: 1px solid var(--border);
    box-shadow: 0 -8px 25px rgba(11, 37, 69, 0.08);
  }

  .mobileCallBar a {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;

    color: var(--ink);
    font-size: 12px;
    font-weight: 700;
    text-decoration: none;
  }

  .mobileCallBar a + a {
    color: #ffffff;
    background: var(--primary);
  }
}

/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {
  .navin {
    width: calc(100% - 20px);
  }

  .brand {
    gap: 8px;
  }

  .logo {
    width: 39px;
