  }

  .hamb {
    width: 40px;
    height: 40px;
  }
}

/* =========================================================
   PREMIUM SERVICE CARDS
========================================================= */

.serviceCard {
  position: relative;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 12px 35px rgba(11, 37, 69, 0.07);
  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease,
    border-color 0.45s ease;
}

.serviceCard:hover {
  transform: translateY(-10px);
  border-color: rgba(31, 138, 138, 0.35);
  box-shadow: 0 25px 60px rgba(11, 37, 69, 0.14);
}

/* IMAGE */

.serviceCardImage {
  position: relative;
  height: 245px;
  overflow: hidden;
  background: var(--soft-bg);
}

.serviceCardImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition:
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.5s ease;
}

.serviceCard:hover .serviceCardImage img {
  transform: scale(1.08);
  filter: brightness(0.9);
}

.serviceCardImageOverlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgba(11, 37, 69, 0.05) 0%,
      rgba(11, 37, 69, 0.12) 45%,
      rgba(11, 37, 69, 0.72) 100%
    );
  pointer-events: none;
}

/* ICON */

.serviceCardIcon {
  position: absolute;
  left: 22px;
  bottom: 22px;
  width: 52px;
  height: 52px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.94);
  color: var(--primary);
  font-size: 22px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.12);
  transition:
    transform 0.4s ease,
    background 0.4s ease,
    color 0.4s ease;
  z-index: 2;
}

.serviceCard:hover .serviceCardIcon {
  transform: translateY(-5px) rotate(-4deg);
  background: var(--primary);
  color: white;
}

/* IMAGE LABEL */

.serviceCardImageLabel {
  position: absolute;
  right: 22px;
  bottom: 24px;
  display: flex;
  align-items: center;
  gap: 9px;
  color: white;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.4px;
  z-index: 2;
}

.serviceCardImageLabel span:first-child {
  opacity: 0.65;
}

/* CONTENT */

.serviceCardContent {
  padding: 28px 28px 26px;
}

.serviceCardTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 13px;
}

.serviceCardSmallTitle {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.7px;
  color: var(--primary);
}

.serviceCardCheck {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  background: var(--light-teal);
  border-radius: 50%;
  transition: transform 0.3s ease;
}

.serviceCard:hover .serviceCardCheck {
  transform: scale(1.1);
}

.serviceCardContent h3 {
  margin: 0 0 12px;
  color: var(--ink);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 25px;
  line-height: 1.2;
}

.serviceCardContent p {
  margin: 0;
  min-height: 58px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.75;
}

/* LINK */

.serviceCardBottom {
  margin-top: 23px;
}

.serviceCardLink {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--ink);
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;
  transition: color 0.3s ease;
}

.serviceCardArrow {
  width: 35px;
  height: 35px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--light-teal);
  color: var(--primary);
  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.serviceCardLink:hover .serviceCardArrow {
  transform: translate(3px, -3px);
  background: var(--primary);
  color: white;
}

.serviceCardLine {
  display: block;
  width: 100%;
  height: 1px;
  margin-top: 18px;
  background: var(--border);
