  border-radius: 13px;
  background: #fff;
  color: var(--ink, #0b2545);
  font-size: 0.85rem;
  font-weight: 800;
  text-decoration: none;
  transition: 0.35s ease;
}

.lightButton:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.22);
}

.bannerTextLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #fff;
  font-size: 0.85rem;
  font-weight: 800;
  text-decoration: none;
  transition: 0.3s ease;
}

.bannerTextLink:hover {
  gap: 14px;
  color: #8bd9d1;
}

/* ---------------------------------------------------------
   TESTIMONIAL
--------------------------------------------------------- */

.homeTestimonial {
  background: var(--cream, #f7fafc);
}

.testimonialTop {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 35px;
}

.testimonialRatingTop {
  display: flex;
  align-items: center;
  gap: 10px;
}

.testimonialRatingTop .stars {
  color: #f3b51b;
  letter-spacing: 2px;
}

.testimonialRatingTop strong {
  color: var(--ink, #0b2545);
}

.testimonialRatingTop span {
  color: var(--muted, #64748b);
  font-size: 0.75rem;
}

.testimonialBox {
  position: relative;
  display: grid;
  grid-template-columns: 100px 1fr auto;
  gap: 30px;
  align-items: center;
  min-height: 360px;
  padding: 60px;
  overflow: hidden;
  border: 1px solid var(--border, #dce8eb);
  border-radius: 30px;
  background: #fff;
  box-shadow: 0 20px 60px rgba(11, 37, 69, 0.07);
}

.testimonialQuote {
  color: var(--primary, #1f8a8a);
  font-family: Georgia, serif;
  font-size: 8rem;
  line-height: 0.7;
  opacity: 0.22;
}

.testimonialContent {
  max-width: 750px;
}

.testimonialSmall {
  color: var(--primary, #1f8a8a);
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.15em;
}

.testimonialContent blockquote {
  margin: 18px 0 28px;
  color: var(--ink, #0b2545);
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(1.45rem, 2.5vw, 2.3rem);
  line-height: 1.35;
}

.testimonialAuthor {
  display: flex;
  align-items: center;
  gap: 13px;
}

.testimonialAvatar {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 50%;
  background: var(--light-teal, #eaf5f4);
  color: var(--primary, #1f8a8a);
  font-size: 0.72rem;
  font-weight: 800;
}

.testimonialAuthor strong,
.testimonialAuthor span {
  display: block;
}

.testimonialAuthor strong {
  color: var(--ink, #0b2545);
  font-size: 0.85rem;
}

.testimonialAuthor span {
  margin-top: 3px;
  color: var(--muted, #64748b);
  font-size: 0.7rem;
}

.testimonialControls {
  display: flex;
  align-items: center;
  gap: 14px;
}

.testimonialControls > button {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--border, #dce8eb);
  border-radius: 50%;
  background: #fff;
  color: var(--ink, #0b2545);
  cursor: pointer;
  transition: 0.3s ease;
}

.testimonialControls > button:hover {
  border-color: var(--primary, #1f8a8a);
  background: var(--primary, #1f8a8a);
  color: #fff;
  transform: translateY(-3px);
}

.rotateLeft {
  transform: rotate(180deg);
}

.testimonialControls > button:hover .rotateLeft {
  transform: rotate(180deg);
}

.testimonialDots {
  display: flex;
  gap: 6px;
}

.testimonialDots button {
  width: 7px;
  height: 7px;
  padding: 0;
  border: 0;
  border-radius: 20px;
  background: #cbd5df;
  cursor: pointer;
  transition: 0.3s ease;
}

.testimonialDots button.active {
  width: 22px;
  background: var(--primary, #1f8a8a);
}

/* ---------------------------------------------------------
   FINAL CTA
--------------------------------------------------------- */

.homeFinalCTA {
  position: relative;
  overflow: hidden;
  padding: 80px 0;
  background: var(--ink, #0b2545);
}

.ctaDecor {
  position: absolute;
  border: 1px solid rgba(85, 184, 176, 0.13);
  border-radius: 50%;
  pointer-events: none;
}

.ctaDecorOne {
  top: -220px;
  right: -100px;
  width: 480px;
  height: 480px;
}

.ctaDecorTwo {
  bottom: -250px;
  left: -150px;
  width: 500px;
  height: 500px;
}

.finalCTACard {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 50px;
  align-items: center;
  padding: 60px;
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 30px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.07),
      rgba(255, 255, 255, 0.025)
    );
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.18);
  backdrop-filter: blur(10px);
}

.ctaBadge {
  grid-column: 1 / -1;
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(118, 209, 200, 0.25);
  border-radius: 50px;
  background: rgba(118, 209, 200, 0.08);
  color: #8bd9d1;
  font-size: 0.7rem;
  font-weight: 700;
}

.finalCTAText .eyebrow {
  color: #76d1c8;
}

.finalCTAText h2 {
  margin-top: 17px;
  color: #fff;
  font-size: clamp(2.5rem, 5vw, 5rem);
}

.finalCTAText h2 span {
  color: #76d1c8;
}

.finalCTAText p {
  max-width: 620px;
  margin-top: 22px;
  color: rgba(255, 255, 255, 0.64);
  line-height: 1.8;
}

.finalCTAActions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 12px;
  min-width: 210px;
}

.primaryButton,
.secondaryButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 50px;
  padding: 13px 18px;
  border-radius: 13px;
  font-size: 0.84rem;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.primaryButton {
  background: var(--primary, #1f8a8a);
  color: #fff;
}

.primaryButton:hover {
  transform: translateY(-4px);
  background: var(--primary-dark, #146b6b);
  box-shadow: 0 15px 35px rgba(31, 138, 138, 0.28);
}

.secondaryButton {
  border: 1px solid rgba(255, 255, 255, 0.20);
  color: #fff;
  background: transparent;
}

.secondaryButton:hover {
  transform: translateY(-4px);
  border-color: rgba(118, 209, 200, 0.55);
  background: rgba(255, 255, 255, 0.06);
}

.largeCTA {
  min-height: 56px;
}

/* ---------------------------------------------------------
   BUTTON MICRO ANIMATION
--------------------------------------------------------- */

.animatedButton svg {
  transition: transform 0.3s ease;
}

.animatedButton:hover svg {
  transform: translateX(4px);
}

.animatedButton:active {
  transform: translateY(-1px) scale(0.98);
}

/* ---------------------------------------------------------
   FLOATING BACKGROUND DETAILS
--------------------------------------------------------- */

.homePage::before {
  content: "";
  position: absolute;
  top: 900px;
  right: -120px;
  width: 260px;
  height: 260px;
  border: 1px solid rgba(31, 138, 138, 0.07);
  border-radius: 50%;
  pointer-events: none;
}

.homePage::after {
  content: "";
  position: absolute;
  top: 1650px;
  left: -160px;
  width: 300px;
  height: 300px;
  border: 1px solid rgba(31, 138, 138, 0.06);
  border-radius: 50%;
  pointer-events: none;
}

/* ---------------------------------------------------------
   TABLET
--------------------------------------------------------- */

@media (max-width: 1000px) {

  .homeIntroGrid {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .homeIntroLabel {
    position: static;
  }

  .homeStatsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .interactiveStat:nth-child(2) {
    border-right: 0;
  }

  .interactiveStat:nth-child(-n + 2) {
    border-bottom: 1px solid rgba(255, 255, 255, 0.10);
  }

  .homeWhyGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .homeWhyImage {
    min-height: 520px;
  }

  .homeWhyImage img {
    height: 520px;
  }

  .homeWhyContent {
    max-width: 800px;
  }

  .testimonialBox {
    grid-template-columns: 70px 1fr;
    padding: 45px;
  }

  .testimonialControls {
    grid-column: 2;
  }

  .finalCTACard {
    grid-template-columns: 1fr;
  }

  .finalCTAActions {
    flex-direction: row;
    justify-content: flex-start;
  }

}

/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 700px) {

  .homeIntro,
  .homeServices,
  .homeWhy,
  .homeDoctors,
  .homeTestimonial {
    padding-top: 75px;
    padding-bottom: 75px;
  }

  .homeIntroContent h2,
  .homeWhyContent h2,
  .enhancedSectionHeader h2,
  .finalCTAText h2 {
    font-size: clamp(2.4rem, 11vw, 3.6rem);
  }

  .largeIntroText {
    font-size: 1.08rem !important;
  }

  .introHighlights {
    display: grid;
  }

  .introHighlights div {
    width: 100%;
  }

  .homeStatsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .interactiveStat {
    min-height: 185px;
    padding: 28px 18px;
  }

  .interactiveStat strong {
    font-size: 2rem;
  }

  .interactiveStat > span {
    font-size: 0.78rem;
  }

  .interactiveStat small {
    font-size: 0.65rem;
  }

  .statIcon {
    width: 38px;
    height: 38px;
    margin-bottom: 17px;
  }

  .enhancedSectionHeader {
    display: block;
    margin-bottom: 35px;
  }

  .enhancedSectionHeader .outlineButton {
    margin-top: 25px;
  }

  .serviceGrid,
  .doctorGrid {
    grid-template-columns: 1fr !important;
  }

  .servicesBottomNote {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .servicesBottomNote > a {
    width: 100%;
    margin-left: 58px;
  }

  .homeWhyImage {
    min-height: 430px;
  }

  .homeWhyImage img {
    height: 430px;
    border-radius: 22px;
  }

  .homeWhyFloating {
    right: 15px;
    bottom: 20px;
  }

  .floatingExperience {
    left: 15px;
    top: 20px;
    width: 82px;
    height: 82px;
  }

  .floatingExperience strong {
    font-size: 1.35rem;
  }

  .interactiveBenefit {
    grid-template-columns: 32px 42px 1fr 20px;
    padding: 12px;
  }

  .benefitIcon {
    width: 36px;
    height: 36px;
  }

  .benefitText > span {
    font-size: 0.68rem;
  }

  .interactiveBenefit:hover,
  .interactiveBenefit.active {
    transform: translateX(3px);
  }

  .homeSmileBanner {
    min-height: 650px;
  }

  .homeSmileOverlay {
    background:
      linear-gradient(
        90deg,
        rgba(5, 23, 43, 0.93),
        rgba(5, 23, 43, 0.70)
      );
  }

  .homeSmileContent {
    padding-top: 70px;
    padding-bottom: 70px;
  }

  .homeSmileContent h2 {
    font-size: clamp(3rem, 15vw, 5rem);
  }

  .bannerActions {
    align-items: flex-start;
    flex-direction: column;
  }

  .testimonialTop {
    display: block;
  }

  .testimonialRatingTop {
    margin-top: 18px;
  }

  .testimonialBox {
    display: block;
    min-height: auto;
    padding: 35px 24px;
    border-radius: 22px;
  }

  .testimonialQuote {
    height: 55px;
    font-size: 6rem;
  }

  .testimonialContent blockquote {
    font-size: 1.35rem;
  }

  .testimonialControls {
    margin-top: 30px;
    justify-content: space-between;
  }

  .homeFinalCTA {
    padding: 55px 0;
  }

  .finalCTACard {
    padding: 35px 24px;
    border-radius: 22px;
  }

  .finalCTAActions {
    flex-direction: column;
  }

  .finalCTAActions a {
    width: 100%;
  }

}

/* ---------------------------------------------------------
   SMALL MOBILE
--------------------------------------------------------- */

@media (max-width: 430px) {

  .homeStatsGrid {
    grid-template-columns: 1fr;
  }

  .interactiveStat {
    min-height: auto;
    border-right: 0 !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.10);
  }

  .interactiveStat:last-child {
    border-bottom: 0;
  }

  .homeWhyImage {
    min-height: 360px;
  }

  .homeWhyImage img {
    height: 360px;
  }

  .homeWhyFloating {
    min-width: 175px;
    padding: 12px;
  }

  .floatingIcon {
    width: 38px;
    height: 38px;
  }

  .interactiveBenefit {
    grid-template-columns: 30px 40px 1fr;
  }

  .benefitArrow {
    display: none;
  }

  .bannerFloatingTag {
    font-size: 0.64rem;
  }

  .homeSmileContent h2 {
    font-size: 3.1rem;
  }

  .servicesBottomNote {
    padding: 15px;
  }

  .servicesBottomNote > a {
    margin-left: 0;
  }

}

/* ---------------------------------------------------------
   REDUCE MOTION ACCESSIBILITY
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }

}

/* =========================================================
   NOVADENT — PREMIUM ABOUT PAGE
   Modern • Interactive • Responsive • Animated
========================================================= */

.aboutPage {
  overflow: hidden;
  background: #f7fafc;
  color: var(--ink, #0b2545);
}

.aboutPage .container {
  width: min(1240px, calc(100% - 40px));
  margin: 0 auto;
}

.aboutPage .section {
  position: relative;
  padding: 115px 0;
}

/* =========================================================
   COMMON TYPOGRAPHY
========================================================= */

.aboutPage h1,
.aboutPage h2,
.aboutPage h3,
.aboutPage p {
  margin-top: 0;
}

.aboutPage h2 {
  font-family: "Playfair Display", serif;
  font-size: clamp(40px, 5vw, 68px);
  line-height: 1.04;
  letter-spacing: -1.8px;
  font-weight: 700;
  color: #0b2545;
}

.aboutPage h2 span {
  display: block;
  color: #1f8a8a;
}

.aboutPage .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #1f8a8a;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 2.8px;
  text-transform: uppercase;
}

.aboutPage .eyebrow::before {
  content: "";
  width: 28px;
  height: 1px;
  background: #55b8b0;
}

/* =========================================================
   HERO
========================================================= */

.aboutHero {
  position: relative;
  min-height: 720px;
  display: flex;
  align-items: center;
  isolation: isolate;
  overflow: hidden;
}

.aboutHeroImage {
  position: absolute;
  inset: 0;
  z-index: -3;
}

.aboutHeroImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.04);
  animation: aboutHeroZoom 12s ease-in-out infinite alternate;
}

@keyframes aboutHeroZoom {
  from {
    transform: scale(1.04);
  }

  to {
    transform: scale(1.12);
  }
}

.aboutHeroOverlay {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(
      90deg,
      rgba(5, 25, 44, 0.93) 0%,
      rgba(8, 36, 56, 0.77) 42%,
      rgba(8, 36, 56, 0.28) 100%
    );
}

.aboutHeroOverlay::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 75% 35%,
      rgba(85, 184, 176, 0.18),
      transparent 32%
    );
}

.aboutHeroContent {
  position: relative;
  padding-top: 70px;
  color: white;
  animation: aboutHeroContentIn 1s cubic-bezier(.2,.8,.2,1) both;
}

@keyframes aboutHeroContentIn {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.aboutHeroBadge {
  width: fit-content;
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 24px;
  padding: 9px 14px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 999px;
  background: rgba(255,255,255,.08);
  backdrop-filter: blur(15px);
  color: #b9eee9;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 1.8px;
}

.aboutHeroBadge svg {
  animation: sparkleFloat 2.5s ease-in-out infinite;
}

@keyframes sparkleFloat {
  0%,100% {
    transform: rotate(0) scale(1);
  }

  50% {
    transform: rotate(12deg) scale(1.12);
  }
}

.aboutLightEyebrow {
  color: #a7e5df !important;
  margin-bottom: 18px;
}

.aboutLightEyebrow::before {
  background: #75d5ce !important;
}

.aboutHero h1 {
  max-width: 820px;
  margin-bottom: 25px;
  color: white;
  font-family: "Playfair Display", serif;
  font-size: clamp(55px, 7vw, 94px);
  line-height: .96;
  letter-spacing: -4px;
  font-weight: 700;
}

.aboutHero h1 span {
  display: block;
  color: #69c9c1;
}

.aboutHeroContent > p {
  max-width: 610px;
  margin-bottom: 34px;
  color: rgba(255,255,255,.78);
  font-size: 17px;
  line-height: 1.8;
}

.aboutHeroActions {
  display: flex;
  align-items: center;
  gap: 28px;
}

.lightButton {
  min-height: 54px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  padding: 0 21px;
  border-radius: 14px;
  color: #0b2545;
  background: white;
  text-decoration: none;
  font-size: 12px;
  font-weight: 900;
  box-shadow: 0 15px 35px rgba(0,0,0,.16);
  transition: .35s ease;
}

.lightButton:hover {
  transform: translateY(-4px);
  box-shadow: 0 22px 45px rgba(0,0,0,.25);
}

.lightButton svg {
  transition: .35s ease;
}

.lightButton:hover svg {
  transform: translate(3px,-3px);
}

.aboutScrollLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: white;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .5px;
  transition: .3s ease;
}

.aboutScrollLink:hover {
  color: #71d5cd;
  transform: translateX(4px);
}

.aboutHeroScroll {
  position: absolute;
  right: 42px;
  bottom: 38px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  color: rgba(255,255,255,.65);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 2px;
  writing-mode: vertical-rl;
}

.aboutHeroScroll div {
  width: 1px;
  height: 65px;
  background: linear-gradient(
    to bottom,
    #63cfc7,
    transparent
  );
  animation: scrollLine 2s ease-in-out infinite;
}

@keyframes scrollLine {
  0%,100% {
    transform: scaleY(.65);
    transform-origin: top;
  }

  50% {
    transform: scaleY(1);
    transform-origin: top;
  }
}

/* =========================================================
   INTRO / OUR STORY
========================================================= */

.aboutIntro {
  background:
    radial-gradient(
      circle at 5% 20%,
      rgba(85,184,176,.08),
      transparent 28%
    ),
    #f7fafc;
}

.aboutIntroGrid {
  display: grid;
  grid-template-columns: .92fr 1.08fr;
  gap: 90px;
  align-items: center;
}

.aboutIntroImage {
  position: relative;
  min-height: 610px;
}

.aboutIntroImage::before {
  content: "";
  position: absolute;
  width: 150px;
  height: 150px;
  top: -22px;
  left: -22px;
  border-top: 2px solid #55b8b0;
  border-left: 2px solid #55b8b0;
  opacity: .7;
}

.aboutIntroImage img {
  width: 100%;
  height: 610px;
  object-fit: cover;
  border-radius: 28px;
  box-shadow: 0 30px 70px rgba(11,37,69,.15);
  transition: transform .7s cubic-bezier(.2,.8,.2,1);
}

.aboutIntroImage:hover img {
  transform: scale(1.025);
}

.aboutImageNumber {
  position: absolute;
  top: 20px;
  left: 20px;
  z-index: 3;
  padding: 9px 12px;
  border-radius: 999px;
  color: white;
  background: rgba(11,37,69,.78);
  backdrop-filter: blur(12px);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 1.7px;
}

.aboutImageGlow {
  position: absolute;
  right: -25px;
  bottom: 35px;
  width: 170px;
  height: 170px;
  border-radius: 50%;
  background: rgba(85,184,176,.18);
  filter: blur(30px);
  pointer-events: none;
  animation: glowFloat 4s ease-in-out infinite;
}

@keyframes glowFloat {
  0%,100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-18px);
  }
}

.floatingAboutCard {
  position: absolute;
  z-index: 5;
  right: -42px;
  bottom: 55px;
  min-width: 220px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 17px;
  border: 1px solid rgba(255,255,255,.75);
  border-radius: 18px;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(18px);
  box-shadow: 0 22px 50px rgba(11,37,69,.18);
  animation: floatingCard 4s ease-in-out infinite;
}

@keyframes floatingCard {
  0%,100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-9px);
  }
}

.aboutFloatingIcon {
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 14px;
  color: white;
  background: linear-gradient(135deg,#1f8a8a,#55b8b0);
  box-shadow: 0 10px 25px rgba(31,138,138,.25);
}

.floatingAboutCard strong,
.floatingAboutCard span {
  display: block;
}

.floatingAboutCard strong {
  color: #0b2545;
  font-size: 15px;
}

.floatingAboutCard span {
  margin-top: 4px;
  color: #64748b;
  font-size: 10px;
}

.aboutIntroContent {
  position: relative;
}

.aboutSectionNumber {
  margin-top: 13px;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 2px;
}

.aboutIntroContent h2 {
  margin: 20px 0 25px;
}

.aboutIntroContent p {
  max-width: 620px;
  color: #64748b;
  font-size: 15px;
  line-height: 1.85;
}

.aboutIntroContent .aboutLead {
  color: #334e68;
  font-size: 18px;
  line-height: 1.75;
}

.aboutChecklist {
  display: grid;
  gap: 12px;
  margin: 28px 0 32px;
}

.aboutChecklist div {
  display: flex;
  align-items: center;
  gap: 11px;
  color: #334e68;
  font-size: 12px;
  font-weight: 700;
}

.aboutChecklist svg {
  flex-shrink: 0;
  color: #1f8a8a;
}

/* =========================================================
   BUTTONS
========================================================= */

.primaryButton,
.outlineButton {
  width: fit-content;
  min-height: 52px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0 19px;
  border-radius: 14px;
  text-decoration: none;
  font-size: 11px;
  font-weight: 900;
  transition: .35s ease;
}

.primaryButton {
  color: white;
  background: #0b2545;
  box-shadow: 0 12px 28px rgba(11,37,69,.15);
}

.primaryButton:hover {
  transform: translateY(-4px);
  background: #1f8a8a;
  box-shadow: 0 18px 35px rgba(31,138,138,.25);
}

.primaryButton svg,
.outlineButton svg {
  transition: .35s ease;
}

.primaryButton:hover svg,
.outlineButton:hover svg {
  transform: translate(3px,-3px);
}

.outlineButton {
  color: #0b2545;
  border: 1px solid rgba(11,37,69,.16);
  background: white;
}

.outlineButton:hover {
  color: white;
  border-color: #1f8a8a;
  background: #1f8a8a;
  transform: translateY(-3px);
}

/* =========================================================
   VALUES
========================================================= */

.valuesSection {
  background: white;
}

.aboutSectionHeading {
  display: grid;
  grid-template-columns: 1fr .65fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 55px;
}

.aboutSectionHeading h2 {
  max-width: 650px;
  margin: 20px 0 0;
}

.aboutSectionHeading > p {
  margin: 0 0 7px;
  color: #64748b;
  font-size: 14px;
  line-height: 1.85;
}

.valueGrid {
  display: grid;
  grid-template-columns: repeat(4,1fr);
  gap: 16px;
}

.valueCard {
  position: relative;
  min-height: 310px;
  padding: 26px;
  overflow: hidden;
  border: 1px solid rgba(11,37,69,.07);
  border-radius: 23px;
  background: linear-gradient(
    145deg,
    #ffffff,
    #f4faf9
  );
  box-shadow: 0 10px 35px rgba(11,37,69,.045);
  transition:
    transform .45s cubic-bezier(.2,.8,.2,1),
    box-shadow .45s ease,
    border-color .45s ease;
}

.valueCard::before {
  content: "";
  position: absolute;
  width: 170px;
  height: 170px;
  right: -80px;
  top: -80px;
  border-radius: 50%;
  background: rgba(85,184,176,.13);
  transition: .5s ease;
}

.valueCard:hover {
  transform: translateY(-12px);
  border-color: rgba(31,138,138,.25);
  box-shadow: 0 25px 55px rgba(11,37,69,.12);
}

.valueCard:hover::before {
  transform: scale(1.45);
}

.valueCardTop {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.valueNumber {
  color: #9aa9b7;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 2px;
}

.valueIcon {
  width: 49px;
  height: 49px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 15px;
  color: #1f8a8a;
  background: #eaf5f4;
  transition: .4s ease;
}

.valueCard:hover .valueIcon {
  color: white;
  background: #1f8a8a;
  transform: rotate(-6deg) scale(1.08);
}

.valueCard h3 {
  margin: 55px 0 13px;
  color: #0b2545;
  font-family: "Playfair Display",serif;
  font-size: 25px;
}

.valueCard p {
  color: #64748b;
  font-size: 12px;
  line-height: 1.8;
}

.valueArrow {
  position: absolute;
  right: 23px;
  bottom: 23px;
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #0b2545;
  background: white;
  box-shadow: 0 7px 20px rgba(11,37,69,.08);
  transition: .4s ease;
}

.valueCard:hover .valueArrow {
  color: white;
  background: #0b2545;
  transform: translate(3px,-3px);
}

/* =========================================================
   TECHNOLOGY
========================================================= */

.aboutTechnology {
  background:
    radial-gradient(
      circle at 90% 50%,
      rgba(85,184,176,.09),
      transparent 30%
    ),
    #f7fafc;
}

.technologyGrid {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: 90px;
  align-items: center;
}

.technologyContent h2 {
  margin: 20px 0;
}

.technologyContent > p {
  max-width: 560px;
  color: #64748b;
  font-size: 15px;
  line-height: 1.85;
}

.technologyPoints {
  display: grid;
  gap: 10px;
  margin: 30px 0;
}

.technologyPoint {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 54px;
  padding: 8px 12px;
  border: 1px solid rgba(11,37,69,.06);
  border-radius: 14px;
  background: white;
  transition: .35s ease;
}

.technologyPoint:hover {
  transform: translateX(8px);
  border-color: rgba(31,138,138,.2);
  box-shadow: 0 10px 25px rgba(11,37,69,.06);
}

.techNumber {
  color: #9aa9b7;
  font-size: 9px;
  font-weight: 900;
}

.techIcon {
  width: 31px;
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #1f8a8a;
  background: #eaf5f4;
}

.technologyPoint > span:last-child {
  color: #334e68;
  font-size: 11px;
  font-weight: 800;
}

.technologyImage {
  position: relative;
  min-height: 550px;
  overflow: visible;
}

.technologyImage img {
  width: 100%;
  height: 550px;
  object-fit: cover;
  border-radius: 30px;
  box-shadow: 0 30px 70px rgba(11,37,69,.16);
  transition: transform .7s ease;
}

.technologyImage:hover img {
  transform: scale(1.025);
}

.technologyImageOverlay {
  position: absolute;
  inset: 0;
  border-radius: 30px;
  background:
    linear-gradient(
      180deg,
      transparent 50%,
      rgba(11,37,69,.55)
    );
  pointer-events: none;
}

.imageOverlayCard {
  position: absolute;
  left: -30px;
  bottom: 35px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px 18px;
  border: 1px solid rgba(255,255,255,.75);
  border-radius: 18px;
  background: rgba(255,255,255,.93);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 50px rgba(11,37,69,.18);
  animation: floatingCard 4.5s ease-in-out infinite;
}

.overlayCardIcon {
  width: 43px;
  height: 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  border-radius: 13px;
  background: linear-gradient(135deg,#0b2545,#1f8a8a);
}

.imageOverlayCard strong,
.imageOverlayCard span {
  display: block;
}

.imageOverlayCard strong {
  color: #0b2545;
  font-size: 13px;
}

.imageOverlayCard span {
  margin-top: 4px;
  color: #64748b;
  font-size: 9px;
}

/* =========================================================
   STATS
========================================================= */

.aboutStats {
  position: relative;
  overflow: hidden;
  padding: 75px 0;
  color: white;
  background:
    linear-gradient(
      135deg,
      #071d34,
      #0b3550 55%,
      #0d5260
    );
}

.aboutStatsGlow {
  position: absolute;
  width: 420px;
  height: 420px;
  right: -130px;
  top: -180px;
  border-radius: 50%;
  background: rgba(85,184,176,.18);
  filter: blur(25px);
}

.aboutStatsGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4,1fr);
}

.aboutStatItem {
  position: relative;
  padding: 10px 35px;
  text-align: center;
}

.aboutStatItem:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 15%;
  width: 1px;
  height: 70%;
  background: rgba(255,255,255,.14);
}

.aboutStatItem strong {
  display: block;
  font-family: "Playfair Display",serif;
  font-size: 52px;
  line-height: 1;
  color: #73d3cb;
}

.aboutStatItem span {
  display: block;
  margin-top: 12px;
  color: white;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: .8px;
}

.aboutStatItem small {
  display: block;
  margin-top: 6px;
  color: rgba(255,255,255,.48);
  font-size: 9px;
}

/* =========================================================
   PROMISE
========================================================= */

.aboutPromise {
  background: white;
}

.aboutPromiseGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 90px;
  align-items: center;
}

.aboutPromiseImage {
  position: relative;
}

.aboutPromiseImage img {
  width: 100%;
  height: 570px;
  object-fit: cover;
  border-radius: 30px;
  box-shadow: 0 30px 70px rgba(11,37,69,.14);
  transition: transform .65s ease;
}

.aboutPromiseImage:hover img {
  transform: scale(1.025);
}

.promiseBadge {
  position: absolute;
  left: 25px;
  bottom: 25px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 16px;
  border-radius: 999px;
  color: white;
  background: rgba(11,37,69,.88);
  backdrop-filter: blur(15px);
  font-size: 10px;
  font-weight: 800;
}

.promiseBadge svg {
  color: #72d4cc;
}

.aboutPromiseContent h2 {
  margin: 20px 0 25px;
}

.aboutPromiseContent > p {
  color: #64748b;
  font-size: 15px;
  line-height: 1.9;
}

.promisePoints {
  display: grid;
  gap: 16px;
  margin-top: 30px;
}

.promisePoints > div {
  display: grid;
  grid-template-columns: 45px 1fr;
  gap: 13px;
  align-items: center;
  padding: 13px;
  border-radius: 16px;
  transition: .35s ease;
}

.promisePoints > div:hover {
  background: #f4faf9;
  transform: translateX(7px);
}

.promisePointIcon {
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 13px;
  color: #1f8a8a;
  background: #eaf5f4;
}

.promisePoints strong,
.promisePoints span {
  display: block;
}

.promisePoints strong {
  color: #0b2545;
  font-size: 12px;
}

.promisePoints span {
  margin-top: 5px;
  color: #64748b;
  font-size: 10px;
  line-height: 1.6;
}

/* =========================================================
   FINAL CTA
========================================================= */

.aboutCTA {
  position: relative;
  overflow: hidden;
  padding: 110px 0;
  background: #f7fafc;
}

.ctaGlow {
  position: absolute;
  width: 500px;
  height: 500px;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-50%);
  border-radius: 50%;
  background: rgba(85,184,176,.12);
  filter: blur(45px);
}

.aboutCTACard {
  position: relative;
  overflow: hidden;
  padding: 80px 70px;
  border-radius: 35px;
  text-align: center;
  background:
    radial-gradient(
      circle at 20% 10%,
      rgba(85,184,176,.18),
      transparent 28%
    ),
    linear-gradient(
      135deg,
      #071d34,
      #0b3550
    );
  box-shadow: 0 35px 80px rgba(11,37,69,.2);
}

.aboutCTACard::before,
.aboutCTACard::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
}

.aboutCTACard::before {
  width: 360px;
  height: 360px;
  right: -130px;
  top: -180px;
}

.aboutCTACard::after {
  width: 250px;
  height: 250px;
  left: -100px;
  bottom: -150px;
}

.aboutCTABadge {
  width: fit-content;
  margin: 0 auto 25px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 13px;
  border: 1px solid rgba(255,255,255,.13);
  border-radius: 999px;
  color: #9de0da;
  background: rgba(255,255,255,.06);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 1.5px;
}

.aboutCTABadge svg {
  animation: pulseIcon 2s ease-in-out infinite;
}

@keyframes pulseIcon {
  0%,100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.15);
  }
}

.lightEyebrow {
  color: #8bded7 !important;
}

.aboutCTACard h2 {
  max-width: 750px;
  margin: 18px auto 18px;
  color: white;
}

.aboutCTACard h2 span {
  color: #69c9c1;
}

.aboutCTACard > p {
  max-width: 600px;
  margin: 0 auto 32px;
  color: rgba(255,255,255,.68);
  font-size: 14px;
  line-height: 1.8;
}

.ctaActions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 25px;
}

.aboutCTASecondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: white;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: .3s ease;
}

.aboutCTASecondary:hover {
  color: #6bd1c9;
  transform: translateX(4px);
}

/* =========================================================
   REVEAL ANIMATION
========================================================= */

.aboutIntroGrid,
.aboutSectionHeading,
.valueGrid,
.technologyGrid,
.aboutStatsGrid,
.aboutPromiseGrid,
.aboutCTACard {
  animation: aboutReveal .9s cubic-bezier(.2,.8,.2,1) both;
}

@keyframes aboutReveal {
  from {
    opacity: 0;
    transform: translateY(30px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1050px) {

  .aboutPage .section {
    padding: 90px 0;
  }

  .aboutHero {
    min-height: 650px;
  }

  .aboutIntroGrid,
  .technologyGrid,
  .aboutPromiseGrid {
    gap: 55px;
  }

  .valueGrid {
    grid-template-columns: repeat(2,1fr);
  }

  .aboutSectionHeading {
    gap: 40px;
  }

  .aboutHero h1 {
    font-size: clamp(52px,8vw,78px);
  }
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 760px) {

  .aboutPage .container {
    width: min(100% - 28px, 600px);
  }

  .aboutPage .section {
    padding: 75px 0;
  }

  .aboutHero {
    min-height: 680px;
  }

  .aboutHeroOverlay {
    background:
      linear-gradient(
        90deg,
        rgba(5,25,44,.94),
        rgba(8,36,56,.68)
      );
  }

  .aboutHeroContent {
    padding-top: 45px;
  }

  .aboutHero h1 {
    font-size: clamp(48px,14vw,68px);
    letter-spacing: -2.5px;
  }

  .aboutHeroContent > p {
    font-size: 14px;
  }

  .aboutHeroActions {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .aboutHeroScroll {
    display: none;
  }

  .aboutIntroGrid,
  .technologyGrid,
  .aboutPromiseGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .aboutIntroImage {
    min-height: 430px;
  }

  .aboutIntroImage img {
    height: 430px;
  }

  .floatingAboutCard {
    right: 12px;
    bottom: -20px;
  }

  .aboutIntroContent h2,
  .technologyContent h2,
  .aboutPromiseContent h2 {
    font-size: 43px;
  }

  .aboutSectionHeading {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .aboutSectionHeading h2 {
    font-size: 43px;
  }

  .valueGrid {
    grid-template-columns: 1fr;
  }

  .valueCard {
    min-height: 275px;
  }

  .technologyImage {
    min-height: 420px;
  }

  .technologyImage img {
    height: 420px;
  }

  .imageOverlayCard {
    left: 12px;
    bottom: 18px;
  }

  .aboutStats {
    padding: 55px 0;
  }

  .aboutStatsGrid {
    grid-template-columns: repeat(2,1fr);
    row-gap: 35px;
  }

  .aboutStatItem {
    padding: 10px 15px;
  }

  .aboutStatItem:nth-child(2)::after {
    display: none;
  }

  .aboutStatItem strong {
    font-size: 42px;
  }

  .aboutPromiseImage img {
    height: 430px;
  }

  .aboutCTACard {
    padding: 60px 24px;
    border-radius: 27px;
  }

  .aboutCTACard h2 {
    font-size: 43px;
  }

  .ctaActions {
    flex-direction: column;
    gap: 18px;
  }
}

/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 430px) {

  .aboutPage .section {
    padding: 65px 0;
  }

  .aboutHero {
    min-height: 650px;
  }

  .aboutHeroBadge {
    font-size: 7px;
  }

  .aboutHero h1 {
    font-size: 47px;
  }

  .aboutIntroContent h2,
  .technologyContent h2,
  .aboutPromiseContent h2,
  .aboutSectionHeading h2,
  .aboutCTACard h2 {
    font-size: 38px;
    letter-spacing: -1px;
  }

  .floatingAboutCard {
    min-width: auto;
    left: 15px;
    right: 15px;
  }

  .aboutStatItem strong {
    font-size: 37px;
  }

  .aboutStatItem span {
    font-size: 10px;
  }

  .aboutStatItem small {
    font-size: 8px;
  }

  .technologyPoint > span:last-child {
    font-size: 10px;
  }

  .imageOverlayCard {
    right: 12px;
  }

  .imageOverlayCard strong {
    font-size: 11px;
  }

  .aboutCTACard {
    padding: 50px 18px;
  }
}

/* =========================================================
   ACCESSIBILITY
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .aboutPage *,
  .aboutPage *::before,
   .aboutPage *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
  }
}

/* =========================================================
   NOVADENT
   PREMIUM ABOUT PAGE
========================================================= */

.aboutPage {
  overflow: hidden;
  background: #f7fafc;
  color: #0b2545;
}

/* =========================================================
   TYPOGRAPHY
========================================================= */

.aboutPage h1,
.aboutPage h2,
.aboutPage h3,
.aboutPage p {
  margin-top: 0;
}

.aboutPage h2 {
  color: #0b2545;
  font-family: "Playfair Display", serif;
  font-size: clamp(40px, 5vw, 68px);
  line-height: 1.04;
  letter-spacing: -1.8px;
  font-weight: 700;
}

.aboutPage h2 span {
  color: #1f8a8a;
  display: block;
}

.aboutHeroOverlay {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(
      90deg,
      rgba(5, 25, 44, 0.94) 0%,
      rgba(8, 36, 56, 0.78) 43%,
      rgba(8, 36, 56, 0.27) 100%
    );
}

.aboutHeroOverlay::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 75% 35%,
      rgba(85, 184, 176, 0.2),
      transparent 32%
    );
}

@keyframes sparkleFloat {
  0%,
  100% {
    transform: rotate(0) scale(1);
  }

  50% {
    transform: rotate(12deg) scale(1.12);
  }
}

.aboutScrollLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: white;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: .3s ease;
}

@keyframes scrollLine {
  0%,
  100% {
    transform: scaleY(.65);
    transform-origin: top;
  }

  50% {
    transform: scaleY(1);
    transform-origin: top;
  }
}

/* =========================================================
   OUR STORY
========================================================= */

.aboutIntro {
  background:
    radial-gradient(
      circle at 5% 20%,
      rgba(85,184,176,.08),
      transparent 28%
    ),
    #f7fafc;
}

.aboutIntroImage img {
  width: 100%;
  height: 610px;
  display: block;
  object-fit: cover;
  border-radius: 28px;
  box-shadow: 0 30px 70px rgba(11,37,69,.15);
  transition: transform .7s cubic-bezier(.2,.8,.2,1);
}

@keyframes glowFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-18px);
  }
}

@keyframes floatingCard {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-9px);
  }
}

.aboutFloatingIcon {
  width: 45px;
  height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 14px;
  color: white;
  background: linear-gradient(
    135deg,
    #1f8a8a,
    #55b8b0
  );
  box-shadow: 0 10px 25px rgba(31,138,138,.25);
}

.technologyContent h2 {
  max-width: 650px;
  margin: 20px 0;
}

/* Makes "supports better care." stay on same line on large screens */
.technologyContent h2 span {
  display: inline;
}

.technologyPoint {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 54px;
  padding: 8px 12px;
  border: 1px solid rgba(11,37,69,.06);
  border-radius: 14px;
  background: white;
  cursor: pointer;
  transition:
    transform .35s ease,
    box-shadow .35s ease,
    border-color .35s ease;
}

.techNumber {
  color: #9aa9b7;
  font-size: 9px;
  font-weight: 900;
  transition: .3s ease;
}

.technologyPoint:hover .techNumber {
  color: #1f8a8a;
}

.techIcon {
  width: 31px;
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  color: #1f8a8a;
  background: #eaf5f4;
  transition:
    transform .35s ease,
    background .35s ease,
    color .35s ease;
}

.technologyPoint:hover .techIcon {
  color: white;
  background: #1f8a8a;
  transform: scale(1.08) rotate(-5deg);
}

/* =========================================================
   TECHNOLOGY IMAGE
========================================================= */

.technologyImage {
  position: relative;
  min-height: 550px;
  overflow: visible;
  isolation: isolate;
}

.technologyImage::before {
  content: "";
  position: absolute;
  z-index: -1;
  width: 180px;
  height: 180px;
  top: -35px;
  right: -35px;
  border-radius: 50%;
  background: rgba(85,184,176,.16);
  filter: blur(25px);
  animation: techGlow 4s ease-in-out infinite;
}

@keyframes techGlow {
  0%,
  100% {
    transform: translate(0,0);
    opacity: .7;
  }

  50% {
    transform: translate(-15px,15px);
    opacity: 1;
  }
}

.technologyImage img {
  position: relative;
  width: 100%;
  height: 550px;
  display: block;
  object-fit: cover;
  border-radius: 30px;
  box-shadow: 0 30px 70px rgba(11,37,69,.16);
  transition:
    transform .8s cubic-bezier(.2,.8,.2,1),
    filter .5s ease;
}

.technologyImage:hover img {
  transform: scale(1.035);
  filter: saturate(1.08);
}

.technologyImageOverlay {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: 30px;
  background:
    linear-gradient(
      180deg,
      transparent 50%,
      rgba(11,37,69,.55)
    );
  pointer-events: none;
}

.technologyImageOverlay::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 60%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,255,255,.20),
    transparent
  );
  transform: skewX(-18deg);
  transition: 1s ease;
}

.technologyImage:hover .technologyImageOverlay::before {
  left: 140%;
}

.technologyImage::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 30px;
  border: 1px solid rgba(255,255,255,.4);
  pointer-events: none;
}

.imageOverlayCard {
  position: absolute;
  z-index: 5;
  left: -30px;
  bottom: 35px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px 18px;
  border: 1px solid rgba(255,255,255,.75);
  border-radius: 18px;
  background: rgba(255,255,255,.93);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 50px rgba(11,37,69,.18);
  animation: floatingCard 4.5s ease-in-out infinite;
  transition:
    transform .35s ease,
    box-shadow .35s ease;
}

.imageOverlayCard:hover {
  transform: translateY(-8px);
  box-shadow: 0 28px 60px rgba(11,37,69,.24);
}

.overlayCardIcon {
  width: 43px;
  height: 43px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  border-radius: 13px;
  background: linear-gradient(
    135deg,
    #0b2545,
    #1f8a8a
  );
}

.aboutStatItem strong {
  display: block;
  color: #73d3cb;
  font-family: "Playfair Display",serif;
  font-size: 52px;
  line-height: 1;
}

/* =========================================================
   OUR PROMISE
========================================================= */

.aboutPromise {
  background: white;
}

.aboutPromiseImage img {
  width: 100%;
  height: 570px;
  display: block;
  object-fit: cover;
  border-radius: 30px;
  box-shadow: 0 30px 70px rgba(11,37,69,.14);
  transition: transform .65s ease;
}

.aboutCTACard::before,
.aboutCTACard::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
  pointer-events: none;
}

@keyframes pulseIcon {
  0%,
  100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.15);
  }
}

.aboutCTACard h2 {
  max-width: 750px;
  margin: 18px auto;
  color: white;
}

/* =========================================================
   PAGE REVEAL
========================================================= */

.aboutIntroGrid,
.aboutSectionHeading,
.valueGrid,
.technologyGrid,
.aboutStatsGrid,
.aboutPromiseGrid,
.aboutCTACard {
  animation: aboutReveal .9s cubic-bezier(.2,.8,.2,1) both;
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 760px) {

  .aboutPage .container {
    width: min(100% - 28px, 600px);
  }

  .aboutPage .section {
    padding: 75px 0;
  }

  .aboutHero {
    min-height: 680px;
  }

  .aboutHeroOverlay {
    background:
      linear-gradient(
        90deg,
        rgba(5,25,44,.94),
        rgba(8,36,56,.68)
      );
  }

  .aboutHeroContent {
    padding-top: 45px;
  }

  .aboutHero h1 {
    font-size: clamp(48px,14vw,68px);
    letter-spacing: -2.5px;
  }

  .aboutHeroContent > p {
    font-size: 14px;
  }

  .aboutHeroActions {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .aboutHeroScroll {
    display: none;
  }

  /* STORY */

  .aboutIntroGrid,
  .technologyGrid,
  .aboutPromiseGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .aboutIntroImage {
    min-height: 430px;
  }

  .aboutIntroImage img {
    height: 430px;
  }

  .floatingAboutCard {
    right: 12px;
    bottom: -20px;
  }

  .aboutIntroContent h2,
  .technologyContent h2,
  .aboutPromiseContent h2 {
    font-size: 43px;
  }

  /* VALUES */

  .aboutSectionHeading {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .aboutSectionHeading h2 {
    font-size: 43px;
  }

  .valueGrid {
    grid-template-columns: 1fr;
  }

  .valueCard {
    min-height: 275px;
  }

  /* TECHNOLOGY */

  .technologyContent h2 span {
    display: block;
  }

  .technologyImage {
    min-height: 420px;
  }

  .technologyImage img {
    height: 420px;
  }

  .imageOverlayCard {
    left: 12px;
    bottom: 18px;
  }

  /* STATS */

  .aboutStats {
    padding: 55px 0;
  }

  .aboutStatsGrid {
    grid-template-columns: repeat(2,1fr);
    row-gap: 35px;
  }

  .aboutStatItem {
    padding: 10px 15px;
  }

  .aboutStatItem:nth-child(2)::after {
    display: none;
  }

  .aboutStatItem strong {
    font-size: 42px;
  }

  /* PROMISE */

  .aboutPromiseImage img {
    height: 430px;
  }

  /* CTA */

  .aboutCTACard {
    padding: 60px 24px;
    border-radius: 27px;
  }

  .aboutCTACard h2 {
    font-size: 43px;
  }

  .ctaActions {
    flex-direction: column;
    gap: 18px;
  }

}

