}

@keyframes servicesFloatGlow {
  0%,100% {
    transform: translate3d(0,0,0);
  }
  50% {
    transform: translate3d(15px,-20px,0);
  }
}

/* HERO TRUST */

.servicesHeroTrust {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 35px;
}

.servicesHeroTrust div {
  display: flex;
