}

.processSmall {
  display: block;
  margin-bottom: 8px;
  color: #1f8a8a;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 1.8px;
}

/* FAQ */

.servicesFAQ {
  background:
    radial-gradient(
      circle at 80% 20%,
      rgba(85,184,176,.09),
      transparent 30%
    ),
