  line-height: 1.85;
}

.servicesFAQList {
  border-top: 1px solid rgba(11,37,69,.09);
}

.serviceFAQItem {
  border-bottom: 1px solid rgba(11,37,69,.09);
}

.serviceFAQItem button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  padding: 24px 0;
  border: 0;
  outline: none;
  cursor: pointer;
  text-align: left;
  color: #0b2545;
  background: transparent;
  font-family: inherit;
}

.serviceFAQItem button > span {
  display: flex;
  align-items: center;
  gap: 17px;
  font-size: 14px;
  font-weight: 800;
}

.serviceFAQItem button small {
  color: #1f8a8a;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 1px;
}

.serviceFAQItem button > div {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(11,37,69,.1);
  border-radius: 50%;
  color: #1f8a8a;
  background: white;
  transition: .35s ease;
}

.serviceFAQItem.isOpen button > div {
