.servicesCTACard {
  transition: transform .5s ease;
}

.servicesCTACard:hover {
  transform: translateY(-5px);
}

.servicesCTACard::after {
  content: "";
  position: absolute;
  width: 1px;
  height: 100%;
  left: 50%;
  top: 0;
  background: linear-gradient(
    transparent,
    rgba(255,255,255,.08),
    transparent
  );
