/* =========================================================
   SERVICES - IMAGE POLISH
========================================================= */

.premiumServiceCard {
  overflow: hidden;
  transform: translateY(0);
  transition:
    transform .55s cubic-bezier(.2,.8,.2,1),
    box-shadow .55s ease,
    border-color .4s ease;
}

.premiumServiceCard:hover {
  transform: translateY(-10px);
  box-shadow:
    0 28px 65px rgba(11, 37, 69, .15);
}

.premiumServiceImage {
  position: relative;
  height: 355px;
  overflow: hidden;
  background: #dfe8ed;
}

.premiumServiceImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  transition:
    transform 1s cubic-bezier(.2,.8,.2,1),
    filter .7s ease;
}

.premiumServiceCard:hover .premiumServiceImage img {
  transform: scale(1.08);
  filter: saturate(1.08) contrast(1.02);
}

.premiumServiceImageOverlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      180deg,
      rgba(11,37,69,.02) 20%,
      rgba(11,37,69,.12) 48%,
      rgba(11,37,69,.82) 100%
    );
  pointer-events: none;
}

.premiumServiceImage::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      115deg,
      transparent 25%,
      rgba(255,255,255,.18) 48%,
      transparent 62%
    );
  transform: translateX(-120%);
  transition: transform .9s ease;
  pointer-events: none;
}

.premiumServiceCard:hover .premiumServiceImage::after {
  transform: translateX(120%);
}

.premiumServiceNumber {
  position: absolute;
  z-index: 4;
  top: 22px;
  left: 22px;
  color: white;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 1.5px;
}

.premiumServiceIcon {
  position: absolute;
  z-index: 4;
  top: 22px;
  right: 22px;

  width: 56px;
  height: 56px;

  display: flex;
  align-items: center;
  justify-content: center;

  color: #0b2545;
  background: rgba(255,255,255,.94);
  border-radius: 18px;

  box-shadow: 0 12px 28px rgba(0,0,0,.14);

  transition:
    transform .5s cubic-bezier(.2,.8,.2,1),
    background .35s ease,
    color .35s ease;
}

.premiumServiceCard:hover .premiumServiceIcon {
  transform: rotate(-8deg) scale(1.08);
  color: white;
  background: #1f8a8a;
}

.premiumServiceImageBottom {
  position: absolute;
  z-index: 4;
  left: 24px;
  right: 24px;
  bottom: 21px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  color: white;
}

.premiumServiceImageBottom span {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 2px;
}

.premiumServiceImageBottom svg {
  transition: transform .4s ease;
}

