  position: relative;
  padding: 28px 29px 25px;
  background: white;
}

.premiumServiceTitleRow {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
}

.premiumServiceTitleRow h3 {
  margin: 0;
  color: #0b2545;
  font-family: "Playfair Display", serif;
  font-size: 29px;
  line-height: 1.05;
  transition: color .3s ease;
}

.premiumServiceCard:hover .premiumServiceTitleRow h3 {
  color: #1f8a8a;
}

.premiumServiceContent > p {
  margin: 17px 0 21px;
