}

.ndtCardCategory {
  position: absolute;
  z-index: 4;
  top: 18px;
  right: 18px;
  padding: 9px 13px;
  border: 1px solid rgba(255,255,255,.3);
  border-radius: 999px;
  background: rgba(255,255,255,.9);
  color: #183b56;
  backdrop-filter: blur(12px);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .13em;
  transition: .35s ease;
}

.ndtCard:hover .ndtCardCategory {
  background: #1f8a8a;
  color: white;
  transform: translateY(-3px);
}

.ndtCardDuration {
  position: absolute;
  z-index: 4;
  bottom: 20px;
  left: 20px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border-radius: 999px;
  background: rgba(11,37,69,.45);
  border: 1px solid rgba(255,255,255,.18);
  color: white;
  backdrop-filter: blur(10px);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.ndtCardDuration svg {
  color: #69d3cd;
}

.ndtImageBottom {
  position: absolute;
  z-index: 4;
  right: 20px;
  bottom: 20px;
  left: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 15px;
}

.ndtImageBottom strong {
  color: white;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 25px;
  font-weight: 600;
}

.ndtImageBottom span {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.3);
  border-radius: 50%;
  background: rgba(255,255,255,.14);
  color: white;
  backdrop-filter: blur(10px);
  transition: .4s ease;
}

.ndtCard:hover .ndtImageBottom span {
  transform: rotate(45deg);
  background: #1f8a8a;
  border-color: #1f8a8a;
}

/* BODY */

.ndtCardBody {
  padding: 26px 27px 23px;
}

.ndtCardTitle {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;
}

.ndtCardTitle small {
  display: block;
  margin-bottom: 8px;
  color: #8ca0b1;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .2em;
}

.ndtCardTitle h3 {
  margin: 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 29px;
  line-height: 1.05;
  transition: .3s ease;
}

.ndtCard:hover .ndtCardTitle h3 {
  color: #1f8a8a;
}

.ndtCardIcon {
  display: grid;
  width: 49px;
  height: 49px;
  flex: 0 0 49px;
  place-items: center;
  border-radius: 15px;
  background: #eaf5f4;
  color: #1f8a8a;
  transition: .4s ease;
}

.ndtCard:hover .ndtCardIcon {
  color: white;
  background: #1f8a8a;
  transform: rotate(-7deg);
}

.ndtCardBody > p {
  min-height: 48px;
  margin: 15px 0 0;
  color: #687f93;
  font-size: 11px;
  line-height: 1.75;
}

.ndtTags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 20px;
}

.ndtTags span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 9px;
  border-radius: 999px;
  background: #f0f8f7;
  color: #46667d;
  font-size: 7.5px;
  font-weight: 800;
  transition: .3s ease;
}

.ndtTags svg {
  color: #1f8a8a;
}

.ndtCard:hover .ndtTags span {
  transform: translateY(-2px);
}

.ndtCardLink {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 21px;
  padding-top: 16px;
  border-top: 1px solid rgba(11,37,69,.08);
  color: #0b2545;
  font-size: 9px;
  font-weight: 900;
  transition: .3s ease;
}

.ndtCardLink:hover {
  color: #1f8a8a;
}

.ndtCardLink svg {
  transition: .3s ease;
}

.ndtCardLink:hover svg {
  transform: translate(4px,-4px);
}

/* =========================================================
   PROCESS
========================================================= */

.ndtProcess {
  padding: 110px 0;
  background: white;
}

.ndtSteps {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: 18px;
}

.ndtStep {
  position: relative;
  min-height: 245px;
  overflow: hidden;
  padding: 25px;
  border: 1px solid rgba(11,37,69,.08);
  border-radius: 20px;
  background: #f8fbfc;
  transition: .4s ease;
}

.ndtStep:hover {
  transform: translateY(-7px);
  background: #0b2545;
  color: white;
  box-shadow: 0 25px 55px rgba(11,37,69,.15);
}

.ndtStepTop {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.ndtStepTop > span {
  color: #91a3b2;
  font-size: 10px;
  font-weight: 900;
}

.ndtStepTop > div {
  display: grid;
  width: 47px;
  height: 47px;
  place-items: center;
  border-radius: 14px;
  background: #eaf5f4;
  color: #1f8a8a;
  transition: .4s ease;
}

.ndtStep:hover .ndtStepTop > div {
  background: #1f8a8a;
  color: white;
}

.ndtStep h3 {
  margin: 32px 0 10px;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 27px;
}

.ndtStep:hover h3 {
  color: white;
}

.ndtStep p {
  max-width: 280px;
  color: #718596;
  font-size: 10px;
  line-height: 1.75;
}

.ndtStep:hover p {
  color: rgba(255,255,255,.7);
}

.ndtStepArrow {
  position: absolute;
  right: 23px;
  bottom: 23px;
  color: #1f8a8a;
  transition: .35s ease;
}

.ndtStep:hover .ndtStepArrow {
  color: white;
  transform: translate(4px,-4px);
}

/* =========================================================
   FAQ
========================================================= */

.ndtFAQ {
  padding: 110px 0;
  background: #f5f9fa;
}

.ndtFAQGrid {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: 100px;
}

.ndtFAQIntro p {
  max-width: 430px;
  margin: 25px 0;
  color: #6d8192;
  font-size: 11px;
  line-height: 1.8;
}

.ndtOutlineButton {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border: 1px solid rgba(11,37,69,.16);
  border-radius: 999px;
  color: #0b2545;
  font-size: 9px;
  font-weight: 900;
  transition: .3s ease;
}

.ndtOutlineButton:hover {
  color: white;
  background: #0b2545;
  transform: translateY(-2px);
}

.ndtFAQList {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ndtFAQItem {
  overflow: hidden;
  border: 1px solid rgba(11,37,69,.08);
  border-radius: 15px;
  background: white;
}

.ndtFAQItem button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 19px 21px;
  border: 0;
  background: transparent;
  color: #0b2545;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  font-size: 10px;
  font-weight: 800;
}

.ndtFAQItem button svg {
  flex: 0 0 auto;
  color: #1f8a8a;
  transition: .35s ease;
}

.ndtFAQItem.open button svg {
  transform: rotate(180deg);
}

.ndtFAQAnswer {
  display: grid;
  grid-template-rows: 0fr;
  transition: .4s ease;
}

.ndtFAQAnswer p {
  overflow: hidden;
  margin: 0;
  padding: 0 21px;
  color: #6c8192;
  font-size: 10px;
  line-height: 1.8;
}

.ndtFAQItem.open .ndtFAQAnswer {
  grid-template-rows: 1fr;
}

.ndtFAQItem.open .ndtFAQAnswer p {
  padding-bottom: 19px;
}

/* =========================================================
   CTA
========================================================= */

.ndtCTA {
  padding: 110px 0;
  background: #0b2545;
}

.ndtCTACard {
  position: relative;
  overflow: hidden;
  max-width: 850px;
  margin: auto;
  text-align: center;
}

.ndtCTACard::before,
.ndtCTACard::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.ndtCTACard::before {
  width: 300px;
  height: 300px;
  left: -160px;
  top: -160px;
  background: rgba(31,138,138,.16);
}

.ndtCTACard::after {
  width: 250px;
  height: 250px;
  right: -140px;
  bottom: -150px;
  background: rgba(85,184,176,.1);
}

.ndtCTABadge {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 25px;
  padding: 8px 12px;
  border: 1px solid rgba(255,255,255,.13);
  border-radius: 999px;
  color: #b8dcda;
  background: rgba(255,255,255,.06);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .13em;
}

.ndtCTACard h2 {
  position: relative;
  z-index: 2;
  color: white;
}

.ndtCTACard > p {
  position: relative;
  z-index: 2;
  max-width: 560px;
  margin: 23px auto;
  color: rgba(255,255,255,.67);
  font-size: 12px;
  line-height: 1.8;
}

.ndtCTAButtons {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 22px;
  margin-top: 30px;
}

.ndtCTASecondary {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: white;
  font-size: 10px;
  font-weight: 800;
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 900px) {

  .ndtIntroGrid,
  .ndtFAQGrid {
    gap: 55px;
  }

  .ndtCards {
    gap: 20px;
  }

  .ndtCardImage {
    height: 280px;
  }

}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 700px) {

  .ndtContainer {
    width: min(100% - 32px, 600px);
  }

  .ndtHero {
    min-height: 680px;
  }

  .ndtHeroContent {
    padding-top: 95px;
  }

  .ndtHero h1 {
    font-size: 49px;
    letter-spacing: -1px;
  }

  .ndtHero p {
    font-size: 11px;
  }

  .ndtHeroButtons {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .ndtTrust {
    flex-direction: column;
    gap: 10px;
  }

  .ndtIntro {
    padding: 75px 0;
  }

  .ndtIntroGrid,
  .ndtFAQGrid {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .ndtIntro h2,
  .ndtHeading h2,
  .ndtFAQIntro h2,
  .ndtCTACard h2 {
    font-size: 42px;
  }

  .ndtHeading {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 35px;
  }

  .ndtCards {
    grid-template-columns: 1fr;
  }

  .ndtCardImage {
    height: 285px;
  }

  .ndtProcess,
  .ndtFAQ,
  .ndtCTA {
    padding: 75px 0;
  }

  .ndtSteps {
    grid-template-columns: 1fr;
  }

  .ndtStep {
    min-height: 220px;
  }

  .ndtCTAButtons {
    flex-direction: column;
  }

}

/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 430px) {

  .ndtHero h1 {
    font-size: 43px;
  }

  .ndtIntro h2,
  .ndtHeading h2,
  .ndtFAQIntro h2,
  .ndtCTACard h2 {
    font-size: 37px;
  }

  .ndtCardImage {
    height: 255px;
  }

  .ndtCardBody {
    padding: 22px 19px;
  }

  .ndtCardTitle h3 {
    font-size: 25px;
  }

  .ndtCardIcon {
    width: 43px;
    height: 43px;
    flex-basis: 43px;
  }

}

/* STEP 3 - PREMIUM TREATMENT CARD HOVER */

.ndtCard {
  position: relative;
  isolation: isolate;
}

.ndtCard::before {
  content: "";
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: 25px;
  background: linear-gradient(
    135deg,
    rgba(31, 138, 138, 0.35),
    transparent 35%,
    rgba(85, 184, 176, 0.25)
  );
  opacity: 0;
  transition: opacity 0.45s ease;
}

.ndtCard:hover::before {
  opacity: 1;
}

.ndtCard:hover {
  transform: translateY(-10px);
  box-shadow:
    0 25px 60px rgba(11, 37, 69, 0.14),
    0 0 0 1px rgba(31, 138, 138, 0.08);
}

.ndtCardTitle h3 {
  transition:
    color 0.35s ease,
    transform 0.35s ease;
}

.ndtCard:hover .ndtCardTitle h3 {
  color: #1f8a8a;
  transform: translateX(4px);
}

.ndtCardBody > p {
  transition: color 0.35s ease;
}

.ndtCard:hover .ndtCardBody > p {
  color: #49677d;
}

.ndtCardIcon {
  transition:
    transform 0.4s ease,
    background 0.4s ease,
    color 0.4s ease;
}

.ndtCard:hover .ndtCardIcon {
  transform: rotate(-8deg) scale(1.08);
  background: #1f8a8a;
  color: white;
}

/* =========================================================
   STEP 4 - PREMIUM IMAGE HOVER
========================================================= */

.ndtCardImage {
  position: relative;
  overflow: hidden;
}

.ndtCardImage img {
  transition:
    transform 0.8s cubic-bezier(.2,.7,.2,1),
    filter 0.6s ease;
}

.ndtCard:hover .ndtCardImage img {
  transform: scale(1.08);
  filter: brightness(1.05) saturate(1.08);
}

/* Light sweep */
.ndtCardImage::after {
  content: "";
  position: absolute;
  top: 0;
  left: -130%;
  z-index: 6;
  width: 65%;
  height: 100%;
  pointer-events: none;

  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(255,255,255,0.05) 35%,
    rgba(255,255,255,0.30) 50%,
    rgba(255,255,255,0.05) 65%,
    transparent 100%
  );

  transform: skewX(-18deg);
}

.ndtCard:hover .ndtCardImage::after {
  left: 150%;
  transition: left 0.9s ease;
}

/* Image overlay becomes slightly richer */
.ndtCard:hover .ndtImageOverlay {
  background:
    linear-gradient(
      180deg,
      rgba(5,25,45,.04) 20%,
      rgba(5,25,45,.12) 45%,
      rgba(5,25,45,.88) 100%
    );
}

/* =========================================================
   STEP 5 - PREMIUM TREATMENT TAGS
========================================================= */

.ndtCardTags {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.ndtCardTag {
  position: relative;
  overflow: hidden;

  display: inline-flex;
  align-items: center;
  gap: 6px;

  padding: 9px 13px;

  border: 1px solid rgba(31, 138, 138, 0.08);
  border-radius: 999px;

  background: #eef8f7;
  color: #31566d;

  font-size: 11px;
  font-weight: 700;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.ndtCardTag::before {
  content: "";
  position: absolute;
  inset: 0;

  background: linear-gradient(
    100deg,
    transparent,
    rgba(255,255,255,.7),
    transparent
  );

  transform: translateX(-120%);
  transition: transform 0.55s ease;
}

.ndtCardTag:hover {
  transform: translateY(-3px);
  background: #1f8a8a;
  color: white;
  border-color: #1f8a8a;

  box-shadow:
    0 8px 20px rgba(31,138,138,.18);
}

.ndtCardTag:hover::before {
  transform: translateX(120%);
}

.ndtCardTag svg {
  color: #1f8a8a;
  transition: color .3s ease, transform .3s ease;
}

.ndtCardTag:hover svg {
  color: white;
  transform: scale(1.15);
}

/* =========================================
   FAQ PREMIUM HOVER EFFECT
========================================= */

.treatmentFaqItem {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.treatmentFaqItem:hover {
  transform: translateX(6px);
  border-color: rgba(31, 138, 138, 0.25);
  box-shadow: 0 14px 35px rgba(11, 37, 69, 0.08);
}

.treatmentFaqItem button {
  transition:
    color 0.3s ease,
    padding 0.3s ease;
}

.treatmentFaqItem:hover button {
  color: #1f8a8a;
}

.treatmentFaqItem svg {
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.treatmentFaqItem:hover svg {
  color: #1f8a8a;
  transform: scale(1.15);
}

/* =========================================
   STEP 7 - PREMIUM FAQ ANIMATION
========================================= */

.treatmentFaqItem {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.treatmentFaqItem::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 70%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(31, 138, 138, 0.06),
    transparent
  );
  transition: left 0.7s ease;
  pointer-events: none;
}

.treatmentFaqItem:hover::before {
  left: 130%;
}

.treatmentFaqItem:hover {
  transform: translateY(-3px);
  border-color: rgba(31, 138, 138, 0.2);
  box-shadow: 0 15px 35px rgba(11, 37, 69, 0.08);
}

.treatmentFaqItem button {
  position: relative;
  z-index: 2;
}

.treatmentFaqItem button svg {
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.treatmentFaqItem:hover button svg {
  color: #1f8a8a;
  transform: scale(1.15);
}

/* =========================================
   STEP 8 - PREMIUM CTA EFFECT
========================================= */

.ndtCTACard {
  animation: ndtCtaFloat 5s ease-in-out infinite;
}

@keyframes ndtCtaFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-5px);
  }
}

.ndtCTACard::before {
  animation: ndtCtaGlowOne 6s ease-in-out infinite alternate;
}

.ndtCTACard::after {
  animation: ndtCtaGlowTwo 7s ease-in-out infinite alternate;
}

@keyframes ndtCtaGlowOne {
  from {
    transform: translate(0, 0) scale(1);
    opacity: .7;
  }

  to {
    transform: translate(45px, 35px) scale(1.25);
    opacity: 1;
  }
}

@keyframes ndtCtaGlowTwo {
  from {
    transform: translate(0, 0) scale(1);
    opacity: .5;
  }

  to {
    transform: translate(-35px, -30px) scale(1.2);
    opacity: .9;
  }
}

.ndtCTA .ndtLightButton {
  transition:
    transform .35s ease,
    box-shadow .35s ease;
}

.ndtCTA .ndtLightButton:hover {
  transform: translateY(-4px) scale(1.03);
  box-shadow:
    0 15px 35px rgba(0, 0, 0, .25),
    0 0 25px rgba(85, 184, 176, .15);
}

.ndtCTASecondary {
  transition:
    transform .3s ease,
    color .3s ease;
}

.ndtCTASecondary:hover {
  transform: translateX(5px);
  color: #55b8b0;
}

/* =========================================
   STEP 9 — PREMIUM 3D TREATMENT CARD EFFECT
========================================= */

.ndtCard {
  transform-style: preserve-3d;
  transition:
    transform 0.5s cubic-bezier(.2,.7,.2,1),
    box-shadow 0.5s ease;
}

.ndtCard:hover {
  transform: translateY(-12px) perspective(900px) rotateX(1deg);
  box-shadow:
    0 30px 65px rgba(11, 37, 69, 0.16),
    0 10px 25px rgba(31, 138, 138, 0.08);
}

/* Card content slightly comes forward */
.ndtCardBody {
  position: relative;
  z-index: 2;
  transition: transform 0.45s ease;
}

.ndtCard:hover .ndtCardBody {
  transform: translateZ(8px);
}

/* Treatment number animation */
.ndtCardNumber {
  transition:
    transform 0.4s ease,
    background 0.4s ease;
}

.ndtCard:hover .ndtCardNumber {
  transform: translateY(-4px) scale(1.05);
}

/* Duration badge */
.ndtCardDuration {
  transition:
    transform 0.4s ease,
    background 0.4s ease;
}

.ndtCard:hover .ndtCardDuration {
  transform: translateY(-4px);
  background: rgba(31, 138, 138, 0.95);
}

/* Tags gently move */
.ndtTags span {
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease;
}

.ndtCard:hover .ndtTags span {
  background: #eaf5f4;
  color: #1f8a8a;
}

.ndtCard:hover .ndtTags span:nth-child(1) {
  transform: translateY(-2px);
}

.ndtCard:hover .ndtTags span:nth-child(2) {
  transform: translateY(-3px);
}

.ndtCard:hover .ndtTags span:nth-child(3) {
  transform: translateY(-2px);
}

/* Main arrow */
.ndtImageArrow {
  transition:
    transform 0.4s ease,
    background 0.4s ease;
}

.ndtCard:hover .ndtImageArrow {
  transform: rotate(45deg) scale(1.08);
  background: #55b8b0;
}

/* Mobile: keep interaction smooth */
@media (max-width: 700px) {
  .ndtCard:hover {
    transform: translateY(-6px);
  }

  .ndtCard:hover .ndtCardBody {
    transform: none;
  }
}

/* =========================================
   STEP 10 — TREATMENT SCROLL REVEAL
========================================= */

.ndtCards .ndtCard {
  animation: ndtTreatmentReveal 0.8s ease both;
}

.ndtCards .ndtCard:nth-child(1) {
  animation-delay: 0.05s;
}

.ndtCards .ndtCard:nth-child(2) {
  animation-delay: 0.15s;
}

.ndtCards .ndtCard:nth-child(3) {
  animation-delay: 0.25s;
}

.ndtCards .ndtCard:nth-child(4) {
  animation-delay: 0.35s;
}

.ndtCards .ndtCard:nth-child(5) {
  animation-delay: 0.45s;
}

.ndtCards .ndtCard:nth-child(6) {
  animation-delay: 0.55s;
}

@keyframes ndtTreatmentReveal {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Respect users who prefer reduced motion */
@media (prefers-reduced-motion: reduce) {
  .ndtCards .ndtCard {
    animation: none;
  }
}

/* =========================================
   STEP 11 — PREMIUM IMAGE INTERACTION
========================================= */

.ndtCardImage {
  position: relative;
  overflow: hidden;
}

.ndtCardImage img {
  transition:
    transform 0.9s cubic-bezier(.2,.7,.2,1),
    filter 0.6s ease;
}

.ndtCard:hover .ndtCardImage img {
  transform: scale(1.1);
  filter: brightness(1.06) saturate(1.08);
}

/* Overlay becomes slightly richer */
.ndtCard:hover .ndtImageOverlay {
  background:
    linear-gradient(
      180deg,
      rgba(5, 25, 45, 0.02) 15%,
      rgba(5, 25, 45, 0.15) 45%,
      rgba(5, 25, 45, 0.82) 100%
    );
}

/* Arrow button */
.ndtImageArrow {
  position: relative;
  overflow: hidden;
}

.ndtImageArrow::before {
  content: "";
  position: absolute;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  transition:
    width 0.45s ease,
    height 0.45s ease;
}

.ndtCard:hover .ndtImageArrow::before {
  width: 90px;
  height: 90px;
}

.ndtImageArrow svg {
  position: relative;
  z-index: 2;
  transition: transform 0.4s ease;
}

.ndtCard:hover .ndtImageArrow svg {
  transform: translate(2px, -2px);
}

/* =========================================
   STEP 12 — PREMIUM TREATMENT TAGS
========================================= */

.ndtTags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ndtTags span {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease,
    box-shadow 0.3s ease;
}

.ndtTags span::before {
  content: "";
  position: absolute;
  left: -120%;
  top: 0;
  width: 80%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.7),
    transparent
  );
  transform: skewX(-20deg);
}

.ndtCard:hover .ndtTags span::before {
  left: 140%;
  transition: left 0.7s ease;
}

.ndtCard:hover .ndtTags span {
  background: #eaf5f4;
  color: #1f8a8a;
  box-shadow: 0 5px 15px rgba(31, 138, 138, 0.08);
}

.ndtTags span svg {
  transition: transform 0.3s ease;
}

.ndtCard:hover .ndtTags span svg {
  transform: scale(1.15);
}

/* Staggered tag movement */
.ndtCard:hover .ndtTags span:nth-child(1) {
  transform: translateY(-2px);
}

.ndtCard:hover .ndtTags span:nth-child(2) {
  transform: translateY(-4px);
}

/* =========================================
   STEP 13 — PREMIUM TREATMENT LINK
========================================= */

.ndtCardLink {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  overflow: hidden;
  transition:
    color 0.35s ease,
    gap 0.35s ease,
    transform 0.35s ease;
}

.ndtCardLink::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -3px;
  width: 100%;
  height: 1.5px;
  background: #1f8a8a;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s ease;
}

.ndtCardLink:hover {
  color: #1f8a8a;
  gap: 13px;
  transform: translateX(2px);
}

.ndtCardLink:hover::after {
  transform: scaleX(1);
}

.ndtCardLink svg {
  transition:
    transform 0.35s ease,
    opacity 0.35s ease;
}

.ndtCardLink:hover svg {
  transform: translate(3px, -3px);
  opacity: 1;
}

/* =========================================
   STEP 14 — PREMIUM PROCESS STEPS
========================================= */

.ndtStep {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.45s cubic-bezier(.2,.7,.2,1),
    box-shadow 0.45s ease,
    border-color 0.4s ease;
}

.ndtStep::before {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(
    90deg,
    #1f8a8a,
    #55b8b0
  );
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.45s ease;
}

.ndtStep:hover {
  transform: translateY(-8px);
  box-shadow:
    0 22px 45px rgba(11, 37, 69, 0.11),
    0 5px 18px rgba(31, 138, 138, 0.07);
  border-color: rgba(31, 138, 138, 0.22);
}

.ndtStep:hover::before {
  transform: scaleX(1);
}

/* Number */
.ndtStepTop > span {
  transition:
    color 0.35s ease,
    transform 0.35s ease;
}

.ndtStep:hover .ndtStepTop > span {
  color: #1f8a8a;
  transform: translateX(3px);
}

/* Icon box */
.ndtStepTop > div {
  transition:
    transform 0.4s ease,
    background 0.4s ease,
    color 0.4s ease;
}

.ndtStep:hover .ndtStepTop > div {
  transform: rotate(-8deg) scale(1.08);
  background: #1f8a8a;
  color: white;
}

/* Heading */
.ndtStep h3 {
  transition:
    color 0.35s ease,
    transform 0.35s ease;
}

.ndtStep:hover h3 {
  color: #1f8a8a;
  transform: translateX(3px);
}

/* Arrow */
.ndtStepArrow {
  transition:
    transform 0.4s ease,
    color 0.35s ease;
}

.ndtStep:hover .ndtStepArrow {
  color: #1f8a8a;
  transform: translate(5px, -5px);
}

/* =========================================
   STEP 15 — PREMIUM FAQ ACCORDION
========================================= */

.ndtFAQItem {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease,
    border-color 0.4s ease,
    background 0.4s ease;
}

.ndtFAQItem::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(
    180deg,
    #1f8a8a,
    #55b8b0
  );
  transform: scaleY(0);
  transform-origin: top;
  transition: transform 0.4s ease;
}

.ndtFAQItem:hover {
  transform: translateX(5px);
  box-shadow:
    0 14px 32px rgba(11, 37, 69, 0.08);
}

.ndtFAQItem:hover::before,
.ndtFAQItem.open::before {
  transform: scaleY(1);
}

/* Question button */
.ndtFAQItem button {
  transition:
    color 0.3s ease,
    padding-left 0.35s ease;
}

.ndtFAQItem:hover button,
.ndtFAQItem.open button {
  color: #1f8a8a;
}

/* Chevron */
.ndtFAQItem button svg {
  transition:
    transform 0.4s ease,
    color 0.3s ease;
}

.ndtFAQItem.open button svg {
  transform: rotate(180deg);
  color: #1f8a8a;
}

/* Answer */
.ndtFAQAnswer {
  transition:
    max-height 0.45s ease,
    opacity 0.35s ease;
}

/* Open FAQ gets subtle background */
.ndtFAQItem.open {
  background: #f8fcfc;
  border-color: rgba(31, 138, 138, 0.18);
  box-shadow:
    0 15px 35px rgba(11, 37, 69, 0.07);
}

/* Mobile */
@media (max-width: 700px) {
  .ndtFAQItem:hover {
    transform: translateX(2px);
  }
}

/* =========================================
   STEP 16 — SCROLL PROGRESS BAR
========================================= */

.ndtPage::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 3px;
  z-index: 9999;
  pointer-events: none;
  background: linear-gradient(
    90deg,
    #1f8a8a,
    #55b8b0,
    #8edbd4
  );
  transform: scaleX(0);
  transform-origin: left;
  animation: ndtScrollProgress linear;
  animation-timeline: scroll(root);
}

@keyframes ndtScrollProgress {
  to {
    transform: scaleX(1);
  }
}

/* Keep it subtle on mobile */
@media (max-width: 700px) {
  .ndtPage::before {
    height: 2px;
  }
}

/* =========================================
   STEP 17 — PREMIUM HERO BUTTONS
========================================= */

.ndtHeroButtons .ndtLightButton {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.ndtHeroButtons .ndtLightButton::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 70%;
  height: 100%;
  background: linear-gradient(
    100deg,
    transparent,
    rgba(255, 255, 255, 0.45),
    transparent
  );
  transform: skewX(-20deg);
  transition: left 0.65s ease;
}

.ndtHeroButtons .ndtLightButton:hover {
  transform: translateY(-4px);
  box-shadow:
    0 16px 35px rgba(0, 0, 0, 0.18),
    0 0 25px rgba(85, 184, 176, 0.18);
}

.ndtHeroButtons .ndtLightButton:hover::before {
  left: 150%;
}

.ndtHeroButtons .ndtLightButton svg {
  transition: transform 0.35s ease;
}

.ndtHeroButtons .ndtLightButton:hover svg {
  transform: translate(3px, -3px);
}

/* Explore Treatments link */
.ndtHeroLink {
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.ndtHeroLink:hover {
  transform: translateX(6px);
  color: #55b8b0;
}

.ndtHeroLink svg {
  transition: transform 0.35s ease;
}

.ndtHeroLink:hover svg {
  transform: translateX(4px);
}

/* =========================================
   STEP 18 — CINEMATIC HERO IMAGE
========================================= */

.ndtHeroImage {
  animation: ndtHeroZoom 12s ease-in-out infinite alternate;
  transform-origin: center center;
}

@keyframes ndtHeroZoom {
  0% {
    transform: scale(1);
  }

  100% {
    transform: scale(1.08);
  }
}

/* Hero content stays stable */
.ndtHeroContent {
  position: relative;
  z-index: 3;
}

/* Keep animation subtle on mobile */
@media (max-width: 700px) {
  .ndtHeroImage {
    animation-duration: 14s;
  }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  .ndtHeroImage {
    animation: none;
  }
}

/* =========================================
   STEP 19 — HERO TRUST BADGES
========================================= */

.ndtTrust {
  animation: ndtTrustFade 0.9s ease both;
  animation-delay: 0.5s;
}

.ndtTrust span {
  transition:
    transform 0.35s ease,
    color 0.35s ease,
    background 0.35s ease;
}

.ndtTrust span:hover {
  transform: translateY(-4px);
  color: #55b8b0;
}

.ndtTrust span svg {
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.ndtTrust span:hover svg {
  transform: scale(1.15);
  color: #55b8b0;
}

@keyframes ndtTrustFade {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mobile */
@media (max-width: 700px) {
  .ndtTrust {
    animation-delay: 0.3s;
  }

  .ndtTrust span:hover {
    transform: translateY(-2px);
  }
}

/* =========================================
   STEP 20 — HERO TEXT REVEAL
========================================= */

.ndtHeroContent .ndtOverline {
  animation: ndtTextReveal 0.8s ease both;
  animation-delay: 0.15s;
}

.ndtHeroContent h1 {
  animation: ndtTextReveal 0.9s ease both;
  animation-delay: 0.3s;
}

.ndtHeroContent > p {
  animation: ndtTextReveal 0.9s ease both;
  animation-delay: 0.45s;
}

.ndtHeroButtons {
  animation: ndtTextReveal 0.9s ease both;
  animation-delay: 0.6s;
}

@keyframes ndtTextReveal {
  from {
    opacity: 0;
    transform: translateY(24px);
    filter: blur(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ndtHeroContent .ndtOverline,
  .ndtHeroContent h1,
  .ndtHeroContent > p,
  .ndtHeroButtons {
    animation: none;
  }
}

/* =========================================
   STEP 21 — SECTION HEADING REVEAL
========================================= */

.ndtIntro .ndtOverline,
.ndtTreatments .ndtOverline,
.ndtProcess .ndtOverline,
.ndtFAQ .ndtOverline {
  animation: ndtSectionFade 0.8s ease both;
}

.ndtIntro h2,
.ndtTreatments h2,
.ndtProcess h2,
.ndtFAQ h2 {
  animation: ndtSectionTitle 0.9s ease both;
}

@keyframes ndtSectionFade {
  from {
    opacity: 0;
    transform: translateY(12px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes ndtSectionTitle {
  from {
    opacity: 0;
    transform: translateY(22px);
    filter: blur(3px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ndtIntro .ndtOverline,
  .ndtTreatments .ndtOverline,
  .ndtProcess .ndtOverline,
  .ndtFAQ .ndtOverline,
  .ndtIntro h2,
  .ndtTreatments h2,
  .ndtProcess h2,
  .ndtFAQ h2 {
    animation: none;
  }
}

/* =========================================
   STEP 22 — CARD TITLE + ICON INTERACTION
========================================= */

.ndtCardTitle {
  transition: transform 0.35s ease;
}

.ndtCard:hover .ndtCardTitle {
  transform: translateX(3px);
}

.ndtCardTitle h3 {
  transition:
    color 0.35s ease,
    letter-spacing 0.35s ease;
}

.ndtCard:hover .ndtCardTitle h3 {
  color: #1f8a8a;
  letter-spacing: 0.2px;
}

.ndtCardTitle small {
  transition:
    color 0.35s ease,
    letter-spacing 0.35s ease;
}

.ndtCard:hover .ndtCardTitle small {
  color: #55b8b0;
  letter-spacing: 1.2px;
}

.ndtCardIcon {
  transition:
    transform 0.45s cubic-bezier(.2,.7,.2,1),
    background 0.4s ease,
    color 0.4s ease,
    box-shadow 0.4s ease;
}

.ndtCard:hover .ndtCardIcon {
  transform: rotate(-10deg) scale(1.1);
  background: #1f8a8a;
  color: #ffffff;
  box-shadow: 0 10px 24px rgba(31, 138, 138, 0.2);
}

.ndtCardIcon svg {
  transition: transform 0.4s ease;
}

.ndtCard:hover .ndtCardIcon svg {
  transform: scale(1.08);
}

/* =========================================
   STEP 23 — CARD CONTENT SPACING
========================================= */

.ndtCardBody {
  display: flex;
  flex-direction: column;
}

.ndtCardBody > p {
  margin-top: 14px;
  margin-bottom: 18px;
  line-height: 1.75;
  transition:
    color 0.35s ease,
    transform 0.35s ease;
}

.ndtCard:hover .ndtCardBody > p {
  transform: translateX(2px);
}

.ndtTags {
  margin-top: 2px;
  margin-bottom: 22px;
}

/* Keep the CTA aligned neatly */
.ndtCardLink {
  margin-top: auto;
}

/* Extra breathing space on smaller screens */
@media (max-width: 700px) {
  .ndtCardBody > p {
    margin-top: 12px;
    margin-bottom: 16px;
  }

  .ndtTags {
    margin-bottom: 18px;
  }
}

/* =========================================
   STEP 24 — PREMIUM CARD BORDER GLOW
========================================= */

.ndtCard {
  border: 1px solid rgba(11, 37, 69, 0.08);
  transition:
    transform 0.5s ease,
    box-shadow 0.5s ease,
    border-color 0.45s ease;
}

.ndtCard:hover {
  border-color: rgba(31, 138, 138, 0.28);
  box-shadow:
    0 25px 55px rgba(11, 37, 69, 0.13),
    0 0 0 1px rgba(85, 184, 176, 0.08);
}

/* Smooth glow around image */
.ndtCardImage {
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.ndtCard:hover .ndtCardImage {
  box-shadow:
    inset 0 0 0 1px rgba(85, 184, 176, 0.22);
}

/* =========================================
   STEP 25 — PREMIUM CARD SHINE
========================================= */

.ndtCard {
  position: relative;
  overflow: hidden;
}

.ndtCard::after {
  content: "";
  position: absolute;
  top: 0;
  left: -140%;
  width: 60%;
  height: 100%;
  pointer-events: none;
  z-index: 10;

  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(255, 255, 255, 0.03) 35%,
    rgba(255, 255, 255, 0.22) 50%,
    rgba(255, 255, 255, 0.03) 65%,
    transparent 100%
  );

  transform: skewX(-18deg);
}

.ndtCard:hover::after {
  left: 150%;
  transition: left 0.9s ease;
}

/* =========================================
   STEP 26 — IMAGE CONTENT DEPTH
========================================= */

.ndtCardNumber,
.ndtCardCategory,
.ndtCardDuration,
.ndtImageBottom {
  transition:
    transform 0.45s cubic-bezier(.2,.7,.2,1),
    opacity 0.4s ease;
}

.ndtCard:hover .ndtCardNumber {
  transform: translateY(-5px);
}

.ndtCard:hover .ndtCardCategory {
  transform: translateY(-4px);
}

.ndtCard:hover .ndtCardDuration {
  transform: translateY(-5px);
}

/* Bottom arrow gets a stronger visual focus */
.ndtCard:hover .ndtImageBottom {
  transform: translateY(-3px);
}

/* Slightly deepen image overlay on hover */
.ndtCard:hover .ndtImageOverlay {
  opacity: 0.96;
}

/* =========================================
   STEP 27 — TREATMENT SECTION GLOW
========================================= */

.ndtTreatments {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.ndtTreatments::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  top: 5%;
  right: -180px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.10);
  filter: blur(80px);
  pointer-events: none;
  z-index: -1;
  animation: ndtTreatmentGlow 8s ease-in-out infinite alternate;
}

.ndtTreatments::after {
  content: "";
  position: absolute;
  width: 320px;
  height: 320px;
  bottom: 8%;
  left: -160px;
  border-radius: 50%;
  background: rgba(31, 138, 138, 0.07);
  filter: blur(75px);
  pointer-events: none;
  z-index: -1;
  animation: ndtTreatmentGlowTwo 10s ease-in-out infinite alternate;
}

@keyframes ndtTreatmentGlow {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
    transform: translate(-60px, 45px) scale(1.2);
  }
}

@keyframes ndtTreatmentGlowTwo {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
    transform: translate(45px, -35px) scale(1.15);
  }
}

@media (max-width: 700px) {
  .ndtTreatments::before {
    width: 260px;
    height: 260px;
    right: -130px;
  }

  .ndtTreatments::after {
    width: 220px;
    height: 220px;
    left: -110px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ndtTreatments::before,
  .ndtTreatments::after {
    animation: none;
  }
}

/* =========================================
   STEP 28 — PROCESS SECTION GLOW
========================================= */

.ndtProcess {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.ndtProcess::before {
  content: "";
  position: absolute;
  width: 380px;
  height: 380px;
  top: 10%;
  left: -180px;
  border-radius: 50%;
  background: rgba(31, 138, 138, 0.08);
  filter: blur(85px);
  pointer-events: none;
  z-index: -1;
  animation: ndtProcessGlow 9s ease-in-out infinite alternate;
}

.ndtProcess::after {
  content: "";
  position: absolute;
  width: 300px;
  height: 300px;
  right: -140px;
  bottom: 5%;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.09);
  filter: blur(75px);
  pointer-events: none;
  z-index: -1;
  animation: ndtProcessGlowTwo 11s ease-in-out infinite alternate;
}

@keyframes ndtProcessGlow {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
    transform: translate(55px, 35px) scale(1.18);
  }
}

@keyframes ndtProcessGlowTwo {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
    transform: translate(-45px, -30px) scale(1.15);
  }
}

@media (max-width: 700px) {
  .ndtProcess::before {
    width: 240px;
    height: 240px;
    left: -120px;
  }

  .ndtProcess::after {
    width: 210px;
    height: 210px;
    right: -100px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ndtProcess::before,
  .ndtProcess::after {
    animation: none;
  }
}

/* =========================================
   STEP 29 — FAQ SECTION GLOW
========================================= */

.ndtFAQ {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.ndtFAQ::before {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  top: 0;
  right: -170px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.08);
  filter: blur(80px);
  pointer-events: none;
  z-index: -1;
  animation: ndtFAQGlow 9s ease-in-out infinite alternate;
}

.ndtFAQ::after {
  content: "";
  position: absolute;
  width: 280px;
  height: 280px;
  bottom: 0;
  left: -140px;
  border-radius: 50%;
  background: rgba(31, 138, 138, 0.06);
  filter: blur(70px);
  pointer-events: none;
  z-index: -1;
  animation: ndtFAQGlowTwo 11s ease-in-out infinite alternate;
}

@keyframes ndtFAQGlow {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
    transform: translate(-45px, 40px) scale(1.18);
  }
}

@keyframes ndtFAQGlowTwo {
  from {
    transform: translate(0, 0) scale(1);
  }

  to {
