/* =========================================
   STEP 34 — ANIMATION PERFORMANCE CLEANUP
========================================= */

/* Smooth rendering for animated elements */
.ndtCard,
.ndtStep,
.ndtCTACard,
.ndtHeroImage,
.ndtImageArrow,
.ndtCardIcon,
.ndtFAQItem,
.ndtFAQItem button svg {
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

/* Prevent animation overflow */
.ndtHero,
.ndtTreatments,
.ndtProcess,
.ndtFAQ,
.ndtCTA {
  overflow: hidden;
}

/* Reduce heavy motion on smaller devices */
@media (max-width: 700px) {

  .ndtHeroImage {
    animation-duration: 16s;
  }

  .ndtCTACard {
    animation-duration: 7s;
  }

  .ndtTreatments::before,
  .ndtTreatments::after,
  .ndtProcess::before,
  .ndtProcess::after,
  .ndtFAQ::before,
  .ndtFAQ::after {
    animation-duration: 14s;
  }
}

/* Accessibility + performance */
@media (prefers-reduced-motion: reduce) {

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* =========================================
   STEP 35 — FINAL VISUAL CLEANUP
========================================= */

/* Keep all treatment cards consistent */
.ndtCard,
.ndtStep,
.ndtFAQItem,
.ndtCTACard {
  box-sizing: border-box;
}

/* Prevent text from accidentally overflowing */
.ndtCard h3,
.ndtStep h3,
.ndtFAQItem button span,
.ndtCTACard h2 {
  overflow-wrap: break-word;
}

/* Keep images clean */
.ndtCardImage img,
.ndtHeroImage {
  display: block;
}

/* Prevent links/buttons from causing horizontal overflow */
.ndtHeroButtons,
.ndtCTAButtons,
.ndtTrust,
.ndtTags {
  max-width: 100%;
}

/* Final smooth focus state */
.ndtCardLink:focus-visible,
.ndtHeroLink:focus-visible,
.ndtLightButton:focus-visible,
.ndtOutlineButton:focus-visible,
.ndtCTASecondary:focus-visible,
.ndtFAQItem button:focus-visible {
