}

.galleryItem:hover img {
  transform: scale(1.09);
  filter: brightness(.78) saturate(1.08);
}

/* Dark overlay */
.galleryItem::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      transparent 40%,
      rgba(5,20,35,.72) 100%
    );
  opacity: 0;
  transition: opacity .45s ease;
  pointer-events: none;
}

.galleryItem:hover::after {
  opacity: 1;
}

/* Gallery overlay content */
.galleryOverlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 22px;
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity .45s ease,
    transform .45s ease;
}

.galleryItem:hover .galleryOverlay {
  opacity: 1;
  transform: translateY(0);
}

/* Gallery title */
.galleryOverlay h3 {
  color: #fff;
  margin: 0;
  transition: transform .35s ease;
}

.galleryItem:hover .galleryOverlay h3 {
  transform: translateX(3px);
}

/* Gallery category */
.galleryOverlay span {
  color: #55b8b0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.6px;
  margin-bottom: 6px;
}

/* Open icon */
.galleryOpenIcon {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #0b2545;
  background: rgba(255,255,255,.92);
  transform: scale(.7) rotate(-15deg);
  transition:
    transform .4s cubic-bezier(.2,.7,.2,1),
    background .3s ease,
    color .3s ease;
}

.galleryItem:hover .galleryOpenIcon {
  transform: scale(1) rotate(0);
  background: #55b8b0;
  color: #fff;
}

/* Shine effect */
.galleryItem .galleryShine {
  position: absolute;
  top: 0;
  left: -140%;
  width: 55%;
  height: 100%;
  z-index: 5;
  pointer-events: none;
  background: linear-gradient(
    110deg,
    transparent 20%,
    rgba(255,255,255,.22) 50%,
    transparent 80%
  );
  transform: skewX(-18deg);
}

.galleryItem:hover .galleryShine {
  left: 150%;
  transition: left .9s ease;
}

/* Gallery entrance */
.galleryGrid .galleryItem {
  animation: galleryReveal .75s ease both;
}

.galleryGrid .galleryItem:nth-child(1) {
  animation-delay: .05s;
}

.galleryGrid .galleryItem:nth-child(2) {
  animation-delay: .12s;
}

.galleryGrid .galleryItem:nth-child(3) {
  animation-delay: .19s;
}

.galleryGrid .galleryItem:nth-child(4) {
  animation-delay: .26s;
}

.galleryGrid .galleryItem:nth-child(5) {
  animation-delay: .33s;
}

.galleryGrid .galleryItem:nth-child(6) {
  animation-delay: .40s;
}

@keyframes galleryReveal {
  from {
    opacity: 0;
    transform: translateY(30px) scale(.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Lightbox */
.galleryLightbox {
  animation: lightboxFade .3s ease both;
}

@keyframes lightboxFade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.galleryLightbox img {
  animation: lightboxImage .45s cubic-bezier(.2,.7,.2,1) both;
}

@keyframes lightboxImage {
  from {
    opacity: 0;
    transform: scale(.92);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Mobile */
@media (max-width: 700px) {

  .galleryItem {
    border-radius: 14px;
  }

  .galleryItem:hover {
    transform: translateY(-4px);
  }

  .galleryOverlay {
    padding: 16px;
  }

  .galleryOpenIcon {
    width: 38px;
    height: 38px;
    top: 12px;
    right: 12px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {

  .galleryGrid .galleryItem,
  .galleryLightbox,
  .galleryLightbox img {
    animation: none;
  }
}

