}

.novaGalleryCard img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: cover;

  object-position: center;

  transition:
    transform 0.55s ease,
    filter 0.4s ease;
}

.novaGalleryCard:hover img {
  transform: scale(1.07);

  filter: brightness(0.75);
}

/* =========================================================
   IMAGE OVERLAY
========================================================= */

.novaGalleryCardOverlay {
