}

.novaReviewsTrustGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.novaReviewTrustCard {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 25px;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  transition: 0.3s ease;
}

.novaReviewTrustCard:hover {
  transform: translateY(-5px);
  border-color: #55b8b0;
  box-shadow: 0 18px 40px rgba(11,37,69,0.08);
}

.novaReviewTrustCard > span {
