/* CARDS */

.novaReviewsCardsSection {
  padding: 110px 0;
  background: #f7fafc;
}

.novaReviewsCardsHeading {
  margin-bottom: 45px;
}

.novaReviewsCardsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

.novaReviewCard {
  position: relative;
  padding: 28px;
  min-height: 330px;
  background: white;
  border: 1px solid #e2e8f0;
