  gap: 2px;
  color: #1f8a8a;
}

.novaReviewCardQuote {
  margin-top: 30px;
  color: #55b8b0;
  opacity: 0.8;
}

.novaReviewCard p {
  margin: 15px 0 30px;
  color: #475569;
  font-size: 14px;
  line-height: 1.8;
}

.novaReviewCardPerson strong,
.novaReviewCardPerson span {
  display: block;
}

.novaReviewCardPerson strong {
  color: #0b2545;
  font-size: 14px;
}

.novaReviewCardPerson span {
  margin-top: 4px;
  color: #94a3b8;
