/* CTA */

.novaReviewsCTA {
  padding: 40px 0 100px;
  background: #f7fafc;
}

.novaReviewsCTACard {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 50px;
  padding: 55px;
  border-radius: 28px;
