  margin: 15px 0;
  font-family: "Playfair Display", serif;
  font-size: clamp(35px, 4vw, 56px);
  line-height: 1.05;
}

.novaReviewsCTACard p {
  max-width: 600px;
  margin: 0;
   margin: 0;
  color: rgba(255,255,255,0.65);
  line-height: 1.8;
}

.novaReviewsCTAButton {
  flex-shrink: 0;
  background: #55b8b0;
  color: #0b2545;
}

.novaReviewsCTAButton:hover {
  background: white;
}

/* MOBILE */

@media (max-width: 900px) {

  .novaReviewsHeroRating {
