/* =========================================================
   NOVADENT REVIEWS — PREMIUM INTERACTION & ANIMATION
   ========================================================= */

/* ---------- HERO FLOATING EFFECT ---------- */

.novaReviewsHeroContent {
  animation: reviewHeroContent 0.9s ease both;
}

.novaReviewsEyebrow {
  animation: reviewEyebrow 0.8s ease both;
  animation-delay: 0.15s;
}

.novaReviewsHero h1 {
  animation: reviewHeroTitle 1s cubic-bezier(.2,.8,.2,1) both;
  animation-delay: 0.2s;
}

.novaReviewsHero p {
  animation: reviewHeroText 0.9s ease both;
  animation-delay: 0.35s;
}

.novaReviewsHeroActions {
  animation: reviewHeroActions 0.9s ease both;
  animation-delay: 0.45s;
}

.novaReviewsHeroRating {
  animation: reviewRatingFloat 4s ease-in-out infinite;
}

/* ---------- HERO BUTTON ---------- */

.novaReviewsPrimary {
  position: relative;
  overflow: hidden;
}

.novaReviewsPrimary::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 80%;
  height: 100%;
  background: linear-gradient(
    100deg,
    transparent,
    rgba(255,255,255,0.22),
    transparent
  );
  transform: skewX(-20deg);
  transition: 0.7s ease;
}

.novaReviewsPrimary:hover::before {
  left: 140%;
}

/* ---------- INTRO REVEAL ---------- */

.novaReviewsIntroGrid > div:first-child {
  animation: reviewRevealLeft 0.9s ease both;
}

.novaReviewsIntroText {
  animation: reviewRevealRight 0.9s ease both;
}

/* ---------- FEATURED REVIEW ---------- */

.novaFeaturedReview {
  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease;
}

.novaFeaturedReview:hover {
  transform: translateY(-7px);
  box-shadow:
    0 35px 90px rgba(11,37,69,0.23);
}

.novaFeaturedQuote {
  transition: transform 0.4s ease;
}

.novaFeaturedReview:hover .novaFeaturedQuote {
  transform: translateY(-5px) rotate(-5deg);
}

.novaFeaturedStars svg {
  transition: transform 0.25s ease;
}

.novaFeaturedReview:hover .novaFeaturedStars svg:nth-child(1) {
  transform: translateY(-3px) rotate(-8deg);
}

.novaFeaturedReview:hover .novaFeaturedStars svg:nth-child(2) {
  transform: translateY(-5px) rotate(5deg);
}

.novaFeaturedReview:hover .novaFeaturedStars svg:nth-child(3) {
  transform: translateY(-4px);
}

.novaFeaturedReview:hover .novaFeaturedStars svg:nth-child(4) {
  transform: translateY(-5px) rotate(-5deg);
}

.novaFeaturedReview:hover .novaFeaturedStars svg:nth-child(5) {
  transform: translateY(-3px) rotate(8deg);
}

/* ---------- REVIEW PERSON ---------- */

.novaPersonAvatar {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.novaFeaturedReview:hover .novaPersonAvatar {
  transform: scale(1.1);
  box-shadow:
    0 0 0 7px rgba(85,184,176,0.12);
}

/* ---------- ARROW BUTTONS ---------- */

.novaReviewButtons button {
  position: relative;
  overflow: hidden;
}

.novaReviewButtons button svg {
  transition: transform 0.3s ease;
}

.novaReviewButtons button:hover svg {
  transform: scale(1.18);
}

.novaReviewButtons button:first-child:hover svg {
  transform: translateX(-3px) scale(1.1);
}

.novaReviewButtons button:last-child:hover svg {
  transform: translateX(3px) scale(1.1);
}

/* ---------- DOTS ---------- */

.novaReviewDots button {
  position: relative;
}

.novaReviewDots button::after {
  content: "";
  position: absolute;
  inset: -6px;
  border-radius: 50px;
  border: 1px solid transparent;
  transition: 0.3s ease;
}

.novaReviewDots button:hover::after {
  border-color: rgba(31,138,138,0.3);
}

/* ---------- TRUST CARDS ---------- */

.novaReviewTrustCard {
  position: relative;
  overflow: hidden;
}

.novaReviewTrustCard::before {
  content: "";
  position: absolute;
  width: 100px;
  height: 100px;
  right: -40px;
  bottom: -40px;
  border-radius: 50%;
  background: rgba(85,184,176,0.08);
  transition: 0.5s ease;
}

.novaReviewTrustCard:hover::before {
  width: 180px;
  height: 180px;
}

.novaReviewTrustCard > svg {
  transition:
    transform 0.4s ease,
    scale 0.4s ease;
}

.novaReviewTrustCard:hover > svg {
  transform: rotate(-8deg) scale(1.2);
}

/* ---------- REVIEW CARDS ---------- */

.novaReviewCard {
  transform-style: preserve-3d;
  perspective: 1000px;
}

.novaReviewCard:hover {
  transform:
    translateY(-10px)
    rotateX(1deg)
    rotateY(-1deg);
}

.novaReviewCardTop {
  transition: transform 0.35s ease;
}

.novaReviewCard:hover .novaReviewCardTop {
  transform: translateY(-3px);
}

.novaReviewMiniAvatar {
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.novaReviewCard:hover .novaReviewMiniAvatar {
  transform: scale(1.12) rotate(-4deg);
  box-shadow:
    0 0 0 6px rgba(85,184,176,0.13);
}

.novaReviewCardQuote {
  transition:
    transform 0.4s ease,
    opacity 0.4s ease;
}

.novaReviewCard:hover .novaReviewCardQuote {
  transform: translateY(-5px) scale(1.08);
  opacity: 1;
}

.novaReviewStars svg {
  transition: transform 0.25s ease;
}

.novaReviewCard:hover .novaReviewStars svg:nth-child(odd) {
  transform: translateY(-2px);
}

.novaReviewCard:hover .novaReviewStars svg:nth-child(even) {
  transform: translateY(-4px);
}

/* ---------- CARD ACTIVE EFFECT ---------- */

.novaReviewCard.isActive {
  position: relative;
}

.novaReviewCard.isActive::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    135deg,
    #55b8b0,
    transparent 45%,
    #1f8a8a
  );

-webkit-mask:
  linear-gradient(#fff 0 0) content-box,
  linear-gradient(#fff 0 0);

-webkit-mask-composite: xor;

mask:
  linear-gradient(#fff 0 0) content-box,
  linear-gradient(#fff 0 0);

mask-composite: exclude;
  pointer-events: none;
}

/* ---------- CTA ANIMATION ---------- */

.novaReviewsCTACard {
  position: relative;
  overflow: hidden;
}

.novaReviewsCTACard::before {
  content: "";
  position: absolute;
  width: 280px;
  height: 280px;
  right: -100px;
  top: -120px;
  border-radius: 50%;
  border: 1px solid rgba(85,184,176,0.18);
  animation: ctaOrbit 8s linear infinite;
}

.novaReviewsCTACard::after {
  content: "";
  position: absolute;
  width: 180px;
  height: 180px;
  right: 40px;
  bottom: -100px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.08);
  animation: ctaOrbitReverse 10s linear infinite;
}

.novaReviewsCTACard > * {
  position: relative;
  z-index: 2;
}

.novaReviewsCTAButton {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.novaReviewsCTAButton:hover {
  transform: translateY(-5px) scale(1.03);
  box-shadow:
    0 15px 35px rgba(85,184,176,0.25);
}

.novaReviewsCTAButton svg {
  transition: transform 0.3s ease;
}

.novaReviewsCTAButton:hover svg {
  transform: translate(3px, -3px);
}

/* =========================================================
   KEYFRAMES
   ========================================================= */

@keyframes reviewHeroContent {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes reviewEyebrow {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes reviewHeroTitle {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes reviewHeroText {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes reviewHeroActions {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes reviewRatingFloat {
  0%,
  100% {
    transform: translateY(0) rotate(0deg);
  }

  50% {
    transform: translateY(-10px) rotate(1deg);
  }
}

@keyframes reviewRevealLeft {
  from {
    opacity: 0;
    transform: translateX(-35px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes reviewRevealRight {
  from {
    opacity: 0;
    transform: translateX(35px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes ctaOrbit {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes ctaOrbitReverse {
  from {
    transform: rotate(360deg);
  }

  to {
    transform: rotate(0deg);
  }
}

/* =========================================================
   MOBILE PERFORMANCE
   ========================================================= */

@media (max-width: 600px) {

  .novaFeaturedReview:hover {
    transform: none;
  }

  .novaReviewCard:hover {
    transform: translateY(-5px);
  }

  .novaReviewsHeroRating {
    animation: none;
  }
}

/* =========================================================
   REDUCED MOTION ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .novaReviewsHeroContent,
  .novaReviewsEyebrow,
  .novaReviewsHero h1,
  .novaReviewsHero p,
  .novaReviewsHeroActions,
  .novaReviewsHeroRating,
  .novaReviewsIntroGrid > div:first-child,
  .novaReviewsIntroText,
  .novaReviewsCTACard::before,
  .novaReviewsCTACard::after {
    animation: none !important;
  }

  .novaReviewCard,
  .novaFeaturedReview,
  .novaReviewTrustCard,
  .novaReviewsPrimary,
  .novaReviewsCTAButton {
    transition: none !important;
  }
}

