  font-size: clamp(52px, 7vw, 86px);
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.novaAppointmentHero h1 em {
  display: block;
  color: #76d1c9;
  font-weight: 500;
}

.novaAppointmentHero p {
  max-width: 620px;
  margin: 28px 0 0;
  color: rgba(255,255,255,0.75);
  font-size: 17px;
  line-height: 1.8;
  animation: appointmentFadeUp .8s ease .25s both;
}

.novaAppointmentHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 36px;
  animation: appointmentFadeUp .8s ease .4s both;
}

.novaAppointmentPrimary {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 56px;
  padding: 0 25px;
  border-radius: 999px;
  overflow: hidden;
  background: #55b8b0;
  color: #08283d;
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform .35s ease,
    box-shadow .35s ease;
}

.novaAppointmentPrimary::before {
  content: "";
  position: absolute;
  left: -120%;
  top: 0;
  width: 80%;
  height: 100%;
  background: linear-gradient(
    100deg,
    transparent,
    rgba(255,255,255,.35),
    transparent
  );
  transform: skewX(-20deg);
  transition: left .7s ease;
}

.novaAppointmentPrimary:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 38px rgba(85,184,176,.25);
}

.novaAppointmentPrimary:hover::before {
  left: 140%;
}

.novaAppointmentPrimary svg {
  transition: transform .3s ease;
}

.novaAppointmentPrimary:hover svg {
  transform: translateX(4px);
}

.novaAppointmentTextLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: rgba(255,255,255,.78);
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
  transition: color .3s ease;
}

.novaAppointmentTextLink:hover {
  color: white;
}

.novaAppointmentTextLink svg {
  transition: transform .3s ease;
}

.novaAppointmentTextLink:hover svg {
  transform: translate(3px,-3px);
}

.novaAppointmentHeroBadge {
  position: absolute;
  right: 0;
  bottom: 35px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 14px 18px;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 18px;
  background: rgba(255,255,255,.06);
  backdrop-filter: blur(12px);
  animation: appointmentBadgeFloat 4s ease-in-out infinite;
}

.appointmentBadgeIcon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: rgba(85,184,176,.16);
  color: #8fe1da;
}

.novaAppointmentHeroBadge strong,
.novaAppointmentHeroBadge span {
  display: block;
}

.novaAppointmentHeroBadge strong {
  color: white;
  font-size: 13px;
}

.novaAppointmentHeroBadge span {
  margin-top: 3px;
  color: rgba(255,255,255,.55);
  font-size: 11px;
}

/* =========================================================
   INTRO
   ========================================================= */

.novaAppointmentIntro {
  padding: 110px 0 80px;
  background: #fff;
}

.novaAppointmentIntroGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: start;
}

.novaAppointmentOverline {
  display: block;
  color: #1f8a8a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
}

.novaAppointmentNumber {
  display: block;
  margin-top: 12px;
  color: #94a3b8;
  font-size: 11px;
  letter-spacing: .12em;
}

.novaAppointmentIntro h2,
.appointmentInfoTop h2,
.novaAppointmentCTACard h2 {
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(42px, 5vw, 66px);
  line-height: 1.04;
  letter-spacing: -.035em;
  color: #0b2545;
}

.novaAppointmentIntro h2 em,
.appointmentInfoTop h2 em,
.novaAppointmentCTACard h2 em {
  color: #1f8a8a;
  font-weight: 500;
}

.novaAppointmentIntroText {
  padding-top: 30px;
}

.novaAppointmentIntroText > p {
  max-width: 510px;
  color: #64748b;
  font-size: 16px;
  line-height: 1.85;
}

.appointmentIntroPoints {
  display: grid;
  gap: 13px;
  margin-top: 28px;
}

.appointmentIntroPoints > div {
  display: flex;
  align-items: center;
  gap: 12px;
}

.appointmentIntroPoints span {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #eaf5f4;
  color: #1f8a8a;
}

.appointmentIntroPoints p {
  margin: 0;
  color: #183b56;
  font-size: 14px;
  font-weight: 700;
}

/* =========================================================
   MAIN APPOINTMENT SECTION
   ========================================================= */

.novaAppointmentSection {
  padding: 50px 0 120px;
  background:
    radial-gradient(
      circle at 8% 20%,
      rgba(85,184,176,.08),
      transparent 30%
    ),
    #f7fafc;
}

.appointmentGrid {
  display: grid;
  grid-template-columns: .82fr 1.18fr;
  gap: 70px;
  align-items: start;
}

/* =========================================================
   LEFT INFORMATION
   ========================================================= */

.appointmentInfo {
  position: sticky;
  top: 110px;
}

.appointmentInfoTop p {
  max-width: 470px;
  margin-top: 25px;
  color: #64748b;
  line-height: 1.8;
  font-size: 15px;
}

.appointmentInfoCards {
  display: grid;
  gap: 12px;
  margin-top: 35px;
}

.appointmentInfoCard {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 18px;
  border: 1px solid rgba(11,37,69,.07);
  border-radius: 18px;
  background: white;
  transition:
    transform .35s ease,
    box-shadow .35s ease,
    border-color .35s ease;
}

.appointmentInfoCard:hover {
  transform: translateX(7px);
  border-color: rgba(31,138,138,.22);
  box-shadow: 0 16px 35px rgba(11,37,69,.08);
}

.appointmentInfoIcon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: #eaf5f4;
  color: #1f8a8a;
  transition:
    transform .35s ease,
    background .35s ease;
}

.appointmentInfoCard:hover .appointmentInfoIcon {
  transform: rotate(-7deg) scale(1.08);
  background: #dff1ef;
}

.appointmentInfoCard small {
  display: block;
  margin-bottom: 4px;
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
}

.appointmentInfoCard strong,
.appointmentInfoCard a {
  color: #183b56;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}

.appointmentInfoCard a:hover {
  color: #1f8a8a;
}

.appointmentTrustBox {
  display: flex;
  gap: 13px;
  margin-top: 25px;
  padding: 18px;
  border-radius: 18px;
  background: #0b2545;
  color: white;
}

.appointmentTrustBox > svg {
  flex: 0 0 auto;
  color: #76d1c9;
}

.appointmentTrustBox strong {
  display: block;
  font-size: 13px;
}

.appointmentTrustBox p {
  margin: 4px 0 0;
  color: rgba(255,255,255,.55);
  font-size: 11px;
}

/* =========================================================
   FORM CARD
   ========================================================= */

.appointmentFormCard {
  position: relative;
  padding: 38px;
  border: 1px solid rgba(11,37,69,.08);
  border-radius: 30px;
  background: white;
  box-shadow:
    0 25px 80px rgba(11,37,69,.10);
  overflow: hidden;
}

.appointmentFormCard::before {
  content: "";
  position: absolute;
  width: 220px;
  height: 220px;
  right: -100px;
  top: -110px;
  border-radius: 50%;
  background: rgba(85,184,176,.08);
  pointer-events: none;
}

.appointmentFormHeader {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 32px;
}

.appointmentFormHeader > div:first-child > span {
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .15em;
}

.appointmentFormHeader h2 {
  margin: 8px 0 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 34px;
  line-height: 1.1;
}

.appointmentFormNumber {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 15px;
  background: #eaf5f4;
  color: #1f8a8a;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 20px;
}

/* =========================================================
   FORM GRID
   ========================================================= */

.novaAppointmentForm {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.appointmentField {
  min-width: 0;
}

.appointmentFieldFull {
  grid-column: 1 / -1;
}

.appointmentField label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  color: #183b56;
  font-size: 12px;
  font-weight: 800;
}

.appointmentField label span {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 600;
}

.appointmentInputWrap {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 54px;
  padding: 0 15px;
  border: 1px solid #dce5eb;
  border-radius: 14px;
  background: #fbfdfe;
  transition:
    border-color .3s ease,
    box-shadow .3s ease,
    background .3s ease,
    transform .3s ease;
}

.appointmentInputWrap > svg {
  flex: 0 0 auto;
  color: #8ca1b2;
  transition: color .3s ease, transform .3s ease;
}

.appointmentField.isFocused .appointmentInputWrap {
  border-color: #1f8a8a;
  background: white;
  box-shadow:
    0 0 0 4px rgba(31,138,138,.08);
  transform: translateY(-2px);
}

.appointmentField.isFocused .appointmentInputWrap > svg {
  color: #1f8a8a;
  transform: scale(1.08);
}

.appointmentInputWrap input,
.appointmentInputWrap select,
.appointmentInputWrap textarea {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #183b56;
  font: inherit;
  font-size: 14px;
}

.appointmentInputWrap input,
.appointmentInputWrap select {
  height: 52px;
}

.appointmentInputWrap input::placeholder,
.appointmentInputWrap textarea::placeholder {
  color: #a4b0ba;
}

.appointmentInputWrap select {
  cursor: pointer;
}

.appointmentTextareaWrap {
  align-items: flex-start;
  padding-top: 15px;
  padding-bottom: 15px;
}

.appointmentTextareaWrap textarea {
  resize: vertical;
  min-height: 90px;
  line-height: 1.6;
}

.appointmentField.hasError .appointmentInputWrap {
  border-color: #e36b6b;
  box-shadow: 0 0 0 4px rgba(227,107,107,.07);
}

.appointmentError {
  display: block;
  margin-top: 6px;
  color: #d95c5c;
  font-size: 11px;
  animation: appointmentError .25s ease both;
}

/* =========================================================
   SUBMIT
   ========================================================= */

.appointmentSubmitArea {
  grid-column: 1 / -1;
  margin-top: 5px;
}

.appointmentSubmit {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 60px;
  padding: 7px 8px 7px 23px;
  border: 0;
  border-radius: 999px;
  background: #0b2545;
  color: white;
  cursor: pointer;
  overflow: hidden;
  font: inherit;
  font-size: 14px;
  font-weight: 800;
  transition:
    transform .35s ease,
    box-shadow .35s ease;
}

.appointmentSubmit::before {
  content: "";
  position: absolute;
  inset: 0;
  width: 0;
  background: #1f8a8a;
  transition: width .45s ease;
}

.appointmentSubmit:hover::before {
  width: 100%;
}

.appointmentSubmit:hover {
  transform: translateY(-4px);
  box-shadow:
    0 16px 35px rgba(11,37,69,.18);
}

.appointmentSubmit > span:first-child,
.appointmentSubmitIcon {
  position: relative;
  z-index: 2;
}

.appointmentSubmitIcon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #55b8b0;
  color: #08283d;
  transition:
    transform .35s ease,
    background .35s ease;
}

.appointmentSubmit:hover .appointmentSubmitIcon {
  transform: rotate(8deg) scale(1.08);
  background: white;
}

.appointmentSubmitArea > p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 10px 0 0;
  color: #94a3b8;
  font-size: 10px;
}

/* =========================================================
   SUCCESS STATE
   ========================================================= */

.appointmentSuccess {
  min-height: 620px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 30px;
  animation: successReveal .7s cubic-bezier(.2,.8,.2,1) both;
}

.successCheck {
  display: grid;
  place-items: center;
  width: 82px;
  height: 82px;
  border-radius: 50%;
  background: #e5f5f2;
  color: #1f8a8a;
  animation:
    successPop .65s cubic-bezier(.2,1.4,.4,1) both,
    successPulse 2.5s ease-in-out 1s infinite;
}

.successEyebrow {
  margin-top: 25px;
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .17em;
}

.appointmentSuccess h2 {
  margin: 12px 0 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 48px;
}

.appointmentSuccess h2 em {
  color: #1f8a8a;
  font-weight: 500;
}

.appointmentSuccess > p {
  max-width: 550px;
  margin: 18px auto 0;
  color: #64748b;
  line-height: 1.8;
  font-size: 14px;
}

.successSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  width: 100%;
  max-width: 580px;
  margin: 30px auto;
  border: 1px solid #e2e9ee;
  border-radius: 18px;
  overflow: hidden;
}

.successSummary > div {
  padding: 17px;
  border-right: 1px solid #e2e9ee;
  background: #fbfdfe;
}

.successSummary > div:last-child {
  border-right: 0;
}

.successSummary small,
.successSummary strong {
  display: block;
}

.successSummary small {
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .12em;
}

.successSummary strong {
  margin-top: 5px;
  color: #183b56;
  font-size: 12px;
}

.appointmentReset {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 20px;
  border: 1px solid #d8e4e9;
  border-radius: 999px;
  background: white;
  color: #183b56;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  transition:
    transform .3s ease,
    border-color .3s ease,
    color .3s ease;
}

.appointmentReset:hover {
  transform: translateY(-3px);
  border-color: #1f8a8a;
  color: #1f8a8a;
}

.successHomeLink {
  margin-top: 16px;
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  text-decoration: none;
}

.successHomeLink:hover {
  color: #1f8a8a;
}

/* =========================================================
   CTA
   ========================================================= */

.novaAppointmentCTA {
  padding: 30px 0 100px;
  background: #f7fafc;
}

.novaAppointmentCTACard {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding: 55px;
  border-radius: 30px;
  overflow: hidden;
  background: #0b2545;
  color: white;
}

.novaAppointmentCTACard::before {
  content: "";
  position: absolute;
  width: 300px;
  height: 300px;
  right: -100px;
  top: -160px;
  border: 1px solid rgba(118,209,201,.18);
  border-radius: 50%;
  animation: appointmentOrbit 9s linear infinite;
}

.novaAppointmentCTACard::after {
  content: "";
  position: absolute;
  width: 170px;
  height: 170px;
  right: 180px;
  bottom: -100px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 50%;
}

.novaAppointmentCTACard > * {
  position: relative;
  z-index: 2;
}

.novaAppointmentCTABadge {
  color: #76d1c9;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .15em;
}

.novaAppointmentCTACard h2 {
  max-width: 650px;
  margin-top: 13px;
  color: white;
}

.novaAppointmentCTACard p {
  max-width: 590px;
  margin-top: 18px;
  color: rgba(255,255,255,.58);
  line-height: 1.7;
  font-size: 14px;
}

.appointmentCTAButtons {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.appointmentSecondaryButton,
.appointmentCallButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 50px;
  padding: 0 20px;
  border-radius: 999px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition:
    transform .3s ease,
    box-shadow .3s ease;
}

.appointmentSecondaryButton {
  background: #55b8b0;
  color: #08283d;
}

.appointmentCallButton {
  border: 1px solid rgba(255,255,255,.15);
  background: rgba(255,255,255,.05);
  color: white;
}

.appointmentSecondaryButton:hover,
.appointmentCallButton:hover {
  transform: translateY(-4px);
}

.appointmentSecondaryButton:hover {
  box-shadow: 0 12px 30px rgba(85,184,176,.2);
}

/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes appointmentHeroReveal {
  from {
    opacity: 0;
    transform: translateY(45px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes appointmentFadeUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes appointmentHeroGlow {
  0%,
  100% {
    transform: translate(0,0) scale(1);
  }
  50% {
    transform: translate(-35px,30px) scale(1.08);
  }
}

@keyframes appointmentCircle {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes appointmentCircleReverse {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes appointmentBadgeFloat {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

@keyframes appointmentError {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes successReveal {
  from {
    opacity: 0;
    transform: scale(.96) translateY(20px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes successPop {
  from {
    opacity: 0;
    transform: scale(.4);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes successPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(31,138,138,.18);
  }
  50% {
    box-shadow: 0 0 0 15px rgba(31,138,138,0);
  }
}

@keyframes appointmentOrbit {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 950px) {

  .novaAppointmentHero {
    min-height: 590px;
  }

  .novaAppointmentHeroBadge {
    display: none;
  }

  .appointmentGrid {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .appointmentInfo {
    position: static;
  }

  .appointmentInfoTop {
    max-width: 700px;
  }

  .appointmentInfoCards {
    grid-template-columns: repeat(3, 1fr);
  }

  .appointmentInfoCard {
    flex-direction: column;
    align-items: flex-start;
  }

  .novaAppointmentCTACard {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .novaAppointmentContainer {
    width: min(100% - 28px, 680px);
  }

  .novaAppointmentHero {
    min-height: 560px;
    padding: 90px 0 70px;
  }

  .novaAppointmentHero h1 {
    font-size: clamp(43px, 12vw, 62px);
  }

  .novaAppointmentHero p {
    font-size: 15px;
    line-height: 1.7;
  }

  .novaAppointmentHeroActions {
    flex-direction: column;
    align-items: stretch;
    gap: 14px;
  }

  .novaAppointmentPrimary {
    width: 100%;
  }

  .novaAppointmentTextLink {
    justify-content: center;
  }

  .circleOne {
    right: -230px;
    top: 30px;
  }

  .circleTwo {
    display: none;
  }

  .novaAppointmentIntro {
    padding: 75px 0 55px;
  }

  .novaAppointmentIntroGrid {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .novaAppointmentIntro h2,
  .appointmentInfoTop h2 {
    font-size: 43px;
  }

  .novaAppointmentIntroText {
    padding-top: 0;
  }

  .novaAppointmentSection {
    padding: 30px 0 75px;
  }

  .appointmentGrid {
    gap: 35px;
  }

  .appointmentInfoCards {
    grid-template-columns: 1fr;
  }

  .appointmentInfoCard {
    flex-direction: row;
    align-items: center;
  }

  .appointmentFormCard {
    padding: 24px 18px;
    border-radius: 23px;
  }

  .appointmentFormHeader h2 {
    font-size: 28px;
  }

  .novaAppointmentForm {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .appointmentFieldFull,
  .appointmentSubmitArea {
    grid-column: auto;
  }

  .appointmentSubmitArea {
    margin-top: 4px;
  }

  .appointmentSuccess {
    min-height: 560px;
    padding: 15px 5px;
  }

  .appointmentSuccess h2 {
    font-size: 39px;
  }

  .successSummary {
    grid-template-columns: 1fr;
  }

  .successSummary > div {
    border-right: 0;
    border-bottom: 1px solid #e2e9ee;
  }

  .successSummary > div:last-child {
    border-bottom: 0;
  }

  .novaAppointmentCTA {
    padding: 15px 0 70px;
  }

  .novaAppointmentCTACard {
    padding: 35px 25px;
    border-radius: 24px;
  }

  .novaAppointmentCTACard h2 {
    font-size: 42px;
  }

  .appointmentCTAButtons {
    width: 100%;
    flex-direction: column;
  }

  .appointmentSecondaryButton,
  .appointmentCallButton {
    width: 100%;
  }
}

/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 420px) {

  .novaAppointmentHero {
    min-height: 530px;
  }

  .novaAppointmentHero h1 {
    font-size: 43px;
  }

  .novaAppointmentIntro h2,
  .appointmentInfoTop h2 {
    font-size: 38px;
  }

  .appointmentFormCard {
    padding: 20px 14px;
  }

  .appointmentFormHeader {
    margin-bottom: 24px;
  }

  .appointmentFormNumber {
    width: 40px;
    height: 40px;
  }

  .appointmentSuccess h2 {
    font-size: 34px;
  }

  .novaAppointmentCTACard h2 {
    font-size: 37px;
  }
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .novaAppointmentHeroGlow,
  .novaAppointmentHeroCircle,
  .novaAppointmentHeroBadge,
  .novaAppointmentCTACard::before,
  .successCheck {
    animation: none !important;
  }

  .novaAppointmentPrimary,
  .novaAppointmentInfoCard,
  .appointmentSubmit,
  .appointmentCTAButtons a {
    transition: none !important;
  }
}

/* =========================================================
   NOVADENT — APPOINTMENT PAGE
   Premium + Interactive + Responsive
   ========================================================= */

.novaAppointmentPage {
  --app-navy: #0b2545;
  --app-teal: #1f8a8a;
  --app-soft-teal: #55b8b0;
  --app-cream: #f7fafc;
  --app-mint: #eaf5f4;
  --app-text: #183b56;
  --app-muted: #64748b;
  background: var(--app-cream);
  color: var(--app-text);
  overflow: hidden;
}

/* ---------- COMMON ---------- */

.appointmentContainer {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.appointmentOverline {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--app-teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.appointmentIntro small,
.appointmentSectionHeading small {
  display: block;
  margin-top: 12px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.appointmentPage h1,
.appointmentPage h2,
.appointmentPage h3 {
  font-family: "Playfair Display", Georgia, serif;
}

/* ---------- HERO ---------- */

.novaAppointmentHero {
  min-height: 720px;
  position: relative;
  display: flex;
  align-items: center;
  background:
    radial-gradient(
      circle at 85% 20%,
      rgba(85, 184, 176, 0.18),
      transparent 30%
    ),
    linear-gradient(135deg, #071c34 0%, #0b2545 55%, #123d58 100%);
  color: white;
  padding: 110px 0 90px;
}

.appointmentHeroGlow {
  position: absolute;
  width: 500px;
  height: 500px;
  right: -180px;
  top: -180px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.12);
  filter: blur(20px);
  animation: appointmentGlow 7s ease-in-out infinite;
}

.appointmentHeroGrid {
  display: grid;
  grid-template-columns: 1.02fr 0.98fr;
  align-items: center;
  gap: 80px;
}

.appointmentHeroContent {
  animation: appointmentHeroText 0.9s ease both;
}

.appointmentEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #8fe1da;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  margin-bottom: 25px;
}

.appointmentHeroContent h1 {
  max-width: 650px;
  margin: 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(48px, 6vw, 78px);
  line-height: 0.98;
  font-weight: 500;
  letter-spacing: -0.045em;
}

.appointmentHeroContent h1 em {
  display: block;
  color: #79d2ca;
  font-style: italic;
  font-weight: 500;
}

.appointmentHeroContent > p {
  max-width: 590px;
  margin: 28px 0 0;
  color: rgba(255, 255, 255, 0.74);
  font-size: 16px;
  line-height: 1.8;
}

.appointmentHeroActions {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-top: 35px;
}

.appointmentPrimaryBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 54px;
  padding: 0 23px;
  border-radius: 999px;
  background: #55b8b0;
  color: #08243c;
  font-size: 13px;
  font-weight: 800;
  text-decoration: none;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.appointmentPrimaryBtn:hover {
  transform: translateY(-4px);
  background: #79d2ca;
  box-shadow: 0 18px 40px rgba(85, 184, 176, 0.25);
}

.appointmentPhoneBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: white;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  transition: color 0.25s ease;
}

.appointmentPhoneBtn:hover {
  color: #79d2ca;
}

.appointmentTrustRow {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 48px;
}

.appointmentTrustRow div {
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 11px;
  font-weight: 700;
}

.appointmentTrustRow svg {
  color: #79d2ca;
}

/* ---------- HERO IMAGE ---------- */

.appointmentHeroVisual {
  position: relative;
  animation: appointmentHeroImage 1s 0.15s ease both;
}

.appointmentHeroImage {
  position: relative;
  height: 520px;
  overflow: hidden;
  border-radius: 30px;
  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.3);
}

.appointmentHeroImage::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      transparent 55%,
      rgba(5, 25, 43, 0.35)
    );
  pointer-events: none;
}

.appointmentHeroImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 1s ease;
}

.appointmentHeroVisual:hover .appointmentHeroImage img {
  transform: scale(1.05);
}

.appointmentFloatingCard {
  position: absolute;
  left: -35px;
  bottom: 32px;
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 245px;
  padding: 16px 18px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 18px;
  background: rgba(10, 37, 69, 0.88);
  backdrop-filter: blur(16px);
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.25);
  animation: appointmentFloat 4s ease-in-out infinite;
}

.floatingIcon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(85, 184, 176, 0.18);
  color: #79d2ca;
}

.appointmentFloatingCard strong,
.appointmentFloatingCard span {
  display: block;
}

.appointmentFloatingCard strong {
  color: white;
  font-size: 12px;
}

.appointmentFloatingCard span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
}

/* ---------- INTRO ---------- */

.appointmentIntro {
  padding: 115px 0 85px;
  background: #fff;
}

.appointmentIntroGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 100px;
}

.appointmentIntro h2,
.appointmentSectionHeading h2 {
  max-width: 560px;
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(40px, 5vw, 62px);
  line-height: 1.02;
  letter-spacing: -0.04em;
  font-weight: 500;
}

.appointmentIntro h2 em,
.appointmentSectionHeading h2 em {
  color: var(--app-teal);
  font-style: italic;
}

.appointmentIntroText {
  padding-top: 38px;
}

.appointmentIntroText > p {
  max-width: 590px;
  margin: 0;
  color: var(--app-muted);
  font-size: 16px;
  line-height: 1.9;
}

.appointmentInfoCards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
  margin-top: 35px;
}

.appointmentInfoCard {
  display: flex;
  gap: 13px;
  padding: 19px;
  border: 1px solid #e5edf1;
  border-radius: 18px;
  background: #fbfdfe;
  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.appointmentInfoCard:hover {
  transform: translateY(-5px);
  border-color: rgba(31, 138, 138, 0.35);
  box-shadow: 0 15px 35px rgba(11, 37, 69, 0.08);
}

.appointmentInfoCard > svg {
  flex: 0 0 auto;
  color: var(--app-teal);
}

.appointmentInfoCard strong,
.appointmentInfoCard span {
  display: block;
}

.appointmentInfoCard strong {
  font-size: 12px;
  color: var(--app-navy);
}

.appointmentInfoCard span {
  margin-top: 5px;
  color: var(--app-muted);
  font-size: 10px;
}

/* ---------- FORM SECTION ---------- */

.appointmentFormSection {
  padding: 100px 0 120px;
  background:
    linear-gradient(
      180deg,
      #f7fafc 0%,
      #edf7f6 100%
    );
}

.appointmentSectionHeading {
  display: grid;
  grid-template-columns: 1fr 0.8fr;
  align-items: end;
  gap: 70px;
  margin-bottom: 55px;
}

.appointmentSectionHeading > p {
  max-width: 470px;
  margin: 0 0 5px auto;
  color: var(--app-muted);
  font-size: 14px;
  line-height: 1.8;
}

.appointmentFormLayout {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.75fr);
  gap: 30px;
  align-items: start;
}

/* ---------- FORM CARD ---------- */

.appointmentFormCard {
  min-height: 600px;
  padding: 42px;
  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 28px;
  background: #fff;
  box-shadow: 0 25px 65px rgba(11, 37, 69, 0.08);
}

.formRow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.formField {
  margin-bottom: 22px;
}

.formField label {
  display: block;
  margin-bottom: 9px;
  color: var(--app-navy);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.formField input,
.formField select,
.formField textarea {
  width: 100%;
  border: 1px solid #dce7ec;
  border-radius: 13px;
  outline: none;
  background: #fbfdfe;
  color: var(--app-text);
  font-family: inherit;
  font-size: 13px;
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.formField input,
.formField select {
  height: 52px;
  padding: 0 15px;
}

.formField textarea {
  min-height: 125px;
  padding: 15px;
  resize: vertical;
}

.formField input::placeholder,
.formField textarea::placeholder {
  color: #9aaabd;
}

.formField input:focus,
.formField select:focus,
.formField textarea:focus {
  border-color: var(--app-teal);
  background: #fff;
  box-shadow: 0 0 0 4px rgba(31, 138, 138, 0.09);
}

.appointmentSubmitBtn {
  width: 100%;
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 0;
  border-radius: 14px;
  cursor: pointer;
  background: var(--app-navy);
  color: white;
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.appointmentSubmitBtn:hover {
  transform: translateY(-3px);
  background: var(--app-teal);
  box-shadow: 0 16px 35px rgba(11, 37, 69, 0.18);
}

.appointmentSubmitBtn svg {
  transition: transform 0.3s ease;
}

.appointmentSubmitBtn:hover svg {
  transform: translate(3px, -3px);
}

.appointmentFormNote {
  margin: 15px 0 0;
  text-align: center;
  color: #94a3b8;
  font-size: 10px;
  line-height: 1.6;
}

/* ---------- SIDE CARDS ---------- */

.appointmentSide {
  display: grid;
  gap: 15px;
}

.appointmentSideCard {
  position: relative;
  overflow: hidden;
  padding: 28px;
  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 22px;
  background: #fff;
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.appointmentSideCard:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 45px rgba(11, 37, 69, 0.1);
}

.appointmentSideCard::after {
  content: "";
  position: absolute;
  width: 130px;
  height: 130px;
  right: -55px;
  bottom: -65px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.1);
  transition: transform 0.5s ease;
}

.appointmentSideCard:hover::after {
  transform: scale(1.35);
}

.appointmentSideNumber {
  display: block;
  margin-bottom: 25px;
  color: #a3b2bf;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.appointmentSideCard > svg {
  color: var(--app-teal);
}

.appointmentSideCard h3 {
  position: relative;
  z-index: 1;
  margin: 17px 0 9px;
  color: var(--app-navy);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 25px;
  line-height: 1.15;
  font-weight: 500;
}

.appointmentSideCard p {
  position: relative;
  z-index: 1;
  margin: 0;
  color: var(--app-muted);
  font-size: 12px;
  line-height: 1.75;
}

.appointmentSideCard a {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 18px;
  color: var(--app-teal);
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
}

.appointmentSideCard a svg {
  transition: transform 0.25s ease;
}

.appointmentSideCard a:hover svg {
  transform: translate(3px, -3px);
}

.appointmentHighlight {
  background:
    linear-gradient(145deg, #0b2545, #123d58);
  color: white;
}

.appointmentHighlight .appointmentSideNumber,
.appointmentHighlight h3 {
  color: white;
}

.appointmentHighlight p {
  color: rgba(255, 255, 255, 0.65);
}

.appointmentHighlight > svg {
  color: #79d2ca;
}

/* ---------- SUCCESS ---------- */

.appointmentSuccess {
  min-height: 510px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
  animation: appointmentSuccessIn 0.6s ease both;
}

.successIcon {
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--app-mint);
  color: var(--app-teal);
  animation: appointmentSuccessPulse 2s ease-in-out infinite;
}

.appointmentSuccess > span {
  margin-top: 25px;
  color: var(--app-teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.appointmentSuccess h3 {
  margin: 13px 0 8px;
  color: var(--app-navy);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 38px;
  font-weight: 500;
}

.appointmentSuccess p {
  max-width: 470px;
  margin: 0 auto;
  color: var(--app-muted);
  font-size: 14px;
  line-height: 1.8;
}

.appointmentAgainBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 28px;
  padding: 13px 19px;
  border: 1px solid #dce7ec;
  border-radius: 999px;
  background: white;
  color: var(--app-navy);
  cursor: pointer;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;
  transition: all 0.3s ease;
}

.appointmentAgainBtn:hover {
  border-color: var(--app-teal);
  color: var(--app-teal);
  transform: translateY(-3px);
}

/* ---------- FINAL CTA ---------- */

.appointmentFinalCTA {
  padding: 80px 0 110px;
  background: #fff;
}

.appointmentCTACard {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding: 60px 65px;
  border-radius: 30px;
  background:
    radial-gradient(
      circle at 85% 10%,
      rgba(85, 184, 176, 0.22),
      transparent 32%
    ),
    linear-gradient(135deg, #0b2545, #123d58);
  color: white;
}

.appointmentCTACard::before {
  content: "";
  position: absolute;
  width: 280px;
  height: 280px;
  right: -90px;
  bottom: -160px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
  animation: appointmentOrbit 8s linear infinite;
}

.appointmentCTACard > div {
  position: relative;
  z-index: 2;
}

.appointmentCTACard > div > span {
  color: #79d2ca;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.appointmentCTACard h2 {
  max-width: 650px;
  margin: 13px 0 8px;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(35px, 4vw, 55px);
  line-height: 1.03;
  font-weight: 500;
}

.appointmentCTACard h2 em {
  color: #79d2ca;
  font-style: italic;
}

.appointmentCTACard p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 13px;
}

.appointmentCTAButton {
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 53px;
  padding: 0 22px;
  border-radius: 999px;
  background: #55b8b0;
  color: #08243c;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition: all 0.3s ease;
}

.appointmentCTAButton:hover {
  transform: translateY(-4px);
  background: #79d2ca;
  box-shadow: 0 18px 40px rgba(85, 184, 176, 0.25);
}

/* ---------- ANIMATIONS ---------- */

@keyframes appointmentHeroText {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes appointmentHeroImage {
  from {
    opacity: 0;
    transform: translateX(40px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes appointmentGlow {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.7;
  }

  50% {
    transform: scale(1.15);
    opacity: 1;
  }
}

@keyframes appointmentFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-9px);
  }
}

@keyframes appointmentSuccessIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(20px);
  }

  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes appointmentSuccessPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(31, 138, 138, 0.2);
  }

  50% {
    box-shadow: 0 0 0 16px rgba(31, 138, 138, 0);
  }
}

/* ---------- TABLET ---------- */

@media (max-width: 1000px) {
  .appointmentHeroGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .appointmentHeroContent {
    max-width: 720px;
  }

  .appointmentHeroVisual {
    max-width: 720px;
    width: 100%;
    margin: 0 auto;
  }

  .appointmentHeroImage {
    height: 450px;
  }

  .appointmentFloatingCard {
    left: 25px;
  }

  .appointmentIntroGrid {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .appointmentIntroText {
    padding-top: 0;
  }

  .appointmentSectionHeading {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .appointmentSectionHeading > p {
    margin-left: 0;
  }

  .appointmentFormLayout {
    grid-template-columns: 1fr;
  }

  .appointmentSide {
    grid-template-columns: repeat(3, 1fr);
  }

  .appointmentCTACard {
    padding: 50px;
  }
}

/* ---------- MOBILE ---------- */

@media (max-width: 700px) {
  .appointmentContainer {
    width: min(100% - 28px, 620px);
  }

  .novaAppointmentHero {
    min-height: auto;
    padding: 90px 0 75px;
  }

  .appointmentHeroGrid {
    gap: 45px;
  }

  .appointmentHeroContent h1 {
    font-size: clamp(43px, 13vw, 62px);
  }

  .appointmentHeroContent > p {
    font-size: 14px;
    line-height: 1.75;
  }

  .appointmentHeroActions {
    flex-direction: column;
    align-items: stretch;
  }

  .appointmentPrimaryBtn {
    width: 100%;
  }

  .appointmentPhoneBtn {
    justify-content: center;
  }

  .appointmentTrustRow {
    gap: 13px 18px;
    margin-top: 34px;
  }

  .appointmentHeroImage {
    height: 360px;
    border-radius: 22px;
  }

  .appointmentFloatingCard {
    left: 12px;
    right: 12px;
    bottom: 15px;
    min-width: 0;
  }

  .appointmentIntro {
    padding: 75px 0 65px;
  }

  .appointmentIntro h2,
  .appointmentSectionHeading h2 {
    font-size: 40px;
  }

  .appointmentInfoCards {
    grid-template-columns: 1fr;
  }

  .appointmentFormSection {
    padding: 75px 0 80px;
  }

  .appointmentSectionHeading {
    margin-bottom: 35px;
  }

  .appointmentFormCard {
    padding: 24px 18px;
    border-radius: 22px;
  }

  .formRow {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .appointmentSide {
    grid-template-columns: 1fr;
  }

  .appointmentSideCard {
    padding: 24px;
  }

  .appointmentSuccess {
    min-height: 470px;
    padding: 20px;
  }

  .appointmentSuccess h3 {
    font-size: 32px;
  }

  .appointmentFinalCTA {
    padding: 60px 0 80px;
  }

  .appointmentCTACard {
    flex-direction: column;
    align-items: flex-start;
    padding: 38px 25px;
    border-radius: 24px;
  }

  .appointmentCTAButton {
    width: 100%;
    justify-content: center;
  }
}

/* ---------- SMALL MOBILE ---------- */

@media (max-width: 420px) {
  .appointmentHeroContent h1 {
    font-size: 42px;
  }

  .appointmentHeroImage {
    height: 310px;
  }

  .appointmentTrustRow {
    flex-direction: column;
    align-items: flex-start;
  }

  .appointmentInfoCard {
    padding: 16px;
  }

  .appointmentIntro h2,
  .appointmentSectionHeading h2 {
    font-size: 35px;
  }

  .appointmentFormCard {
    padding: 20px 15px;
  }
}

/* ---------- REDUCED MOTION ---------- */

@media (prefers-reduced-motion: reduce) {
  .novaAppointmentHero *,
  .appointmentHeroGlow,
  .appointmentFloatingCard,
  .appointmentCTACard::before,
  .successIcon {
    animation: none !important;
    transition: none !important;
  }
}

/* =========================================================
   NOVADENT — CONTACT PAGE
   Premium / Interactive / Responsive
   ========================================================= */

.novaContactPage {
  --contact-navy: #0b2545;
  --contact-teal: #1f8a8a;
  --contact-soft: #55b8b0;
  --contact-cream: #f7fafc;
  --contact-mint: #eaf5f4;
  --contact-text: #183b56;
  --contact-muted: #64748b;

  background: var(--contact-cream);
  color: var(--contact-text);
  overflow: hidden;
}

/* ================= COMMON ================= */

.contactContainer {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.contactOverline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--contact-teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.contactSectionIntro small,
.contactFormHeader small,
.contactLocationContent small {
  display: block;
  margin-top: 12px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

/* ================= HERO ================= */

.novaContactHero {
  position: relative;
  min-height: 690px;
  display: flex;
  align-items: center;
  padding: 110px 0 90px;
  color: #fff;

  background:
    radial-gradient(
      circle at 82% 18%,
      rgba(85, 184, 176, 0.2),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #071c34 0%,
      #0b2545 55%,
      #123d58 100%
    );
}

.contactHeroGlow {
  position: absolute;
  width: 520px;
  height: 520px;
  right: -210px;
  top: -180px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.12);
  filter: blur(18px);
  animation: contactHeroGlow 8s ease-in-out infinite;
}

.contactHeroGrid {
  display: grid;
  grid-template-columns: 1fr 0.95fr;
  align-items: center;
  gap: 80px;
}

.contactHeroContent {
  animation: contactHeroContentIn 0.85s ease both;
}

.contactEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 25px;
  color: #8fe1da;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.contactHeroContent h1 {
  max-width: 650px;
  margin: 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.98;
  letter-spacing: -0.045em;
  font-weight: 500;
}

.contactHeroContent h1 em {
  display: block;
  color: #79d2ca;
  font-style: italic;
  font-weight: 500;
}

.contactHeroContent > p {
  max-width: 570px;
  margin: 28px 0 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 16px;
  line-height: 1.8;
}

.contactHeroActions {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 35px;
}

.contactPrimaryBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 54px;
  padding: 0 24px;
  border-radius: 999px;
  background: var(--contact-soft);
  color: #08243c;
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.contactPrimaryBtn:hover {
  transform: translateY(-4px);
  background: #79d2ca;
  box-shadow: 0 18px 40px rgba(85, 184, 176, 0.25);
}

.contactPhoneLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #fff;
  text-decoration: none;
  font-size: 13px;
  font-weight: 700;
  transition: color 0.25s ease;
}

.contactPhoneLink:hover {
  color: #79d2ca;
}

/* ================= HERO IMAGE ================= */

.contactHeroVisual {
  position: relative;
  animation: contactHeroVisualIn 1s 0.15s ease both;
}

.contactHeroImage {
  position: relative;
  height: 500px;
  overflow: hidden;
  border-radius: 30px;
  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.3);
}

.contactHeroImage::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      transparent 48%,
      rgba(4, 22, 40, 0.42)
    );
  pointer-events: none;
}

.contactHeroImage img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;

  transition: transform 1s ease;
}

.contactHeroVisual:hover .contactHeroImage img {
  transform: scale(1.06);
}

.contactHeroFloating {
  position: absolute;
  left: -35px;
  bottom: 30px;

  display: flex;
  align-items: center;
  gap: 13px;

  min-width: 245px;
  padding: 16px 18px;

  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 18px;

  background: rgba(10, 37, 69, 0.9);
  backdrop-filter: blur(16px);

  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.25);

  animation: contactFloatingCard 4s ease-in-out infinite;
}

.contactFloatingIcon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;

  display: grid;
  place-items: center;

  border-radius: 13px;
  background: rgba(85, 184, 176, 0.17);
  color: #79d2ca;
}

.contactHeroFloating strong,
.contactHeroFloating span {
  display: block;
}

.contactHeroFloating strong {
  color: #fff;
  font-size: 12px;
}

.contactHeroFloating span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
}

/* ================= CONTACT DETAILS ================= */

.contactDetailsSection {
  padding: 115px 0 110px;
  background: #fff;
}

.contactSectionIntro {
  display: grid;
  grid-template-columns: 1fr 0.8fr;
  align-items: end;
  gap: 80px;
  margin-bottom: 55px;
}

.contactSectionIntro h2,
.contactFormHeader h2,
.contactLocationContent h2 {
  max-width: 570px;
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(40px, 5vw, 62px);
  line-height: 1.02;
  letter-spacing: -0.04em;
  font-weight: 500;
}

.contactSectionIntro h2 em,
.contactFormHeader h2 em,
.contactLocationContent h2 em {
  color: var(--contact-teal);
  font-style: italic;
}

.contactSectionIntro > p {
  max-width: 470px;
  margin: 0 0 4px auto;
  color: var(--contact-muted);
  font-size: 14px;
  line-height: 1.85;
}

.contactInfoGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.contactInfoCard {
  position: relative;
  overflow: hidden;
  min-height: 235px;
  padding: 28px;

  display: flex;
  flex-direction: column;

  border: 1px solid #e4edf1;
  border-radius: 22px;

  background: #fbfdfe;
  color: var(--contact-text);
  text-decoration: none;

  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.contactInfoCard::after {
  content: "";
  position: absolute;
  width: 150px;
  height: 150px;
  right: -80px;
  bottom: -80px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.1);
  transition: transform 0.5s ease;
}

.contactInfoCard:hover {
  transform: translateY(-8px);
  border-color: rgba(31, 138, 138, 0.3);
  box-shadow: 0 22px 50px rgba(11, 37, 69, 0.09);
}

.contactInfoCard:hover::after {
  transform: scale(1.45);
}

.contactInfoNumber {
  color: #a2b0bc;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.contactInfoIcon {
  width: 48px;
  height: 48px;
  margin-top: 22px;

  display: grid;
  place-items: center;

  border-radius: 15px;
  background: var(--contact-mint);
  color: var(--contact-teal);

  transition:
    transform 0.35s ease,
    background 0.35s ease;
}

.contactInfoCard:hover .contactInfoIcon {
  transform: rotate(-6deg) scale(1.08);
  background: #dcefed;
}

.contactInfoContent {
  position: relative;
  z-index: 2;
  margin-top: 20px;
}

.contactInfoContent > span {
  color: var(--contact-teal);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.contactInfoContent h3 {
  margin: 7px 0 5px;
  color: var(--contact-navy);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 22px;
  line-height: 1.15;
  font-weight: 500;
  word-break: break-word;
}

.contactInfoContent p {
  margin: 0;
  color: var(--contact-muted);
  font-size: 11px;
  line-height: 1.6;
}

.contactInfoArrow {
  position: absolute;
  z-index: 2;
  right: 24px;
  bottom: 25px;
  color: var(--contact-teal);

  transition: transform 0.3s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  transform: translate(4px, -4px);
}

/* ================= FORM SECTION ================= */

.contactFormSection {
  padding: 105px 0 120px;
  background:
    linear-gradient(
      180deg,
      #f7fafc 0%,
      #edf7f6 100%
    );
}

.contactFormHeader {
  margin-bottom: 50px;
}

.contactFormHeader p {
  max-width: 560px;
  margin: 22px 0 0;
  color: var(--contact-muted);
  font-size: 14px;
  line-height: 1.8;
}

.contactFormLayout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(290px, 0.75fr);
  gap: 28px;
  align-items: start;
}

/* ================= FORM CARD ================= */

.contactFormCard {
  min-height: 590px;
  padding: 42px;

  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 28px;

  background: #fff;
  box-shadow: 0 25px 65px rgba(11, 37, 69, 0.08);
}

.contactFormRow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.contactField {
  margin-bottom: 21px;
}

.contactField label {
  display: block;
  margin-bottom: 9px;

  color: var(--contact-navy);
  font-size: 11px;
  font-weight: 800;
}

.contactField input,
.contactField textarea {
  width: 100%;
  border: 1px solid #dce7ec;
  border-radius: 13px;
  outline: none;

  background: #fbfdfe;
  color: var(--contact-text);

  font-family: inherit;
  font-size: 13px;

  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.contactField input {
  height: 52px;
  padding: 0 15px;
}

.contactField textarea {
  min-height: 145px;
  padding: 15px;
  resize: vertical;
}

.contactField input::placeholder,
.contactField textarea::placeholder {
  color: #9aaabd;
}

.contactField input:focus,
.contactField textarea:focus {
  border-color: var(--contact-teal);
  background: #fff;
  box-shadow: 0 0 0 4px rgba(31, 138, 138, 0.09);
}

.contactSubmitBtn {
  width: 100%;
  min-height: 56px;

  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;

  border: 0;
  border-radius: 14px;

  background: var(--contact-navy);
  color: #fff;

  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}

.contactSubmitBtn:hover {
  transform: translateY(-3px);
  background: var(--contact-teal);
  box-shadow: 0 16px 35px rgba(11, 37, 69, 0.18);
}

.contactSubmitBtn svg {
  transition: transform 0.3s ease;
}

.contactSubmitBtn:hover svg {
  transform: translate(3px, -3px);
}

.contactFormNote {
  margin: 14px 0 0;
  color: #94a3b8;
  text-align: center;
  font-size: 10px;
  line-height: 1.6;
}

/* ================= SIDE PANEL ================= */

.contactSidePanel {
  display: grid;
  gap: 16px;
}

.contactSideCard {
  padding: 28px;

  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 22px;

  background: #fff;
  box-shadow: 0 14px 35px rgba(11, 37, 69, 0.05);

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.contactSideCard:hover {
  transform: translateY(-6px);
  box-shadow: 0 22px 45px rgba(11, 37, 69, 0.09);
}

.contactSideTop {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--contact-teal);
}

.contactSideTop span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.contactSideCard h3 {
  margin: 18px 0 20px;

  color: var(--contact-navy);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 29px;
  line-height: 1.08;
  font-weight: 500;
}

.contactSideCard h3 em {
  color: var(--contact-teal);
  font-style: italic;
}

.contactHours {
  border-top: 1px solid #e8eef2;
}

.contactHours div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  padding: 13px 0;
  border-bottom: 1px solid #e8eef2;
}

.contactHours span {
  color: var(--contact-muted);
  font-size: 10px;
}

.contactHours strong {
  color: var(--contact-navy);
  font-size: 10px;
}

.contactAppointmentCard {
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(85, 184, 176, 0.2),
      transparent 35%
    ),
    linear-gradient(145deg, #0b2545, #123d58);
  color: #fff;
}

.contactAppointmentCard > svg {
  color: #79d2ca;
}

.contactAppointmentCard > span {
  display: block;
  margin-top: 18px;
  color: #79d2ca;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.15em;
}

.contactAppointmentCard h3 {
  color: #fff;
  margin-bottom: 10px;
}

.contactAppointmentCard h3 em {
  color: #79d2ca;
}

.contactAppointmentCard p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 11px;
  line-height: 1.7;
}

.contactAppointmentBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  margin-top: 22px;
  padding: 12px 17px;

  border-radius: 999px;
  background: #55b8b0;
  color: #08243c;

  text-decoration: none;
  font-size: 11px;
  font-weight: 800;

  transition: all 0.3s ease;
}

.contactAppointmentBtn:hover {
  transform: translateY(-3px);
  background: #79d2ca;
}

/* ================= SUCCESS ================= */

.contactSuccess {
  min-height: 500px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  padding: 35px;
  text-align: center;

  animation: contactSuccessIn 0.55s ease both;
}

.contactSuccessIcon {
  width: 82px;
  height: 82px;

  display: grid;
  place-items: center;

  border-radius: 50%;
  background: var(--contact-mint);
  color: var(--contact-teal);

  animation: contactSuccessPulse 2s ease-in-out infinite;
}

.contactSuccess > span {
  margin-top: 24px;
  color: var(--contact-teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.contactSuccess h3 {
  margin: 13px 0 9px;

  color: var(--contact-navy);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 36px;
  font-weight: 500;
}

.contactSuccess p {
  max-width: 470px;
  margin: 0 auto;

  color: var(--contact-muted);
  font-size: 13px;
  line-height: 1.8;
}

.contactAgainBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  margin-top: 26px;
  padding: 13px 19px;

  border: 1px solid #dce7ec;
  border-radius: 999px;

  background: #fff;
  color: var(--contact-navy);

  cursor: pointer;
  font-family: inherit;
  font-size: 11px;
  font-weight: 800;

  transition: all 0.3s ease;
}

.contactAgainBtn:hover {
  transform: translateY(-3px);
  border-color: var(--contact-teal);
  color: var(--contact-teal);
}

/* ================= LOCATION ================= */

.contactLocationSection {
  padding: 110px 0;
  background: #fff;
}

.contactLocationGrid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 80px;
  align-items: center;
}

.contactLocationContent p {
  max-width: 500px;
  margin: 24px 0 0;

  color: var(--contact-muted);
  font-size: 14px;
  line-height: 1.85;
}

.contactLocationAddress {
  display: flex;
  align-items: flex-start;
  gap: 13px;

  margin-top: 30px;
  padding: 18px;

  border: 1px solid #e4edf1;
  border-radius: 17px;
  background: #fbfdfe;
}

.contactLocationAddress svg {
  flex: 0 0 auto;
  color: var(--contact-teal);
}

.contactLocationAddress strong,
.contactLocationAddress span {
  display: block;
}

.contactLocationAddress strong {
  color: var(--contact-navy);
  font-size: 12px;
}

.contactLocationAddress span {
  margin-top: 5px;
  color: var(--contact-muted);
  font-size: 11px;
  line-height: 1.6;
}

.contactMapLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  margin-top: 20px;
  color: var(--contact-teal);

  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
}

.contactMapLink svg {
  transition: transform 0.25s ease;
}

.contactMapLink:hover svg {
  transform: translate(3px, -3px);
}

/* ================= MAP VISUAL ================= */

.contactMapVisual {
  height: 450px;
  overflow: hidden;
  border-radius: 28px;

  background:
    linear-gradient(
      135deg,
      #dcefed,
      #eef7f6
    );

  box-shadow: 0 25px 60px rgba(11, 37, 69, 0.09);
}

.contactMapPattern {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background:
    linear-gradient(
      35deg,
      transparent 48%,
      rgba(31, 138, 138, 0.13) 49%,
      rgba(31, 138, 138, 0.13) 51%,
      transparent 52%
    ),
    linear-gradient(
      120deg,
      transparent 47%,
      rgba(11, 37, 69, 0.08) 48%,
      rgba(11, 37, 69, 0.08) 50%,
      transparent 51%
    ),
    #eaf5f4;
}

.mapGridLines {
  position: absolute;
  inset: 0;

  background-image:
    linear-gradient(
      rgba(31, 138, 138, 0.08) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(31, 138, 138, 0.08) 1px,
      transparent 1px
    );

  background-size: 45px 45px;
}

.mapPinLarge {
  position: absolute;
  left: 50%;
  top: 50%;

  width: 78px;
  height: 78px;

  display: grid;
  place-items: center;

  border: 8px solid rgba(255, 255, 255, 0.7);
  border-radius: 50% 50% 50% 0;

  background: var(--contact-teal);
  color: #fff;

  transform: translate(-50%, -50%) rotate(-45deg);

  box-shadow:
    0 20px 35px rgba(31, 138, 138, 0.25);

  animation: contactMapPin 2.5s ease-in-out infinite;
}

.mapPinLarge svg {
  transform: rotate(45deg);
}

.mapLocationLabel {
  position: absolute;
  left: 50%;
  top: calc(50% + 65px);

  display: flex;
  flex-direction: column;
  align-items: center;

  transform: translateX(-50%);
  text-align: center;
}

.mapLocationLabel strong {
  color: var(--contact-navy);
  font-size: 12px;
  letter-spacing: 0.1em;
}

.mapLocationLabel span {
  margin-top: 3px;
  color: var(--contact-muted);
  font-size: 10px;
}

/* ================= FINAL CTA ================= */

.contactFinalCTA {
  padding: 80px 0 110px;
  background: #fff;
}

.contactCTACard {
  position: relative;
  overflow: hidden;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;

  padding: 60px 65px;
  border-radius: 30px;

  background:
    radial-gradient(
      circle at 85% 10%,
      rgba(85, 184, 176, 0.22),
      transparent 32%
    ),
    linear-gradient(135deg, #0b2545, #123d58);

  color: #fff;
}

.contactCTACard::before {
  content: "";

  position: absolute;
  width: 280px;
  height: 280px;

  right: -100px;
  bottom: -170px;

  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;

  animation: contactCTAOrbit 8s linear infinite;
}

.contactCTACard > div:first-child {
  position: relative;
  z-index: 2;
}

.contactCTACard > div:first-child > span {
  color: #79d2ca;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.17em;
}

.contactCTACard h2 {
  max-width: 650px;
  margin: 13px 0 8px;

  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(36px, 4vw, 55px);
  line-height: 1.03;
  font-weight: 500;
}

.contactCTACard h2 em {
  color: #79d2ca;
  font-style: italic;
}

.contactCTACard p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 13px;
}

.contactCTAActions {
  position: relative;
  z-index: 2;

  display: flex;
  align-items: center;
  gap: 12px;
}

.contactCTASecondary,
.contactCTAButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-height: 51px;
  padding: 0 20px;

  border-radius: 999px;

  text-decoration: none;
  font-size: 11px;
  font-weight: 800;

  transition: all 0.3s ease;
}

.contactCTASecondary {
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #fff;
}

.contactCTASecondary:hover {
  border-color: #79d2ca;
  color: #79d2ca;
  transform: translateY(-3px);
}

.contactCTAButton {
  background: #55b8b0;
  color: #08243c;
}

.contactCTAButton:hover {
  background: #79d2ca;
  transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(85, 184, 176, 0.22);
}

/* ================= ANIMATIONS ================= */

@keyframes contactHeroContentIn {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes contactHeroVisualIn {
  from {
    opacity: 0;
    transform: translateX(40px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes contactHeroGlow {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.65;
  }

  50% {
    transform: scale(1.16);
    opacity: 1;
  }
}

@keyframes contactFloatingCard {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-9px);
  }
}

@keyframes contactSuccessIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(20px);
  }

  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes contactSuccessPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(31, 138, 138, 0.2);
  }

  50% {
    box-shadow: 0 0 0 16px rgba(31, 138, 138, 0);
  }
}

@keyframes contactMapPin {
  0%,
  100% {
    transform: translate(-50%, -50%) rotate(-45deg) translateY(0);
  }

  50% {
    transform: translate(-50%, -50%) rotate(-45deg) translateY(-8px);
  }
}

@keyframes contactCTAOrbit {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

/* ================= TABLET ================= */

@media (max-width: 1000px) {
  .contactHeroGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .contactHeroContent {
    max-width: 720px;
  }

  .contactHeroVisual {
