/* =========================================================
   NOVADENT CONTACT PAGE — PREMIUM HOVER & ANIMATIONS
   ========================================================= */

/* ---------- CONTACT INFO CARDS ---------- */

.contactInfoCard {
  position: relative;
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
  overflow: hidden;
}

.contactInfoCard::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 70%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.22),
    transparent
  );
  transform: skewX(-20deg);
  transition: left 0.65s ease;
  pointer-events: none;
}

.contactInfoCard:hover {
  transform: translateY(-7px);
  box-shadow: 0 20px 45px rgba(11, 37, 69, 0.13);
  border-color: rgba(31, 138, 138, 0.35);
}

.contactInfoCard:hover::before {
  left: 140%;
}

.contactInfoIcon {
  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.contactInfoCard:hover .contactInfoIcon {
  transform: translateY(-3px) scale(1.08);
  background: #1f8a8a;
  color: #fff;
}

.contactInfoArrow {
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  transform: translate(4px, -4px);
  color: #1f8a8a;
}

/* ---------- CONTACT HERO IMAGE ---------- */

.contactHeroImage {
  overflow: hidden;
  border-radius: inherit;
}

.contactHeroImage img {
  transition:
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.5s ease;
}

.contactHeroImage:hover img {
  transform: scale(1.045);
  filter: brightness(1.04);
}

/* ---------- FLOATING HERO ELEMENT ---------- */

.contactHeroFloating {
  animation: contactFloat 4s ease-in-out infinite;
}

@keyframes contactFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-9px);
  }
}

/* ---------- PRIMARY BUTTONS ---------- */

.contactPrimaryBtn,
.contactAppointmentBtn,
.contactCTAButton,
.contactCTASecondary,
.contactSubmitBtn {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.contactPrimaryBtn::before,
.contactAppointmentBtn::before,
.contactCTAButton::before,
.contactSubmitBtn::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 80%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.25),
    transparent
  );
  transform: skewX(-20deg);
  transition: left 0.6s ease;
}

.contactPrimaryBtn:hover,
.contactAppointmentBtn:hover,
.contactCTAButton:hover,
.contactSubmitBtn:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 30px rgba(31, 138, 138, 0.22);
}

.contactPrimaryBtn:hover::before,
.contactAppointmentBtn:hover::before,
.contactCTAButton:hover::before,
.contactSubmitBtn:hover::before {
  left: 140%;
}

/* ---------- PHONE LINK ---------- */

.contactPhoneLink {
  transition:
    color 0.3s ease,
    transform 0.3s ease;
}

.contactPhoneLink:hover {
  color: #1f8a8a;
  transform: translateX(4px);
}

/* ---------- FORM FIELDS ---------- */

.contactField input,
.contactField textarea {
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

.contactField input:focus,
.contactField textarea:focus {
  outline: none;
  border-color: #1f8a8a !important;
  background: #ffffff;
  box-shadow:
    0 0 0 4px rgba(31, 138, 138, 0.09),
    0 8px 24px rgba(11, 37, 69, 0.05);
}

/* ---------- SIDE CARD ---------- */

.contactSideCard {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.contactSideCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.11);
}

/* ---------- MAP ---------- */

.contactMapVisual {
  position: relative;
  overflow: hidden;
  transition:
    box-shadow 0.4s ease,
    border-color 0.4s ease;
}

.contactMapVisual:hover {
  box-shadow: 0 20px 50px rgba(11, 37, 69, 0.13);
  border-color: rgba(31, 138, 138, 0.3);
}

.contactMapPattern {
  transition: transform 0.8s ease;
}

.contactMapVisual:hover .contactMapPattern {
  transform: scale(1.025);
}

.mapPinLarge {
  animation: mapPinPulse 2.2s ease-in-out infinite;
}

@keyframes mapPinPulse {
  0%,
  100% {
    transform: translateY(0) scale(1);
  }

  50% {
    transform: translateY(-4px) scale(1.05);
  }
}

/* ---------- MAP LINK ---------- */

.contactMapLink {
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.contactMapLink:hover {
  transform: translateX(5px);
  color: #1f8a8a;
}

/* ---------- FINAL CTA ---------- */

.contactCTACard {
  position: relative;
  overflow: hidden;
}

.contactCTACard::after {
  content: "";
  position: absolute;
  width: 220px;
  height: 220px;
  right: -100px;
  top: -100px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  pointer-events: none;
  transition: transform 0.7s ease;
}

.contactCTACard:hover::after {
  transform: scale(1.25);
}

/* ---------- CTA SECONDARY BUTTON ---------- */

.contactCTASecondary {
  transition:
    transform 0.3s ease,
    background 0.3s ease,
    border-color 0.3s ease;
}

.contactCTASecondary:hover {
  transform: translateY(-3px);
}

/* ---------- CONTACT PAGE ENTRANCE ANIMATION ---------- */

.novaContactHero,
.contactDetailsSection,
.contactFormSection,
.contactLocationSection,
.contactFinalCTA {
  animation: contactSectionReveal 0.8s ease both;
}

.contactDetailsSection {
  animation-delay: 0.08s;
}

.contactFormSection {
  animation-delay: 0.16s;
}

.contactLocationSection {
  animation-delay: 0.24s;
}

.contactFinalCTA {
  animation-delay: 0.32s;
}

@keyframes contactSectionReveal {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ---------- MOBILE ---------- */

@media (max-width: 600px) {
  .contactInfoCard:hover {
    transform: translateY(-4px);
  }

  .contactSideCard:hover {
    transform: translateY(-3px);
  }

  .contactPrimaryBtn:hover,
  .contactAppointmentBtn:hover,
  .contactCTAButton:hover,
  .contactCTASecondary:hover,
  .contactSubmitBtn:hover {
    transform: translateY(-2px);
  }

  .contactHeroFloating {
    animation-duration: 5s;
  }
}

/* ---------- REDUCED MOTION ---------- */

@media (prefers-reduced-motion: reduce) {
  .contactHeroFloating,
  .mapPinLarge {
    animation: none !important;
  }

  .novaContactHero,
  .contactDetailsSection,
  .contactFormSection,
  .contactLocationSection,
  .contactFinalCTA {
    animation: none !important;
  }

  .contactInfoCard,
  .contactSideCard,
  .contactPrimaryBtn,
  .contactAppointmentBtn,
  .contactCTAButton,
  .contactCTASecondary,
  .contactSubmitBtn {
    transition: none !important;
  }
}

/* =========================================================
   NOVADENT GALLERY — PREMIUM DESIGN
   ========================================================= */

.novaGalleryPage {
  background: #f7fafc;
  overflow: hidden;
}

/* =========================================================
   HERO
   ========================================================= */

.novaGalleryHero {
  position: relative;
  min-height: 560px;
  display: flex;
  align-items: center;
  background:
    linear-gradient(
      115deg,
      rgba(7, 30, 55, 0.97),
      rgba(11, 37, 69, 0.88),
      rgba(31, 138, 138, 0.72)
    ),
    url("https://images.unsplash.com/photo-1606811971618-4486d14f3f99?auto=format&fit=crop&w=1800&q=85")
      center / cover;
  color: #fff;
  overflow: hidden;
}

.galleryHeroGlow {
  position: absolute;
  width: 420px;
  height: 420px;
  right: -120px;
  top: -130px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.18);
  filter: blur(5px);
  animation: galleryGlowMove 7s ease-in-out infinite;
}

@keyframes galleryGlowMove {
  0%,
  100% {
    transform: translate(0, 0);
  }

  50% {
    transform: translate(-30px, 25px);
  }
}

.galleryHeroContent {
  position: relative;
  z-index: 2;
  max-width: 820px;
  padding-top: 80px;
  padding-bottom: 100px;
}

.galleryEyebrow,
.gallerySectionEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: #55b8b0;
}

.galleryEyebrowLine {
  width: 34px;
  height: 1px;
  background: #55b8b0;
}

.galleryHeroContent h1 {
  max-width: 800px;
  margin: 22px 0 22px;
  font-family: "Playfair Display", serif;
  font-size: clamp(48px, 7vw, 88px);
  line-height: 0.98;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.galleryHeroContent h1 span {
  color: #7bd0c8;
  font-style: italic;
}

.galleryHeroContent p {
  max-width: 590px;
  margin: 0;
  color: rgba(255, 255, 255, 0.78);
  font-size: 17px;
  line-height: 1.8;
}

.galleryHeroBottom {
  position: absolute;
  bottom: 28px;
  left: 50%;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 12px;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.galleryScrollLine {
  width: 45px;
  height: 1px;
  background: rgba(255, 255, 255, 0.4);
}

/* =========================================================
   MAIN GALLERY
   ========================================================= */

.novaGallerySection {
  padding: 110px 0 120px;
  background: #f7fafc;
}

.gallerySectionHeader {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 70px;
  align-items: end;
  margin-bottom: 48px;
}

.gallerySectionHeader h2 {
  max-width: 650px;
  margin: 15px 0 0;
  font-family: "Playfair Display", serif;
  font-size: clamp(38px, 5vw, 64px);
  line-height: 1.02;
  font-weight: 500;
  color: #0b2545;
  letter-spacing: -0.035em;
}

.gallerySectionHeader h2 span {
  color: #1f8a8a;
  font-style: italic;
}

.gallerySectionHeader p {
  max-width: 470px;
  margin: 0;
  color: #64748b;
  font-size: 15px;
  line-height: 1.85;
}

/* =========================================================
   FILTERS
   ========================================================= */

.galleryFilters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 34px;
}

.galleryFilter {
  position: relative;
  min-height: 42px;
  padding: 0 20px;
  border: 1px solid rgba(11, 37, 69, 0.12);
  border-radius: 999px;
  background: #fff;
  color: #64748b;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition:
    color 0.3s ease,
    background 0.3s ease,
    border-color 0.3s ease,
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.galleryFilter:hover {
  color: #1f8a8a;
  border-color: rgba(31, 138, 138, 0.35);
  transform: translateY(-2px);
}

.galleryFilter.active {
  background: #0b2545;
  border-color: #0b2545;
  color: #fff;
  box-shadow: 0 8px 20px rgba(11, 37, 69, 0.16);
}

/* =========================================================
   PREMIUM MASONRY GRID
   ========================================================= */

.novaGalleryGrid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  grid-auto-rows: 180px;
  gap: 16px;
}

.galleryCard {
  position: relative;
  display: block;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 20px;
  background: #dfe9ec;
  overflow: hidden;
  cursor: pointer;
  isolation: isolate;
  text-align: left;
  animation: galleryCardReveal 0.65s ease both;
}

@keyframes galleryCardReveal {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* GRID POSITIONS */

.galleryCard-large {
  grid-column: span 6;
  grid-row: span 3;
}

.galleryCard-normal {
  grid-column: span 3;
  grid-row: span 2;
}

.galleryCard-tall {
  grid-column: span 3;
  grid-row: span 3;
}

/* IMAGE */

.galleryCard img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition:
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.5s ease;
}

.galleryCard:hover img {
  transform: scale(1.09);
  filter: saturate(1.08);
}

/* DARK OVERLAY */

.galleryCardOverlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      180deg,
      transparent 35%,
      rgba(5, 19, 35, 0.78) 100%
    );
  opacity: 0.72;
  transition: opacity 0.4s ease;
}

.galleryCard:hover .galleryCardOverlay {
  opacity: 0.9;
}

/* CARD CONTENT */

.galleryCardContent {
  position: absolute;
  right: 22px;
  bottom: 20px;
  left: 22px;
  z-index: 2;
  color: #fff;
  transform: translateY(8px);
  transition: transform 0.4s ease;
}

.galleryCard:hover .galleryCardContent {
  transform: translateY(0);
}

.galleryCardContent > span {
  display: block;
  margin-bottom: 7px;
  color: #7bd0c8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.galleryCardContent h3 {
  max-width: 230px;
  margin: 0;
  font-family: "Playfair Display", serif;
  font-size: 22px;
  line-height: 1.15;
  font-weight: 500;
}

.galleryViewIcon {
  position: absolute;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(8px);
  opacity: 0;
  transform: translateY(8px) scale(0.85);
  transition:
    opacity 0.35s ease,
    transform 0.35s ease,
    background 0.35s ease;
}

.galleryCard:hover .galleryViewIcon {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.galleryCard:hover .galleryViewIcon:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* =========================================================
   EMPTY STATE
   ========================================================= */

.galleryEmpty {
  padding: 80px 20px;
  text-align: center;
}

.galleryEmpty h3 {
  margin: 0 0 8px;
  color: #0b2545;
  font-family: "Playfair Display", serif;
  font-size: 30px;
}

.galleryEmpty p {
  margin: 0;
  color: #64748b;
}

/* =========================================================
   CTA
   ========================================================= */

.galleryFinalCTA {
  padding: 0 0 110px;
  background: #f7fafc;
}

.galleryCTACard {
  position: relative;
  min-height: 400px;
  display: flex;
  align-items: center;
  padding: 70px;
  border-radius: 28px;
  background:
    linear-gradient(
      115deg,
      #0b2545 0%,
      #12385e 52%,
      #1f8a8a 100%
    );
  overflow: hidden;
  color: #fff;
}

.galleryCTACard::before {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  right: -130px;
  top: -150px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 50%;
}

.galleryCTACard::after {
  content: "";
  position: absolute;
  width: 230px;
  height: 230px;
  right: 70px;
  bottom: -150px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
}

.galleryCTAContent {
  position: relative;
  z-index: 2;
  max-width: 650px;
}

.galleryCTAContent > span {
  color: #7bd0c8;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.17em;
}

.galleryCTAContent h2 {
  margin: 17px 0;
  font-family: "Playfair Display", serif;
  font-size: clamp(40px, 5vw, 62px);
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.03em;
}

.galleryCTAContent p {
  max-width: 500px;
  margin: 0 0 28px;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.75;
}

.galleryCTAButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 50px;
  padding: 0 25px;
  border-radius: 999px;
  background: #fff;
  color: #0b2545;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.galleryCTAButton:hover {
  transform: translateY(-3px);
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.18);
}

.galleryCTADecoration {
  position: absolute;
  right: 110px;
  top: 50%;
  z-index: 1;
  color: rgba(255, 255, 255, 0.15);
  font-size: 180px;
  line-height: 1;
  transform: translateY(-50%);
  animation: galleryStarFloat 5s ease-in-out infinite;
}

@keyframes galleryStarFloat {
  0%,
  100% {
    transform: translateY(-50%) rotate(0deg);
  }

  50% {
    transform: translateY(calc(-50% - 12px)) rotate(8deg);
  }
}

/* =========================================================
   LIGHTBOX
   ========================================================= */

.galleryLightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 70px;
  background: rgba(4, 14, 27, 0.94);
  backdrop-filter: blur(14px);
  animation: lightboxFadeIn 0.3s ease both;
}

@keyframes lightboxFadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.galleryLightboxContent {
  width: min(100%, 1050px);
  animation: lightboxImageIn 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes lightboxImageIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.96);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.galleryLightboxImageWrap {
  position: relative;
  display: flex;
  justify-content: center;
  max-height: calc(100vh - 170px);
  overflow: hidden;
  border-radius: 16px;
  background: #071523;
}

.galleryLightboxImageWrap img {
  display: block;
  width: auto;
  max-width: 100%;
  max-height: calc(100vh - 170px);
  object-fit: contain;
}

.galleryLightboxInfo {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 18px;
  color: #fff;
}

.galleryLightboxInfo span {
  color: #7bd0c8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.galleryLightboxInfo h3 {
  margin: 5px 0 0;
  font-family: "Playfair Display", serif;
  font-size: 24px;
  font-weight: 500;
}

.galleryLightboxCounter {
  flex-shrink: 0;
  color: rgba(255, 255, 255, 0.55);
  font-size: 12px;
}

/* CLOSE BUTTON */

.galleryLightboxClose {
  position: absolute;
  top: 22px;
  right: 25px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  cursor: pointer;
  transition:
    background 0.3s ease,
    transform 0.3s ease;
}

.galleryLightboxClose:hover {
  background: rgba(255, 255, 255, 0.17);
  transform: rotate(90deg);
}

/* ARROWS */

.galleryLightboxArrow {
  position: absolute;
  top: 50%;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  cursor: pointer;
  transform: translateY(-50%);
  transition:
    background 0.3s ease,
    transform 0.3s ease;
}

.galleryLightboxArrow:hover {
  background: rgba(31, 138, 138, 0.75);
}

.galleryLightboxPrev {
  left: 22px;
}

.galleryLightboxNext {
  right: 22px;
}

.galleryLightboxPrev:hover {
  transform: translate(-3px, -50%);
}

.galleryLightboxNext:hover {
  transform: translate(3px, -50%);
}

/* =========================================================
   RESPONSIVE — TABLET
   ========================================================= */

@media (max-width: 1000px) {
  .novaGalleryGrid {
    grid-template-columns: repeat(6, 1fr);
    grid-auto-rows: 190px;
  }

  .galleryCard-large {
    grid-column: span 6;
    grid-row: span 3;
  }

  .galleryCard-normal {
    grid-column: span 3;
    grid-row: span 2;
  }

  .galleryCard-tall {
    grid-column: span 3;
    grid-row: span 3;
  }

  .gallerySectionHeader {
    gap: 40px;
  }

  .galleryCTADecoration {
    right: 30px;
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 700px) {
  .novaGalleryHero {
    min-height: 500px;
  }

  .galleryHeroContent {
    padding-top: 60px;
    padding-bottom: 80px;
  }

  .galleryHeroContent h1 {
    font-size: clamp(43px, 13vw, 62px);
  }

  .galleryHeroContent p {
    font-size: 15px;
  }

  .galleryHeroBottom {
    display: none;
  }

  .novaGallerySection {
    padding: 70px 0 75px;
  }

  .gallerySectionHeader {
    display: block;
    margin-bottom: 35px;
  }

  .gallerySectionHeader h2 {
    font-size: 42px;
  }

  .gallerySectionHeader p {
    margin-top: 22px;
  }

  .galleryFilters {
    gap: 8px;
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 7px;
    scrollbar-width: none;
  }

  .galleryFilters::-webkit-scrollbar {
    display: none;
  }

  .galleryFilter {
    flex-shrink: 0;
    padding: 0 17px;
  }

  .novaGalleryGrid {
    grid-template-columns: repeat(2, 1fr);
    grid-auto-rows: 180px;
    gap: 10px;
  }

  .galleryCard-large {
    grid-column: span 2;
    grid-row: span 2;
  }

  .galleryCard-normal {
    grid-column: span 1;
    grid-row: span 1;
  }

  .galleryCard-tall {
    grid-column: span 1;
    grid-row: span 2;
  }

  .galleryCard {
    border-radius: 14px;
  }

  .galleryCardContent {
    right: 13px;
    bottom: 13px;
    left: 13px;
  }

  .galleryCardContent h3 {
    font-size: 17px;
  }

  .galleryViewIcon {
    width: 34px;
    height: 34px;
  }

  .galleryFinalCTA {
    padding-bottom: 70px;
  }

  .galleryCTACard {
    min-height: 420px;
    padding: 45px 28px;
    border-radius: 22px;
  }

  .galleryCTAContent h2 {
    font-size: 42px;
  }

  .galleryCTADecoration {
    right: 10px;
    bottom: 10px;
    top: auto;
    font-size: 100px;
    transform: none;
  }

  .galleryLightbox {
    padding: 65px 14px 30px;
  }

  .galleryLightboxArrow {
    width: 42px;
    height: 42px;
  }

  .galleryLightboxPrev {
    left: 8px;
  }

  .galleryLightboxNext {
    right: 8px;
  }

  .galleryLightboxInfo h3 {
    font-size: 20px;
  }

  .galleryLightboxCounter {
    font-size: 11px;
  }

  .galleryLightboxClose {
    top: 14px;
    right: 14px;
    width: 42px;
    height: 42px;
  }
}

/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {
  .novaGalleryHero {
    min-height: 470px;
  }

  .galleryHeroContent h1 {
    font-size: 43px;
  }

  .gallerySectionHeader h2 {
    font-size: 36px;
  }

  .novaGalleryGrid {
    grid-auto-rows: 150px;
  }

  .galleryCardContent h3 {
    font-size: 15px;
  }

  .galleryCardContent > span {
    font-size: 8px;
  }

  .galleryCTACard {
    padding: 38px 22px;
  }

  .galleryCTAContent h2 {
    font-size: 36px;
  }

  .galleryLightbox {
    padding-left: 10px;
    padding-right: 10px;
  }

  .galleryLightboxInfo {
    align-items: flex-start;
  }
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

