/* =========================
   PREMIUM GRID
   ========================= */

.novaGalleryGrid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: 280px;
  gap: 18px;
  width: 100%;
}

.galleryCard {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  border-radius: 24px;
  overflow: hidden;
  background: #dcefee;
  cursor: pointer;
  box-shadow: 0 12px 30px rgba(11,37,69,.08);
  isolation: isolate;
}

.galleryCard-large {
  grid-column: span 2;
  grid-row: span 2;
}

.galleryCard-tall {
  grid-row: span 2;
}

.galleryCard img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition:
    transform .65s cubic-bezier(.2,.7,.2,1),
    filter .5s ease;
}

.galleryCard::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      to top,
      rgba(5,24,43,.92) 0%,
      rgba(5,24,43,.45) 35%,
      rgba(5,24,43,0) 70%
    );
  opacity: .82;
  transition: opacity .4s ease;
}

.galleryCard:hover img {
  transform: scale(1.07);
  filter: saturate(1.08);
}

.galleryCard:hover::after {
  opacity: 1;
}

/* =========================
