  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255,255,255,.35);
  border-radius: 50%;
  background: rgba(255,255,255,.12);
  backdrop-filter: blur(10px);

  color: white;

  transform: translateY(8px);
  opacity: 0;

  transition:
    transform .35s ease,
    opacity .35s ease,
    background .35s ease;
}

.galleryCard:hover .galleryExpand {
  opacity: 1;
  transform: translateY(0);
}

.galleryExpand:hover {
  background: #1f8a8a;
