  inset: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 35px;

  background: rgba(3,16,29,.94);
  backdrop-filter: blur(16px);

  animation: galleryLightboxIn .25s ease;
}

@keyframes galleryLightboxIn {
  from {
