  margin: 0 0 38px;

  padding: 0;
}

/* =========================================================
   GRID
   ========================================================= */

.novaGalleryGrid {
  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  grid-template-rows: none !important;

  grid-auto-rows: 360px !important;

  gap: 22px !important;

  width: 100% !important;
}

/* =========================================================
   CARDS
   ========================================================= */

.novaGalleryGrid .galleryCard,
.novaGalleryGrid .galleryCard-large,
.novaGalleryGrid .galleryCard-tall {
  position: relative !important;

  display: block !important;

  width: 100% !important;

  height: 360px !important;

  min-height: 360px !important;

  min-width: 0 !important;

  grid-column: auto !important;

  grid-row: auto !important;

  overflow: hidden !important;

  border-radius: 24px !important;

  background: #dff4f2 !important;

  cursor: pointer !important;

  isolation: isolate !important;

  box-shadow:
    0 12px 35px rgba(11,37,69,.10) !important;

  transition:
    transform .35s ease,
    box-shadow .35s ease !important;
}

.novaGalleryGrid .galleryCard:hover {
  transform: translateY(-7px) !important;

  box-shadow:
    0 25px 55px rgba(11,37,69,.18) !important;
}

/* =========================================================
   IMAGE
   ========================================================= */

.novaGalleryGrid .galleryCard img {
  position: absolute !important;

  inset: 0 !important;

  display: block !important;

  width: 100% !important;

  height: 100% !important;

  max-width: none !important;

  object-fit: cover !important;

  object-position: center !important;

  transform: scale(1) !important;

  transition:
    transform .65s
    cubic-bezier(.2,.7,.2,1) !important;
}

.novaGalleryGrid .galleryCard:hover img {
  transform: scale(1.08) !important;
}

/* =========================================================
   CARD GRADIENT
   ========================================================= */

.novaGalleryGrid .galleryCard::after {
  content: "";

  position: absolute;

  inset: 0;

  z-index: 2;

  background:
    linear-gradient(
      to top,
      rgba(5,20,35,.94) 0%,
      rgba(5,20,35,.50) 40%,
      rgba(5,20,35,0) 78%
    );

  opacity: 1;

  pointer-events: none;
}

/* =========================================================
   CARD CONTENT
   ========================================================= */

.novaGalleryGrid .galleryCardOverlay {
  position: absolute !important;

  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;

  z-index: 5 !important;

  display: flex !important;

  align-items: flex-end !important;

  justify-content: space-between !important;

  gap: 15px !important;

  padding: 25px !important;

  color: white !important;
}

.novaGalleryGrid
.galleryCardOverlay
> div:first-child {
  min-width: 0 !important;
}

/* =========================================================
   EXPAND BUTTON
   ========================================================= */

.novaGalleryGrid .galleryExpand {
  flex-shrink: 0 !important;

  width: 45px !important;

  height: 45px !important;

  display: flex !important;

  align-items: center !important;

  justify-content: center !important;

  border-radius: 50% !important;

  border: 1px solid
    rgba(255,255,255,.35) !important;

  background:
    rgba(255,255,255,.14) !important;

  color: white !important;

  backdrop-filter: blur(10px) !important;

  opacity: 1 !important;

  transform: none !important;

  transition:
    background .25s ease,
    border-color .25s ease,
    transform .25s ease !important;
}

.novaGalleryGrid .galleryExpand:hover {
  background: #1f8a8a !important;

  border-color: #1f8a8a !important;

  transform: rotate(5deg) !important;
}

/* =========================================================
   CTA
   ========================================================= */

.galleryCTA {
  padding: 0 0 110px;

  background: #f7fafc;
}

.galleryCTABox {
  position: relative;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 40px;

  padding: 65px 70px;

  border-radius: 32px;

  overflow: hidden;

  background:
    radial-gradient(
      circle at 85% 30%,
      rgba(85,184,176,.18),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      #0b2545,
      #123d59
    );

  color: white;
}

.galleryCTABox h2 {
  margin: 14px 0;

  color: white;

  font-size: clamp(30px, 4vw, 48px);

  line-height: 1.1;

  letter-spacing: -1px;
}

.galleryCTABox p {
  max-width: 560px;

  margin: 0;

  color: rgba(255,255,255,.72);

  line-height: 1.7;
}

/* =========================================================
   LIGHTBOX
   ========================================================= */

.galleryLightbox {
  position: fixed;

  z-index: 9999;

  inset: 0;

  display: flex;

  align-items: center;

  justify-content: center;

  padding: 35px;

  background:
    rgba(3,16,29,.94);

  backdrop-filter: blur(16px);

  animation:
    galleryLightboxIn .25s ease;
}

/* =========================================================
   LIGHTBOX BUTTONS
   ========================================================= */

.galleryLightboxClose,
.galleryLightboxPrev,
.galleryLightboxNext {
  position: absolute;

  display: flex;

