/* =========================================================
   NOVADENT GALLERY — PREMIUM HOVER
   ========================================================= */

.novaGalleryItem {
  position: relative;
  overflow: hidden;
  cursor: pointer;
  border-radius: 28px;
  background: #0b2545;
  isolation: isolate;
  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease;
}

.novaGalleryItem:hover {
  transform: translateY(-8px);
  box-shadow:
    0 25px 60px rgba(11, 37, 69, 0.18);
}

/* IMAGE */

.novaGalleryImageWrap {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 390px;
  overflow: hidden;
}

.novaGalleryImage {
  width: 100%;
  height: 100%;
  min-height: 390px;
  display: block;
  object-fit: cover;
  transition:
    transform 0.8s cubic-bezier(.2,.7,.2,1),
    filter 0.5s ease;
}

.novaGalleryItem:hover .novaGalleryImage {
  transform: scale(1.08);
  filter: brightness(0.78);
}

/* DARK OVERLAY */

.novaGalleryImageShade {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      to top,
      rgba(5, 22, 40, 0.92) 0%,
      rgba(5, 22, 40, 0.35) 45%,
      rgba(5, 22, 40, 0.05) 75%
    );
  opacity: 0.65;
  transition: opacity 0.5s ease;
}

.novaGalleryItem:hover .novaGalleryImageShade {
  opacity: 0.9;
}

/* CATEGORY + TITLE */

.novaGalleryInfo {
  position: absolute;
  left: 28px;
  right: 28px;
  bottom: 26px;
  z-index: 3;
  transform: translateY(12px);
  transition:
    transform 0.5s ease;
}

.novaGalleryItem:hover .novaGalleryInfo {
  transform: translateY(0);
}

.novaGalleryInfo span {
  display: inline-block;
  margin-bottom: 8px;
  color: #55b8b0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.novaGalleryInfo h3 {
  margin: 0;
  color: #ffffff;
  font-size: 25px;
  font-weight: 700;
  line-height: 1.15;
}

.novaGalleryInfo p {
  margin: 9px 0 0;
  color: rgba(255, 255, 255, 0.75);
  font-size: 14px;
  line-height: 1.6;
  opacity: 0;
  transform: translateY(8px);
  transition:
    opacity 0.45s ease,
    transform 0.45s ease;
}

.novaGalleryItem:hover .novaGalleryInfo p {
  opacity: 1;
  transform: translateY(0);
}

/* NUMBER */

.novaGalleryIndex {
  position: absolute;
  top: 22px;
  left: 24px;
  z-index: 3;

  color: rgba(255, 255, 255, 0.75);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;

  transition:
    color 0.35s ease,
    transform 0.35s ease;
}

.novaGalleryItem:hover .novaGalleryIndex {
  color: #ffffff;
  transform: translateY(-3px);
}

/* OPEN ICON */

.novaGalleryOpen {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 4;

  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255,255,255,0.35);
  border-radius: 50%;

  color: #ffffff;
  background: rgba(11, 37, 69, 0.28);

  backdrop-filter: blur(10px);

  opacity: 0;
  transform: scale(0.75) rotate(-15deg);

  transition:
    opacity 0.4s ease,
    transform 0.4s ease,
    background 0.3s ease;
}

.novaGalleryItem:hover .novaGalleryOpen {
  opacity: 1;
  transform: scale(1) rotate(0);
}

.novaGalleryOpen:hover {
  background: #1f8a8a;
  border-color: #1f8a8a;
}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .novaGalleryItem {
    border-radius: 20px;
  }

  .novaGalleryImageWrap,
  .novaGalleryImage {
    min-height: 320px;
  }

  .novaGalleryInfo {
    left: 20px;
    right: 20px;
    bottom: 20px;
  }

  .novaGalleryInfo h3 {
    font-size: 20px;
  }

  .novaGalleryInfo p {
    opacity: 1;
    transform: none;
    font-size: 13px;
  }

  .novaGalleryOpen {
    opacity: 1;
    transform: scale(1);
    width: 42px;
    height: 42px;
  }

  .novaGalleryIndex {
    top: 18px;
    left: 18px;
  }
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .novaGalleryItem,
  .novaGalleryImage,
  .novaGalleryInfo,
  .novaGalleryInfo p,
  .novaGalleryOpen {
    transition: none !important;
  }

  .novaGalleryItem:hover {
    transform: none;
  }

  .novaGalleryItem:hover .novaGalleryImage {
    transform: none;
  }

}

