  top: 25px;
  right: 25px;

  width: 48px;
  height: 48px;

  border-radius: 50%;
}

.novaGalleryPrev,
.novaGalleryNext {
  top: 50%;

  width: 52px;
  height: 52px;

  border-radius: 50%;

  transform: translateY(-50%);
}

.novaGalleryPrev {
  left: 25px;
}

.novaGalleryNext {
  right: 25px;
}

