.novaGalleryFilters {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 38px;
}

.galleryFilter {
  min-height: 42px;
  padding: 0 21px;

  border: 1px solid #cbdde2;
  border-radius: 30px;

  background: white;
  color: #183b56;

  font-size: 12px;
  font-weight: 800;

  cursor: pointer;
  transition: all 0.25s ease;
}

.galleryFilter:hover {
  border-color: #1f8a8a;
  color: #1f8a8a;
  transform: translateY(-2px);
}

.galleryFilter.active {
  border-color: #0b2545;
  background: #0b2545;
  color: white;
  box-shadow: 0 10px 25px rgba(11, 37, 69, 0.18);
}

/* GRID */

.novaGalleryGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

/* CARD */

.novaGalleryCard {
  position: relative;
  height: 250px;

  overflow: hidden;
  border-radius: 18px;

  background: #dfecef;
  cursor: pointer;

  box-shadow: 0 8px 25px rgba(11, 37, 69, 0.07);

  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.novaGalleryCard:hover {
  transform: translateY(-7px);
  box-shadow: 0 20px 40px rgba(11, 37, 69, 0.16);
}

.novaGalleryCard img {
  width: 100%;
  height: 100%;

  display: block;
  object-fit: cover;

  transition:
    transform 0.55s ease,
    filter 0.35s ease;
}

.novaGalleryCard:hover img {
  transform: scale(1.07);
  filter: brightness(0.78);
}

/* CARD OVERLAY */

.novaGalleryCardOverlay {
  position: absolute;
  inset: auto 0 0 0;

  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 15px;

  padding: 24px 20px 19px;

  color: white;

  background: linear-gradient(
    to top,
    rgba(5, 27, 46, 0.92),
    rgba(5, 27, 46, 0.1)
  );

  transform: translateY(5px);
  transition: transform 0.3s ease;
}

.novaGalleryCard:hover .novaGalleryCardOverlay {
  transform: translateY(0);
}

.novaGalleryCardOverlay small {
  display: block;
  margin-bottom: 5px;

  color: #71d5ce;
  font-size: 9px;
  font-weight: 800;
