  overflow: hidden;
}

/* ================= CONTAINER ================= */

.appointmentContainer {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

/* ================= HERO ================= */

.novaAppointmentHero {
  position: relative;
  min-height: 650px;
  display: flex;
  align-items: center;
  background:
    linear-gradient(
      110deg,
      #061d32 0%,
      #0b3048 48%,
      #123f54 100%
    );
  color: #fff;
  overflow: hidden;
}

.appointmentHeroGlow {
  position: absolute;
  width: 500px;
  height: 500px;
  right: -180px;
  top: -180px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.16);
  filter: blur(10px);
  pointer-events: none;
}

.appointmentHeroGrid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 70px;
  align-items: center;
}

.appointmentHeroContent {
  max-width: 650px;
}

.appointmentEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 24px;
  color: #8bd8d1;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
}

.appointmentHeroContent h1 {
  margin: 0;
  max-width: 650px;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.98;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.appointmentHeroContent h1 em {
  display: block;
  color: #65c7bf;
  font-style: italic;
}

.appointmentHeroContent > p {
  max-width: 570px;
  margin: 28px 0 0;
  color: rgba(255, 255, 255, 0.74);
  font-size: 17px;
  line-height: 1.8;
}

.appointmentHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 36px;
}

.appointmentPrimaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 15px 22px;
  border-radius: 8px;
  background: #55b8b0;
  color: #06253a;
  text-decoration: none;
  font-weight: 700;
  transition: 0.3s ease;
}

.appointmentPrimaryBtn:hover {
  transform: translateY(-3px);
  background: #72cdc5;
  box-shadow: 0 16px 35px rgba(0, 0, 0, 0.2);
}

.appointmentPhoneBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #fff;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  opacity: 0.85;
  transition: 0.25s ease;
}

.appointmentPhoneBtn:hover {
  opacity: 1;
  color: #75cec7;
}

.appointmentTrustRow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
  margin-top: 45px;
}

.appointmentTrustRow > div {
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 12px;
}

.appointmentTrustRow svg {
  color: #69c9c1;
}

/* ================= HERO IMAGE ================= */

.appointmentHeroVisual {
  position: relative;
  max-width: 500px;
  justify-self: end;
}

.appointmentHeroImage {
  position: relative;
  height: 500px;
  overflow: hidden;
  border-radius: 160px 160px 20px 20px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 35px 80px rgba(0, 0, 0, 0.28);
}

.appointmentHeroImage::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      transparent 55%,
      rgba(4, 25, 42, 0.3)
    );
}

.appointmentHeroImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 0.8s ease;
}

.appointmentFloatingCard {
  position: absolute;
  left: -35px;
  bottom: 35px;
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 245px;
  padding: 17px 19px;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.96);
  color: #183b56;
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(12px);
  animation: appointmentFloat 4s ease-in-out infinite;
}

.floatingIcon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border-radius: 10px;
  background: #eaf5f4;
  color: #1f8a8a;
}

.appointmentFloatingCard strong {
  display: block;
  font-size: 13px;
  margin-bottom: 4px;
}

.appointmentFloatingCard span {
  display: block;
  color: #64748b;
  font-size: 11px;
}

@keyframes appointmentFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }
}

/* ================= INTRO ================= */

.appointmentIntro {
  padding: 105px 0 95px;
  background: #fff;
}

.appointmentIntroGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 100px;
  align-items: start;
}

.appointmentOverline {
  display: block;
  margin-bottom: 14px;
  color: #1f8a8a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.appointmentIntro small,
.appointmentSectionHeading small {
  display: block;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.appointmentIntro h2,
.appointmentSectionHeading h2 {
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(38px, 4.5vw, 58px);
  line-height: 1.05;
  font-weight: 500;
  letter-spacing: -0.035em;
  color: #0b2545;
}

.appointmentIntro h2 em,
.appointmentSectionHeading h2 em {
  color: #1f8a8a;
  font-style: italic;
}

.appointmentIntroText > p {
  max-width: 600px;
  margin: 0;
  color: #64748b;
  font-size: 16px;
  line-height: 1.85;
}

.appointmentInfoCards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 15px;
  margin-top: 35px;
}

.appointmentInfoCard {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 18px;
  border: 1px solid #e4eeee;
  border-radius: 12px;
  background: #f8fbfb;
  transition: 0.3s ease;
}

.appointmentInfoCard:hover {
  transform: translateY(-4px);
  border-color: #b9dedb;
  box-shadow: 0 12px 30px rgba(31, 138, 138, 0.08);
}

.appointmentInfoCard > svg {
  flex-shrink: 0;
  color: #1f8a8a;
}

.appointmentInfoCard strong {
  display: block;
  margin-bottom: 4px;
  color: #183b56;
  font-size: 13px;
}

.appointmentInfoCard span {
  color: #64748b;
  font-size: 11px;
}

/* ================= FORM SECTION ================= */

.appointmentFormSection {
  padding: 110px 0;
  background: #f7fafc;
}

.appointmentSectionHeading {
  display: flex;
  justify-content: space-between;
  gap: 60px;
  align-items: end;
  margin-bottom: 55px;
}

.appointmentSectionHeading > p {
  max-width: 420px;
  margin: 0;
  color: #64748b;
  font-size: 15px;
  line-height: 1.8;
}

.appointmentFormLayout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(280px, 0.7fr);
  gap: 28px;
  align-items: start;
}

.appointmentFormCard {
  padding: 42px;
  border: 1px solid #e2ebee;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 20px 60px rgba(11, 37, 69, 0.07);
}

.formRow {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-bottom: 19px;
}

.formField {
  margin-bottom: 19px;
}

.formField label {
  display: block;
  margin-bottom: 8px;
  color: #183b56;
  font-size: 12px;
  font-weight: 700;
}

.formField input,
.formField select,
.formField textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #dbe6ea;
  border-radius: 9px;
  outline: none;
  background: #fbfdfd;
  color: #183b56;
  font-family: inherit;
  font-size: 14px;
  transition: 0.25s ease;
}

.formField input,
.formField select {
  height: 50px;
  padding: 0 14px;
}

.formField textarea {
  min-height: 125px;
  padding: 14px;
  resize: vertical;
}

.formField input::placeholder,
.formField textarea::placeholder {
  color: #a5b2bd;
}

.formField input:focus,
.formField select:focus,
.formField textarea:focus {
  border-color: #55b8b0;
  background: #fff;
  box-shadow: 0 0 0 4px rgba(85, 184, 176, 0.1);
}

.appointmentSubmitBtn {
  width: 100%;
  min-height: 53px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  margin-top: 7px;
  border: 0;
  border-radius: 9px;
  background: #0b2545;
  color: #fff;
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  transition: 0.3s ease;
}

.appointmentSubmitBtn:hover {
  background: #1f8a8a;
  transform: translateY(-2px);
  box-shadow: 0 13px 28px rgba(31, 138, 138, 0.2);
}

.appointmentFormNote {
  margin: 15px 0 0;
  color: #94a3b8;
  text-align: center;
  font-size: 10px;
  line-height: 1.6;
}

/* ================= SIDE CARDS ================= */

.appointmentSide {
  display: grid;
  gap: 17px;
}

.appointmentSideCard {
  position: relative;
  padding: 28px;
  overflow: hidden;
  border: 1px solid #dfe9eb;
  border-radius: 16px;
  background: #fff;
  transition: 0.3s ease;
}

.appointmentSideCard:hover {
  transform: translateY(-5px);
  border-color: #b7dcd9;
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.08);
}

.appointmentSideCard.appointmentHighlight {
  background: #0b2545;
  border-color: #0b2545;
  color: #fff;
}

.appointmentSideNumber {
  position: absolute;
  top: 18px;
  right: 20px;
  color: #a7b6c1;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.appointmentHighlight .appointmentSideNumber {
  color: rgba(255, 255, 255, 0.35);
}

.appointmentSideCard > svg {
  margin-bottom: 22px;
  color: #1f8a8a;
}

.appointmentHighlight > svg {
  color: #6ed0c8;
}

.appointmentSideCard h3 {
  margin: 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 25px;
  line-height: 1.15;
  font-weight: 500;
}

.appointmentHighlight h3 {
  color: #fff;
}

.appointmentSideCard p {
  margin: 14px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.7;
}

.appointmentSideCard a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 18px;
  color: #1f8a8a;
  text-decoration: none;
  font-size: 12px;
  font-weight: 700;
}

.appointmentSideCard a:hover {
  color: #0b2545;
}

/* ================= SUCCESS ================= */

.appointmentSuccess {
  min-height: 450px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
}

.successIcon {
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  margin-bottom: 24px;
  border-radius: 50%;
  background: #eaf5f4;
  color: #1f8a8a;
}

.appointmentSuccess > span {
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.appointmentSuccess h3 {
  margin: 12px 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 36px;
  font-weight: 500;
}

.appointmentSuccess p {
  max-width: 480px;
  margin: 0 auto;
  color: #64748b;
  font-size: 14px;
  line-height: 1.8;
}

.appointmentAgainBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 25px;
  padding: 12px 18px;
  border: 1px solid #dbe7e8;
  border-radius: 8px;
  background: #fff;
  color: #183b56;
  cursor: pointer;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  transition: 0.25s ease;
}

.appointmentAgainBtn:hover {
  border-color: #55b8b0;
  color: #1f8a8a;
}

/* ================= FINAL CTA ================= */

.appointmentFinalCTA {
  padding: 90px 0;
  background: #fff;
}

.appointmentCTACard {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding: 58px 65px;
  overflow: hidden;
  border-radius: 20px;
  background:
    radial-gradient(
      circle at 90% 10%,
      rgba(85, 184, 176, 0.28),
      transparent 35%
    ),
    #0b2545;
  color: #fff;
}

.appointmentCTACard > div {
  position: relative;
  z-index: 1;
}

.appointmentCTACard > div > span {
  color: #6ed0c8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.15em;
}

.appointmentCTACard h2 {
  max-width: 650px;
  margin: 15px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1.05;
  font-weight: 500;
}

.appointmentCTACard h2 em {
  color: #68c8c1;
  font-style: italic;
}

.appointmentCTACard p {
  margin: 15px 0 0;
  color: rgba(255, 255, 255, 0.65);
  font-size: 14px;
}

.appointmentCTAButton {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 15px 21px;
  border-radius: 8px;
  background: #55b8b0;
  color: #06253a;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition: 0.3s ease;
}

.appointmentCTAButton:hover {
  transform: translateY(-3px);
  background: #75cec7;
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.2);
}

/* ================= TABLET ================= */

@media (max-width: 1000px) {
  .novaAppointmentHero {
    min-height: auto;
    padding: 90px 0;
  }

  .appointmentHeroGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .appointmentHeroVisual {
    width: min(100%, 560px);
    justify-self: start;
  }

  .appointmentHeroImage {
    height: 430px;
  }

  .appointmentIntroGrid {
    gap: 55px;
  }

  .appointmentFormLayout {
    grid-template-columns: 1fr;
  }

  .appointmentSide {
    grid-template-columns: repeat(3, 1fr);
  }

  .appointmentSideCard {
    padding: 23px;
  }
}

/* ================= MOBILE ================= */

@media (max-width: 700px) {
  .appointmentContainer {
    width: min(100% - 32px, 600px);
  }

  .novaAppointmentHero {
    padding: 72px 0 80px;
  }

  .appointmentHeroContent h1 {
    font-size: 48px;
  }

  .appointmentHeroContent > p {
    font-size: 14px;
    line-height: 1.7;
  }

  .appointmentHeroActions {
    align-items: flex-start;
    flex-direction: column;
  }

  .appointmentTrustRow {
    gap: 14px;
    margin-top: 32px;
  }

  .appointmentTrustRow > div {
    font-size: 11px;
  }

  .appointmentHeroImage {
    height: 350px;
    border-radius: 100px 100px 16px 16px;
  }

  .appointmentFloatingCard {
    left: 15px;
    bottom: 18px;
    min-width: 0;
    width: calc(100% - 30px);
    box-sizing: border-box;
  }

  .appointmentIntro {
    padding: 70px 0;
  }

  .appointmentIntroGrid {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .appointmentInfoCards {
    grid-template-columns: 1fr;
  }

  .appointmentFormSection {
    padding: 75px 0;
  }

  .appointmentSectionHeading {
    display: block;
    margin-bottom: 35px;
  }

  .appointmentSectionHeading > p {
    margin-top: 22px;
  }

  .appointmentFormCard {
    padding: 25px 20px;
    border-radius: 14px;
  }

  .formRow {
    grid-template-columns: 1fr;
    gap: 0;
    margin-bottom: 0;
  }

  .appointmentSide {
    grid-template-columns: 1fr;
  }

  .appointmentSuccess {
    min-height: 400px;
    padding: 25px 10px;
  }

  .appointmentSuccess h3 {
    font-size: 30px;
  }

  .appointmentFinalCTA {
    padding: 60px 0;
  }

  .appointmentCTACard {
    flex-direction: column;
    align-items: flex-start;
    padding: 38px 28px;
    border-radius: 16px;
  }
}

/* ================= SMALL MOBILE ================= */

@media (max-width: 480px) {
  .appointmentContainer {
    width: calc(100% - 26px);
  }

  .novaAppointmentHero {
    padding: 62px 0 70px;
  }

  .appointmentHeroContent h1 {
    font-size: 40px;
  }

  .appointmentEyebrow {
    font-size: 10px;
  }

  .appointmentHeroImage {
    height: 285px;
    border-radius: 75px 75px 14px 14px;
  }

  .appointmentTrustRow {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .appointmentTrustRow > div {
    font-size: 10px;
  }

  .appointmentIntro h2,
  .appointmentSectionHeading h2 {
    font-size: 37px;
  }

  .appointmentFormSection {
    padding: 60px 0;
  }

  .appointmentFormCard {
    padding: 22px 16px;
  }

  .formField input,
  .formField select {
    height: 48px;
  }

  .appointmentSideCard {
    padding: 23px 20px;
  }

  .appointmentCTACard h2 {
    font-size: 34px;
  }

  .appointmentCTAButton {
    width: 100%;
    justify-content: center;
  }
}

