.contactHeroImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 0.8s ease;
}

.contactHeroVisual:hover .contactHeroImage img {
  transform: scale(1.05);
}

.contactHeroFloating {
  position: absolute;
  left: -30px;
  bottom: 30px;
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 235px;
  padding: 16px 18px;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.96);
  color: #183b56;
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(12px);
  animation: contactFloat 4s ease-in-out infinite;
}

.contactFloatingIcon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  border-radius: 10px;
  background: #eaf5f4;
  color: #1f8a8a;
}

.contactHeroFloating strong {
  display: block;
  margin-bottom: 4px;
  font-size: 13px;
}

.contactHeroFloating span {
  color: #64748b;
  font-size: 11px;
}

@keyframes contactFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }
}

/* ================= CONTACT DETAILS ================= */

.contactDetailsSection {
  padding: 100px 0;
  background: #fff;
}

.contactSectionIntro {
  display: flex;
  justify-content: space-between;
  gap: 60px;
  align-items: end;
  margin-bottom: 50px;
}

.contactOverline {
  display: block;
  margin-bottom: 13px;
  color: #1f8a8a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.contactSectionIntro small,
.contactFormHeader small,
.contactLocationContent small {
  color: #94a3b8;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.contactSectionIntro h2,
.contactFormHeader h2,
.contactLocationContent h2 {
  margin: 18px 0 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(38px, 4.5vw, 58px);
  line-height: 1.05;
  font-weight: 500;
  letter-spacing: -0.035em;
}

.contactSectionIntro h2 em,
.contactFormHeader h2 em,
.contactLocationContent h2 em {
  color: #1f8a8a;
  font-style: italic;
}

.contactSectionIntro > p {
  max-width: 410px;
  margin: 0;
  color: #64748b;
  font-size: 15px;
  line-height: 1.8;
}

/* ================= INFO CARDS ================= */

.contactInfoGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
}

.contactInfoCard {
  position: relative;
  min-height: 190px;
  padding: 28px;
  overflow: hidden;
  box-sizing: border-box;
  border: 1px solid #e0eaed;
  border-radius: 15px;
  background: #fbfdfd;
  color: #183b56;
  text-decoration: none;
  transition: 0.35s ease;
}

.contactInfoCard:hover {
  transform: translateY(-7px);
  border-color: #b7dcd9;
  background: #fff;
  box-shadow: 0 20px 45px rgba(11, 37, 69, 0.08);
}

.contactInfoNumber {
  position: absolute;
  top: 20px;
  right: 22px;
  color: #a9b8c2;
  font-size: 10px;
  font-weight: 800;
}

.contactInfoIcon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin-bottom: 22px;
  border-radius: 11px;
  background: #eaf5f4;
  color: #1f8a8a;
  transition: 0.3s ease;
}

.contactInfoCard:hover .contactInfoIcon {
  transform: rotate(-5deg) scale(1.05);
  background: #1f8a8a;
  color: #fff;
}

.contactInfoContent > span {
  color: #1f8a8a;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.contactInfoContent h3 {
  margin: 7px 0 6px;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 20px;
  font-weight: 500;
}

.contactInfoContent p {
  margin: 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.6;
}

.contactInfoArrow {
  position: absolute;
  right: 22px;
  bottom: 20px;
  color: #9aaab4;
  transition: 0.25s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  color: #1f8a8a;
  transform: translate(3px, -3px);
}

/* ================= FORM ================= */

.contactFormSection {
  padding: 110px 0;
  background: #f7fafc;
}

.contactFormHeader {
  max-width: 700px;
  margin-bottom: 48px;
}

.contactFormHeader > p {
  max-width: 500px;
  margin: 18px 0 0;
  color: #64748b;
  font-size: 15px;
  line-height: 1.8;
}

.contactFormLayout {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(280px, 0.7fr);
  gap: 28px;
  align-items: start;
}

.contactFormCard {
  padding: 42px;
  border: 1px solid #e1eaed;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 20px 60px rgba(11, 37, 69, 0.06);
}

.contactFormRow {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}

.contactField {
  margin-bottom: 20px;
}

.contactField label {
  display: block;
  margin-bottom: 8px;
  color: #183b56;
  font-size: 12px;
  font-weight: 700;
}

.contactField input,
.contactField textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #dbe6ea;
  border-radius: 9px;
  outline: none;
  background: #fbfdfd;
  color: #183b56;
  font-family: inherit;
  font-size: 14px;
  transition: 0.25s ease;
}

.contactField input {
  height: 50px;
  padding: 0 14px;
}

.contactField textarea {
  min-height: 145px;
  padding: 14px;
  resize: vertical;
}

.contactField input::placeholder,
.contactField textarea::placeholder {
  color: #a7b4bd;
}

.contactField input:focus,
.contactField textarea:focus {
  border-color: #55b8b0;
  background: #fff;
  box-shadow: 0 0 0 4px rgba(85, 184, 176, 0.1);
}

.contactSubmitBtn {
  width: 100%;
  min-height: 53px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 9px;
  border: 0;
  border-radius: 9px;
  background: #0b2545;
  color: #fff;
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;
  transition: 0.3s ease;
}

.contactSubmitBtn:hover {
  transform: translateY(-2px);
  background: #1f8a8a;
  box-shadow: 0 14px 30px rgba(31, 138, 138, 0.2);
}

/* ================= SIDE PANEL ================= */

.contactSidePanel {
  display: grid;
  gap: 17px;
}

.contactSideCard {
  padding: 27px;
  border: 1px solid #dfe9eb;
  border-radius: 16px;
  background: #fff;
  transition: 0.3s ease;
}

.contactSideCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.08);
}

.contactSideTop {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.contactSideCard h3 {
  margin: 20px 0 22px;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 28px;
  line-height: 1.05;
  font-weight: 500;
}

.contactSideCard h3 em {
  color: #1f8a8a;
  font-style: italic;
}

.contactHours {
  display: grid;
  gap: 14px;
}

.contactHours > div {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  padding-bottom: 13px;
  border-bottom: 1px solid #edf2f3;
}

.contactHours > div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.contactHours span {
  color: #64748b;
  font-size: 11px;
}

.contactHours strong {
  color: #183b56;
  font-size: 11px;
  text-align: right;
}

.contactAppointmentCard {
  background: #0b2545;
  border-color: #0b2545;
  color: #fff;
}

.contactAppointmentCard > svg {
  color: #67c9c2;
}

.contactAppointmentCard > span {
  display: block;
  margin-top: 4px;
  color: #67c9c2;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.contactAppointmentCard h3 {
  margin-top: 13px;
  color: #fff;
}

.contactAppointmentCard p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 12px;
  line-height: 1.7;
}

.contactAppointmentBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 20px;
  padding: 12px 16px;
  border-radius: 8px;
  background: #55b8b0;
  color: #06253a;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: 0.3s ease;
}

.contactAppointmentBtn:hover {
  background: #75cec7;
  transform: translateY(-2px);
}

/* ================= SUCCESS ================= */

.contactSuccess {
  min-height: 430px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 35px;
  text-align: center;
}

.contactSuccessIcon {
  width: 80px;
  height: 80px;
  display: grid;
  place-items: center;
  margin-bottom: 22px;
  border-radius: 50%;
  background: #eaf5f4;
  color: #1f8a8a;
}

.contactSuccess > span {
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.contactSuccess h3 {
  margin: 13px 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 34px;
  font-weight: 500;
}

.contactSuccess p {
  max-width: 440px;
  margin: 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.8;
}

.contactAgainBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 23px;
  padding: 12px 17px;
  border: 1px solid #dbe6e8;
  border-radius: 8px;
  background: #fff;
  color: #183b56;
  cursor: pointer;
  font-family: inherit;
  font-size: 11px;
  font-weight: 700;
  transition: 0.25s ease;
}

.contactAgainBtn:hover {
  border-color: #55b8b0;
  color: #1f8a8a;
}

/* ================= LOCATION ================= */

.contactLocationSection {
  padding: 90px 0;
  background: #fff;
}

.contactLocationGrid {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 65px;
  align-items: center;
}

.contactLocationContent > p {
  max-width: 470px;
  margin: 22px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.8;
}

.contactLocationAddress {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  margin-top: 30px;
}

.contactLocationAddress > svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: #1f8a8a;
}

.contactLocationAddress strong {
  display: block;
  color: #183b56;
  font-size: 13px;
}

.contactLocationAddress span {
  display: block;
  margin-top: 5px;
  color: #64748b;
  font-size: 12px;
  line-height: 1.6;
}

.contactMapLink {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 22px;
  color: #1f8a8a;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition: 0.25s ease;
}

.contactMapLink:hover {
  color: #0b2545;
  transform: translateX(3px);
}

.contactMapVisual {
  min-height: 450px;
  position: relative;
  overflow: hidden;
  border-radius: 22px;
  background: #eaf5f4;
}

.contactMapPattern {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      35deg,
      transparent 48%,
      rgba(31, 138, 138, 0.12) 49%,
      transparent 50%
    ),
    linear-gradient(
      145deg,
      transparent 48%,
      rgba(31, 138, 138, 0.1) 49%,
      transparent 50%
    ),
    #edf7f6;
  background-size: 90px 90px;
}

.mapGridLines {
  position: absolute;
  inset: 0;
  opacity: 0.35;
  background:
    linear-gradient(
      90deg,
      transparent 49%,
      rgba(31, 138, 138, 0.12) 50%,
      transparent 51%
    ),
    linear-gradient(
      transparent 49%,
      rgba(31, 138, 138, 0.12) 50%,
      transparent 51%
    );
  background-size: 70px 70px;
}

.mapPinLarge {
  position: absolute;
  left: 50%;
  top: 48%;
  width: 70px;
  height: 70px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #1f8a8a;
  color: #fff;
  transform: translate(-50%, -50%);
  box-shadow:
    0 0 0 14px rgba(31, 138, 138, 0.12),
    0 0 0 30px rgba(31, 138, 138, 0.06);
  animation: mapPulse 2.5s ease-in-out infinite;
}

.mapLocationLabel {
  position: absolute;
  left: 50%;
  top: calc(48% + 65px);
  min-width: 180px;
  padding: 13px 17px;
  border-radius: 9px;
  background: #fff;
  text-align: center;
  box-shadow: 0 12px 30px rgba(11, 37, 69, 0.12);
  transform: translateX(-50%);
}

.mapLocationLabel strong {
  display: block;
  color: #0b2545;
  font-size: 12px;
  letter-spacing: 0.08em;
}

.mapLocationLabel span {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 10px;
}

@keyframes mapPulse {
  0%,
  100% {
    box-shadow:
      0 0 0 14px rgba(31, 138, 138, 0.12),
      0 0 0 30px rgba(31, 138, 138, 0.06);
  }

  50% {
    box-shadow:
      0 0 0 20px rgba(31, 138, 138, 0.08),
      0 0 0 40px rgba(31, 138, 138, 0.03);
  }
}

/* ================= FINAL CTA ================= */

.contactFinalCTA {
  padding: 85px 0 100px;
  background: #fff;
}

.contactCTACard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding: 55px 62px;
  border-radius: 20px;
  background:
    radial-gradient(
      circle at 90% 15%,
      rgba(85, 184, 176, 0.28),
      transparent 34%
    ),
    #0b2545;
  color: #fff;
}

.contactCTACard > div:first-child > span {
  color: #69ccc4;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.15em;
}

.contactCTACard h2 {
  margin: 14px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(34px, 4vw, 50px);
  line-height: 1.05;
  font-weight: 500;
}

.contactCTACard h2 em {
  color: #67c9c2;
  font-style: italic;
}

.contactCTACard p {
  margin: 13px 0 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 13px;
}

.contactCTAActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.contactCTASecondary,
.contactCTAButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 47px;
  padding: 0 17px;
  border-radius: 8px;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: 0.3s ease;
}

.contactCTASecondary:hover {
  border-color: #69ccc4;
  color: #69ccc4;
}

.contactCTAButton {
  background: #55b8b0;
  color: #06253a;
}

.contactCTAButton:hover {
  transform: translateY(-3px);
  background: #75cec7;
}

/* ================= TABLET ================= */

@media (max-width: 1000px) {
  .novaContactHero {
    min-height: auto;
    padding: 90px 0;
  }

  .contactHeroGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .contactHeroVisual {
    width: min(100%, 560px);
    justify-self: start;
  }

  .contactSectionIntro {
    gap: 35px;
  }

  .contactFormLayout {
    grid-template-columns: 1fr;
  }

  .contactSidePanel {
    grid-template-columns: repeat(2, 1fr);
  }

  .contactLocationGrid {
    gap: 45px;
  }
}

/* ================= MOBILE ================= */

@media (max-width: 700px) {
  .contactContainer {
    width: min(100% - 32px, 600px);
  }

  .novaContactHero {
    padding: 72px 0 80px;
  }

  .contactHeroContent h1 {
    font-size: 48px;
  }

  .contactHeroContent > p {
    font-size: 14px;
    line-height: 1.7;
  }

  .contactHeroActions {
    align-items: flex-start;
    flex-direction: column;
  }

  .contactHeroImage {
    height: 350px;
    border-radius: 100px 100px 16px 16px;
  }

  .contactHeroFloating {
    left: 15px;
    bottom: 18px;
    width: calc(100% - 30px);
    min-width: 0;
    box-sizing: border-box;
  }

  .contactDetailsSection {
    padding: 70px 0 !important;
  }

  .contactSectionIntro {
    display: block;
    margin-bottom: 35px;
  }

  .contactSectionIntro > p {
    margin-top: 22px;
  }

  .contactInfoGrid {
    grid-template-columns: 1fr;
  }

  .contactFormSection {
    padding: 75px 0 !important;
  }

  .contactFormCard {
    padding: 25px 20px;
    border-radius: 14px;
  }

  .contactFormRow {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .contactSidePanel {
    grid-template-columns: 1fr;
  }

  .contactLocationSection {
    padding: 65px 0 !important;
  }

  .contactLocationGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .contactMapVisual {
    min-height: 340px !important;
    height: 340px;
  }

  .contactFinalCTA {
    padding: 55px 0 70px !important;
  }

  .contactCTACard {
    flex-direction: column;
    align-items: flex-start;
    padding: 38px 27px;
    border-radius: 16px;
  }

  .contactCTAActions {
    width: 100%;
  }

  .contactCTASecondary,
  .contactCTAButton {
    flex: 1;
  }
}

/* ================= SMALL MOBILE ================= */

@media (max-width: 480px) {
  .contactContainer {
    width: calc(100% - 26px);
  }

  .novaContactHero {
    padding: 62px 0 70px;
  }

  .contactHeroContent h1 {
    font-size: 40px;
  }

  .contactHeroImage {
    height: 285px;
    border-radius: 75px 75px 14px 14px;
  }

  .contactSectionIntro h2,
  .contactFormHeader h2,
  .contactLocationContent h2 {
    font-size: 37px;
  }

  .contactInfoCard {
    min-height: 175px;
    padding: 23px;
  }

  .contactFormCard {
    padding: 22px 16px;
  }

  .contactField input {
    height: 48px;
  }

  .contactSuccess {
    min-height: 380px;
    padding: 25px 10px;
  }

  .contactSuccess h3 {
    font-size: 29px;
  }

  .contactMapVisual {
    min-height: 280px !important;
    height: 280px;
  }

  .contactCTACard h2 {
    font-size: 33px;
  }

  .contactCTAActions {
    flex-direction: column;
  }

  .contactCTASecondary,
  .contactCTAButton {
    width: 100%;
    flex: none;
  }
}

/* =========================================================
   NOVADENT — DOCTORS PAGE PREMIUM STYLES
   ========================================================= */

.doctorsPage {
  background:
    radial-gradient(circle at 10% 10%, rgba(20, 184, 166, 0.12), transparent 30%),
    radial-gradient(circle at 90% 20%, rgba(59, 130, 246, 0.10), transparent 30%),
    linear-gradient(135deg, #e8f8f6 0%, #eef6fb 50%, #f5fbfa 100%) !important;
  color: #183b56;
  overflow: hidden;
}
.doctorsPage .container {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

/* ================= HERO ================= */

.doctorsHero {
  position: relative;
  min-height: 650px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #071f35;
  color: #fff;
}

.doctorsHeroImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.04);
  animation: doctorsHeroZoom 12s ease-in-out infinite alternate;
}

@keyframes doctorsHeroZoom {
  from {
    transform: scale(1.04);
  }

  to {
    transform: scale(1.1);
  }
}

.doctorsHeroOverlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(4, 25, 43, 0.96) 0%,
      rgba(6, 34, 53, 0.88) 42%,
      rgba(6, 34, 53, 0.45) 72%,
      rgba(6, 34, 53, 0.2) 100%
    );
}

.doctorsHeroGlow {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(4px);
}

.doctorsGlowOne {
  width: 420px;
  height: 420px;
  right: -160px;
  top: -130px;
  background: rgba(85, 184, 176, 0.16);
}

.doctorsGlowTwo {
  width: 280px;
  height: 280px;
  left: 38%;
  bottom: -180px;
  background: rgba(85, 184, 176, 0.08);
}

.doctorsHeroContent {
  position: relative;
  z-index: 3;
  padding-top: 70px;
  padding-bottom: 100px;
}

.doctorsHeroBadge {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 9px 13px;
  margin-bottom: 23px;
  border: 1px solid rgba(112, 207, 199, 0.28);
  border-radius: 30px;
  background: rgba(85, 184, 176, 0.08);
  color: #75cec7;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  backdrop-filter: blur(8px);
}

.doctorsLightEyebrow {
  display: block;
  color: rgba(255, 255, 255, 0.58) !important;
}

.doctorsHeroContent h1 {
  max-width: 750px;
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(52px, 7vw, 84px);
  line-height: 0.97;
  font-weight: 500;
  letter-spacing: -0.045em;
}

.doctorsHeroContent h1 span {
  display: block;
  color: #67c9c2;
  font-style: italic;
}

.doctorsHeroContent > p {
  max-width: 610px;
  margin: 30px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 15px;
  line-height: 1.85;
}

.doctorsHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 35px;
}

.doctorsHeroLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  text-decoration: none;
  font-size: 12px;
  font-weight: 700;
  transition: 0.25s ease;
}

.doctorsHeroLink:hover {
  color: #67c9c2;
  transform: translateX(4px);
}

.lightButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 8px;
  background: #55b8b0;
  color: #06253a;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: 0.3s ease;
}

.lightButton:hover {
  transform: translateY(-3px);
  background: #76cec7;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.22);
}

.doctorsHeroTrust {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 25px;
  margin-top: 50px;
}

.doctorsHeroTrust > div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 10px;
}

.doctorsHeroTrust svg {
  flex-shrink: 0;
  color: #67c9c2;
}

.doctorsHeroBottom {
  position: absolute;
  z-index: 4;
  left: 50%;
  bottom: 22px;
  width: min(1180px, calc(100% - 48px));
  display: flex;
  justify-content: space-between;
  color: rgba(255, 255, 255, 0.42);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  transform: translateX(-50%);
}

/* ================= STATS ================= */

.doctorsStats {
  position: relative;
  z-index: 5;
  background: #0b2545;
  color: #fff;
}

.doctorsStatsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.doctorStat {
  min-height: 150px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 25px 28px;
  border-right: 1px solid rgba(255, 255, 255, 0.09);
  transition: 0.3s ease;
}

.doctorStat:hover {
  background: rgba(85, 184, 176, 0.08);
}

.doctorStat svg {
  margin-bottom: 12px;
  color: #63c8c0;
}

.doctorStat strong {
  color: #fff;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 32px;
  font-weight: 500;
}

.doctorStat span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.55);
  font-size: 10px;
}

/* ================= INTRO ================= */

.doctorsIntro {
  padding: 105px 0;
  background: #fff;
}

.doctorsIntroGrid {
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  gap: 100px;
  align-items: start;
}

.eyebrow {
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.doctorsSectionNumber {
  margin-top: 14px;
  color: #9aaab4;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.doctorsIntro h2,
.doctorsSectionHeading h2,
.doctorsValuesHeading h2,
.doctorProcessContent h2 {
  margin: 22px 0 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(40px, 5vw, 62px);
  line-height: 1.02;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.doctorsIntroText {
  padding-top: 34px;
}

.doctorsIntroText > p {
  margin: 0 0 18px;
  color: #64748b;
  font-size: 14px;
  line-height: 1.85;
}

.doctorIntroHighlights {
  display: grid;
  gap: 13px;
  margin-top: 28px;
}

.doctorIntroHighlights > div {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #183b56;
  font-size: 12px;
  font-weight: 600;
}

/* ================= DOCTOR LIST ================= */

.doctorList {
  padding: 110px 0;
  background: #f7fafc;
}

.doctorsSectionHeading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 50px;
  margin-bottom: 55px;
}

.doctorsSectionHeading > p {
  max-width: 400px;
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.8;
}

.doctorsPremiumGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 26px;
}

.premiumDoctorCard {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  min-height: 405px;
  overflow: hidden;
  border: 1px solid #e0e9ec;
  border-radius: 17px;
  background: #fff;
  transition: 0.4s ease;
}

.premiumDoctorCard:hover {
  transform: translateY(-8px);
  border-color: #b7dcd9;
  box-shadow: 0 25px 60px rgba(11, 37, 69, 0.1);
}

.premiumDoctorImage {
  position: relative;
  min-height: 405px;
  overflow: hidden;
  background: #dcebea;
}

.premiumDoctorImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 0.7s ease;
}

.premiumDoctorCard:hover .premiumDoctorImage img {
  transform: scale(1.07);
}

.premiumDoctorImageOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(5, 27, 44, 0.05) 35%,
    rgba(5, 27, 44, 0.7) 100%
  );
}

.doctorNumber {
  position: absolute;
  top: 18px;
  left: 18px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 11px;
  font-weight: 800;
}

.doctorTopBadge {
  position: absolute;
  top: 16px;
  right: 15px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 20px;
  background: rgba(5, 27, 44, 0.48);
  color: #fff;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.1em;
  backdrop-filter: blur(8px);
}

.doctorImageBottom {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 18px;
  color: #fff;
}

.doctorImageBottom span {
  display: block;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 26px;
}

.doctorImageBottom small {
  color: rgba(255, 255, 255, 0.65);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.premiumDoctorContent {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 31px 28px 25px;
}

.doctorRole {
  color: #1f8a8a;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.premiumDoctorContent h3 {
  margin: 8px 0 4px;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 27px;
  font-weight: 500;
}

.doctorSpecialtyPremium {
  margin: 0;
  color: #64748b;
  font-size: 10px;
  font-weight: 600;
}

.doctorDescription {
  margin: 20px 0 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.75;
}

.doctorSkills {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 18px;
}

.doctorSkills span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 5px;
  background: #edf7f6;
  color: #1f7272;
  font-size: 8px;
  font-weight: 700;
}

.doctorSkills svg {
  flex-shrink: 0;
}

.doctorConsultLink {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: auto;
  padding-top: 20px;
  color: #183b56;
  text-decoration: none;
  font-size: 10px;
  font-weight: 800;
  transition: 0.25s ease;
}

.doctorConsultLink svg {
  color: #1f8a8a;
  transition: 0.25s ease;
}

.doctorConsultLink:hover svg {
  transform: translate(3px, -3px);
}

/* ================= VALUES ================= */

.doctorsValues {
  padding: 110px 0;
  background: #fff;
}

.doctorsValuesHeading {
  max-width: 760px;
}

.doctorsValuesHeading p {
  max-width: 610px;
  margin: 25px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.85;
}

.doctorsValuesGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-top: 55px;
}

.doctorValueCard {
  position: relative;
  min-height: 260px;
  padding: 28px;
  overflow: hidden;
  border: 1px solid #e0e9ec;
  border-radius: 15px;
  background: #fbfdfd;
  transition: 0.35s ease;
}

.doctorValueCard:hover {
  transform: translateY(-8px);
  border-color: #a9d5d1;
  box-shadow: 0 20px 45px rgba(11, 37, 69, 0.08);
}

.doctorValueTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.doctorValueTop > span {
  color: #9eacb5;
  font-size: 10px;
  font-weight: 800;
}

.doctorValueTop > div {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: #eaf5f4;
  color: #1f8a8a;
  transition: 0.3s ease;
}

.doctorValueCard:hover .doctorValueTop > div {
  transform: rotate(-6deg) scale(1.06);
  background: #1f8a8a;
  color: #fff;
}

.doctorValueCard h3 {
  margin: 42px 0 10px;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 25px;
  font-weight: 500;
}

.doctorValueCard p {
  max-width: 300px;
  margin: 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.75;
}

.doctorValueArrow {
  position: absolute;
  right: 26px;
  bottom: 26px;
  color: #b2c1c8;
  transition: 0.25s ease;
}

.doctorValueCard:hover .doctorValueArrow {
  color: #1f8a8a;
  transform: translate(3px, -3px);
}

/* ================= CONSULTATION PROCESS ================= */

.doctorProcess {
  padding: 110px 0;
  background: #f7fafc;
}

.doctorProcessGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 90px;
  align-items: center;
}

.doctorProcessImage {
  position: relative;
  min-height: 560px;
  overflow: hidden;
  border-radius: 18px;
}

.doctorProcessImage img {
  width: 100%;
  height: 560px;
  display: block;
  object-fit: cover;
  transition: transform 0.7s ease;
}

.doctorProcessImage:hover img {
  transform: scale(1.04);
}

.doctorProcessImageOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 50%,
    rgba(5, 27, 44, 0.45)
  );
}

.doctorFloatingCard {
  position: absolute;
  left: 22px;
  bottom: 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 35px rgba(11, 37, 69, 0.15);
  animation: doctorFloat 4s ease-in-out infinite;
}

@keyframes doctorFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-7px);
  }
}

.doctorFloatingIcon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #eaf5f4;
  color: #1f8a8a;
}

.doctorFloatingCard strong {
  display: block;
  color: #183b56;
  font-size: 12px;
}

.doctorFloatingCard span {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 10px;
}

.doctorProcessContent > p {
  max-width: 560px;
  margin: 28px 0 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.85;
}

.doctorProcessSteps {
  display: grid;
  gap: 17px;
  margin-top: 35px;
}

.doctorProcessSteps > div {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 14px;
  align-items: start;
}

.doctorProcessSteps > div > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid #cfe2e1;
  border-radius: 50%;
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 800;
}

.doctorProcessSteps strong {
  display: block;
  color: #183b56;
  font-size: 12px;
}

.doctorProcessSteps p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 10px;
  line-height: 1.65;
}

.doctorProcessContent > .primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 32px;
  padding: 14px 19px;
  border-radius: 8px;
  background: #0b2545;
  color: #fff;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: 0.3s ease;
}

.doctorProcessContent > .primaryButton:hover {
  transform: translateY(-3px);
  background: #1f8a8a;
  box-shadow: 0 15px 30px rgba(31, 138, 138, 0.18);
}

/* ================= CTA ================= */

.doctorsCTA {
  position: relative;
  padding: 110px 0;
  overflow: hidden;
  background: #0b2545;
  color: #fff;
}

.doctorsCTAGlow {
  position: absolute;
  width: 550px;
  height: 550px;
  right: -180px;
  top: -280px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.13);
}

.doctorsCTACard {
  position: relative;
  z-index: 2;
  max-width: 850px;
  margin: 0 auto;
  text-align: center;
}

.doctorsCTABadge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 30px;
  color: #6bcac2;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.doctorsCTAeyebrow {
  display: block;
  margin-top: 32px;
  color: rgba(255, 255, 255, 0.5) !important;
}

.doctorsCTACard h2 {
  margin: 18px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(42px, 6vw, 68px);
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.doctorsCTACard h2 span {
  display: block;
  color: #67c9c2;
  font-style: italic;
}

.doctorsCTACard > p {
  max-width: 570px;
  margin: 25px auto 0;
  color: rgba(255, 255, 255, 0.63);
  font-size: 14px;
  line-height: 1.8;
}

.doctorsCTAActions {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
  margin-top: 34px;
}

.doctorsCTASecondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 0 17px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  color: #fff;
  text-decoration: none;
  font-size: 11px;
  font-weight: 800;
  transition: 0.3s ease;
}

.doctorsCTASecondary:hover {
  border-color: #67c9c2;
  color: #67c9c2;
  transform: translateX(3px);
}

/* ================= TABLET ================= */

@media (max-width: 1050px) {
  .doctorsIntroGrid {
    gap: 55px;
  }

  .doctorProcessGrid {
    gap: 50px;
  }

  .premiumDoctorCard {
    grid-template-columns: 1fr;
  }

  .premiumDoctorImage {
    min-height: 350px;
    height: 350px;
  }

  .premiumDoctorContent {
    min-height: 330px;
  }
}

/* ================= TABLET / MOBILE ================= */

@media (max-width: 850px) {
  .doctorsHero {
    min-height: 620px;
  }

  .doctorsHeroContent {
    padding-top: 65px;
    padding-bottom: 95px;
  }

  .doctorsHeroBottom {
    width: calc(100% - 32px);
  }

  .doctorsHeroBottom span:nth-child(2) {
    display: none;
  }

  .doctorsStatsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .doctorStat:nth-child(2) {
    border-right: 0;
  }

  .doctorStat:nth-child(-n + 2) {
    border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  }

  .doctorsIntroGrid {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .doctorsIntroText {
    padding-top: 0;
  }

  .doctorsSectionHeading {
    display: block;
  }

  .doctorsSectionHeading > p {
    margin-top: 25px;
  }

  .doctorsValuesGrid {
    grid-template-columns: 1fr;
  }

  .doctorValueCard {
    min-height: 230px;
  }

  .doctorProcessGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .doctorProcessImage {
    min-height: 450px;
  }

  .doctorProcessImage img {
    height: 450px;
  }
}

/* ================= MOBILE ================= */

@media (max-width: 600px) {
  .doctorsPage .container {
    width: calc(100% - 30px);
  }

  .doctorsHero {
    min-height: 650px;
  }

  .doctorsHeroOverlay {
    background:
      linear-gradient(
        90deg,
        rgba(4, 25, 43, 0.95),
        rgba(4, 25, 43, 0.76)
      );
  }

  .doctorsHeroContent {
    padding-top: 45px;
    padding-bottom: 95px;
  }

  .doctorsHeroContent h1 {
    font-size: 48px;
  }

  .doctorsHeroContent > p {
    font-size: 13px;
    line-height: 1.7;
  }

  .doctorsHeroActions {
    flex-direction: column;
    align-items: flex-start;
  }

  .doctorsHeroTrust {
    display: grid;
    gap: 13px;
    margin-top: 35px;
  }

  .doctorsHeroBottom {
    bottom: 18px;
    font-size: 8px;
  }

  .doctorsHeroBottom span:first-child {
    display: none;
  }

  .doctorsStatsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .doctorStat {
    min-height: 130px;
    padding: 20px 16px;
  }

  .doctorStat strong {
    font-size: 27px;
  }

  .doctorStat span {
    font-size: 9px;
    line-height: 1.4;
  }

  .doctorsIntro,
  .doctorList,
  .doctorsValues,
  .doctorProcess {
    padding: 75px 0;
  }

  .doctorsIntro h2,
  .doctorsSectionHeading h2,
  .doctorsValuesHeading h2,
  .doctorProcessContent h2 {
    font-size: 40px;
  }

  .doctorsPremiumGrid {
    grid-template-columns: 1fr;
  }

  .premiumDoctorCard {
    grid-template-columns: 1fr;
  }

  .premiumDoctorImage {
    height: 330px;
    min-height: 330px;
  }

  .premiumDoctorContent {
    min-height: auto;
    padding: 27px 22px 23px;
  }

  .premiumDoctorContent h3 {
    font-size: 25px;
  }

  .doctorDescription {
    font-size: 11px;
  }

  .doctorValueCard {
    min-height: 215px;
    padding: 23px;
  }

  .doctorValueCard h3 {
    margin-top: 35px;
  }

  .doctorProcessImage {
    min-height: 350px;
  }

  .doctorProcessImage img {
    height: 350px;
  }

  .doctorFloatingCard {
    left: 15px;
    bottom: 15px;
  }

  .doctorsCTA {
    padding: 80px 0;
  }

  .doctorsCTACard h2 {
    font-size: 43px;
  }

  .doctorsCTAActions {
    flex-direction: column;
  }

  .doctorsCTAActions .lightButton,
  .doctorsCTASecondary {
    width: 100%;
    box-sizing: border-box;
  }
}

/* ================= SMALL MOBILE ================= */

@media (max-width: 420px) {
  .doctorsHeroContent h1 {
    font-size: 41px;
  }

  .doctorsHeroBadge {
    font-size: 8px;
  }

  .doctorsStatsGrid {
    grid-template-columns: 1fr;
  }

  .doctorStat {
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  }

  .doctorStat:last-child {
    border-bottom: 0;
  }

  .premiumDoctorImage {
    height: 290px;
    min-height: 290px;
  }

  .doctorsIntro h2,
  .doctorsSectionHeading h2,
  .doctorsValuesHeading h2,
  .doctorProcessContent h2 {
    font-size: 35px;
  }

