  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(48px, 6vw, 78px);
  line-height: 0.98;
  letter-spacing: -2px;
  color: #fff;
}

.novaDoctorsHero h1 span {
  display: block;
  color: #8ddbd5;
  font-style: italic;
  margin-top: 8px;
}

.novaDoctorsHeroContent > p {
  max-width: 650px;
  margin: 28px 0 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 16px;
  line-height: 1.8;
}

.novaDoctorsHeroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 34px;
}

.novaDoctorsPrimaryBtn,
.novaDoctorsSecondaryBtn {
