}

.novaDoctorsHeroBadge strong,
.novaDoctorsHeroBadge span {
  display: block;
}

.novaDoctorsHeroBadge strong {
  font-size: 14px;
  color: #fff;
}

.novaDoctorsHeroBadge span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 12px;
}

/* =========================
   STATS
========================= */

.novaDoctorsStats {
  background: #0b2545;
  color: #fff;
}

.novaDoctorsStatsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.novaDoctorsStat {
  min-height: 125px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 22px 25px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
}

.novaDoctorsStat:last-child {
  border-right: 0;
}

.novaDoctorsStat strong {
  font-family: "Playfair Display", Georgia, serif;
  font-size: 34px;
  color: #8ddbd5;
}

.novaDoctorsStat span {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 13px;
}

/* =========================
   INTRO
========================= */

.novaDoctorsIntro {
  padding: 105px 0;
  background: #eef8f7 !important;
}
.novaDoctorsIntroGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 90px;
  align-items: start;
}

.novaDoctorsMiniTitle {
  display: inline-block;
  color: #1f8a8a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 2px;
}

.novaDoctorsIntroHeading h2,
.novaDoctorsSectionHeading h2,
.novaDoctorsValuesHeader h2,
.novaDoctorsProcessContent h2,
.novaDoctorsCTAContent h2 {
  margin: 16px 0 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(38px, 4vw, 56px);
  line-height: 1.05;
  letter-spacing: -1.5px;
  color: #0b2545;
}

.novaDoctorsIntroHeading h2 span,
.novaDoctorsSectionHeading h2 span,
.novaDoctorsValuesHeader h2 span,
.novaDoctorsProcessContent h2 span,
.novaDoctorsCTAContent h2 span {
  color: #1f8a8a;
  font-style: italic;
}

.novaDoctorsIntroText {
  max-width: 650px;
}

.novaDoctorsIntroText p {
  margin: 0 0 18px;
  color: #64748b;
  font-size: 15px;
  line-height: 1.85;
}

.novaDoctorsTextLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  color: #0b2545;
  font-weight: 800;
  text-decoration: none;
  transition: gap 0.25s ease;
}

.novaDoctorsTextLink:hover {
  gap: 13px;
  color: #1f8a8a;
}

/* =========================
   TEAM
========================= */

.novaDoctorsTeam {
  padding: 100px 0 110px;
  background: #f7fafc;
}

.novaDoctorsSectionHeading {
  display: grid;
  grid-template-columns: 1fr 0.7fr;
  gap: 60px;
  align-items: end;
  margin-bottom: 48px;
}

.novaDoctorsSectionHeading > p {
  margin: 0;
  color: #64748b;
  line-height: 1.8;
  font-size: 15px;
}

/* =========================
   DOCTOR GRID
========================= */

.novaDoctorsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}

.novaDoctorCard {
  overflow: hidden;
  background: #fff;
  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 22px;
  box-shadow: 0 10px 35px rgba(11, 37, 69, 0.06);
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.novaDoctorCard:hover {
  transform: translateY(-10px);
  border-color: rgba(31, 138, 138, 0.2);
  box-shadow: 0 24px 55px rgba(11, 37, 69, 0.13);
}

/* Doctor image */

.novaDoctorImageWrap {
  position: relative;
  height: 350px;
  overflow: hidden;
  background: #eaf5f4;
}

.novaDoctorImageWrap img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center top;
  transition: transform 0.6s ease;
}

.novaDoctorCard:hover .novaDoctorImageWrap img {
  transform: scale(1.06);
}

.novaDoctorImageOverlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      to top,
      rgba(5, 29, 48, 0.72) 0%,
      rgba(5, 29, 48, 0.12) 48%,
      transparent 75%
    );
  pointer-events: none;
}

.novaDoctorNumber {
  position: absolute;
  top: 15px;
  left: 15px;
  min-width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  color: #0b2545;
  font-size: 12px;
  font-weight: 900;
}

.novaDoctorExperience {
  position: absolute;
  top: 15px;
  right: 15px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 999px;
  background: rgba(11, 37, 69, 0.75);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  backdrop-filter: blur(8px);
}

.novaDoctorExperience svg {
  color: #8ddbd5;
}

.novaDoctorImageContent {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 17px;
}

.novaDoctorImageContent span {
  display: inline-block;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  backdrop-filter: blur(8px);
}

/* Doctor content */

.novaDoctorInfo {
  padding: 25px 22px 23px;
}

.novaDoctorRole {
  margin-bottom: 8px;
  color: #1f8a8a;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 1.3px;
  text-transform: uppercase;
}

.novaDoctorInfo h3 {
  margin: 0;
  color: #0b2545;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 24px;
}

.novaDoctorInfo > p {
  margin: 13px 0 18px;
  color: #64748b;
  font-size: 13px;
  line-height: 1.7;
}

.novaDoctorSkills {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.novaDoctorSkills span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  border-radius: 8px;
  background: #eaf5f4;
  color: #276b6a;
  font-size: 10px;
  font-weight: 700;
}

.novaDoctorSkills svg {
  color: #1f8a8a;
}

.novaDoctorAppointmentLink {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #e8eef2;
  color: #0b2545;
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
  transition: color 0.25s ease;
}

.novaDoctorAppointmentLink:hover {
  color: #1f8a8a;
}

/* =========================
   VALUES
========================= */

.novaDoctorsValues {
  padding: 100px 0;
  background: #fff;
}

.novaDoctorsValuesHeader {
  max-width: 680px;
  margin-bottom: 45px;
}

.novaDoctorsValuesHeader p {
  max-width: 580px;
  margin: 20px 0 0;
  color: #64748b;
  line-height: 1.8;
}

.novaDoctorsValuesGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

.novaDoctorsValueCard {
  position: relative;
  padding: 28px 24px;
  border: 1px solid #e3ebef;
  border-radius: 20px;
  background: #f7fafc;
  transition: all 0.3s ease;
}

.novaDoctorsValueCard:hover {
  transform: translateY(-7px);
  background: #eaf5f4;
  border-color: rgba(31, 138, 138, 0.2);
}

.novaDoctorsValueIcon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: #dcefed;
  color: #1f8a8a;
  transition: transform 0.3s ease;
}

.novaDoctorsValueCard:hover .novaDoctorsValueIcon {
  transform: rotate(-5deg) scale(1.05);
}

.novaDoctorsValueCard h3 {
  margin: 22px 0 10px;
  color: #0b2545;
  font-size: 17px;
}

.novaDoctorsValueCard p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.7;
}

.novaDoctorsValueArrow {
  position: absolute;
  top: 25px;
  right: 23px;
  color: #1f8a8a;
}

/* =========================
   PROCESS
========================= */

.novaDoctorsProcess {
  padding: 100px 0;
  background: #eaf5f4;
}

.novaDoctorsProcessGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 75px;
  align-items: center;
}

.novaDoctorsProcessImage {
  position: relative;
  min-height: 580px;
  overflow: hidden;
  border-radius: 26px;
}

.novaDoctorsProcessImage img {
  width: 100%;
  height: 100%;
  min-height: 580px;
  display: block;
  object-fit: cover;
}

.novaDoctorsProcessImageOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(5, 29, 48, 0.55),
    transparent 55%
  );
}

.novaDoctorsProcessFloating {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 22px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.94);
  color: #0b2545;
}

.novaDoctorsProcessFloating > svg {
  color: #1f8a8a;
}

.novaDoctorsProcessFloating strong,
.novaDoctorsProcessFloating span {
  display: block;
}

.novaDoctorsProcessFloating strong {
  font-size: 13px;
}

.novaDoctorsProcessFloating span {
  margin-top: 3px;
  color: #64748b;
  font-size: 11px;
}

.novaDoctorsProcessContent > p {
  max-width: 620px;
  margin: 22px 0 30px;
  color: #64748b;
  line-height: 1.8;
}

.novaDoctorsSteps {
  border-top: 1px solid rgba(11, 37, 69, 0.1);
}

.novaDoctorsStep {
  display: grid;
  grid-template-columns: 48px 1fr;
  gap: 18px;
  padding: 20px 0;
  border-bottom: 1px solid rgba(11, 37, 69, 0.1);
}

.novaDoctorsStep > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #0b2545;
  color: #8ddbd5;
  font-size: 11px;
  font-weight: 900;
}

.novaDoctorsStep h3 {
  margin: 0 0 5px;
  color: #0b2545;
  font-size: 16px;
}

.novaDoctorsStep p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.65;
}

.novaDoctorsProcessBtn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 30px;
  padding: 14px 19px;
  border-radius: 999px;
  background: #0b2545;
  color: #fff;
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;
  transition: all 0.3s ease;
}

.novaDoctorsProcessBtn:hover {
  transform: translateY(-3px);
  background: #1f8a8a;
}

/* =========================
   CTA
========================= */

.novaDoctorsCTA {
  position: relative;
  overflow: hidden;
  padding: 105px 0;
  background:
    linear-gradient(
      90deg,
      rgba(5, 29, 48, 0.96),
      rgba(5, 29, 48, 0.78)
    ),
    url("https://images.unsplash.com/photo-1606811971618-4486d14f3f99?auto=format&fit=crop&w=1800&q=85")
      center / cover;
  color: #fff;
}

.novaDoctorsCTAContent {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.novaDoctorsCTAContent h2 {
  color: #fff;
}

.novaDoctorsCTAContent h2 span {
  color: #8ddbd5;
}

.novaDoctorsCTAContent > p {
  max-width: 600px;
  margin: 22px 0 0;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.8;
}

.novaDoctorsCTAActions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
  margin-top: 30px;
}

.novaDoctorsCTAButton,
.novaDoctorsCTASecondary {
  min-height: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 19px;
  border-radius: 999px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 800;
  transition: all 0.3s ease;
}

.novaDoctorsCTAButton {
  background: #55b8b0;
  color: #083246;
}

.novaDoctorsCTAButton:hover {
  transform: translateY(-3px);
  background: #78cec7;
}

.novaDoctorsCTASecondary {
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
  background: rgba(255, 255, 255, 0.07);
}

.novaDoctorsCTASecondary:hover {
  transform: translateY(-3px);
  background: rgba(255, 255, 255, 0.14);
}

/* =========================
   TABLET
========================= */

@media (max-width: 1100px) {
  .novaDoctorsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .novaDoctorsValuesGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .novaDoctorsProcessGrid {
    gap: 45px;
  }

  .novaDoctorImageWrap {
    height: 390px;
  }
}

