/* =====================================================
   NOVADENT HERO - LEFT RIGHT SLIDER
===================================================== */

.hero {
  position: relative;
  overflow: hidden;
}

.heroSlides {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.heroSlide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  transition:
    transform 0.9s cubic-bezier(0.77, 0, 0.175, 1),
    opacity 0.9s ease;
  will-change: transform;
}

/* Current image */
.heroSlide-current {
  transform: translateX(0);
  opacity: 1;
  z-index: 2;
}

/* Next image comes from right */
.heroSlide-next {
  transform: translateX(100%);
  opacity: 1;
  z-index: 3;
}

/* Previous image stays on left */
.heroSlide-prev {
  transform: translateX(-100%);
  opacity: 1;
  z-index: 3;
}

/* Hidden slides */
.heroSlide-hidden {
  transform: translateX(100%);
  opacity: 0;
  z-index: 1;
}

/* =====================================================
   CENTER HERO CONTENT
===================================================== */

.heroContent {
  position: relative;
  z-index: 5;
  max-width: 850px;
  margin: 0 auto;
  text-align: center;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.heroEyebrow {
  justify-content: center;
}

.heroTitle {
  text-align: center;
}

.heroText {
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.heroActions {
  justify-content: center;
}

.heroTrust {
  justify-content: center;
}

/* =====================================================
   TEXT LEFT / RIGHT ANIMATION
===================================================== */

.heroContentSlide {
  animation-duration: 0.8s;
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  animation-fill-mode: both;
}

.heroTextFromRight {
  animation-name: heroTextRight;
}

.heroTextFromLeft {
  animation-name: heroTextLeft;
}

@keyframes heroTextRight {
  from {
    opacity: 0;
    transform: translateX(70px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes heroTextLeft {
  from {
    opacity: 0;
    transform: translateX(-70px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* =====================================================
   IMAGE ZOOM EFFECT
===================================================== */

.heroSlide-current {
  animation: heroImageZoom 5s ease forwards;
}

@keyframes heroImageZoom {
  from {
    background-size: 105%;
  }

  to {
    background-size: 100%;
  }
}

