/* =========================================================
   NOVADENT - CLEAR & ATTRACTIVE HERO BACKGROUND
========================================================= */

.novaHero {
  position: relative;
  min-height: 690px;
  height: calc(100vh - 92px);
  max-height: 820px;
  overflow: hidden;
  isolation: isolate;
  background: #0b2545;
}

/* Background slider */
.novaHero .heroSlides {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.novaHero .heroSlide {
  position: absolute;
  inset: 0;
  z-index: 0;

  opacity: 0;
  visibility: hidden;

  transform: scale(1.03);

  transition:
    opacity 0.8s ease,
    transform 1.2s ease,
    visibility 0.8s ease;
}

.novaHero .heroSlide-current {
  opacity: 1;
  visibility: visible;
  z-index: 1;
  transform: scale(1);
}

/* IMPORTANT:
   Image stays CLEAR */
.novaHero .heroSlide img {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center center;

  filter: none !important;
  opacity: 1 !important;

  transform: scale(1.01);
}

/* =========================================================
   LIGHTER OVERLAY
   Image will remain clearly visible
========================================================= */

.novaHero .heroOverlay {
  position: absolute;
  inset: 0;
  z-index: 3;

  pointer-events: none;

  background:
    linear-gradient(
      90deg,
      rgba(7, 27, 48, 0.72) 0%,
      rgba(7, 27, 48, 0.42) 35%,
      rgba(7, 27, 48, 0.12) 68%,
      rgba(7, 27, 48, 0.20) 100%
    );

  backdrop-filter: none !important;
}

/* Subtle bottom readability */
.novaHero .heroOverlay::after {
  content: "";
  position: absolute;
  inset: 0;

  background: linear-gradient(
