/* =========================================
   ABOUT INTRO / STORY
========================================= */

.aboutIntroGrid {
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: 80px;
  align-items: center;
}

.aboutIntroImage {
  position: relative;
  min-height: 570px;
  overflow: visible;
  border-radius: 28px;
}

.aboutIntroImage img {
  width: 100%;
  height: 570px;
  display: block;
  object-fit: cover;
  border-radius: 28px;
  transition:
    transform 0.7s ease,
    filter 0.5s ease;
}

.aboutIntroImage:hover img {
  transform: scale(1.025);
  filter: saturate(1.05);
}

.aboutImageNumber {
  position: absolute;
  z-index: 3;
  top: 20px;
  left: 20px;
  padding: 8px 12px;
  color: white;
  background: rgba(11, 37, 69, 0.78);
  border-radius: 8px;
  backdrop-filter: blur(8px);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.13em;
}

.aboutImageGlow {
  position: absolute;
  z-index: -1;
  width: 150px;
  height: 150px;
  left: -35px;
  bottom: -35px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.2);
  filter: blur(4px);
}

.floatingAboutCard {
  position: absolute;
  z-index: 4;
  right: -30px;
  bottom: 35px;
  min-width: 220px;
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 13px;
  color: #0b2545;
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 17px;
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.16);
