}

.aboutIntroImage:hover .floatingAboutCard {
  transform: translateY(-7px);
}

.aboutFloatingIcon {
  width: 43px;
  height: 43px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: #1f8a8a;
  background: #eaf5f4;
}

.floatingAboutCard strong,
.floatingAboutCard span {
  display: block;
}

.floatingAboutCard strong {
  font-size: 15px;
}

.floatingAboutCard span {
  margin-top: 4px;
  color: #64748b;
  font-size: 11px;
}

/* Story content */

.aboutIntroContent h2,
.aboutSectionHeading h2,
.technologyContent h2,
.aboutPromiseContent h2 {
  margin: 12px 0 22px;
  color: #0b2545;
  font-family: "Playfair Display", serif;
  font-size: clamp(38px, 4vw, 56px);
  line-height: 1.08;
  letter-spacing: -0.025em;
}

.aboutIntroContent h2 span,
.aboutSectionHeading h2 span,
.technologyContent h2 span,
.aboutPromiseContent h2 span {
  display: block;
  color: #1f8a8a;
}

.aboutIntroContent p {
  color: #64748b;
  line-height: 1.8;
}

.aboutIntroContent .aboutLead {
  color: #183b56;
  font-size: 17px;
  line-height: 1.75;
}

.aboutChecklist {
  margin: 25px 0 28px;
  display: grid;
  gap: 12px;
}

.aboutChecklist > div {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #183b56;
  font-size: 14px;
  font-weight: 600;
}

.aboutChecklist svg {
  flex-shrink: 0;
  color: #1f8a8a;
}

/* =========================================
   VALUES
========================================= */

.valuesSection {
  background: #f7fafc;
}

.aboutSectionHeading {
  display: grid;
  grid-template-columns: 1fr 0.7fr;
  gap: 70px;
  align-items: end;
  margin-bottom: 45px;
}

.aboutSectionHeading > p {
  margin: 0;
  color: #64748b;
  line-height: 1.8;
}

.valueGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

.valueCard {
  position: relative;
  min-height: 290px;
  padding: 25px;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid rgba(11, 37, 69, 0.08);
  border-radius: 20px;
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease,
    border-color 0.3s ease;
}

.valueCard:hover {
  transform: translateY(-9px);
  border-color: rgba(31, 138, 138, 0.28);
  box-shadow: 0 22px 45px rgba(11, 37, 69, 0.11);
}

.valueCardTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.valueNumber {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.valueIcon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  color: #1f8a8a;
  background: #eaf5f4;
  border-radius: 14px;
  transition:
    transform 0.35s ease,
    background 0.35s ease;
}

.valueCard:hover .valueIcon {
  transform: rotate(-5deg) scale(1.08);
  background: #d9efed;
}

.valueCard h3 {
  margin: 55px 0 10px;
  color: #0b2545;
  font-family: "Playfair Display", serif;
  font-size: 22px;
}

.valueCard p {
  color: #64748b;
  font-size: 13px;
  line-height: 1.7;
}

.valueArrow {
  position: absolute;
  right: 20px;
  bottom: 20px;
  color: #1f8a8a;
  transition: transform 0.3s ease;
}

.valueCard:hover .valueArrow {
  transform: translate(4px, -4px);
}

/* =========================================
   TECHNOLOGY
========================================= */

.aboutTechnology {
  background: #ffffff;
}

.technologyGrid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 80px;
  align-items: center;
}

.technologyPoints {
  margin: 30px 0;
  display: grid;
  gap: 13px;
}

.technologyPoint {
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 48px;
  padding: 8px 12px;
  border-radius: 12px;
  transition:
    background 0.3s ease,
    transform 0.3s ease;
}

.technologyPoint:hover {
  background: #f1f8f7;
  transform: translateX(5px);
}

.techNumber {
  width: 25px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
}

.techIcon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  color: #1f8a8a;
  background: #eaf5f4;
  border-radius: 9px;
}

.technologyPoint > span:last-child {
  color: #183b56;
  font-size: 13px;
  font-weight: 600;
}

.technologyImage {
  position: relative;
  min-height: 570px;
  overflow: hidden;
  border-radius: 28px;
}

.technologyImage img {
  width: 100%;
  height: 570px;
  display: block;
  object-fit: cover;
  transition: transform 0.8s ease;
}

.technologyImage:hover img {
  transform: scale(1.05);
}

.technologyImageOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 45%,
    rgba(11, 37, 69, 0.72)
  );
}

.imageOverlayCard {
  position: absolute;
  right: 24px;
  bottom: 24px;
  left: 24px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 16px;
  color: white;
  background: rgba(11, 37, 69, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 15px;
  backdrop-filter: blur(10px);
}

.overlayCardIcon {
  width: 43px;
  height: 43px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  color: #55b8b0;
  background: rgba(85, 184, 176, 0.15);
  border-radius: 11px;
}

.imageOverlayCard strong,
.imageOverlayCard span {
  display: block;
}

.imageOverlayCard strong {
  font-size: 14px;
}

.imageOverlayCard span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 10px;
}

/* =========================================
   STATS
========================================= */

.aboutStats {
  position: relative;
  overflow: hidden;
  padding: 70px 0;
  background: #0b2545;
}

.aboutStatsGlow {
  position: absolute;
  width: 360px;
  height: 360px;
  top: -220px;
  right: -100px;
  border-radius: 50%;
  background: rgba(85, 184, 176, 0.12);
}

.aboutStatsGrid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.aboutStatItem {
  padding: 15px 30px;
  text-align: center;
  border-right: 1px solid rgba(255, 255, 255, 0.12);
}

.aboutStatItem:last-child {
  border-right: 0;
}

.aboutStatItem strong,
.aboutStatItem span,
.aboutStatItem small {
  display: block;
}

.aboutStatItem strong {
  color: #8ed3ce;
  font-family: "Playfair Display", serif;
  font-size: 48px;
}

.aboutStatItem span {
  margin-top: 5px;
  color: white;
  font-size: 13px;
  font-weight: 700;
}

.aboutStatItem small {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.52);
  font-size: 10px;
}

/* =========================================
   PROMISE
========================================= */

.aboutPromiseGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.aboutPromiseImage {
  position: relative;
  overflow: hidden;
  border-radius: 28px;
}

.aboutPromiseImage img {
  width: 100%;
  height: 520px;
  display: block;
  object-fit: cover;
  transition: transform 0.7s ease;
}

.aboutPromiseImage:hover img {
  transform: scale(1.05);
}

.promiseBadge {
  position: absolute;
  left: 22px;
  bottom: 22px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 15px;
  color: white;
  background: rgba(11, 37, 69, 0.86);
  border-radius: 11px;
  backdrop-filter: blur(10px);
  font-size: 11px;
  font-weight: 700;
}

.promiseBadge svg {
  color: #55b8b0;
}

.promisePoints {
  margin-top: 30px;
  display: grid;
  gap: 18px;
}

.promisePoints > div {
  display: flex;
  align-items: flex-start;
  gap: 13px;
}

.promisePointIcon {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  color: #1f8a8a;
  background: #eaf5f4;
  border-radius: 11px;
}

.promisePoints strong,
.promisePoints span {
  display: block;
}

.promisePoints strong {
  color: #0b2545;
  font-size: 14px;
}

.promisePoints span {
  margin-top: 4px;
  color: #64748b;
  font-size: 12px;
  line-height: 1.6;
}

/* =========================================
   ABOUT CTA
========================================= */

.aboutCTA {
  position: relative;
  overflow: hidden;
  padding: 90px 0;
  background: #eaf5f4;
}

.ctaGlow {
  position: absolute;
  width: 400px;
  height: 400px;
  top: -250px;
  right: -100px;
  border-radius: 50%;
  background: rgba(31, 138, 138, 0.12);
}

.aboutCTACard {
  position: relative;
  z-index: 2;
  padding: 65px;
  overflow: hidden;
  text-align: center;
  background: #0b2545;
  border-radius: 28px;
  box-shadow: 0 25px 55px rgba(11, 37, 69, 0.18);
}

.aboutCTABadge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 13px;
  color: #8ed3ce;
  background: rgba(85, 184, 176, 0.1);
  border: 1px solid rgba(85, 184, 176, 0.2);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.aboutCTACard h2 {
  margin: 18px auto;
  max-width: 700px;
  color: white;
  font-family: "Playfair Display", serif;
  font-size: clamp(40px, 5vw, 62px);
  line-height: 1.05;
}

.aboutCTACard h2 span {
  display: block;
  color: #8ed3ce;
}

.aboutCTACard > p {
  max-width: 590px;
  margin: 0 auto 28px;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.7;
}

.ctaActions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 18px;
}

.aboutCTASecondary {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: white;
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  transition:
    color 0.3s ease,
    transform 0.3s ease;
}

.aboutCTASecondary:hover {
  color: #8ed3ce;
  transform: translateX(4px);
}

/* =========================================
   RESPONSIVE
========================================= */

@media (max-width: 1024px) {
  .aboutIntroGrid,
  .technologyGrid,
  .aboutPromiseGrid {
    gap: 45px;
  }

  .valueGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .aboutSectionHeading {
    gap: 35px;
  }
}

@media (max-width: 768px) {
  .aboutHero,
  .aboutHeroContent {
    min-height: 600px;
  }

  .aboutHeroOverlay {
    background:
      linear-gradient(
        90deg,
        rgba(5, 24, 45, 0.88),
        rgba(5, 24, 45, 0.62)
      );
  }

  .aboutHeroContent h1 {
    font-size: clamp(42px, 10vw, 62px);
  }

  .aboutHeroContent > p {
    font-size: 15px;
  }

  .aboutHeroActions {
    flex-wrap: wrap;
  }

  .aboutHeroScroll {
    display: none;
  }

  .aboutIntroGrid,
  .technologyGrid,
  .aboutPromiseGrid,
  .aboutSectionHeading {
    grid-template-columns: 1fr;
  }

  .aboutIntroImage,
  .technologyImage {
    min-height: 430px;
  }

  .aboutIntroImage img,
  .technologyImage img {
    height: 430px;
  }

  .floatingAboutCard {
    right: 18px;
    bottom: 20px;
  }

  .valueGrid {
    grid-template-columns: 1fr 1fr;
  }

  .aboutStatsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .aboutStatItem:nth-child(2) {
    border-right: 0;
  }

  .aboutStatItem {
    margin-bottom: 20px;
  }

  .aboutCTACard {
    padding: 45px 25px;
  }

  .ctaActions {
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .aboutHero,
  .aboutHeroContent {
    min-height: 560px;
  }

  .aboutHeroContent h1 {
    font-size: 40px;
  }

  .aboutHeroContent > p {
    font-size: 14px;
  }

  .aboutHeroActions {
    width: 100%;
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

  .aboutIntroImage,
  .technologyImage {
    min-height: 340px;
  }

  .aboutIntroImage img,
  .technologyImage img {
    height: 340px;
  }

  .floatingAboutCard {
    min-width: 190px;
    padding: 12px;
  }

  .aboutIntroContent h2,
  .aboutSectionHeading h2,
  .technologyContent h2,
  .aboutPromiseContent h2 {
    font-size: 34px;
  }

  .valueGrid {
    grid-template-columns: 1fr;
  }

  .valueCard {
    min-height: 250px;
  }

  .aboutStats {
    padding: 50px 0;
  }

  .aboutStatsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .aboutStatItem {
    padding: 12px 8px;
  }

  .aboutStatItem strong {
    font-size: 35px;
  }

  .aboutStatItem span {
    font-size: 11px;
  }

  .aboutCTACard {
    padding: 38px 20px;
    border-radius: 20px;
  }

  .aboutCTACard h2 {
    font-size: 36px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .aboutPage *,
  .aboutPage *::before,
  .aboutPage *::after {
    animation: none !important;
    transition: none !important;
  }
}
