/* =========================================
   FILTERS
========================================= */

.novaGalleryFilters {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 35px;
}

.galleryFilter {
  border: 1px solid #d9e5e8;
  background: white;
  color: #64748b;
  padding: 11px 19px;
  border-radius: 999px;
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  transition: all 0.25s ease;
}

.galleryFilter:hover {
  border-color: #1f8a8a;
  color: #1f8a8a;
  transform: translateY(-2px);
}

.galleryFilter.active {
  border-color: #0b2545;
  background: #0b2545;
  color: white;
}

/* =========================================
   IMAGE GRID
========================================= */

.novaGalleryGrid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 18px;
}

/* IMPORTANT:
   The button itself must not hide the image.
*/

.novaGalleryItem {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  padding: 0;
  margin: 0;
  border: 0;
  background: transparent;
  overflow: hidden;
  cursor: pointer;
  text-align: left;
  border-radius: 20px;
  min-height: 330px;
}

/* Large cards */

.novaGalleryItem.galleryItem-1,
.novaGalleryItem.galleryItem-4 {
  grid-column: span 6;
  min-height: 440px;
}

/* Small cards */

.novaGalleryItem.galleryItem-2,
.novaGalleryItem.galleryItem-3,
.novaGalleryItem.galleryItem-5,
.novaGalleryItem.galleryItem-6,
.novaGalleryItem.galleryItem-7,
.novaGalleryItem.galleryItem-8 {
  grid-column: span 3;
  min-height: 330px;
}

/* =========================================
   IMAGE WRAPPER
========================================= */

.novaGalleryImageWrap {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #dfe9eb;
  border-radius: inherit;
}

/* =========================================
   ACTUAL IMAGE
========================================= */

.novaGalleryImageWrap img {
  position: absolute !important;
  inset: 0 !important;

  display: block !important;

  width: 100% !important;
  height: 100% !important;

  min-width: 100% !important;
  min-height: 100% !important;

  max-width: none !important;
  max-height: none !important;

  object-fit: cover !important;
  object-position: center !important;

  opacity: 1 !important;
  visibility: visible !important;

  z-index: 1 !important;

  transition:
    transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1),
    filter 0.5s ease;
}

.novaGalleryItem:hover .novaGalleryImageWrap img {
  transform: scale(1.06);
  filter: saturate(1.08);
}

/* =========================================
   IMAGE OVERLAY
========================================= */

.novaGalleryImageOverlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      to bottom,
      rgba(4, 20, 38, 0.05) 15%,
      rgba(4, 20, 38, 0.12) 45%,
      rgba(4, 20, 38, 0.78) 100%
    );
  pointer-events: none;
}

.novaGalleryShine {
  position: absolute;
  inset: -100%;
  z-index: 3;
  background: linear-gradient(
    120deg,
    transparent 35%,
    rgba(255, 255, 255, 0.18) 50%,
    transparent 65%
  );
  transform: translateX(-40%);
  transition: transform 0.8s ease;
  pointer-events: none;
}

.novaGalleryItem:hover .novaGalleryShine {
  transform: translateX(40%);
}

/* =========================================
   TOP LABELS
========================================= */

.novaGalleryTop {
  position: absolute;
  top: 18px;
  left: 18px;
  right: 18px;
  z-index: 4;

  display: flex;
  align-items: center;
  justify-content: space-between;

  pointer-events: none;
}

.novaGalleryIndex,
.novaGalleryCategory {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 30px;
  padding: 5px 10px;

  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 999px;

  background: rgba(5, 25, 45, 0.3);
  backdrop-filter: blur(8px);

  color: white;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.novaGalleryIndex {
  min-width: 34px;
}

/* =========================================
   OPEN ICON
========================================= */

.novaGalleryOpen {
  position: absolute;
  top: 18px;
  right: 18px;

  z-index: 5;

  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.92);
  color: #0b2545;

  opacity: 0;
  transform: translateY(-8px) scale(0.9);

  transition: all 0.3s ease;
  pointer-events: none;
}

.novaGalleryItem:hover .novaGalleryOpen {
  opacity: 1;
  transform: translateY(0) scale(1);
}

/* =========================================
   IMAGE INFO
========================================= */

.novaGalleryInfo {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 22px;
  z-index: 4;
  pointer-events: none;
}

.novaGalleryInfo h3 {
  margin: 0;
  color: white;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 24px;
  font-weight: 500;
}

/* =========================================
   EMPTY STATE
========================================= */

.novaGalleryEmpty {
  padding: 80px 20px;
  text-align: center;
  background: white;
  border-radius: 20px;
}

.novaGalleryEmpty h3 {
  margin: 0 0 10px;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 28px;
}

.novaGalleryEmpty p {
  margin: 0;
  color: #64748b;
}

/* =========================================
   CTA
========================================= */

.novaGalleryCTA {
  padding: 0 0 120px;
  background: #f7fafc;
}

.novaGalleryCTACard {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 50px;

  padding: 65px;

  border-radius: 30px;

  background:
    radial-gradient(
      circle at 85% 15%,
      rgba(85, 184, 176, 0.22),
      transparent 30%
    ),
    #0b2545;

  color: white;
  overflow: hidden;
}

.novaGalleryCTACard .novaGalleryOverline {
  color: #8ed8d1;
}

.novaGalleryCTACard h2 {
  max-width: 650px;
  color: white;
}

.novaGalleryCTACard h2 em {
  color: #8ed8d1;
}

.novaGalleryCTACard p {
  max-width: 600px;
  margin: 22px 0 0;
  color: rgba(255, 255, 255, 0.7);
  line-height: 1.8;
}

.novaGalleryCTAButton {
  flex-shrink: 0;

  display: inline-flex;
  align-items: center;
  gap: 12px;

  padding: 16px 22px;

  border-radius: 999px;

  background: white;
  color: #0b2545;

  text-decoration: none;
  font-size: 14px;
  font-weight: 800;

  transition: 0.3s ease;
}

.novaGalleryCTAButton:hover {
  background: #8ed8d1;
  transform: translateY(-3px);
}

/* =========================================
   LIGHTBOX
========================================= */

.novaGalleryLightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 30px;

  background: rgba(3, 14, 28, 0.94);
  backdrop-filter: blur(12px);
}

.novaGalleryLightboxContent {
  position: relative;
  width: min(1000px, 90vw);
  max-height: 90vh;
}

.novaGalleryLightboxContent img {
  display: block;
  width: 100%;
  max-height: 75vh;
  object-fit: contain;
  border-radius: 16px;
}

.novaGalleryLightboxCaption {
  padding-top: 18px;
  color: white;
}

.novaGalleryLightboxCaption span {
  color: #8ed8d1;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.novaGalleryLightboxCaption h3 {
  margin: 6px 0;
  font-family: "Playfair Display", Georgia, serif;
  font-size: 26px;
  font-weight: 500;
}

.novaGalleryLightboxCaption p {
  margin: 0;
  color: rgba(255, 255, 255, 0.55);
  font-size: 13px;
}

.novaGalleryClose,
.novaGalleryPrev,
.novaGalleryNext {
  position: absolute;
  z-index: 10;

  border: 1px solid rgba(255, 255, 255, 0.18);

  background: rgba(255, 255, 255, 0.1);
  color: white;

  display: grid;
  place-items: center;

  cursor: pointer;

  transition: 0.25s ease;
}

.novaGalleryClose:hover,
.novaGalleryPrev:hover,
.novaGalleryNext:hover {
  background: white;
  color: #0b2545;
}

.novaGalleryClose {
  top: 25px;
  right: 25px;

  width: 46px;
  height: 46px;

  border-radius: 50%;
}

.novaGalleryPrev,
.novaGalleryNext {
  top: 50%;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  transform: translateY(-50%);
}

.novaGalleryPrev {
  left: 25px;
}

.novaGalleryNext {
  right: 25px;
}

/* =========================================
   TABLET
========================================= */

@media (max-width: 900px) {

  .novaGalleryHero {
    min-height: 600px;
  }

  .novaGalleryHero .novaGalleryContainer {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .novaGalleryHeroSide {
    display: none;
  }

  .novaGalleryIntroGrid,
  .novaGalleryHeading {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .novaGalleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .novaGalleryItem.galleryItem-1,
  .novaGalleryItem.galleryItem-4,
  .novaGalleryItem.galleryItem-2,
  .novaGalleryItem.galleryItem-3,
  .novaGalleryItem.galleryItem-5,
  .novaGalleryItem.galleryItem-6,
  .novaGalleryItem.galleryItem-7,
  .novaGalleryItem.galleryItem-8 {
    grid-column: span 1;
    min-height: 300px;
  }

  .novaGalleryItem.galleryItem-1,
  .novaGalleryItem.galleryItem-4 {
    grid-column: span 2;
  }

  .novaGalleryCTACard {
    padding: 50px;
  }
}

/* =========================================
   MOBILE
========================================= */

@media (max-width: 600px) {

  .novaGalleryContainer {
    width: min(100% - 28px, 1180px);
  }

  .novaGalleryHero {
    min-height: 620px;
    padding: 80px 0;
  }

  .novaGalleryHero h1 {
    font-size: 48px;
  }

  .novaGalleryHero p {
    font-size: 15px;
  }

  .novaGalleryHeroActions {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .novaGalleryIntro {
    padding: 80px 0 55px;
  }

  .novaGallerySection {
    padding: 50px 0 80px;
  }

  .novaGalleryGrid {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .novaGalleryItem,
  .novaGalleryItem.galleryItem-1,
  .novaGalleryItem.galleryItem-4,
  .novaGalleryItem.galleryItem-2,
  .novaGalleryItem.galleryItem-3,
  .novaGalleryItem.galleryItem-5,
  .novaGalleryItem.galleryItem-6,
  .novaGalleryItem.galleryItem-7,
  .novaGalleryItem.galleryItem-8 {
    grid-column: span 1;
    min-height: 210px;
    border-radius: 14px;
  }

  .novaGalleryItem.galleryItem-1,
  .novaGalleryItem.galleryItem-4 {
    grid-column: span 2;
    min-height: 290px;
  }

  .novaGalleryInfo {
    left: 14px;
    right: 14px;
    bottom: 14px;
  }

  .novaGalleryInfo h3 {
    font-size: 19px;
  }

  .novaGalleryTop {
    top: 12px;
    left: 12px;
    right: 12px;
  }

  .novaGalleryOpen {
    top: 12px;
    right: 12px;
    width: 36px;
    height: 36px;
  }

  .novaGalleryCategory {
    display: none;
  }

  .novaGalleryCTACard {
    padding: 35px 25px;
    flex-direction: column;
    align-items: flex-start;
    border-radius: 22px;
  }

  .novaGalleryLightbox {
    padding: 18px;
  }

  .novaGalleryPrev {
    left: 10px;
  }

  .novaGalleryNext {
    right: 10px;
  }

  .novaGalleryClose {
    top: 12px;
    right: 12px;
  }
}
/* =========================================================
   NOVADENT PREMIUM GALLERY
   ========================================================= */

.nd-gallery {
  width: 100%;
  overflow: hidden;
  background: #f7fafc;
  color: #183b56;
}

/* CONTAINER */

.nd-gallery-container {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

/* =========================================================
   HERO
   ========================================================= */

.nd-gallery-hero {
  position: relative;
  min-height: 720px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: #0b2545;
}

.nd-gallery-hero-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  animation: ndGalleryZoom 12s ease-in-out infinite alternate;
}

@keyframes ndGalleryZoom {
  from {
    transform: scale(1);
  }

  to {
    transform: scale(1.08);
  }
}

.nd-gallery-hero-overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(7, 28, 53, 0.97) 0%,
      rgba(7, 28, 53, 0.84) 38%,
      rgba(7, 28, 53, 0.46) 72%,
      rgba(7, 28, 53, 0.22) 100%
    );
}

.nd-gallery-hero-content {
  position: relative;
  z-index: 2;
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
  padding: 100px 0;
}

.nd-gallery-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: #55b8b0;
  font-family: Arial, sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 2.5px;
}

.nd-gallery-eyebrow::before {
  content: "";
  width: 34px;
  height: 1px;
  background: #55b8b0;
}

.nd-gallery-hero h1 {
  max-width: 850px;
  margin: 24px 0;
  color: #fff;
  font-family: Georgia, serif;
  font-size: clamp(54px, 8vw, 100px);
  line-height: 0.98;
  font-weight: 500;
  letter-spacing: -4px;
}

.nd-gallery-hero h1 span {
  color: #55b8b0;
  font-style: italic;
}

.nd-gallery-hero-content > p {
  max-width: 570px;
  margin: 0;
  color: rgba(255, 255, 255, 0.78);
  font-family: Arial, sans-serif;
  font-size: 16px;
  line-height: 1.85;
}

.nd-gallery-main-btn {
  display: inline-flex;
  align-items: center;
  gap: 18px;
  margin-top: 34px;
  padding: 15px 22px 15px 25px;
  border-radius: 40px;
  background: #55b8b0;
  color: #0b2545;
  text-decoration: none;
  font-family: Arial, sans-serif;
  font-size: 13px;
  font-weight: 800;
  transition: 0.3s ease;
}

.nd-gallery-main-btn span {
  font-size: 18px;
  transition: transform 0.3s ease;
}

.nd-gallery-main-btn:hover {
  background: #fff;
  transform: translateY(-3px);
}

.nd-gallery-main-btn:hover span {
  transform: translateY(4px);
}

.nd-gallery-scroll {
  position: absolute;
  right: 34px;
  bottom: 35px;
  z-index: 2;
  color: rgba(255, 255, 255, 0.65);
  font-family: Arial, sans-serif;
  font-size: 9px;
  letter-spacing: 2px;
  writing-mode: vertical-rl;
}

/* =========================================================
   INTRO
   ========================================================= */

.nd-gallery-intro {
  padding: 125px 0;
  background: #fff;
}

.nd-gallery-intro-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 100px;
  align-items: center;
}

.nd-gallery-small-title {
  color: #1f8a8a;
  font-family: Arial, sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2.5px;
  text-transform: uppercase;
}

.nd-gallery-small-title::before {
  content: "—";
  margin-right: 9px;
}

.nd-gallery-small-title.light {
  color: #55b8b0;
}

.nd-gallery-intro h2,
.nd-gallery-section-top h2,
.nd-gallery-cta h2 {
  margin: 18px 0 0;
  color: #0b2545;
  font-family: Georgia, serif;
  font-size: clamp(45px, 5.4vw, 72px);
  line-height: 1;
  font-weight: 500;
  letter-spacing: -2.5px;
}

.nd-gallery-intro h2 em,
.nd-gallery-section-top h2 em,
.nd-gallery-cta h2 em {
  color: #55b8b0;
  font-style: italic;
}

.nd-gallery-intro-copy {
  padding-top: 15px;
}

.nd-gallery-intro-copy p {
  margin: 0 0 22px;
  color: #64748b;
  font-family: Arial, sans-serif;
  font-size: 16px;
  line-height: 1.9;
}

.nd-gallery-line {
  width: 80px;
  height: 2px;
  margin-top: 35px;
  background: #55b8b0;
}

/* =========================================================
   GALLERY SECTION
   ========================================================= */

.nd-gallery-section {
  padding: 125px 0 135px;
  background:
    radial-gradient(
      circle at 10% 0%,
      rgba(85, 184, 176, 0.08),
      transparent 30%
    ),
    #f7fafc;
}

.nd-gallery-section-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
}

.nd-gallery-total {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding-bottom: 5px;
}

.nd-gallery-total strong {
  color: #0b2545;
  font-family: Georgia, serif;
  font-size: 44px;
  font-weight: 500;
}

.nd-gallery-total span {
  color: #64748b;
  font-family: Arial, sans-serif;
  font-size: 11px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

/* FILTER */

.nd-gallery-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin: 48px 0 42px;
}

.nd-gallery-filters button {
  padding: 11px 19px;
  border: 1px solid #d7e4e7;
  border-radius: 50px;
  background: #fff;
  color: #64748b;
  font-family: Arial, sans-serif;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.25s ease;
}

.nd-gallery-filters button:hover {
  border-color: #55b8b0;
  color: #1f8a8a;
  transform: translateY(-2px);
}

.nd-gallery-filters button.active {
  border-color: #0b2545;
  background: #0b2545;
  color: #fff;
}

/* =========================================================
   IMAGE GRID
   ========================================================= */

.nd-gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 250px;
  gap: 18px;
}

.nd-gallery-card {
  position: relative;
  min-width: 0;
  min-height: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 14px;
  background: #dcebea;
  cursor: pointer;
  text-align: left;
  isolation: isolate;
}

.nd-gallery-card.card-1 {
  grid-column: span 2;
  grid-row: span 2;
}

.nd-gallery-card.card-4 {
  grid-column: span 2;
}

.nd-gallery-card img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition:
    transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1),
    filter 0.7s ease;
}

.nd-gallery-card-shade {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      180deg,
      transparent 30%,
      rgba(7, 28, 53, 0.18) 50%,
      rgba(7, 28, 53, 0.94) 100%
    );
  opacity: 0.85;
  transition: 0.5s ease;
}

.nd-gallery-card-content {
  position: absolute;
  left: 24px;
  right: 24px;
  bottom: 23px;
  z-index: 2;
  transform: translateY(8px);
  transition: 0.4s ease;
}

.nd-gallery-card-content > span {
  color: #55b8b0;
  font-family: Arial, sans-serif;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.nd-gallery-card-content h3 {
  margin: 7px 0 8px;
  color: #fff;
  font-family: Georgia, serif;
  font-size: 25px;
  line-height: 1.1;
  font-weight: 500;
}

.nd-gallery-view {
  display: flex;
  align-items: center;
  gap: 9px;
  color: rgba(255, 255, 255, 0.7);
  font-family: Arial, sans-serif;
  font-size: 10px;
  letter-spacing: 0.5px;
  opacity: 0;
  transform: translateY(7px);
  transition: 0.35s ease;
}

.nd-gallery-view b {
  color: #55b8b0;
  font-size: 15px;
}

.nd-gallery-number {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 2;
  color: rgba(255, 255, 255, 0.8);
  font-family: Arial, sans-serif;
  font-size: 10px;
  letter-spacing: 1px;
}

.nd-gallery-card:hover img {
  transform: scale(1.09);
  filter: brightness(0.78);
}

.nd-gallery-card:hover .nd-gallery-card-shade {
  opacity: 1;
}

.nd-gallery-card:hover .nd-gallery-card-content {
  transform: translateY(0);
}

.nd-gallery-card:hover .nd-gallery-view {
  opacity: 1;
  transform: translateY(0);
}

/* =========================================================
   CTA
   ========================================================= */

.nd-gallery-cta {
  padding: 0 0 120px;
  background: #fff;
}

.nd-gallery-cta-inner {
  position: relative;
  overflow: hidden;
  padding: 75px 80px;
  display: flex;
  align-items: flex-end;
