  transition: 0.25s ease;
}

.nova-gallery-filters button:hover {
  border-color: #55b8b0;
  color: #1f8a8a;
  transform: translateY(-2px);
}

.nova-gallery-filters button.active {
  border-color: #0b2545;
  background: #0b2545;
  color: #ffffff;
}

/* =====================================================
   IMAGE GRID
===================================================== */

.nova-gallery-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: 250px;
  gap: 16px;
}

.nova-gallery-card {
  position: relative;
  min-width: 0;
  min-height: 250px;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 14px;
  background: #dcebea;
  cursor: pointer;
  text-align: left;
}

.nova-gallery-card:nth-child(1) {
  grid-column: span 2;
  grid-row: span 2;
}

.nova-gallery-card:nth-child(4) {
  grid-column: span 2;
}

.nova-gallery-card > img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition:
    transform 0.65s ease,
    filter 0.65s ease;
}

.nova-gallery-card:hover > img {
  transform: scale(1.08);
  filter: brightness(0.82);
}

.nova-gallery-card-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  padding: 23px;
  background: linear-gradient(
    transparent 25%,
    rgba(11, 37, 69, 0.92) 100%
  );
}

.nova-gallery-card-overlay small {
  color: #55b8b0;
  font-family: Arial, sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.nova-gallery-card-overlay h3 {
  margin: 7px 0;
  color: #ffffff;
  font-family: Georgia, serif;
  font-size: 23px;
  line-height: 1.1;
  font-weight: 500;
}

.nova-gallery-card-overlay span {
  color: rgba(255, 255, 255, 0.72);
  font-family: Arial, sans-serif;
  font-size: 10px;
}

.nova-gallery-card > b {
  position: absolute;
  top: 18px;
  right: 18px;
  color: #ffffff;
  font-family: Arial, sans-serif;
  font-size: 10px;
}

/* =====================================================
   CTA
===================================================== */

.nova-gallery-cta {
  padding: 30px 0 115px;
  background: #ffffff;
}

.nova-gallery-cta-box {
  padding: 68px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 45px;
  border-radius: 18px;
  background: #0b2545;
}

.nova-gallery-cta small {
  color: #55b8b0;
}

.nova-gallery-cta h2 {
  color: #ffffff;
}

.nova-gallery-cta p {
  max-width: 520px;
  margin: 20px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-family: Arial, sans-serif;
  font-size: 14px;
  line-height: 1.8;
}

.nova-gallery-cta-box > a {
  flex-shrink: 0;
  padding: 15px 23px;
  border-radius: 30px;
  background: #55b8b0;
  color: #0b2545;
  text-decoration: none;
  font-family: Arial, sans-serif;
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transition: 0.3s ease;
}

.nova-gallery-cta-box > a:hover {
  background: #ffffff;
  transform: translateY(-3px);
}

/* =====================================================
   LIGHTBOX
===================================================== */

.nova-gallery-lightbox {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 25px;
  background: rgba(3, 13, 25, 0.96);
}

.nova-gallery-lightbox-box {
  position: relative;
  width: min(900px, 100%);
}

.nova-gallery-lightbox-box img {
  width: 100%;
  max-height: 75vh;
  display: block;
  object-fit: contain;
  border-radius: 12px;
}

.nova-gallery-lightbox-box button {
  position: absolute;
  top: -52px;
  right: 0;
  width: 42px;
  height: 42px;
  border: 0;
  border-radius: 50%;
  background: #ffffff;
  color: #0b2545;
  font-size: 27px;
  cursor: pointer;
}

.nova-gallery-lightbox-box small {
  display: block;
  margin-top: 15px;
  color: #55b8b0;
  font-family: Arial, sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.nova-gallery-lightbox-box h3 {
  margin: 5px 0 0;
  color: #ffffff;
  font-family: Georgia, serif;
  font-size: 28px;
  font-weight: 500;
}

/* =====================================================
   TABLET
===================================================== */

@media (max-width: 900px) {
  .nova-gallery-intro .nova-gallery-container {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .nova-gallery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: 260px;
  }

  .nova-gallery-card:nth-child(1) {
