  .homeIntroContent,
  .homeWhyContent,
  .aboutIntroContent {
    order: 2;
  }

  .appointmentHeroVisual,
  .contactHeroVisual {
    order: 1;
  }

  .appointmentHeroContent,
  .contactHeroContent {
    order: 2;
  }
}

@media (max-width: 600px) {

  .novaHero {
    min-height: 700px;
    height: 760px;
  }

  .heroOverlay {
    background:
      linear-gradient(
