  }

  .heroTrustItem strong {
    font-size: 18px;
  }

  .heroTrustItem span {
    font-size: 8px;
  }

  .heroArrow {
    top: 48%;
    width: 42px;
    height: 42px;
  }

  .heroArrowLeft {
    left: 10px;
  }

  .heroArrowRight {
    right: 10px;
  }

  .heroBottomControls {
