/* =========================================================
   NOVADENT — TREATMENTS HERO
   ========================================================= */

.ndtHero {
  position: relative;
  min-height: 620px;
  overflow: hidden;

  display: flex;
  align-items: center;
  justify-content: center;

  isolation: isolate;
}

/* Background Image */

.ndtHeroImage {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  object-fit: cover;

  z-index: -2;

  transition: transform 8s ease;
}

.ndtHero:hover .ndtHeroImage {
  transform: scale(1.05);
}

/* Dark Overlay */

.ndtHeroOverlay {
  position: absolute;
  inset: 0;

  z-index: -1;

  background:
    linear-gradient(
      90deg,
      rgba(7, 30, 52, 0.88) 0%,
      rgba(7, 30, 52, 0.72) 45%,
      rgba(7, 30, 52, 0.55) 100%
