  position: absolute;

  width: 320px;
  height: 320px;

  right: -150px;
  top: -130px;

  border-radius: 50%;

  background: rgba(22, 139, 136, 0.07);

  pointer-events: none;
}

.ndtIntroGrid {
  position: relative;
  z-index: 2;

  display: grid;

  grid-template-columns: 0.95fr 1.05fr;

  gap: 90px;

  align-items: center;
}

/* LEFT */

