  margin-bottom: 20px;

  color: #89999c;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 1.6px;
}

.ndtIntro h2 {
  margin: 0;

  color: #173d46;

  font-size: clamp(42px, 5vw, 64px);

  line-height: 1.02;

  font-weight: 600;

  letter-spacing: -2.5px;
}

.ndtIntro h2 em {
  display: block;

  color: #168b88;

  font-style: italic;
}

/* RIGHT */

.ndtIntroText {
  max-width: 590px;
}

.ndtIntroText p {
  margin: 0 0 22px;

  color: #718287;

  font-size: 14px;

  line-height: 1.85;
}

.ndtIntroText .ndtLead {
  color: #36535a;

  font-size: 17px;

  line-height: 1.75;

  font-weight: 500;
}

/* LIST */

.ndtIntroList {
  display: flex;

  flex-direction: column;

  gap: 13px;

  margin-top: 30px;
}

.ndtIntroList span {
  display: flex;

  align-items: center;

  gap: 11px;

  color: #3e5b61;

  font-size: 12px;

  font-weight: 600;
}

.ndtIntroList svg {
  flex-shrink: 0;

  color: #168b88;
}

/* HOVER */

.ndtIntroList span {
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.ndtIntroList span:hover {
  transform: translateX(7px);

  color: #168b88;
}

