/* =========================================================
   NOVADENT — TREATMENTS CARDS
========================================================= */

.ndtTreatments {
  position: relative;
  padding: 110px 0;
  background: #ffffff;
}

.ndtHeading {
  display: grid;
  grid-template-columns: 1fr 0.65fr;
  gap: 70px;
  align-items: end;
  margin-bottom: 55px;
}

.ndtHeading h2 {
  margin: 0;
  color: #173d46;
  font-size: clamp(42px, 5vw, 64px);
  line-height: 1.02;
  letter-spacing: -2.5px;
  font-weight: 600;
}

.ndtHeading h2 em {
  display: block;
  color: #168b88;
  font-style: italic;
}

.ndtHeading > p {
  margin: 0;
  color: #718287;
  font-size: 14px;
  line-height: 1.8;
}

/* CARDS GRID */

.ndtCards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}

/* CARD */

.ndtCard {
  overflow: hidden;

  border: 1px solid rgba(23, 61, 70, 0.08);
  border-radius: 26px;

  background: #ffffff;

  box-shadow: 0 12px 35px rgba(23, 61, 70, 0.05);

  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease,
    border-color 0.4s ease;
}

.ndtCard:hover {
  transform: translateY(-10px);

  border-color: rgba(22, 139, 136, 0.2);

  box-shadow: 0 28px 60px rgba(23, 61, 70, 0.13);
}

/* IMAGE */

.ndtCardImage {
  position: relative;
  height: 275px;
  overflow: hidden;
}

.ndtCardImage img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transition: transform 0.7s ease;
}

.ndtCard:hover .ndtCardImage img {
  transform: scale(1.08);
}

.ndtImageOverlay {
  position: absolute;
  inset: 0;

  background: linear-gradient(
    to bottom,
    rgba(7, 30, 52, 0.05),
    rgba(7, 30, 52, 0.6)
  );
}

/* NUMBER */

.ndtCardNumber {
  position: absolute;
  top: 18px;
  left: 18px;

  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.94);
  color: #173d46;

  font-size: 11px;
  font-weight: 800;

  backdrop-filter: blur(8px);
}

/* CATEGORY */

.ndtCardCategory {
  position: absolute;
  top: 20px;
  right: 18px;

  padding: 8px 12px;

  border-radius: 30px;

  background: rgba(23, 61, 70, 0.82);
  color: #ffffff;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 1.1px;

  backdrop-filter: blur(8px);
}

/* DURATION */

.ndtCardDuration {
  position: absolute;
  bottom: 18px;
  left: 18px;

  display: inline-flex;
  align-items: center;
  gap: 7px;

  color: #ffffff;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 1px;
}

/* IMAGE ARROW */

.ndtImageBottom {
  position: absolute;
  right: 18px;
  bottom: 16px;
}

.ndtImageArrow {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #ffffff;
  color: #168b88;

  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.ndtCard:hover .ndtImageArrow {
  transform: rotate(45deg);

  background: #168b88;
  color: #ffffff;
}

/* CARD BODY */

.ndtCardBody {
  padding: 27px 25px 25px;
}

.ndtCardTitle {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.ndtCardTitle small {
  color: #168b88;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 1.5px;
}

.ndtCardTitle h3 {
  margin: 7px 0 0;

  color: #173d46;

  font-size: 22px;
  font-weight: 700;
}

.ndtCardIcon {
  width: 43px;
  height: 43px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background: #e5f6f4;
  color: #168b88;

  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.ndtCard:hover .ndtCardIcon {
  transform: rotate(-8deg);

  background: #168b88;
  color: #ffffff;
}

.ndtCardBody > p {
  margin: 17px 0 20px;

  color: #718287;

  font-size: 12.5px;

  line-height: 1.75;
}

/* TAGS */

.ndtTags {
  display: flex;
  flex-wrap: wrap;

  gap: 7px;
}

.ndtTags span {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  padding: 7px 9px;

  border-radius: 20px;

  background: #f2f8f7;
  color: #547077;

  font-size: 9px;
  font-weight: 600;
}

.ndtTags svg {
  color: #168b88;
}

/* LINK */

.ndtCardLink {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 25px;
  padding-top: 17px;

  border-top: 1px solid rgba(23, 61, 70, 0.08);

  color: #168b88;

  font-size: 11px;
  font-weight: 700;

  text-decoration: none;

  transition:
    color 0.3s ease,
    transform 0.3s ease;
}

.ndtCardLink:hover {
  color: #126f6d;
}

.ndtCardLink svg {
  transition: transform 0.3s ease;
}

.ndtCardLink:hover svg {
  transform: translate(3px, -3px);
}

/* TABLET */

@media (max-width: 1000px) {

  .ndtTreatments {
    padding: 85px 0;
  }

  .ndtHeading {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .ndtCards {
    grid-template-columns: repeat(2, 1fr);
  }

}

/* MOBILE */

@media (max-width: 650px) {

  .ndtTreatments {
    padding: 70px 0;
  }

  .ndtHeading {
    margin-bottom: 38px;
  }

  .ndtHeading h2 {
    font-size: 43px;
    letter-spacing: -1.5px;
  }

  .ndtHeading > p {
    font-size: 13px;
  }

  .ndtCards {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .ndtCardImage {
    height: 250px;
  }

  .ndtCardBody {
    padding: 23px 20px;
  }

}
/* =========================================================
   NOVADENT — CARE JOURNEY / PROCESS
========================================================= */

.ndtProcess {
  position: relative;
  overflow: hidden;
  padding: 110px 0;
  background: #f3f9f8;
}

.ndtProcess::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  top: -180px;
  right: -140px;
  border-radius: 50%;
  background: rgba(22, 139, 136, 0.07);
}

.ndtProcessHeading {
  position: relative;
  z-index: 2;
}

/* PROCESS CARDS */

.ndtSteps {
  position: relative;
  z-index: 2;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;

  margin-top: 55px;
}

.ndtStep {
  position: relative;

  min-height: 290px;
  padding: 30px;

  border: 1px solid rgba(23, 61, 70, 0.08);
  border-radius: 24px;

  background: #ffffff;

  box-shadow: 0 12px 35px rgba(23, 61, 70, 0.05);

  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease,
    background 0.4s ease;
}

.ndtStep:hover {
  transform: translateY(-9px);

  background: #173d46;

  box-shadow: 0 25px 55px rgba(23, 61, 70, 0.17);
}

/* TOP */

.ndtStepTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ndtStepTop > span {
  color: #168b88;

  font-size: 12px;
  font-weight: 800;

  letter-spacing: 1.5px;
}

.ndtStepTop > div {
  width: 50px;
  height: 50px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  background: #e5f6f4;
  color: #168b88;

  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.ndtStep:hover .ndtStepTop > div {
  transform: rotate(-8deg);

  background: #168b88;
  color: #ffffff;
}

/* TITLE */

.ndtStep h3 {
  margin: 55px 0 13px;

  color: #173d46;

  font-size: 24px;
  font-weight: 700;

  transition: color 0.3s ease;
}

.ndtStep:hover h3 {
  color: #ffffff;
}

/* TEXT */

.ndtStep p {
  max-width: 320px;

  margin: 0;

  color: #718287;

  font-size: 13px;
  line-height: 1.8;

  transition: color 0.3s ease;
}

.ndtStep:hover p {
  color: rgba(255, 255, 255, 0.72);
}

/* ARROW */

.ndtStepArrow {
  position: absolute;
  right: 28px;
  bottom: 28px;

  color: #168b88;

  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.ndtStep:hover .ndtStepArrow {
  color: #ffffff;
  transform: translate(4px, -4px);
}

/* CONNECTOR LINE */

.ndtSteps::before {
  content: "";

  position: absolute;
  top: 55px;
  left: 16.5%;
  right: 16.5%;

  height: 1px;

  background: rgba(22, 139, 136, 0.16);

  z-index: -1;
}

/* TABLET */

@media (max-width: 900px) {

  .ndtProcess {
    padding: 85px 0;
  }

  .ndtSteps {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .ndtStep {
    min-height: 250px;
  }

  .ndtStep h3 {
    margin-top: 40px;
  }

  .ndtSteps::before {
    display: none;
  }

}

/* MOBILE */

@media (max-width: 650px) {

  .ndtProcess {
    padding: 70px 0;
  }

  .ndtSteps {
    margin-top: 38px;
  }

  .ndtStep {
    min-height: 235px;
    padding: 24px;
    border-radius: 20px;
  }

  .ndtStepTop > div {
    width: 45px;
    height: 45px;
  }

  .ndtStep h3 {
    margin-top: 35px;
    font-size: 22px;
  }

  .ndtStep p {
    font-size: 12.5px;
  }

  .ndtStepArrow {
    right: 23px;
    bottom: 23px;
  }

}
/* =========================================================
   NOVADENT — FAQ SECTION
========================================================= */

.ndtFAQ {
  position: relative;
  padding: 110px 0;
  background: #ffffff;
  overflow: hidden;
}

.ndtFAQ::after {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  right: -180px;
  top: 50%;
  transform: translateY(-50%);
  border-radius: 50%;
  background: rgba(22, 139, 136, 0.05);
  pointer-events: none;
}

.ndtFAQGrid {
  position: relative;
  z-index: 2;

  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 90px;
  align-items: start;
}

/* LEFT */

.ndtFAQIntro {
  max-width: 460px;
}

.ndtFAQIntro h2 {
  margin: 12px 0 22px;

  color: #173d46;

  font-size: clamp(44px, 5vw, 62px);
  line-height: 1.02;
  letter-spacing: -2px;
  font-weight: 600;
}

.ndtFAQIntro h2 em {
  display: block;

  color: #168b88;

  font-style: italic;
}

.ndtFAQIntro > p {
  margin: 0 0 30px;

  color: #718287;

  font-size: 13px;
  line-height: 1.8;
}

/* OUTLINE BUTTON */

.ndtOutlineButton {
  display: inline-flex;
  align-items: center;
  gap: 10px;

  padding: 13px 18px;

  border: 1px solid rgba(23, 61, 70, 0.18);
  border-radius: 30px;

  color: #173d46;
  background: #ffffff;

  font-size: 11px;
  font-weight: 700;

  text-decoration: none;

  transition:
    background 0.3s ease,
    color 0.3s ease,
    border-color 0.3s ease,
    transform 0.3s ease;
}

.ndtOutlineButton:hover {
  background: #173d46;
  border-color: #173d46;
  color: #ffffff;

  transform: translateY(-2px);
}

/* FAQ LIST */

.ndtFAQList {
  border-top: 1px solid rgba(23, 61, 70, 0.1);
}

.ndtFAQItem {
  border-bottom: 1px solid rgba(23, 61, 70, 0.1);
}

/* QUESTION */

.ndtFAQItem button {
  width: 100%;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;

  padding: 24px 4px;

  border: 0;
  background: transparent;

  color: #173d46;

  font-family: inherit;
  font-size: 15px;
  font-weight: 700;

  text-align: left;

  cursor: pointer;

  transition: color 0.3s ease;
}

.ndtFAQItem button svg {
  flex-shrink: 0;

  color: #168b88;

  transition: transform 0.35s ease;
}

.ndtFAQItem button:hover {
  color: #168b88;
}

/* OPEN */

.ndtFAQItem.open button {
  color: #168b88;
}

.ndtFAQItem.open button svg {
  transform: rotate(180deg);
}

/* ANSWER */

.ndtFAQAnswer {
  display: grid;
  grid-template-rows: 0fr;

  transition: grid-template-rows 0.4s ease;
}

.ndtFAQAnswer p {
  min-height: 0;
  overflow: hidden;

  margin: 0;

  color: #718287;

  font-size: 13px;
  line-height: 1.8;

  opacity: 0;

  transition:
    opacity 0.3s ease,
    padding 0.4s ease;
}

.ndtFAQItem.open .ndtFAQAnswer {
  grid-template-rows: 1fr;
}

.ndtFAQItem.open .ndtFAQAnswer p {
  padding: 0 35px 25px 4px;
  opacity: 1;
}

/* TABLET */

@media (max-width: 900px) {

  .ndtFAQ {
    padding: 85px 0;
  }

  .ndtFAQGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .ndtFAQIntro {
    max-width: 600px;
  }

}

/* MOBILE */

@media (max-width: 650px) {

  .ndtFAQ {
    padding: 70px 0;
  }

  .ndtFAQGrid {
    gap: 40px;
  }

  .ndtFAQIntro h2 {
    font-size: 43px;
    letter-spacing: -1.5px;
  }

  .ndtFAQIntro > p {
    font-size: 12.5px;
  }

  .ndtFAQItem button {
    padding: 20px 2px;

    font-size: 13px;
  }

  .ndtFAQItem.open .ndtFAQAnswer p {
    padding: 0 25px 22px 2px;
    font-size: 12px;
  }

}
/* =========================================================
   NOVADENT — FINAL CTA
========================================================= */

.ndtCTA {
  position: relative;
  padding: 90px 0 110px;
  background: #ffffff;
}

.ndtCTACard {
  position: relative;
  overflow: hidden;

  min-height: 430px;
  padding: 75px 80px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  text-align: center;

  border-radius: 30px;

  background:
