  box-shadow: 0 30px 70px rgba(23, 61, 70, 0.18);

  isolation: isolate;
}

.ndtCTACard::before {
  content: "";

  position: absolute;
  width: 420px;
  height: 420px;

  top: -220px;
  right: -120px;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.07);

  z-index: -1;
}

.ndtCTACard::after {
  content: "";

  position: absolute;
  width: 300px;
  height: 300px;

  bottom: -190px;
  left: -100px;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.05);

  z-index: -1;
