  margin: 0;

  color: rgba(255, 255, 255, 0.72);

  font-size: 13px;
  line-height: 1.8;
}

/* BUTTONS */

.ndtCTAButtons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;

  margin-top: 32px;
}

.ndtLightButton,
.ndtCTASecondary {
