  color: white;
}

/* =====================================================
   NEW MAGAZINE GALLERY
===================================================== */

.nova-gallery-grid {
  display: grid !important;
  grid-template-columns: repeat(12, 1fr) !important;
  grid-auto-rows: 230px !important;
  gap: 18px !important;
  width: 100%;
  margin: 0;
  padding: 0;
}

/* EVERY CARD IS A NORMAL GRID ITEM */

.nova-gallery-card {
  position: relative !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 0;
  min-height: 0;

  grid-column: span 4 !important;
  grid-row: span 1 !important;

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden !important;
  border: none !important;
  border-radius: 20px !important;

  background: #dce8e8;
  cursor: pointer;
}

/* FIRST IMAGE — LARGE */

.nova-gallery-card:nth-child(1) {
  grid-column: span 8 !important;
  grid-row: span 2 !important;
}

/* SECOND + THIRD */

.nova-gallery-card:nth-child(2),
.nova-gallery-card:nth-child(3) {
  grid-column: span 4 !important;
  grid-row: span 1 !important;
}

/* FOURTH — LARGE */

.nova-gallery-card:nth-child(4) {
  grid-column: span 4 !important;
  grid-row: span 2 !important;
}

/* FIFTH + SIXTH */

.nova-gallery-card:nth-child(5),
.nova-gallery-card:nth-child(6) {
  grid-column: span 4 !important;
  grid-row: span 1 !important;
}

/* SEVENTH + EIGHTH */

.nova-gallery-card:nth-child(7),
.nova-gallery-card:nth-child(8) {
  grid-column: span 6 !important;
  grid-row: span 1 !important;
}

/* IMAGE */

.nova-gallery-card img {
  position: absolute !important;
  inset: 0 !important;

  width: 100% !important;
  height: 100% !important;

  display: block !important;
  object-fit: cover !important;

  margin: 0 !important;
  padding: 0 !important;

  transition: transform 0.6s ease;
}

.nova-gallery-card:hover img {
  transform: scale(1.07);
}

/* DARK GRADIENT */

.nova-gallery-card::after {
  content: "";
  position: absolute;
  inset: 0;

  background: linear-gradient(
    to top,
    rgba(5, 25, 29, 0.78),
    rgba(5, 25, 29, 0.05) 65%
  );

  pointer-events: none;
}

/* CONTENT */

.nova-gallery-card-overlay {
  position: absolute !important;
  inset: 0 !important;

  z-index: 2;

  display: flex;
  align-items: flex-end;

  padding: 24px;
  color: white;

  pointer-events: none;
}

.nova-gallery-card-overlay small {
  display: block;
  margin-bottom: 7px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  opacity: 0.8;
}

.nova-gallery-card-overlay h3 {
  margin: 0 0 10px;
  font-size: 20px;
  line-height: 1.15;
}

.nova-gallery-card-overlay span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
}

.nova-gallery-card > b {
  position: absolute;
  top: 16px;
  right: 18px;
  z-index: 3;

  color: white;
  font-size: 11px;
  opacity: 0.85;
}

/* =====================================================
   LIGHTBOX
===================================================== */

.nova-gallery-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 20px;
  background: rgba(5, 22, 25, 0.88);
  backdrop-filter: blur(8px);
}

.nova-gallery-lightbox-box {
  position: relative;
  width: min(900px, 95%);
  max-height: 90vh;
  overflow: hidden;
  border-radius: 20px;
  background: #102f35;
}

.nova-gallery-lightbox-box img {
  display: block;
  width: 100%;
  max-height: 75vh;
  object-fit: contain;
  background: #071d21;
}

.nova-gallery-lightbox-content {
  padding: 18px 22px;
  color: white;
}

.nova-gallery-lightbox-content small {
  font-size: 10px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.nova-gallery-lightbox-content h3 {
  margin: 6px 0 0;
  font-size: 22px;
}

.nova-gallery-close {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 10;

  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  border: 0;
  border-radius: 50%;

  background: rgba(0,0,0,0.6);
  color: white;
  cursor: pointer;
}

/* =====================================================
   TABLET
===================================================== */

@media (max-width: 900px) {

  .nova-gallery-intro .nova-gallery-container {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .nova-gallery-grid {
    grid-template-columns: repeat(2, 1fr) !important;
