  font-family: Georgia, serif;
  font-size: 18px;
  line-height: 1.65;
  color: #31565d;
}

.nova-review-author {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: auto;
}

.nova-review-avatar {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #dceeed;
  color: #164b54;
  font-weight: 800;
}

.nova-review-author strong {
  display: block;
  font-size: 13px;
}

.nova-review-author span {
  font-size: 11px;
  color: #829497;
}

/* FEATURED REVIEW */

.nova-review-featured {
  grid-column: span 2;
  background: #164b54;
  color: white;
}

.nova-review-featured .nova-review-quote {
  color: rgba(255,255,255,0.9);
  font-size: 22px;
}

.nova-review-featured .nova-review-author strong {
  color: white;
}

.nova-review-featured .nova-review-author span {
  color: rgba(255,255,255,0.65);
}

.nova-review-featured .nova-review-avatar {
  background: rgba(255,255,255,0.15);
  color: white;
}

/* CTA */

.nova-reviews-cta {
  padding: 20px 0 85px;
}

.nova-reviews-cta-box {
  padding: 55px 40px;
  border-radius: 28px;
  text-align: center;
  background: #e4f0ef;
}

.nova-reviews-cta-box h2 {
  margin: 0;
  font-size: clamp(30px, 4vw, 48px);
}

.nova-reviews-cta-box p {
  max-width: 560px;
  margin: 15px auto 25px;
  color: #64797d;
}

.nova-reviews-cta-box a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 23px;
  border-radius: 999px;
  background: #164b54;
  color: white;
  text-decoration: none;
  font-weight: 700;
  transition: 0.3s ease;
}

.nova-reviews-cta-box a:hover {
  transform: translateY(-3px);
}

/* TABLET */

@media (max-width: 900px) {

  .nova-reviews-intro-grid {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .nova-reviews-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .nova-review-featured {
    grid-column: span 2;
  }
}

/* MOBILE */

@media (max-width: 600px) {

  .nova-reviews-hero {
    min-height: 430px;
  }

  .nova-reviews-hero h1 {
    font-size: 42px;
  }

  .nova-reviews-intro {
    padding: 50px 0 35px;
  }

  .nova-reviews-section {
    padding: 15px 0 55px;
  }

  .nova-reviews-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .nova-review-card,
  .nova-review-featured {
    grid-column: span 1;
    min-height: auto;
    padding: 25px;
  }

  .nova-review-featured .nova-review-quote {
    font-size: 19px;
  }

  .nova-reviews-cta {
    padding: 10px 0 55px;
  }

  .nova-reviews-cta-box {
    padding: 40px 22px;
    border-radius: 22px;
  }
}
/* =========================================================
   NOVADENT REVIEWS PAGE
   ========================================================= */

.novaReviewsPage {
  width: 100%;
  overflow: hidden;
  background: #f7fbfa;
  color: #16363b;
}

.novaReviewsContainer {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
}

/* =========================================================
   HERO
   ========================================================= */

.novaReviewsHero {
  position: relative;
  min-height: 620px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 85% 20%,
      rgba(87, 183, 171, 0.22),
      transparent 34%
    ),
    linear-gradient(135deg, #0d3037, #174a51 55%, #0c2930);
  color: #fff;
}

.novaReviewsHero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(7, 31, 37, 0.96),
      rgba(12, 49, 55, 0.82),
      rgba(12, 49, 55, 0.35)
    );
  pointer-events: none;
}

.novaReviewsHero::after {
  content: "";
  position: absolute;
  width: 520px;
  height: 520px;
  right: -180px;
  bottom: -260px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.13);
  box-shadow:
    0 0 0 70px rgba(255, 255, 255, 0.025),
    0 0 0 140px rgba(255, 255, 255, 0.02);
}

.novaReviewsHeroGlow {
  position: absolute;
  width: 360px;
  height: 360px;
  right: 10%;
  top: 15%;
  border-radius: 50%;
  background: rgba(89, 203, 189, 0.16);
  filter: blur(70px);
  animation: novaReviewGlow 6s ease-in-out infinite alternate;
}

@keyframes novaReviewGlow {
  from {
    transform: translate3d(0, 0, 0) scale(0.95);
  }

  to {
    transform: translate3d(-30px, 25px, 0) scale(1.08);
  }
}

.novaReviewsHero .novaReviewsContainer {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 70px;
  align-items: end;
}

.novaReviewsHeroContent {
  max-width: 760px;
  padding: 100px 0;
  animation: novaReviewHeroIn 0.9s ease both;
}

@keyframes novaReviewHeroIn {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.novaReviewsEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 26px;
  color: #8ed9cf;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.novaReviewsHero h1 {
  margin: 0;
  max-width: 760px;
  font-size: clamp(48px, 7vw, 86px);
  line-height: 0.98;
  letter-spacing: -0.055em;
  font-weight: 800;
}

.novaReviewsHero h1 em {
  display: block;
  color: #8ed9cf;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.novaReviewsHeroContent > p {
  max-width: 600px;
  margin: 30px 0 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 17px;
  line-height: 1.8;
}

.novaReviewsHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 25px;
  margin-top: 38px;
}

.novaReviewsPrimary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 15px 22px;
  border-radius: 999px;
  background: #fff;
  color: #163f45;
  text-decoration: none;
  font-weight: 800;
  transition: 0.3s ease;
}

.novaReviewsPrimary:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 35px rgba(0, 0, 0, 0.2);
}

.novaReviewsTextLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #fff;
  text-decoration: none;
  font-size: 14px;
  font-weight: 700;
  transition: 0.3s ease;
}

.novaReviewsTextLink:hover {
  color: #8ed9cf;
  transform: translateX(5px);
}

.novaReviewsHeroRating {
  align-self: end;
  margin-bottom: 80px;
  padding: 24px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(14px);
  animation: novaReviewHeroRating 1s 0.2s ease both;
}

@keyframes novaReviewHeroRating {
  from {
    opacity: 0;
    transform: translateY(30px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.novaReviewStars {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #d9ad5a;
}

.novaReviewsHeroRating > strong {
  display: block;
  margin-top: 10px;
  font-size: 42px;
  line-height: 1;
}

.novaReviewsHeroRating > span {
  display: block;
  margin-top: 7px;
  color: rgba(255, 255, 255, 0.65);
  font-size: 13px;
}

.novaRatingVerified {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 18px;
  color: #8ed9cf;
  font-size: 12px;
  font-weight: 700;
}

/* =========================================================
   INTRO
   ========================================================= */

.novaReviewsIntro {
  padding: 115px 0;
  background: #fff;
}

.novaReviewsIntroGrid {
  display: grid;
  grid-template-columns: 1fr 0.85fr;
  gap: 100px;
  align-items: center;
}

.novaReviewsOverline {
  display: block;
  margin-bottom: 13px;
  color: #4b9690;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.2em;
}

.novaReviewsNumber {
  display: block;
  margin-bottom: 22px;
  color: #9aaeb0;
  font-size: 11px;
  letter-spacing: 0.15em;
  font-weight: 700;
}

.novaReviewsIntro h2,
.novaReviewsSectionHeading h2,
.novaReviewsCardsHeading h2 {
  margin: 0;
  color: #16363b;
  font-size: clamp(38px, 5vw, 62px);
  line-height: 1.03;
  letter-spacing: -0.045em;
}

.novaReviewsIntro h2 em,
.novaReviewsSectionHeading h2 em,
.novaReviewsCardsHeading h2 em {
  color: #4e9992;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.novaReviewsIntroText {
  max-width: 510px;
}

.novaReviewsIntroText p {
  margin: 0 0 22px;
  color: #657b7e;
  font-size: 16px;
  line-height: 1.85;
}

.novaReviewsIntroText p:last-child {
  margin-bottom: 0;
}

/* =========================================================
   FEATURED REVIEWS
   ========================================================= */

.novaReviewsFeatured {
  padding: 110px 0 120px;
  background: #edf7f5;
}

.novaReviewsSectionHeading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 50px;
  margin-bottom: 50px;
}

.novaReviewsSectionHeading > p {
  max-width: 360px;
  margin: 0 0 5px;
  color: #667d80;
  font-size: 14px;
  line-height: 1.8;
}

.novaFeaturedReview {
  position: relative;
  display: grid;
  grid-template-columns: 100px minmax(0, 1fr) 130px;
  gap: 35px;
  min-height: 360px;
  padding: 55px;
  border: 1px solid rgba(35, 91, 91, 0.12);
  border-radius: 30px;
  background: #fff;
  box-shadow: 0 25px 70px rgba(22, 67, 73, 0.08);
  animation: novaFeaturedIn 0.55s ease both;
}

@keyframes novaFeaturedIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.novaFeaturedQuote {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  color: #76bdb5;
}

.novaFeaturedContent {
  max-width: 760px;
}

.novaFeaturedContent .novaReviewStars {
  margin-bottom: 24px;
}

.novaFeaturedContent blockquote {
  margin: 0;
  color: #23494e;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1.45;
}

.novaFeaturedPerson {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 35px;
}

.novaPersonAvatar,
.novaReviewMiniAvatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #dff4f0, #b9ded8);
  color: #17474d;
  font-weight: 900;
}

.novaPersonAvatar {
  width: 52px;
  height: 52px;
  font-size: 14px;
}

.novaFeaturedPerson strong {
  display: block;
  color: #1c4146;
  font-size: 15px;
}

.novaFeaturedPerson span {
  display: block;
  margin-top: 4px;
  color: #8a9c9f;
  font-size: 12px;
}

.novaFeaturedControls {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  color: #8ba0a2;
  font-size: 12px;
  font-weight: 700;
}

.novaReviewButtons {
  display: flex;
  gap: 10px;
}

.novaReviewButtons button {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border: 1px solid #d8e5e3;
  border-radius: 50%;
  background: #fff;
  color: #23494e;
  cursor: pointer;
  transition: 0.3s ease;
}

.novaReviewButtons button:hover {
  border-color: #4d9991;
  background: #4d9991;
  color: #fff;
  transform: translateY(-3px);
}

.novaReviewDots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 28px;
}

.novaReviewDots button {
  width: 9px;
  height: 9px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: #b7ceca;
  cursor: pointer;
  transition: 0.3s ease;
}

.novaReviewDots button.active {
  width: 30px;
  border-radius: 20px;
  background: #397f79;
}

/* =========================================================
   TRUST POINTS
   ========================================================= */

.novaReviewsTrust {
  padding: 90px 0;
  background: #fff;
}

.novaReviewsTrustGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.novaReviewTrustCard {
  position: relative;
  display: grid;
  grid-template-columns: auto 48px 1fr;
  gap: 18px;
  align-items: center;
  padding: 30px;
  border: 1px solid #e1ecea;
  border-radius: 22px;
  background: #f9fcfb;
  transition: 0.35s ease;
}

.novaReviewTrustCard:hover {
  transform: translateY(-7px);
  border-color: #afd6d1;
  box-shadow: 0 20px 45px rgba(27, 76, 79, 0.08);
}

.novaReviewTrustCard > span {
  align-self: start;
  color: #9cb2b3;
  font-size: 11px;
  font-weight: 800;
}

.novaTrustIcon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: #e3f3f0;
  color: #3d8b84;
}

.novaReviewTrustCard h3 {
  margin: 0 0 5px;
  color: #24474c;
  font-size: 17px;
}

.novaReviewTrustCard p {
  margin: 0;
  color: #819496;
  font-size: 12px;
  line-height: 1.6;
}

/* =========================================================
   REVIEW CARDS
   ========================================================= */

.novaReviewsCardsSection {
  padding: 110px 0 120px;
  background: #f5faf9;
}

.novaReviewsCardsHeading {
  margin-bottom: 45px;
}

.novaReviewsCardsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}

.novaReviewCard {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 370px;
  padding: 28px;
  border: 1px solid #dfeae8;
  border-radius: 24px;
  background: #fff;
  cursor: pointer;
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.novaReviewCard:hover,
.novaReviewCard.isActive {
  transform: translateY(-9px);
  border-color: #93c8c2;
  box-shadow: 0 25px 50px rgba(27, 73, 77, 0.11);
}

.novaReviewCard:focus-visible {
  outline: 3px solid rgba(70, 145, 138, 0.3);
  outline-offset: 3px;
}

.novaReviewCardTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.novaReviewMiniAvatar {
  width: 42px;
  height: 42px;
  font-size: 11px;
}

.novaReviewCardQuote {
  margin: 35px 0 18px;
  color: #75b9b2;
}

.novaReviewCard > p {
  margin: 0;
  color: #617679;
  font-size: 14px;
  line-height: 1.75;
}

.novaReviewCardPerson {
  margin-top: auto;
  padding-top: 28px;
}

.novaReviewCardPerson strong {
  display: block;
  color: #21474c;
  font-size: 14px;
}

.novaReviewCardPerson span {
  display: block;
  margin-top: 5px;
  color: #91a2a4;
  font-size: 11px;
}

.novaReviewCardLine {
  width: 100%;
  height: 1px;
  margin: 20px 0 15px;
  background: #e7efee;
}

.novaReviewCardView {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #4b918a;
  font-size: 12px;
  font-weight: 800;
}

/* =========================================================
   CTA
   ========================================================= */

.novaReviewsCTA {
  padding: 100px 0;
  background: #fff;
}

.novaReviewsCTACard {
  position: relative;
  overflow: hidden;
  padding: 75px;
  border-radius: 32px;
  background:
    radial-gradient(
      circle at 90% 10%,
      rgba(142, 217, 207, 0.2),
      transparent 35%
    ),
    linear-gradient(135deg, #123b42, #1c555a);
  color: #fff;
}

.novaReviewsCTACard::before {
  content: "";
  position: absolute;
  width: 300px;
  height: 300px;
  right: -100px;
  bottom: -180px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 50%;
  box-shadow:
    0 0 0 55px rgba(255, 255, 255, 0.025),
    0 0 0 110px rgba(255, 255, 255, 0.02);
}

.novaReviewsCTACard > div {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.novaReviewsCTABadge {
  display: inline-flex;
  margin-bottom: 20px;
  padding: 8px 13px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  color: #9de0d6;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.novaReviewsCTACard h2 {
  margin: 0;
  font-size: clamp(38px, 5vw, 60px);
  line-height: 1.05;
  letter-spacing: -0.045em;
}

.novaReviewsCTACard h2 em {
  display: block;
  color: #9de0d6;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.novaReviewsCTACard p {
  max-width: 600px;
  margin: 25px 0 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 15px;
  line-height: 1.8;
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 950px) {

  .novaReviewsHero {
    min-height: 570px;
  }

  .novaReviewsHero .novaReviewsContainer {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .novaReviewsHeroContent {
    padding: 85px 0 20px;
  }

  .novaReviewsHeroRating {
    width: 250px;
    margin: 0 0 60px;
  }

  .novaReviewsIntroGrid {
    grid-template-columns: 1fr;
