  }

  .novaFeaturedReview {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 30px 24px;
    border-radius: 24px;
  }

  .novaFeaturedQuote {
    justify-content: flex-start;
  }

  .novaFeaturedContent blockquote {
    font-size: 23px;
