    margin-top: 10px;
  }

  .novaReviewsTrust {
    padding: 65px 0;
  }

  .novaReviewTrustCard {
    grid-template-columns: auto 45px 1fr;
    padding: 22px 18px;
  }

  .novaReviewsCardsSection {
    padding: 75px 0;
  }

  .novaReviewsCardsGrid {
    grid-template-columns: 1fr;
  }

  .novaReviewCard {
    min-height: 330px;
  }

  .novaReviewsCTA {
    padding: 65px 0;
  }

  .novaReviewsCTACard {
    padding: 45px 25px;
