  font-size: 11px;
}

.novaReviewCardQuote {
  margin: 35px 0 18px;

  color: #75b9b2;
}

.novaReviewCard > p {
  margin: 0;

  color: #617679;

  font-size: 14px;

  line-height: 1.75;
}

.novaReviewCardPerson {
  margin-top: auto;

  padding-top: 28px;
}

.novaReviewCardPerson strong {
  display: block;

  color: #21474c;

  font-size: 14px;
}

.novaReviewCardPerson span {
  display: block;

  margin-top: 5px;

  color: #91a2a4;

  font-size: 11px;
}

/* VIEW STORY + LINE */

.novaReviewCardView {
  position: relative;

  display: flex;

  align-items: center;

  justify-content: space-between;

  width: 100%;

  margin-top: 20px;

  padding-top: 15px;

  color: #4b918a;

  font-size: 12px;

  font-weight: 800;

  box-sizing: border-box;
}

.novaReviewCardView::before {
  content: "";

  position: absolute;

  top: 0;
  left: 0;

  width: 100%;
  height: 1px;

  background: #dfe9e7;

  transition:
    background 0.3s ease;
}

.novaReviewCard:hover .novaReviewCardView::before,
.novaReviewCard.isActive .novaReviewCardView::before {
  background: #78b9b2;
}

.novaReviewCardView svg {
  transition:
    transform 0.3s ease;
}

.novaReviewCard:hover .novaReviewCardView svg {
  transform: translate(3px, -3px);
}

/* =========================================================
   CTA
   ========================================================= */

.novaReviewsCTA {
  padding: 100px 0;

  background: #fff;
}

.novaReviewsCTACard {
  position: relative;

  overflow: hidden;

  padding: 75px;

  border-radius: 32px;

  background:
    radial-gradient(
      circle at 90% 10%,
      rgba(142, 217, 207, 0.2),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #123b42,
      #1c555a
    );

  color: #fff;
}

.novaReviewsCTACard::before {
  content: "";

  position: absolute;

  width: 300px;
  height: 300px;

  right: -100px;
  bottom: -180px;

  border: 1px solid rgba(255, 255, 255, 0.14);

  border-radius: 50%;

  box-shadow:
    0 0 0 55px rgba(255, 255, 255, 0.025),
    0 0 0 110px rgba(255, 255, 255, 0.02);
}

.novaReviewsCTACard > div {
  position: relative;

  z-index: 2;

  max-width: 720px;
}

.novaReviewsCTABadge {
  display: inline-flex;

  margin-bottom: 20px;

  padding: 8px 13px;

  border: 1px solid rgba(255, 255, 255, 0.2);

  border-radius: 999px;

  color: #9de0d6;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.16em;
}

.novaReviewsCTACard h2 {
  margin: 0;

  font-size: clamp(38px, 5vw, 60px);

  line-height: 1.05;

  letter-spacing: -0.045em;
}

.novaReviewsCTACard h2 em {
  display: block;

  color: #9de0d6;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.novaReviewsCTACard p {
  max-width: 600px;

  margin: 25px 0 0;

  color: rgba(255, 255, 255, 0.7);

  font-size: 15px;

  line-height: 1.8;
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 950px) {

  .novaReviewsIntroGrid {
    grid-template-columns: 1fr;

    gap: 45px;
  }

  .novaFeaturedReview {
    grid-template-columns:
      70px
      minmax(0, 1fr);
  }

  .novaFeaturedControls {
    grid-column: 2;

    flex-direction: row;

    align-items: center;
  }

  .novaReviewsTrustGrid {
    grid-template-columns: 1fr;
  }

  .novaReviewsCardsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 640px) {

  .novaReviewsContainer {
    width: calc(100% - 28px);
  }

  /* HERO */

  .novaReviewsHero {
    min-height: 650px;
  }

  .novaReviewsHero > .novaReviewsContainer {
    width: calc(100% - 28px);
  }

  .novaReviewsHeroContent {
    max-width: 100%;

    padding: 70px 0;
  }

  .novaReviewsEyebrow {
    font-size: 9px;

    letter-spacing: 0.12em;
  }

  .novaReviewsHero h1 {
    font-size: clamp(40px, 13vw, 58px);

    line-height: 1;
  }

  .novaReviewsHeroContent > p {
    max-width: 500px;

    font-size: 14px;

    line-height: 1.7;
  }

  .novaReviewsHeroActions {
    flex-direction: column;

    gap: 17px;
  }

  /* INTRO */

  .novaReviewsIntro {
    padding: 75px 0;
  }

  .novaReviewsIntro h2,
  .novaReviewsSectionHeading h2,
  .novaReviewsCardsHeading h2 {
    font-size: 40px;
  }

  /* FEATURED */

  .novaReviewsFeatured {
    padding: 75px 0;
  }

  .novaReviewsSectionHeading {
    display: block;

    margin-bottom: 35px;
  }

  .novaReviewsSectionHeading > p {
    margin-top: 22px;
  }

  .novaFeaturedReview {
    grid-template-columns: 1fr;

    gap: 20px;

    padding: 30px 24px;

    border-radius: 24px;
  }

  .novaFeaturedQuote {
    justify-content: flex-start;
  }

  .novaFeaturedContent blockquote {
    font-size: 23px;
  }

  .novaFeaturedControls {
    grid-column: auto;

    margin-top: 10px;
  }

  /* TRUST */

  .novaReviewsTrust {
    padding: 65px 0;
  }

  .novaReviewTrustCard {
    grid-template-columns:
      auto
      45px
      1fr;

    padding: 22px 18px;
  }

  /* PATIENT VOICES */

  .novaReviewsCardsSection {
    padding: 75px 0;
  }

  .novaReviewsCardsGrid {
    grid-template-columns: 1fr;
  }

  .novaReviewCard {
    min-height: 330px;
  }

  /* CTA */

  .novaReviewsCTA {
    padding: 65px 0;
  }

  .novaReviewsCTACard {
    padding: 45px 25px;

    border-radius: 25px;
  }

  .novaReviewsCTACard h2 {
    font-size: 39px;
  }

  .novaReviewsCTACard p {
    font-size: 14px;
  }

}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .novaReviewsHeroContent,
  .novaFeaturedReview {
    animation: none;
  }

  .novaReviewsPrimary,
  .novaReviewsTextLink,
  .novaReviewButtons button,
  .novaReviewTrustCard,
  .novaReviewCard,
  .novaReviewCardView svg {
    transition: none;
  }

}
/* =========================================================
   NOVADENT APPOINTMENT PAGE
   ========================================================= */

.novaAppointmentPage {
  width: 100%;
  overflow: hidden;
  background: #f6fbfa;
  color: #16363b;
}

/* =========================================================
   COMMON CONTAINER
   ========================================================= */

.appointmentContainer {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
}

/* =========================================================
   HERO
   ========================================================= */

.novaAppointmentHero {
  position: relative;
  min-height: 690px;
  overflow: hidden;

  display: flex;
  align-items: center;

  background:
    radial-gradient(
      circle at 75% 35%,
      rgba(103, 196, 185, 0.16),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      #0a2c33 0%,
      #15464d 58%,
      #0b2930 100%
    );

  color: #fff;
}

.appointmentHeroGlow {
  position: absolute;

  width: 500px;
  height: 500px;

  right: -150px;
  top: 50%;

  transform: translateY(-50%);

  border-radius: 50%;

  background: rgba(86, 185, 175, 0.1);

  filter: blur(80px);

  pointer-events: none;
}

.appointmentHeroGrid {
  position: relative;
  z-index: 2;

  display: grid;

  grid-template-columns:
    minmax(0, 0.95fr)
    minmax(0, 0.9fr);

  gap: 85px;

  align-items: center;

  padding: 90px 0;
}

/* =========================================================
   HERO CONTENT
   ========================================================= */

.appointmentHeroContent {
  animation: appointmentHeroIn 0.8s ease both;
}

@keyframes appointmentHeroIn {

  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }

}

.appointmentEyebrow {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  margin-bottom: 24px;

  color: #91dcd2;

  font-size: 11px;

  font-weight: 900;

  letter-spacing: 0.18em;
}

.appointmentHeroContent h1 {
  margin: 0;

  max-width: 700px;

  color: #fff;

  font-size: clamp(48px, 6vw, 78px);

  line-height: 0.98;

  letter-spacing: -0.055em;

  font-weight: 800;
}

.appointmentHeroContent h1 em {
  display: block;

  margin-top: 5px;

  color: #91dcd2;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;

  font-style: italic;
}

.appointmentHeroContent > p {
  max-width: 600px;

  margin: 28px 0 0;

  color: rgba(255, 255, 255, 0.72);

  font-size: 16px;

  line-height: 1.8;
}

/* =========================================================
   HERO ACTIONS
   ========================================================= */

.appointmentHeroActions {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 22px;

  margin-top: 35px;
}

.appointmentPrimaryBtn {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 9px;

  min-height: 52px;

  padding: 14px 23px;

  border-radius: 999px;

  background: #fff;

  color: #17434a;

  text-decoration: none;

  font-size: 13px;

  font-weight: 800;

  transition: 0.3s ease;
}

.appointmentPrimaryBtn:hover {
  transform: translateY(-4px);

  box-shadow:
    0 15px 35px rgba(0, 0, 0, 0.22);
}

.appointmentPhoneBtn {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  color: #fff;

  text-decoration: none;

  font-size: 13px;

  font-weight: 700;

  transition: 0.3s ease;
}

.appointmentPhoneBtn:hover {
  color: #91dcd2;

  transform: translateX(3px);
}

/* =========================================================
   HERO TRUST
   ========================================================= */

.appointmentTrustRow {
  display: flex;

  flex-wrap: wrap;

  gap: 22px;

  margin-top: 42px;

  padding-top: 25px;

  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.appointmentTrustRow div {
  display: flex;

  align-items: center;

  gap: 8px;

  color: rgba(255, 255, 255, 0.68);

  font-size: 11px;

  font-weight: 700;
}

.appointmentTrustRow svg {
  color: #8bd6cc;
}

/* =========================================================
   HERO IMAGE
   ========================================================= */

.appointmentHeroVisual {
  position: relative;

  width: 100%;

  max-width: 570px;

  margin-left: auto;
}

.appointmentHeroImage {
  position: relative;

  overflow: hidden;

  aspect-ratio: 0.95;

  border-radius: 30px;

  border: 1px solid rgba(255, 255, 255, 0.14);

  box-shadow:
    0 35px 80px rgba(0, 0, 0, 0.25);
}

.appointmentHeroImage img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transition: transform 0.8s ease;
}

.appointmentHeroImage:hover img {
  transform: scale(1.04);
}

.appointmentImageOverlay {
  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      180deg,
      transparent 45%,
      rgba(7, 34, 40, 0.28)
    );

  pointer-events: none;
}

/* =========================================================
   FLOATING CARD
   ========================================================= */

.appointmentFloatingCard {
  position: absolute;

  left: -35px;
  bottom: 35px;

  display: flex;

  align-items: center;

  gap: 13px;

  min-width: 250px;

  padding: 18px;

  border: 1px solid rgba(255, 255, 255, 0.55);

  border-radius: 18px;

  background: rgba(255, 255, 255, 0.94);

  color: #193f44;

  box-shadow:
    0 20px 50px rgba(0, 0, 0, 0.2);

  backdrop-filter: blur(14px);

  animation: floatingCard 4s ease-in-out infinite;
}

@keyframes floatingCard {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }

}

.floatingIcon {
  width: 42px;
  height: 42px;

  flex-shrink: 0;

  display: grid;

  place-items: center;

  border-radius: 13px;

  background: #dff3ef;

  color: #438d86;
}

.appointmentFloatingCard strong {
  display: block;

  font-size: 13px;
}

.appointmentFloatingCard span {
  display: block;

  margin-top: 4px;

  color: #84999b;

  font-size: 11px;
}

/* =========================================================
   INTRO
   ========================================================= */

.appointmentIntro {
  padding: 115px 0;

  background: #fff;
}

.appointmentIntroGrid {
  display: grid;

  grid-template-columns: 1fr 0.9fr;

  gap: 100px;

  align-items: center;
}

.appointmentOverline {
  display: block;

  margin-bottom: 13px;

  color: #4c9690;

  font-size: 11px;

  font-weight: 900;

  letter-spacing: 0.2em;
}

.appointmentIntro small,
.appointmentSectionHeading small {
  display: block;

  margin-bottom: 22px;

  color: #9badad;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 0.15em;
}

.appointmentIntro h2,
.appointmentSectionHeading h2 {
  margin: 0;

  color: #173b40;

  font-size: clamp(40px, 5vw, 62px);

  line-height: 1.03;

  letter-spacing: -0.045em;
}

.appointmentIntro h2 em,
.appointmentSectionHeading h2 em {
  color: #4d9891;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.appointmentIntroText > p {
  margin: 0;

  color: #667b7d;

  font-size: 16px;

  line-height: 1.85;
}

.appointmentInfoCards {
  display: grid;

  grid-template-columns: repeat(2, 1fr);

  gap: 14px;

  margin-top: 30px;
}

.appointmentInfoCard {
  display: flex;

  align-items: center;

  gap: 13px;

  padding: 20px;

  border: 1px solid #e1ecea;

  border-radius: 18px;

  background: #f8fcfb;

  transition: 0.3s ease;
}

.appointmentInfoCard:hover {
  transform: translateY(-5px);

  border-color: #b4d7d2;

  box-shadow:
    0 15px 35px rgba(31, 80, 82, 0.08);
}

.appointmentInfoCard > svg {
  color: #4e9891;

  flex-shrink: 0;
}

.appointmentInfoCard strong {
  display: block;

  color: #264a4e;

  font-size: 13px;
}

.appointmentInfoCard span {
  display: block;

  margin-top: 4px;

  color: #8a9c9e;

  font-size: 11px;
}

/* =========================================================
   FORM SECTION
   ========================================================= */

.appointmentFormSection {
  padding: 110px 0 120px;

  background: #eef7f5;
}

.appointmentSectionHeading {
  display: flex;

  align-items: end;

  justify-content: space-between;

  gap: 60px;

  margin-bottom: 55px;
}

.appointmentSectionHeading > p {
  max-width: 390px;

  margin: 0 0 4px;

  color: #6b8082;

  font-size: 14px;

  line-height: 1.8;
}

/* =========================================================
   FORM LAYOUT
   ========================================================= */

.appointmentFormLayout {
  display: grid;

  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(280px, 0.7fr);

  gap: 24px;

  align-items: start;
}

/* =========================================================
   FORM CARD
   ========================================================= */

.appointmentFormCard {
  min-height: 100%;

  padding: 42px;

  border: 1px solid #dbeae7;

  border-radius: 28px;

  background: #fff;

  box-shadow:
    0 25px 70px rgba(27, 75, 78, 0.07);
}

.formRow {
  display: grid;

  grid-template-columns: repeat(2, 1fr);

  gap: 18px;

  margin-bottom: 20px;
}

.formField {
  display: flex;

  flex-direction: column;

  gap: 8px;

  margin-bottom: 20px;
}

.formField label {
  color: #294b4f;

  font-size: 12px;

  font-weight: 800;
}

.formField input,
.formField select,
.formField textarea {
  width: 100%;

  box-sizing: border-box;

  border: 1px solid #dce8e6;

  border-radius: 13px;

  background: #f9fcfb;

  color: #24484c;

  font-family: inherit;

  font-size: 14px;

  outline: none;

  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.formField input,
.formField select {
  min-height: 52px;

  padding: 13px 15px;
}

.formField textarea {
  min-height: 125px;

  padding: 14px 15px;

  resize: vertical;
}

.formField input::placeholder,
.formField textarea::placeholder {
  color: #a3b2b3;
}

.formField input:focus,
.formField select:focus,
.formField textarea:focus {
  border-color: #67aaa3;

  background: #fff;

  box-shadow:
    0 0 0 4px rgba(103, 170, 163, 0.1);
}

/* =========================================================
   SUBMIT BUTTON
   ========================================================= */

.appointmentSubmitBtn {
  width: 100%;

  min-height: 56px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  margin-top: 5px;

  padding: 14px 20px;

  border: 0;

  border-radius: 14px;

  background: #17484e;

  color: #fff;

  font-family: inherit;

  font-size: 13px;

  font-weight: 800;

  cursor: pointer;

  transition: 0.3s ease;
}

.appointmentSubmitBtn:hover {
  background: #236b6d;

  transform: translateY(-3px);

  box-shadow:
    0 15px 30px rgba(23, 72, 78, 0.18);
}

.appointmentFormNote {
  margin: 15px 0 0;

  color: #98a8a9;

  font-size: 10px;

  line-height: 1.6;

  text-align: center;
}

/* =========================================================
   SUCCESS
   ========================================================= */

.appointmentSuccess {
  min-height: 570px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  padding: 40px;

  text-align: center;
}

.successIcon {
  width: 86px;
  height: 86px;

  display: grid;

  place-items: center;

  margin-bottom: 25px;

  border-radius: 50%;

  background: #e1f4f0;

  color: #4a9990;
}

.appointmentSuccess > span {
  color: #5a9b94;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.2em;
}

.appointmentSuccess h3 {
  margin: 15px 0 10px;

  color: #1b4247;

  font-size: 30px;
}

.appointmentSuccess p {
  max-width: 500px;

  margin: 0;

  color: #708486;

  font-size: 14px;

  line-height: 1.8;
}

.appointmentAgainBtn {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  margin-top: 28px;

  padding: 13px 18px;

  border: 0;

  border-radius: 999px;

  background: #17484e;

  color: #fff;

  font-family: inherit;

  font-size: 12px;

  font-weight: 800;

  cursor: pointer;

  transition: 0.3s ease;
}

.appointmentAgainBtn:hover {
  background: #286e70;

  transform: translateY(-3px);
}

/* =========================================================
   SIDE CARDS
   ========================================================= */

.appointmentSide {
  display: flex;

  flex-direction: column;

  gap: 16px;
}

.appointmentSideCard {
  position: relative;

  padding: 28px;

  border: 1px solid #dbe8e6;

  border-radius: 22px;

  background: #fff;

  overflow: hidden;

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    border-color 0.3s ease;
}

.appointmentSideCard:hover {
  transform: translateY(-6px);

  border-color: #acd4cf;

  box-shadow:
    0 18px 40px rgba(28, 77, 79, 0.08);
}

.appointmentSideCard.appointmentHighlight {
  background:
    linear-gradient(
      145deg,
      #17484e,
      #286a6d
    );

  color: #fff;

  border-color: transparent;
}

.appointmentSideNumber {
  position: absolute;

  top: 20px;
  right: 22px;

  color: #9aadae;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.12em;
}

.appointmentHighlight .appointmentSideNumber {
  color: rgba(255, 255, 255, 0.4);
}

.appointmentSideCard > svg {
  margin-bottom: 25px;

  color: #4b9890;
}

.appointmentHighlight > svg {
  color: #98ddd3;
}

.appointmentSideCard h3 {
  margin: 0;

  color: #23474c;

  font-size: 21px;

  line-height: 1.25;
}

.appointmentHighlight h3 {
  color: #fff;
}

.appointmentSideCard p {
  margin: 15px 0 0;

  color: #809294;

  font-size: 12px;

  line-height: 1.75;
}

.appointmentHighlight p {
  color: rgba(255, 255, 255, 0.68);
}

.appointmentSideCard a {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  margin-top: 20px;

  color: #438e87;

  text-decoration: none;

  font-size: 12px;

  font-weight: 800;

  transition: 0.3s ease;
}

.appointmentSideCard a:hover {
  color: #17484e;

  transform: translateX(3px);
}

/* =========================================================
   FINAL CTA
   ========================================================= */

.appointmentFinalCTA {
  padding: 100px 0;

  background: #fff;
}

.appointmentCTACard {
  position: relative;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 50px;

  overflow: hidden;

  padding: 65px 70px;

  border-radius: 30px;

  background:
    radial-gradient(
      circle at 90% 15%,
      rgba(133, 213, 203, 0.2),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      #123d44,
      #1d595d
    );

  color: #fff;
}

.appointmentCTACard::after {
  content: "";

  position: absolute;

  width: 260px;
  height: 260px;

  right: -100px;
  bottom: -170px;

  border: 1px solid rgba(255, 255, 255, 0.14);

  border-radius: 50%;

  box-shadow:
    0 0 0 55px rgba(255, 255, 255, 0.025),
    0 0 0 110px rgba(255, 255, 255, 0.018);
}

.appointmentCTACard > div {
  position: relative;

  z-index: 2;
}

.appointmentCTACard > div > span {
  display: inline-block;

  margin-bottom: 18px;

  color: #9bddd4;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.18em;
}

.appointmentCTACard h2 {
  max-width: 650px;

  margin: 0;

  color: #fff;

  font-size: clamp(38px, 5vw, 58px);

  line-height: 1.04;

  letter-spacing: -0.045em;
}

.appointmentCTACard h2 em {
  display: block;

  color: #9bddd4;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.appointmentCTACard p {
  margin: 20px 0 0;

  color: rgba(255, 255, 255, 0.68);

  font-size: 14px;
}

.appointmentCTAButton {
  position: relative;

  z-index: 3;

  flex-shrink: 0;

  display: inline-flex;

  align-items: center;

  gap: 9px;

  padding: 15px 21px;

  border-radius: 999px;

  background: #fff;

  color: #17464c;

  text-decoration: none;

  font-size: 12px;

  font-weight: 900;

  transition: 0.3s ease;
}

.appointmentCTAButton:hover {
  transform: translateY(-4px);

  box-shadow:
    0 15px 30px rgba(0, 0, 0, 0.2);
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1000px) {

  .appointmentHeroGrid {
    grid-template-columns: 1fr;

    gap: 55px;
  }

  .appointmentHeroContent {
    max-width: 750px;

    margin: 0 auto;

    text-align: center;
  }

  .appointmentHeroContent h1 {
    margin: 0 auto;
  }

  .appointmentHeroContent > p {
    margin-left: auto;
    margin-right: auto;
  }

  .appointmentHeroActions,
  .appointmentTrustRow {
    justify-content: center;
  }

  .appointmentHeroVisual {
    margin: 0 auto;
  }

  .appointmentIntroGrid {
    grid-template-columns: 1fr;

    gap: 45px;
  }

  .appointmentFormLayout {
    grid-template-columns: 1fr;
  }

  .appointmentSide {
    display: grid;

    grid-template-columns: repeat(3, 1fr);
  }

  .appointmentSectionHeading {
    display: block;
  }

  .appointmentSectionHeading > p {
    margin-top: 22px;
  }

}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

  .appointmentContainer {
    width: calc(100% - 28px);
  }

  /* HERO */

  .novaAppointmentHero {
    min-height: auto;
  }

  .appointmentHeroGrid {
    padding: 75px 0 90px;

    gap: 45px;
  }

  .appointmentHeroContent {
    text-align: center;
  }

  .appointmentEyebrow {
    font-size: 9px;

    letter-spacing: 0.12em;
  }

  .appointmentHeroContent h1 {
    font-size: clamp(42px, 13vw, 58px);
  }

  .appointmentHeroContent > p {
    font-size: 14px;

    line-height: 1.7;
  }

  .appointmentHeroActions {
    flex-direction: column;

    gap: 18px;
  }

  .appointmentTrustRow {
    gap: 13px;

    flex-direction: column;
  }

  .appointmentHeroVisual {
    width: 100%;
  }

  .appointmentHeroImage {
    aspect-ratio: 0.9;

    border-radius: 23px;
  }

  .appointmentFloatingCard {
    left: 15px;
    bottom: 18px;

    min-width: 0;

    width: calc(100% - 30px);

    box-sizing: border-box;
  }

  /* INTRO */

  .appointmentIntro {
    padding: 75px 0;
  }

  .appointmentIntro h2,
  .appointmentSectionHeading h2 {
    font-size: 40px;
  }

  .appointmentInfoCards {
    grid-template-columns: 1fr;
  }

  /* FORM */

  .appointmentFormSection {
    padding: 75px 0;
  }

  .appointmentSectionHeading {
    margin-bottom: 35px;
  }

  .appointmentFormCard {
    padding: 25px 18px;

    border-radius: 22px;
  }

  .formRow {
    grid-template-columns: 1fr;

    gap: 0;

    margin-bottom: 0;
  }

  .formField {
    margin-bottom: 18px;
  }

  /* SIDE */

  .appointmentSide {
    grid-template-columns: 1fr;
  }

  .appointmentSideCard {
    padding: 24px;
  }

  /* SUCCESS */

  .appointmentSuccess {
    min-height: 500px;

    padding: 25px 10px;
  }

  /* CTA */

  .appointmentFinalCTA {
    padding: 65px 0;
  }

  .appointmentCTACard {
    flex-direction: column;

    align-items: flex-start;

    padding: 45px 25px;

    gap: 30px;

    border-radius: 24px;
  }

  .appointmentCTACard h2 {
    font-size: 40px;
  }

  .appointmentCTAButton {
    align-self: flex-start;
  }

}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .appointmentHeroContent,
  .appointmentFloatingCard {
    animation: none;
  }

  .appointmentPrimaryBtn,
  .appointmentPhoneBtn,
  .appointmentInfoCard,
  .appointmentSubmitBtn,
  .appointmentAgainBtn,
  .appointmentSideCard,
  .appointmentCTAButton {
    transition: none;
  }

}
/* =========================================================
   NOVADENT CONTACT PAGE
   ========================================================= */

.novaContactPage {
  width: 100%;
  overflow: hidden;
  background: #f6fbfa;
  color: #173a3f;
}

.contactContainer {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
}

/* =========================================================
   HERO
   ========================================================= */

.novaContactHero {
  position: relative;
  min-height: 680px;

  display: flex;
  align-items: center;

  overflow: hidden;

  background:
    radial-gradient(
      circle at 75% 30%,
      rgba(100, 196, 185, 0.18),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #092c33 0%,
      #16484e 58%,
      #0b2930 100%
    );

  color: #fff;
}

.contactHeroGlow {
  position: absolute;

  width: 500px;
  height: 500px;

  right: -170px;
  top: 50%;

  transform: translateY(-50%);

  border-radius: 50%;

  background: rgba(91, 191, 181, 0.1);

  filter: blur(90px);

  pointer-events: none;
}

.contactHeroGrid {
  position: relative;
  z-index: 2;

  display: grid;

  grid-template-columns:
    minmax(0, 0.95fr)
    minmax(0, 0.9fr);

  gap: 80px;

  align-items: center;

  padding: 90px 0;
}

.contactHeroContent {
  animation: contactHeroIn 0.8s ease both;
}

@keyframes contactHeroIn {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.contactEyebrow {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  margin-bottom: 24px;

  color: #96ddd4;

  font-size: 11px;

  font-weight: 900;

  letter-spacing: 0.18em;
}

.contactHeroContent h1 {
  max-width: 700px;

  margin: 0;

  color: #fff;

  font-size: clamp(48px, 6vw, 78px);

  line-height: 0.98;

  letter-spacing: -0.055em;

  font-weight: 800;
}

.contactHeroContent h1 em {
  display: block;

  margin-top: 6px;

  color: #96ddd4;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;

  font-style: italic;
}

.contactHeroContent > p {
  max-width: 590px;

  margin: 28px 0 0;

  color: rgba(255, 255, 255, 0.72);

  font-size: 16px;

  line-height: 1.8;
}

/* HERO ACTIONS */

.contactHeroActions {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 22px;

  margin-top: 35px;
}

.contactPrimaryBtn {
  display: inline-flex;

  align-items: center;
  justify-content: center;

  gap: 9px;

  min-height: 52px;

  padding: 14px 23px;

  border-radius: 999px;

  background: #fff;

  color: #17444a;

  text-decoration: none;

  font-size: 13px;

  font-weight: 800;

  transition: 0.3s ease;
}

.contactPrimaryBtn:hover {
  transform: translateY(-4px);

  box-shadow:
    0 15px 35px rgba(0, 0, 0, 0.23);
}

.contactPhoneLink {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  color: #fff;

  text-decoration: none;

  font-size: 13px;

  font-weight: 700;

  transition: 0.3s ease;
}

.contactPhoneLink:hover {
  color: #96ddd4;

  transform: translateX(3px);
}

/* HERO TRUST */

.contactHeroTrust {
  display: flex;

  flex-wrap: wrap;

  gap: 20px;

  margin-top: 40px;

  padding-top: 23px;

  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.contactHeroTrust div {
  display: flex;

  align-items: center;

  gap: 8px;

  color: rgba(255, 255, 255, 0.66);

  font-size: 11px;

  font-weight: 700;
}

.contactHeroTrust svg,
.contactHeroTrust span + span {
  color: #91d8ce;
}

/* HERO IMAGE */

.contactHeroVisual {
  position: relative;

  width: 100%;

  max-width: 570px;

  margin-left: auto;
}

.contactHeroImage {
  position: relative;

  overflow: hidden;

  aspect-ratio: 0.95;

  border-radius: 30px;

  border: 1px solid rgba(255, 255, 255, 0.14);

  box-shadow:
    0 35px 80px rgba(0, 0, 0, 0.25);
}

.contactHeroImage img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transition: transform 0.8s ease;
}

.contactHeroImage:hover img {
  transform: scale(1.04);
}

.contactHeroImageOverlay {
  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      180deg,
      transparent 45%,
      rgba(7, 34, 40, 0.28)
    );

  pointer-events: none;
}

/* FLOATING CARD */

.contactHeroFloating {
  position: absolute;

  left: -30px;
  bottom: 32px;

  display: flex;

  align-items: center;

  gap: 13px;

  min-width: 250px;

  padding: 18px;

  border: 1px solid rgba(255, 255, 255, 0.5);

  border-radius: 18px;

  background: rgba(255, 255, 255, 0.95);

  color: #183f44;

  box-shadow:
    0 20px 50px rgba(0, 0, 0, 0.2);

  backdrop-filter: blur(14px);

  animation: contactFloat 4s ease-in-out infinite;
}

@keyframes contactFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }
}

.contactFloatingIcon {
  width: 42px;
  height: 42px;

  display: grid;

  place-items: center;

  flex-shrink: 0;

  border-radius: 13px;

  background: #dff3ef;

  color: #438d86;
}

.contactHeroFloating strong {
  display: block;

  font-size: 13px;
}

.contactHeroFloating span {
  display: block;

  margin-top: 4px;

  color: #829698;

  font-size: 11px;
}

/* =========================================================
   CONTACT DETAILS
   ========================================================= */

.contactDetailsSection {
  padding: 110px 0;

  background: #fff;
}

.contactSectionIntro {
  display: flex;

  align-items: end;

  justify-content: space-between;

  gap: 60px;

  margin-bottom: 50px;
}

.contactOverline {
  display: block;

  margin-bottom: 13px;

  color: #4c9790;

  font-size: 11px;

  font-weight: 900;

  letter-spacing: 0.2em;
}

.contactSectionIntro small,
.contactFormHeader small,
.contactLocationContent small {
  display: block;

  margin-bottom: 21px;

  color: #9baeb0;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 0.15em;
}

.contactSectionIntro h2,
.contactFormHeader h2,
.contactLocationContent h2 {
  margin: 0;

  color: #173a3f;

  font-size: clamp(40px, 5vw, 62px);

  line-height: 1.03;

  letter-spacing: -0.045em;
}

.contactSectionIntro h2 em,
.contactFormHeader h2 em,
.contactLocationContent h2 em {
  color: #4c9790;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.contactSectionIntro > p {
  max-width: 400px;

  margin: 0 0 5px;

  color: #6c8082;

  font-size: 14px;

  line-height: 1.8;
}

/* INFO CARDS */

.contactInfoGrid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 17px;
}

.contactInfoCard {
  position: relative;

  display: grid;

  grid-template-columns: auto 48px minmax(0, 1fr) auto;

  gap: 16px;

  align-items: center;

  min-height: 160px;

  padding: 25px;

  overflow: hidden;

  border: 1px solid #dfeae8;

  border-radius: 22px;

  background: #f8fcfb;

  color: inherit;

  text-decoration: none;

  transition:
    transform 0.35s ease,
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    background 0.35s ease;
}

.contactInfoCard:hover {
  transform: translateY(-7px);

  border-color: #a8d2cd;

  background: #fff;

  box-shadow:
    0 22px 45px rgba(25, 75, 78, 0.1);
}

.contactInfoNumber {
  align-self: start;

  color: #9caeaf;

  font-size: 10px;

  font-weight: 900;
}

.contactInfoIcon {
  width: 48px;
  height: 48px;

  display: grid;

  place-items: center;

  border-radius: 15px;

  background: #e1f3ef;

  color: #438f88;
}

.contactInfoContent {
  min-width: 0;
}

.contactInfoContent > span {
  display: block;

  color: #6d9691;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: 0.15em;
}

.contactInfoContent h3 {
  margin: 7px 0 5px;

  color: #23474c;

  font-size: 15px;

  overflow-wrap: anywhere;
}

.contactInfoContent p {
  margin: 0;

  color: #849698;

  font-size: 11px;

  line-height: 1.6;
}

.contactInfoArrow {
  color: #4b9891;

  transition: transform 0.3s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  transform: translate(3px, -3px);
}

/* =========================================================
   FORM SECTION
   ========================================================= */

.contactFormSection {
  padding: 110px 0 120px;

  background: #edf7f5;
}

.contactFormHeader {
  max-width: 700px;

  margin-bottom: 50px;
}

.contactFormHeader > p {
  max-width: 530px;

  margin: 22px 0 0;

  color: #718587;

  font-size: 14px;

  line-height: 1.8;
}

.contactFormLayout {
  display: grid;

  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(280px, 0.7fr);

  gap: 24px;

  align-items: start;
}

/* FORM */

.contactFormCard {
  padding: 42px;

  border: 1px solid #dceae7;

  border-radius: 28px;

  background: #fff;

  box-shadow:
    0 25px 65px rgba(28, 75, 78, 0.07);
}

.contactFormRow {
  display: grid;

  grid-template-columns: repeat(2, 1fr);

  gap: 18px;

  margin-bottom: 1px;
}

.contactField {
  display: flex;

  flex-direction: column;

  gap: 8px;

  margin-bottom: 20px;
}

.contactField label {
  color: #294b50;

  font-size: 12px;

  font-weight: 800;
}

.contactField input,
.contactField textarea {
  width: 100%;

  box-sizing: border-box;

  border: 1px solid #dce8e6;

  border-radius: 13px;

  background: #f9fcfb;

  color: #24484c;

  font-family: inherit;

  font-size: 14px;

  outline: none;

  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}

.contactField input {
  min-height: 52px;

  padding: 13px 15px;
}

.contactField textarea {
  min-height: 145px;

  padding: 14px 15px;

  resize: vertical;
}

.contactField input::placeholder,
.contactField textarea::placeholder {
  color: #a4b2b3;
}

.contactField input:focus,
.contactField textarea:focus {
  border-color: #67aaa3;

  background: #fff;

  box-shadow:
    0 0 0 4px rgba(103, 170, 163, 0.1);
}

/* SUBMIT */

.contactSubmitBtn {
  width: 100%;

  min-height: 56px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 14px 20px;

  border: 0;

  border-radius: 14px;

  background: #17484e;

  color: #fff;

  font-family: inherit;

  font-size: 13px;

  font-weight: 800;

  cursor: pointer;

  transition: 0.3s ease;
}

.contactSubmitBtn:hover {
  background: #266c6e;

  transform: translateY(-3px);

  box-shadow:
    0 15px 30px rgba(23, 72, 78, 0.18);
}

.contactFormNote {
  margin: 14px 0 0;

  color: #9aa9aa;

  font-size: 10px;

  line-height: 1.6;

  text-align: center;
}

/* SUCCESS */

.contactSuccess {
  min-height: 510px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  padding: 35px;

  text-align: center;
}

.contactSuccessIcon {
  width: 84px;
  height: 84px;

  display: grid;

  place-items: center;

  margin-bottom: 24px;

  border-radius: 50%;

  background: #e0f4ef;

  color: #4a9890;
}

.contactSuccess > span {
  color: #559a92;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.18em;
}

.contactSuccess h3 {
  margin: 15px 0 10px;

  color: #1b4247;

  font-size: 29px;
}

.contactSuccess p {
  max-width: 480px;

  margin: 0;

  color: #718486;

  font-size: 14px;

  line-height: 1.8;
}

.contactAgainBtn {
  display: inline-flex;

  align-items: center;

  gap: 9px;

  margin-top: 27px;

  padding: 13px 18px;

  border: 0;

  border-radius: 999px;

  background: #17484e;

  color: #fff;

  font-family: inherit;

  font-size: 12px;

  font-weight: 800;

  cursor: pointer;

  transition: 0.3s ease;
}

.contactAgainBtn:hover {
  background: #286e70;

  transform: translateY(-3px);
}

/* =========================================================
   SIDE PANEL
   ========================================================= */

.contactSidePanel {
  display: flex;

  flex-direction: column;

  gap: 16px;
}

.contactSideCard {
  position: relative;

  padding: 28px;

  border: 1px solid #dce9e7;

  border-radius: 22px;

  background: #fff;

  transition:
    transform 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.contactSideCard:hover {
  transform: translateY(-6px);

  border-color: #acd4cf;

  box-shadow:
    0 18px 40px rgba(28, 77, 79, 0.08);
}

.contactSideTop {
  display: flex;

  align-items: center;

  gap: 9px;

  color: #4b9690;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.16em;
}

.contactSideCard h3 {
  margin: 20px 0 25px;

  color: #23474c;

  font-size: 25px;

  line-height: 1.15;
}

.contactSideCard h3 em {
  color: #4b9790;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.contactHours {
  display: flex;

  flex-direction: column;

  gap: 13px;
}

.contactHours > div {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding-bottom: 12px;

  border-bottom: 1px solid #edf1f0;
}

.contactHours > div:last-child {
  padding-bottom: 0;

  border-bottom: 0;
}

.contactHours span {
  color: #8a9a9c;

  font-size: 11px;
}

.contactHours strong {
  color: #35575b;

  font-size: 11px;

  text-align: right;
}

/* APPOINTMENT CARD */

.contactAppointmentCard {
  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(111, 204, 193, 0.18),
      transparent 38%
    ),
    linear-gradient(
      145deg,
      #17484e,
      #286a6d
    );

  border-color: transparent;

  color: #fff;
}

.contactAppointmentCard > svg {
  color: #9be0d6;
}

.contactAppointmentCard > span {
  display: block;

  margin-top: 18px;

  color: #9be0d6;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: 0.16em;
}

.contactAppointmentCard h3 {
  margin: 12px 0 0;

  color: #fff;
}

.contactAppointmentCard h3 em {
  color: #9be0d6;
}

.contactAppointmentCard p {
  margin: 17px 0 0;

  color: rgba(255, 255, 255, 0.67);

  font-size: 12px;

  line-height: 1.7;
}

.contactAppointmentBtn {
  display: inline-flex;

  align-items: center;

  gap: 8px;

  margin-top: 22px;

  padding: 13px 17px;

  border-radius: 999px;

  background: #fff;

  color: #17484e;

  text-decoration: none;

  font-size: 11px;

  font-weight: 900;

  transition: 0.3s ease;
}

.contactAppointmentBtn:hover {
  transform: translateY(-3px);

  box-shadow:
    0 12px 25px rgba(0, 0, 0, 0.18);
}

/* DIRECT CONTACT */

.contactDirectCard > span {
  display: block;

  margin-bottom: 15px;

  color: #6d9691;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: 0.16em;
}

.contactDirectCard > a {
  display: flex;

  align-items: center;

  gap: 9px;

  padding: 12px 0;

  border-bottom: 1px solid #edf1f0;

  color: #34595e;

  text-decoration: none;

  font-size: 12px;

  font-weight: 700;

  transition: 0.3s ease;
}

.contactDirectCard > a:last-child {
  border-bottom: 0;
}

.contactDirectCard > a:hover {
  color: #3e9189;

  transform: translateX(3px);
}

.contactDirectCard > a svg:last-child {
  margin-left: auto;
}

/* =========================================================
   LOCATION SECTION
   ========================================================= */

.contactLocationSection {
  padding: 115px 0;

  background: #fff;
}

.contactLocationGrid {
  display: grid;

  grid-template-columns:
    minmax(0, 0.8fr)
    minmax(0, 1.2fr);

  gap: 75px;

  align-items: center;
}

.contactLocationContent > p {
  max-width: 490px;

  margin: 25px 0 0;

  color: #718486;

  font-size: 15px;

  line-height: 1.8;
}

.contactLocationAddress {
  display: flex;

  align-items: center;

  gap: 14px;

  margin-top: 32px;

  padding: 20px;

  border: 1px solid #dfeae8;

  border-radius: 18px;

  background: #f8fcfb;
}

.contactLocationIcon {
  width: 44px;
  height: 44px;

  display: grid;

  place-items: center;

  flex-shrink: 0;

  border-radius: 13px;

  background: #e1f3ef;

  color: #438f88;
}

.contactLocationAddress strong {
  display: block;

  color: #264a4e;

  font-size: 13px;
}

.contactLocationAddress span {
  display: block;

  margin-top: 5px;

  color: #859799;

  font-size: 11px;

  line-height: 1.5;
}

.contactLocationLinks {
  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 18px;

  margin-top: 24px;
}

.contactMapLink,
.contactDirectionsLink {
  display: inline-flex;

  align-items: center;

  gap: 8px;

  text-decoration: none;

  font-size: 12px;

  font-weight: 900;

  transition: 0.3s ease;
}

.contactMapLink {
  color: #3e8e87;
}

.contactDirectionsLink {
  color: #6e8385;
}

.contactMapLink:hover,
.contactDirectionsLink:hover {
  transform: translateX(3px);
}

/* =========================================================
   PROFESSIONAL MAP
   ========================================================= */

.contactMapVisual {
  overflow: hidden;

  border: 1px solid #dbe8e6;

  border-radius: 28px;

  background: #eef6f4;

  box-shadow:
    0 25px 65px rgba(28, 75, 78, 0.1);
}

.contactMapHeader {
  display: flex;

  align-items: center;

  justify-content: space-between;

  padding: 20px 24px;

  border-bottom: 1px solid #d7e4e2;

  background: #fff;
}

.contactMapHeader span {
  display: block;

  color: #6d9994;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: 0.15em;
}

.contactMapHeader strong {
  display: block;

  margin-top: 5px;

  color: #274b50;

  font-size: 14px;
}

.contactMapHeader > svg {
  color: #4a958e;
}

/* MAP CANVAS */

.contactMapCanvas {
  position: relative;

  min-height: 390px;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      #e8f1ee,
      #f5f8f5
    );
}

.mapGridLines {
  position: absolute;

  inset: 0;

  opacity: 0.45;

  background-image:
    linear-gradient(
      rgba(93, 133, 129, 0.09) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(93, 133, 129, 0.09) 1px,
      transparent 1px
    );

  background-size: 42px 42px;
}

/* MAP ROADS */

.mapRoad {
  position: absolute;

  background: rgba(255, 255, 255, 0.95);

  box-shadow:
    0 0 0 1px rgba(110, 145, 140, 0.08);
}

.roadOne {
  width: 130%;

  height: 28px;

  left: -10%;
  top: 28%;

  transform: rotate(-11deg);
}

.roadTwo {
  width: 120%;

  height: 20px;

  left: -8%;
  top: 61%;

  transform: rotate(15deg);
}

.roadThree {
  width: 25px;

  height: 120%;

  left: 42%;
  top: -10%;

  transform: rotate(17deg);
}

.roadFour {
  width: 18px;

  height: 110%;

  left: 72%;
  top: -5%;

  transform: rotate(-28deg);
}

/* MAP LABELS */

.mapArea {
  position: absolute;

  color: #91a7a4;

  font-size: 10px;

  font-weight: 700;

  letter-spacing: 0.05em;
}

.areaOne {
  left: 10%;

  top: 19%;
}

.areaTwo {
  right: 12%;

  top: 35%;
}

.areaThree {
  left: 14%;

  bottom: 17%;
}

/* MAP PIN */

.mapPinLarge {
  position: absolute;

  left: 52%;
  top: 49%;

  transform: translate(-50%, -50%);
}

.mapPinCore {
  position: relative;

  width: 62px;
  height: 62px;

  display: grid;

  place-items: center;

  border: 7px solid rgba(255, 255, 255, 0.85);

  border-radius: 50% 50% 50% 0;

  background: #398982;

  color: #fff;

  transform: rotate(-45deg);

  box-shadow:
    0 12px 30px rgba(44, 111, 105, 0.28);
}

.mapPinCore svg {
  transform: rotate(45deg);
}

.mapPinPulse {
  position: absolute;

  width: 110px;
  height: 110px;

  border-radius: 50%;

  background: rgba(65, 147, 139, 0.14);

  animation: mapPulse 2.5s ease-out infinite;
}

@keyframes mapPulse {
  0% {
    transform: scale(0.65);

    opacity: 0.9;
  }

  70% {
    transform: scale(1.15);

    opacity: 0;
  }

  100% {
    transform: scale(1.15);

    opacity: 0;
  }
}

/* MAP LABEL CARD */

.mapLocationLabel {
  position: absolute;

  left: calc(52% + 45px);
  top: calc(49% - 15px);

  display: flex;

  flex-direction: column;

  padding: 12px 15px;

  border: 1px solid rgba(220, 233, 230, 0.95);

  border-radius: 12px;

  background: rgba(255, 255, 255, 0.95);

  box-shadow:
    0 10px 25px rgba(50, 90, 87, 0.1);
}

.mapLocationLabel strong {
  color: #285158;

  font-size: 12px;

  letter-spacing: 0.08em;
}

.mapLocationLabel span {
  margin-top: 3px;

  color: #8a9c9e;

  font-size: 10px;
}

/* MAP BOTTOM */

.contactMapBottom {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 15px;

  padding: 17px 22px;

  border-top: 1px solid #d7e4e2;

  background: #fff;
}

.contactMapBottom span {
  display: inline-flex;

  align-items: center;

  gap: 7px;

  color: #829596;

  font-size: 11px;
}

.contactMapBottom a {
  display: inline-flex;

  align-items: center;

  gap: 6px;

  color: #438f88;

  text-decoration: none;

  font-size: 11px;

  font-weight: 900;

  white-space: nowrap;
}

.contactMapBottom a:hover {
  transform: translateX(3px);
}

/* =========================================================
   FINAL CTA
   ========================================================= */

.contactFinalCTA {
  padding: 100px 0;

  background: #f7fbfa;
}

.contactCTACard {
  position: relative;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 50px;

  overflow: hidden;

  padding: 65px 70px;

  border-radius: 30px;

  background:
    radial-gradient(
      circle at 90% 10%,
      rgba(133, 213, 203, 0.2),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      #123d44,
      #1d595d
    );

  color: #fff;
}

.contactCTACard::after {
  content: "";

  position: absolute;

  width: 260px;
  height: 260px;

  right: -100px;
  bottom: -170px;

  border: 1px solid rgba(255, 255, 255, 0.14);

  border-radius: 50%;

  box-shadow:
    0 0 0 55px rgba(255, 255, 255, 0.025),
    0 0 0 110px rgba(255, 255, 255, 0.018);
}

.contactCTACard > div:first-child {
  position: relative;

  z-index: 2;
}

.contactCTACard > div:first-child > span {
  display: inline-block;

  margin-bottom: 18px;

  color: #9bddd4;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 0.18em;
}

.contactCTACard h2 {
  max-width: 650px;

  margin: 0;

  color: #fff;

  font-size: clamp(38px, 5vw, 58px);

  line-height: 1.04;

  letter-spacing: -0.045em;
}

.contactCTACard h2 em {
  display: block;

  color: #9bddd4;

  font-family: Georgia, "Times New Roman", serif;

  font-weight: 400;
}

.contactCTACard p {
  margin: 20px 0 0;

  color: rgba(255, 255, 255, 0.68);

  font-size: 14px;
}

.contactCTAActions {
  position: relative;

  z-index: 3;

  display: flex;

  align-items: center;

  gap: 12px;

  flex-shrink: 0;
}

.contactCTASecondary,
.contactCTAButton {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 8px;

  min-height: 48px;

  padding: 13px 18px;

  border-radius: 999px;

  text-decoration: none;

  font-size: 12px;

  font-weight: 900;

  transition: 0.3s ease;
}

.contactCTASecondary {
  border: 1px solid rgba(255, 255, 255, 0.24);

  color: #fff;
}

.contactCTASecondary:hover {
  border-color: #9bddd4;

  color: #9bddd4;

  transform: translateY(-3px);
}

.contactCTAButton {
  background: #fff;

  color: #17464c;
}

.contactCTAButton:hover {
  transform: translateY(-4px);

  box-shadow:
    0 15px 30px rgba(0, 0, 0, 0.2);
}

/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1000px) {

  .contactHeroGrid {
    grid-template-columns: 1fr;

    gap: 55px;
  }

  .contactHeroContent {
    max-width: 760px;

    margin: 0 auto;

    text-align: center;
  }

  .contactHeroContent h1 {
    margin-left: auto;
    margin-right: auto;
  }

  .contactHeroContent > p {
    margin-left: auto;
    margin-right: auto;
  }

  .contactHeroActions,
  .contactHeroTrust {
    justify-content: center;
  }

  .contactHeroVisual {
    margin: 0 auto;
  }

  .contactSectionIntro {
    display: block;
  }

  .contactSectionIntro > p {
    margin-top: 22px;
  }

  .contactInfoGrid {
    grid-template-columns: 1fr;
  }

  .contactFormLayout {
    grid-template-columns: 1fr;
  }

  .contactSidePanel {
    display: grid;

    grid-template-columns: repeat(3, 1fr);
  }

  .contactLocationGrid {
    grid-template-columns: 1fr;

    gap: 50px;
  }

}

/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

  .contactContainer {
    width: calc(100% - 28px);
  }

  /* HERO */

  .novaContactHero {
    min-height: auto;
  }

  .contactHeroGrid {
    padding: 75px 0 90px;

    gap: 45px;
  }

  .contactHeroContent {
    text-align: center;
  }

  .contactEyebrow {
    font-size: 9px;

    letter-spacing: 0.12em;
  }

  .contactHeroContent h1 {
    font-size: clamp(42px, 13vw, 58px);
  }

  .contactHeroContent > p {
    font-size: 14px;

    line-height: 1.7;
  }

  .contactHeroActions {
    flex-direction: column;

    gap: 18px;
  }

  .contactHeroTrust {
    flex-direction: column;

    align-items: center;

    gap: 12px;
  }

  .contactHeroVisual {
    width: 100%;
  }

  .contactHeroImage {
    aspect-ratio: 0.9;

    border-radius: 23px;
  }

  .contactHeroFloating {
    left: 15px;
    bottom: 18px;

    width: calc(100% - 30px);

    min-width: 0;

    box-sizing: border-box;
  }

  /* DETAILS */

  .contactDetailsSection {
    padding: 75px 0;
  }

  .contactSectionIntro h2,
  .contactFormHeader h2,
  .contactLocationContent h2 {
    font-size: 40px;
  }

  .contactInfoCard {
    grid-template-columns:
      auto
      44px
      minmax(0, 1fr)
      auto;

    min-height: 140px;

    padding: 20px 17px;
  }

  .contactInfoIcon {
    width: 44px;
    height: 44px;
  }

  .contactInfoContent h3 {
    font-size: 13px;
  }

  /* FORM */

  .contactFormSection {
    padding: 75px 0;
  }

  .contactFormHeader {
    margin-bottom: 35px;
  }

  .contactFormCard {
    padding: 25px 18px;

    border-radius: 22px;
  }

  .contactFormRow {
    grid-template-columns: 1fr;

    gap: 0;
  }

  /* SIDE */

  .contactSidePanel {
    grid-template-columns: 1fr;
  }

  .contactSideCard {
    padding: 24px;
  }

  /* LOCATION */

  .contactLocationSection {
    padding: 75px 0;
  }

  .contactMapCanvas {
    min-height: 320px;
  }

  .mapLocationLabel {
    left: auto;
    right: 15px;
    top: 52%;
  }

  .contactMapBottom {
    flex-direction: column;

    align-items: flex-start;
  }

  .contactLocationLinks {
    flex-direction: column;

    align-items: flex-start;

    gap: 13px;
  }

  /* CTA */

  .contactFinalCTA {
    padding: 65px 0;
  }

  .contactCTACard {
    flex-direction: column;

    align-items: flex-start;

    padding: 45px 25px;

    gap: 30px;

    border-radius: 24px;
  }

  .contactCTACard h2 {
    font-size: 40px;
  }

  .contactCTAActions {
    width: 100%;

    flex-direction: column;

    align-items: stretch;
  }

  .contactCTASecondary,
  .contactCTAButton {
    width: 100%;

    box-sizing: border-box;
  }

}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .contactHeroContent,
  .contactHeroFloating,
  .mapPinPulse {
    animation: none;
  }

  .contactPrimaryBtn,
  .contactPhoneLink,
  .contactInfoCard,
  .contactInfoArrow,
  .contactSubmitBtn,
  .contactAgainBtn,
  .contactSideCard,
  .contactAppointmentBtn,
  .contactDirectCard > a,
  .contactMapLink,
  .contactDirectionsLink,
  .contactCTASecondary,
  .contactCTAButton {
    transition: none;
  }

}
/* =========================================================
   CONTACT DETAILS — PREMIUM ALIGNMENT
========================================================= */

.contactDetailsSection {
  padding: 110px 0;
  background: #f6faf9;
}

.contactSectionIntro {
  display: grid;
  grid-template-columns: 1fr 0.8fr;
  gap: 80px;
  align-items: end;
  margin-bottom: 55px;
}

.contactSectionIntro > div {
  min-width: 0;
}

.contactSectionIntro p {
  margin: 0;
  max-width: 520px;
  justify-self: end;
  color: #667b7b;
  font-size: 16px;
  line-height: 1.8;
}

/* Number + heading alignment */

.contactOverline {
  display: block;
  margin-bottom: 12px;
  color: #4b918a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.contactSectionIntro small {
  display: block;
  margin-bottom: 18px;
  color: #91a2a2;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.contactSectionIntro h2 {
  margin: 0;
  color: #173f46;
  font-size: clamp(40px, 5vw, 68px);
  font-weight: 500;
  line-height: 0.98;
  letter-spacing: -0.045em;
}

.contactSectionIntro h2 em {
  color: #4b918a;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

/* Cards */

.contactInfoGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
  align-items: stretch;
}

.contactInfoCard {
  position: relative;
  min-height: 290px;
  padding: 30px;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  border: 1px solid #dce9e7;
  border-radius: 24px;
  background: #ffffff;
  overflow: hidden;
  transition:
    transform 0.35s ease,
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    background 0.35s ease;
}

.contactInfoCard::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 3px;
  background: #4b918a;
  transition: width 0.4s ease;
}

.contactInfoCard:hover {
  transform: translateY(-8px);
  border-color: #b8d8d3;
  box-shadow: 0 22px 55px rgba(25, 67, 73, 0.12);
}

.contactInfoCard:hover::before {
  width: 100%;
}

/* Number */

.contactInfoNumber {
  position: absolute;
  top: 25px;
  right: 28px;
  color: #b8c8c7;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

/* Icon */

.contactInfoIcon {
  width: 52px;
  height: 52px;
  margin-bottom: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  background: #e9f4f2;
  color: #4b918a;
  transition:
    background 0.3s ease,
    color 0.3s ease,
    transform 0.3s ease;
}

.contactInfoCard:hover .contactInfoIcon {
  background: #4b918a;
  color: #ffffff;
  transform: translateY(-3px);
}

/* Content */

.contactInfoContent {
  margin-top: auto;
  min-width: 0;
}

.contactInfoContent > span {
  display: block;
  margin-bottom: 9px;
  color: #94a6a5;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.contactInfoContent h3 {
  margin: 0 38px 10px 0;
  color: #173f46;
  font-size: clamp(20px, 2vw, 25px);
  font-weight: 650;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.contactInfoContent p {
  margin: 0;
  max-width: 270px;
  color: #718483;
  font-size: 13px;
  line-height: 1.65;
}

/* Arrow */

.contactInfoArrow {
  position: absolute;
  right: 27px;
  bottom: 28px;
  color: #a2b3b2;
  transition:
    transform 0.3s ease,
    color 0.3s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  color: #4b918a;
  transform: translate(4px, -4px);
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {

  .contactDetailsSection {
    padding: 85px 0;
  }

  .contactSectionIntro {
    grid-template-columns: 1fr;
    gap: 25px;
    margin-bottom: 40px;
  }

  .contactSectionIntro p {
    justify-self: start;
    max-width: 650px;
  }

  .contactInfoGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 600px) {

  .contactDetailsSection {
    padding: 70px 0;
  }

  .contactSectionIntro h2 {
    font-size: 42px;
  }

  .contactInfoGrid {
    grid-template-columns: 1fr;
    gap: 15px;
  }

  .contactInfoCard {
    min-height: 255px;
    padding: 25px;
  }

  .contactInfoIcon {
    margin-bottom: 35px;
  }

  .contactInfoNumber {
    top: 22px;
    right: 23px;
  }

  .contactInfoArrow {
    right: 23px;
    bottom: 23px;
  }

}
/* =========================================================
   NOVADENT CONTACT PAGE
   PREMIUM + RESPONSIVE
========================================================= */

.novaContactPage {
  background: #f8fbfa;
  color: #173f46;
  overflow: hidden;
}

.contactContainer {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
}

