.contactHeroGrid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 80px;
  align-items: center;
}

.contactHeroContent {
  min-width: 0;
}

.contactEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 25px;
  color: #4b918a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.contactHeroContent h1 {
  max-width: 680px;
  margin: 0;
  color: #173f46;
  font-size: clamp(48px, 6vw, 82px);
  font-weight: 500;
  line-height: 0.98;
  letter-spacing: -0.055em;
}

.contactHeroContent h1 em {
  display: block;
  color: #4b918a;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.contactHeroContent > p {
  max-width: 570px;
  margin: 28px 0 0;
  color: #667d7c;
  font-size: 16px;
  line-height: 1.8;
}

.contactHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 25px;
  margin-top: 38px;
}

.contactPrimaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 15px 22px;
  border-radius: 999px;
  background: #173f46;
  color: #fff;
  font-size: 13px;
  font-weight: 750;
  text-decoration: none;
  transition:
    transform 0.3s ease,
    background 0.3s ease,
