  width: 100%;
}

.contactInfoNumber {
  position: absolute;
  top: 25px;
  right: 28px;
  color: #b8c8c7;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .12em;
}

.contactInfoIcon {
  width: 52px;
  height: 52px;
  margin-bottom: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  background: #e9f4f2;
  color: #4b918a;
  transition:
    background .3s ease,
    color .3s ease,
    transform .3s ease;
}

.contactInfoCard:hover .contactInfoIcon {
  background: #4b918a;
  color: #fff;
  transform: translateY(-3px);
}

.contactInfoContent {
  margin-top: auto;
  min-width: 0;
}

.contactInfoContent > span {
  display: block;
  margin-bottom: 9px;
  color: #94a6a5;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .16em;
}

.contactInfoContent h3 {
  margin: 0 38px 10px 0;
  color: #173f46;
  font-size: clamp(19px, 2vw, 25px);
  font-weight: 650;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.contactInfoContent p {
  max-width: 270px;
  margin: 0;
  color: #718483;
  font-size: 13px;
  line-height: 1.65;
}

.contactInfoArrow {
  position: absolute;
  right: 27px;
  bottom: 28px;
  color: #a2b3b2;
  transition:
    transform .3s ease,
    color .3s ease;
}

.contactInfoCard:hover .contactInfoArrow {
  color: #4b918a;
  transform: translate(4px,-4px);
}


/* =========================================================
   FORM SECTION
========================================================= */

.contactFormSection {
  padding: 120px 0;
  background: #edf6f4;
}

.contactFormHeader {
  max-width: 720px;
  margin-bottom: 55px;
}

.contactFormHeader > p {
  max-width: 540px;
  margin: 25px 0 0;
  color: #6d8180;
  font-size: 15px;
  line-height: 1.8;
}

.contactFormLayout {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(300px, .75fr);
  gap: 24px;
  align-items: start;
}

.contactFormCard {
  padding: 42px;
  border: 1px solid #d7e7e4;
  border-radius: 28px;
  background: #fff;
  box-shadow: 0 25px 65px rgba(24,68,73,.07);
}

