  font-size: 13px;
  font-weight: 800;
  transition:
    transform .3s ease,
    background .3s ease,
    box-shadow .3s ease;
}

.contactSubmitBtn:hover {
  transform: translateY(-3px);
  background: #4b918a;
  box-shadow: 0 15px 30px rgba(23,63,70,.15);
}

.contactFormNote {
  margin: 15px 0 0;
