}


/* MAP VISUAL */

.contactMapVisual {
  position: relative;
  min-height: 550px;
  overflow: hidden;
  border: 1px solid #d7e7e4;
  border-radius: 30px;
  background: #e8f1ef;
  box-shadow: 0 25px 60px rgba(23,63,70,.10);
}

.contactMapTopBar {
  position: absolute;
  z-index: 10;
  left: 22px;
  right: 22px;
  top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px;
  border: 1px solid rgba(255,255,255,.8);
  border-radius: 15px;
  background: rgba(255,255,255,.91);
  box-shadow: 0 10px 25px rgba(23,63,70,.08);
  backdrop-filter: blur(10px);
}

.contactMapTopBar span,
.contactMapTopBar strong {
  display: block;
}

.contactMapTopBar span {
  margin-bottom: 4px;
  color: #8a9b9a;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
}

.contactMapTopBar strong {
  color: #173f46;
  font-size: 13px;
}

.contactMapTopBar svg {
  color: #4b918a;
}

.contactMapCanvas {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background:
    linear-gradient(
      115deg,
      #e6f0ed 0%,
      #f2f6f3 50%,
      #e4efec 100%
    );
}

.mapGridLines {
  position: absolute;
  inset: 0;
  opacity: .5;
  background-image:
    linear-gradient(
      rgba(82,133,128,.12) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(82,133,128,.12) 1px,
      transparent 1px
    );
  background-size: 42px 42px;
}

.mapRoad {
  position: absolute;
  height: 18px;
  border-radius: 30px;
  background: rgba(255,255,255,.88);
  box-shadow: 0 0 0 1px rgba(112,145,140,.12);
}

.roadOne {
  width: 130%;
  left: -15%;
  top: 43%;
  transform: rotate(-17deg);
}

.roadTwo {
  width: 120%;
  left: -10%;
  top: 66%;
  transform: rotate(24deg);
}

.roadThree {
  width: 100%;
  left: 8%;
  top: 28%;
  transform: rotate(72deg);
}

.roadFour {
  width: 85%;
  left: 27%;
  top: 51%;
  transform: rotate(-65deg);
}

.mapArea {
  position: absolute;
  color: rgba(23,63,70,.35);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.areaOne {
  top: 33%;
  left: 12%;
}

.areaTwo {
  right: 12%;
  bottom: 25%;
}

.areaThree {
  left: 42%;
  bottom: 12%;
}

.mapPinLarge {
  position: absolute;
  left: 54%;
  top: 52%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.mapPinLarge > div {
  position: relative;
  z-index: 2;
  width: 68px;
  height: 68px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 8px solid rgba(255,255,255,.8);
  border-radius: 50%;
  background: #4b918a;
  color: #fff;
  box-shadow: 0 15px 35px rgba(75,145,138,.35);
}

.mapPulse {
  position: absolute;
  width: 115px;
  height: 115px;
  border-radius: 50%;
  background: rgba(75,145,138,.13);
  animation: mapPulseAnimation 2.2s ease-out infinite;
}

@keyframes mapPulseAnimation {
  0% {
    transform: scale(.55);
    opacity: .8;
  }

  70% {
    transform: scale(1);
    opacity: .15;
  }

  100% {
    transform: scale(1.15);
    opacity: 0;
  }
}

.mapLocationLabel {
  position: absolute;
  z-index: 5;
  top: 77px;
  left: 50%;
  transform: translateX(-50%);
  min-width: 145px;
  padding: 10px 13px;
  border-radius: 11px;
  background: rgba(255,255,255,.95);
  box-shadow: 0 10px 25px rgba(23,63,70,.12);
  text-align: center;
}

.mapLocationLabel strong,
.mapLocationLabel span {
  display: block;
}

.mapLocationLabel strong {
  margin-bottom: 3px;
  color: #173f46;
  font-size: 11px;
}

.mapLocationLabel span {
  color: #829291;
  font-size: 9px;
}

.mapOpenButton {
  position: absolute;
  z-index: 10;
  right: 22px;
  bottom: 22px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  border-radius: 999px;
  background: #173f46;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  text-decoration: none;
  box-shadow: 0 10px 25px rgba(23,63,70,.16);
  transition:
    transform .3s ease,
    background .3s ease;
}

.mapOpenButton:hover {
  transform: translateY(-3px);
  background: #4b918a;
}


