/* =========================================================
   NOVADENT PREMIUM NAVBAR
========================================================= */

.novaNavbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.94);
  border-bottom: 1px solid rgba(220, 232, 235, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  box-shadow: 0 8px 30px rgba(11, 37, 69, 0.06);
}

.novaNavbarInner {
  width: min(1440px, calc(100% - 56px));
  min-height: 82px;
  margin: 0 auto;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 28px;
}


/* =========================================================
   BRAND
========================================================= */

.novaBrand {
  display: inline-flex;
  align-items: center;
  gap: 12px;

  flex-shrink: 0;

  color: var(--ink);
  text-decoration: none;

  transition: transform 0.3s ease;
}

.novaBrand:hover {
  transform: translateY(-1px);
}


.novaLogoWrap {
  position: relative;

  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;
}


.novaLogo {
  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 15px;

  background: var(--ink);
  color: #ffffff;

  box-shadow:
    0 8px 24px rgba(11, 37, 69, 0.16);

  transition:
    transform 0.35s ease,
    background 0.35s ease,
    box-shadow 0.35s ease;
}


.novaBrand:hover .novaLogo {
  transform: translateY(-2px) rotate(-3deg);

  background: var(--primary);

  box-shadow:
    0 12px 28px rgba(11, 37, 69, 0.18);
}


.novaLogo svg {
  width: 30px;
  height: 30px;
}


.novaSparkle {
  position: absolute;

  top: -3px;
  right: -4px;

  width: 18px;
  height: 18px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #ffffff;
  color: var(--primary);

  border: 1px solid #dce9e7;

  box-shadow:
    0 4px 12px rgba(11, 37, 69, 0.12);
}


.novaBrandText {
  display: flex;
  flex-direction: column;

  gap: 4px;
}


.novaBrandText strong {
  color: var(--ink);

  font-size: 19px;
  font-weight: 850;

  letter-spacing: 2.2px;
  line-height: 1;
}


.novaBrandText span {
  color: var(--primary);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 3px;
  line-height: 1;

  text-transform: uppercase;
}


/* =========================================================
   NAVIGATION
========================================================= */

.novaNavigation {
  display: flex;
  align-items: center;
  justify-content: center;

  flex: 1;
}


.novaNavLinks {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 27px;
}


.novaNavLink {
  position: relative;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 82px;

  padding: 0;

  color: #53677c;

  font-size: 13px;
  font-weight: 700;

  white-space: nowrap;

  text-decoration: none;

  transition:
    color 0.25s ease,
    transform 0.25s ease;
}


.novaNavLink:hover {
  color: var(--primary);

  transform: translateY(-1px);
}


.novaNavLink.isActive {
  color: var(--primary);
}


.novaNavLink::after {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  bottom: 20px;

  height: 2px;

  border-radius: 20px;

  background: var(--primary);

  transform: scaleX(0);
  transform-origin: center;

  transition: transform 0.3s ease;
}


.novaNavLink:hover::after,
.novaNavLink.isActive::after {
  transform: scaleX(1);
}


.activeDot {
  position: absolute;

  top: 18px;
  right: -6px;

  width: 5px;
  height: 5px;

  border-radius: 50%;

  background: var(--primary);
}


/* =========================================================
   DESKTOP APPOINTMENT CTA
========================================================= */

.novaDesktopCTA {
  min-height: 52px;

  display: inline-flex;
  align-items: center;

  gap: 10px;

  padding: 8px 10px 8px 9px;

  flex-shrink: 0;

  border-radius: 16px;

  background: var(--ink);
  color: #ffffff;

  text-decoration: none;

  box-shadow:
    0 10px 26px rgba(11, 37, 69, 0.14);

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    box-shadow 0.3s ease;
}


.novaDesktopCTA:hover {
  transform: translateY(-2px);

  background: var(--primary);

  box-shadow:
