}


.ctaIcon {
  width: 34px;
  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 10px;

  background: rgba(255, 255, 255, 0.12);
}


.ctaText {
  display: flex;
  flex-direction: column;

  gap: 3px;

  padding-right: 8px;
}


.ctaText small {
  font-size: 7px;
  font-weight: 800;

  letter-spacing: 1.5px;

  opacity: 0.62;
}


.ctaText strong {
  font-size: 12px;
  font-weight: 800;

  white-space: nowrap;
}


.ctaArrow {
