/* =========================================================
   NOVADENT — PREMIUM HERO
========================================================= */

.novaHero {
  position: relative;
  min-height: 760px;
  height: min(92vh, 900px);
  width: 100%;
  overflow: hidden;
  display: flex;
  align-items: center;
  background: #123b42;
  isolation: isolate;
}

/* =========================================================
   BACKGROUND SLIDES
========================================================= */

.heroSlides {
  position: absolute;
  inset: 0;
  z-index: -5;
  overflow: hidden;
}

.heroSlide {
  position: absolute;
  inset: 0;
  opacity: 0;
  visibility: hidden;
  transform: scale(1.08);
  transition:
    opacity 0.9s ease,
    transform 6s ease,
    visibility 0.9s ease;
}

.heroSlide-current {
  opacity: 1;
  visibility: visible;
  transform: scale(1);
}

.heroSlide img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
}

/* Subtle image movement */

.heroSlide-current.slide-next img {
  animation: heroZoomNext 5.8s ease forwards;
}

.heroSlide-current.slide-prev img {
  animation: heroZoomPrev 5.8s ease forwards;
}

@keyframes heroZoomNext {
  from {
    transform: scale(1.08);
  }

  to {
    transform: scale(1);
  }
}

@keyframes heroZoomPrev {
  from {
    transform: scale(1.02);
  }

  to {
    transform: scale(1.08);
  }
}

/* =========================================================
   OVERLAY
========================================================= */

.heroOverlay {
  position: absolute;
  inset: 0;
  z-index: -4;

  background:
    linear-gradient(
      90deg,
      rgba(7, 32, 38, 0.92) 0%,
      rgba(7, 32, 38, 0.78) 35%,
      rgba(7, 32, 38, 0.42) 68%,
      rgba(7, 32, 38, 0.18) 100%
    ),
    linear-gradient(
      180deg,
      rgba(6, 29, 34, 0.25) 0%,
      rgba(6, 29, 34, 0.05) 45%,
      rgba(6, 29, 34, 0.6) 100%
    );
}

/* =========================================================
   SOFT GLOW
========================================================= */

.heroSoftGlow {
  position: absolute;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(5px);
  opacity: 0.3;
  z-index: -3;
}

.heroSoftGlowOne {
  width: 420px;
  height: 420px;
  left: -180px;
  top: 80px;
  background: rgba(111, 181, 174, 0.22);
}

.heroSoftGlowTwo {
  width: 330px;
  height: 330px;
  right: -130px;
  bottom: -120px;
  background: rgba(255, 255, 255, 0.08);
}

/* =========================================================
   CONTENT
========================================================= */

.heroContent {
  width: min(1180px, calc(100% - 80px));
  margin: 0 auto;
  padding: 120px 0 100px;
  position: relative;
  z-index: 3;
}

/* =========================================================
   EYEBROW
========================================================= */

.heroEyebrow {
  display: flex;
  align-items: center;
  gap: 14px;
  width: fit-content;
  margin-bottom: 22px;

  color: rgba(255, 255, 255, 0.86);

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.22em;
  line-height: 1.4;
}

.heroEyebrowLine {
  width: 42px;
  height: 1px;
  background: rgba(255, 255, 255, 0.65);
}

/* =========================================================
   MINI BRAND LABEL
========================================================= */

.heroMiniLabel {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  margin-bottom: 16px;
  padding: 7px 12px;

  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 30px;

  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px);

  color: rgba(255, 255, 255, 0.75);

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

/* =========================================================
   TITLE
========================================================= */

.heroTitle {
  max-width: 760px;
  margin: 0;

  color: #ffffff;

  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(58px, 7vw, 104px);
  font-weight: 400;
  line-height: 0.94;
  letter-spacing: -0.055em;
}

.heroTitleLine {
  display: block;

  opacity: 0;
  animation: heroTitleIn 0.8s ease forwards;
}

.heroTitleLine:nth-child(2) {
  animation-delay: 0.1s;
}

@keyframes heroTitleIn {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   DESCRIPTION
========================================================= */

.heroDescription {
  max-width: 535px;
  margin: 28px 0 0;

  color: rgba(255, 255, 255, 0.78);

  font-size: 16px;
  font-weight: 400;
  line-height: 1.75;

  animation: heroDescriptionIn 0.9s ease 0.15s both;
}

@keyframes heroDescriptionIn {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   ACTIONS
========================================================= */

.heroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;

  margin-top: 34px;
}

.heroPrimaryBtn,
.heroSecondaryBtn {
  min-height: 54px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 11px;

  padding: 0 20px;

  border-radius: 4px;

  text-decoration: none;

  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.heroPrimaryBtn {
  color: #16434c;
  background: #ffffff;
  border: 1px solid #ffffff;
}

.heroPrimaryBtn:hover {
  transform: translateY(-3px);
  background: #e7f3f1;
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.18);
}

.heroBtnIcon {
  width: 30px;
  height: 30px;

  display: grid;
  place-items: center;

  border-radius: 50%;

  background: #e4f1ef;
}

.heroSecondaryBtn {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.35);
  backdrop-filter: blur(8px);
}

.heroSecondaryBtn:hover {
  transform: translateY(-3px);
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.65);
}

/* =========================================================
   TRUST
========================================================= */

.heroTrust {
  display: flex;
  align-items: center;
  gap: 25px;

  margin-top: 52px;
}

.heroTrustItem {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.heroTrustItem strong {
  color: #ffffff;

  font-family: Georgia, "Times New Roman", serif;
  font-size: 27px;
  font-weight: 400;
  line-height: 1;
}

.heroTrustItem span {
  color: rgba(255, 255, 255, 0.62);

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.heroTrustDivider {
  width: 1px;
  height: 38px;

  background: rgba(255, 255, 255, 0.22);
}

/* =========================================================
   ARROWS
========================================================= */

.heroArrow {
  position: absolute;
  top: 50%;
  z-index: 5;

  width: 50px;
  height: 50px;

  display: grid;
  place-items: center;

  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;

  background: rgba(8, 36, 42, 0.28);
  backdrop-filter: blur(10px);

  color: #ffffff;

  cursor: pointer;

  transform: translateY(-50%);

  transition:
    background 0.3s ease,
    border-color 0.3s ease,
    transform 0.3s ease;
}

.heroArrow:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.65);
}

.heroArrowLeft {
  left: 30px;
}

.heroArrowRight {
  right: 30px;
}

.heroArrowLeft:hover {
  transform: translate(-3px, -50%);
}

.heroArrowRight:hover {
  transform: translate(3px, -50%);
}

/* =========================================================
   BOTTOM CONTROLS
========================================================= */

.heroBottomControls {
  position: absolute;
  left: 50%;
  bottom: 38px;

  width: min(1180px, calc(100% - 80px));

  display: flex;
  align-items: center;
  justify-content: space-between;

  transform: translateX(-50%);

  z-index: 6;
}

/* =========================================================
   DOTS
========================================================= */

.heroDots {
  display: flex;
  align-items: center;
  gap: 8px;
}

.heroDots button {
  width: 30px;
  height: 3px;

  padding: 0;
  border: 0;

  border-radius: 10px;

  background: rgba(255, 255, 255, 0.35);

  cursor: pointer;

  transition:
    width 0.35s ease,
    background 0.35s ease;
}

.heroDots button.active {
  width: 58px;
  background: #ffffff;
}

/* =========================================================
   SLIDE NUMBER
========================================================= */

.heroSlideNumber {
  display: flex;
  align-items: center;
  gap: 12px;

  color: rgba(255, 255, 255, 0.72);

  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.heroSlideNumber span:first-child {
  color: #ffffff;
}

.heroSlideNumber i {
  display: block;

  width: 35px;
  height: 1px;

  background: rgba(255, 255, 255, 0.35);
}

/* =========================================================
   SCROLL INDICATOR
========================================================= */

.heroScrollIndicator {
  position: absolute;
  right: 42px;
  bottom: 135px;

  z-index: 4;

  display: flex;
  align-items: center;
  gap: 13px;

  color: rgba(255, 255, 255, 0.55);

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.2em;

  writing-mode: vertical-rl;
}

.heroScrollLine {
  width: 1px;
  height: 55px;

  background: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.65),
    transparent
  );

  animation: scrollLine 2s ease-in-out infinite;
}

@keyframes scrollLine {
  0%,
  100% {
    transform: scaleY(0.55);
    transform-origin: top;
    opacity: 0.45;
  }

  50% {
    transform: scaleY(1);
    transform-origin: top;
    opacity: 1;
  }
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1100px) {

  .novaHero {
    min-height: 700px;
    height: 86vh;
  }

  .heroContent {
    width: min(100% - 110px, 900px);
  }

  .heroTitle {
    font-size: clamp(55px, 8vw, 82px);
  }

  .heroArrowLeft {
    left: 18px;
  }

  .heroArrowRight {
    right: 18px;
  }

  .heroScrollIndicator {
    right: 22px;
  }
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 768px) {

  .novaHero {
