  .heroTitle {
    max-width: 100%;

    font-size: clamp(48px, 14vw, 68px);
    line-height: 0.98;
    letter-spacing: -0.045em;
  }

  .heroDescription {
    max-width: 100%;

    margin-top: 22px;

    font-size: 14px;
    line-height: 1.7;
  }

  .heroActions {
    align-items: stretch;
    flex-direction: column;

    width: 100%;
    max-width: 340px;

    margin-top: 28px;
  }

  .heroPrimaryBtn,
  .heroSecondaryBtn {
