    width: calc(100% - 42px);
  }

  .heroDots button {
    width: 20px;
  }

  .heroDots button.active {
    width: 42px;
  }

  .heroSlideNumber {
    font-size: 9px;
    gap: 8px;
  }

  .heroSlideNumber i {
    width: 22px;
  }

  .heroScrollIndicator {
    display: none;
  }

