    width: 260px;
    height: 260px;
  }

  .heroSoftGlowTwo {
    width: 220px;
    height: 220px;
  }
}

/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 480px) {

  .novaHero {
    min-height: 690px;
  }

  .heroContent {
    width: calc(100% - 32px);
    padding-top: 115px;
    padding-bottom: 140px;
  }

  .heroTitle {
    font-size: clamp(43px, 14vw, 58px);
  }

  .heroDescription {
    font-size: 13px;
  }

  .heroTrust {
    gap: 10px;
  }

  .heroTrustItem strong {
    font-size: 19px;
  }

  .heroTrustItem span {
    max-width: 72px;
    line-height: 1.4;
  }

  .heroArrow {
    bottom: 73px;

    width: 39px;
    height: 39px;
  }

  .heroArrowLeft {
    left: 16px;
  }

  .heroArrowRight {
    right: 16px;
  }

  .heroBottomControls {
    width: calc(100% - 32px);
    bottom: 27px;
  }

  .heroDots {
    gap: 6px;
  }

  .heroDots button {
    width: 18px;
  }

  .heroDots button.active {
    width: 36px;
  }
}

/* =========================================================
   ACCESSIBILITY / REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .heroSlide,
  .heroSlide img,
  .heroTitleLine,
  .heroDescription,
  .heroArrow,
  .heroPrimaryBtn,
  .heroSecondaryBtn,
  .heroDots button {
    animation: none !important;
    transition: none !important;
  }

  .heroScrollLine {
    animation: none !important;
  }
}
/* =========================================================
   NOVADENT — HOME DOCTOR CARDS
========================================================= */

.novaDoctorMiniCard {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(22, 67, 76, 0.08);
  background: #ffffff;
  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease,
    border-color 0.45s ease;
}

.novaDoctorMiniCard:hover {
  transform: translateY(-10px);
  border-color: rgba(78, 145, 138, 0.25);
  box-shadow: 0 24px 55px rgba(22, 67, 76, 0.14);
}

/* Image */

.novaDoctorMiniImage {
  position: relative;
  overflow: hidden;
  aspect-ratio: 4 / 4.6;
}

.novaDoctorMiniImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.novaDoctorMiniCard:hover .novaDoctorMiniImage img {
  transform: scale(1.07);
}

/* Image overlay */

.novaDoctorMiniOverlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 18px;
  background:
    linear-gradient(
      to bottom,
      rgba(8, 35, 42, 0.48),
      transparent 35%,
      transparent 60%,
      rgba(8, 35, 42, 0.25)
    );
}

/* Badge */

.novaDoctorMiniCard .doctorBadge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 13px;
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.94);
  color: #16434c;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.12);
}

/* Sparkle */

.novaDoctorMiniSparkle {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.88);
  color: #4b918a;
  backdrop-filter: blur(10px);
  transition: transform 0.4s ease;
}

.novaDoctorMiniCard:hover .novaDoctorMiniSparkle {
  transform: rotate(15deg) scale(1.08);
}

/* Body */

.novaDoctorMiniBody {
  padding: 25px 24px 24px;
}

/* Top row */

.novaDoctorMiniTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.novaDoctorMiniBody .doctorLabel {
  color: #4b918a;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.novaDoctorMiniYears {
  color: #7b8d91;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

/* Name */

.novaDoctorMiniBody h3 {
  margin: 0;
  color: #123d46;
  font-size: clamp(21px, 2vw, 27px);
  line-height: 1.15;
  font-weight: 800;
  letter-spacing: -0.035em;
}

/* Specialty */

.novaDoctorMiniBody .doctorSpecialty {
  margin: 8px 0 0;
  color: #557177;
  font-size: 14px;
  line-height: 1.6;
}

/* Experience */

.novaDoctorMiniBody .doctorExperience {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 18px 0 14px;
  padding-top: 15px;
  border-top: 1px solid #e5eeee;
}

.novaDoctorMiniBody .doctorExperience span {
  color: #4b918a;
  font-size: 24px;
  font-weight: 800;
  line-height: 1;
}

.novaDoctorMiniBody .doctorExperience small {
  color: #7b8d91;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
}

/* Description */

.novaDoctorMiniBody .doctorText {
  margin: 0;
  color: #718488;
  font-size: 13px;
  line-height: 1.75;
}

/* Link */

.novaDoctorMiniLink {
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid #e5eeee;
  color: #16434c;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition: color 0.3s ease;
}

.novaDoctorMiniLink > span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.novaDoctorMiniLink > svg {
  transition: transform 0.35s ease;
}

.novaDoctorMiniLink:hover {
  color: #4b918a;
}

.novaDoctorMiniLink:hover > svg {
  transform: translate(3px, -3px);
}

/* Responsive */

@media (max-width: 768px) {
  .novaDoctorMiniBody {
    padding: 22px 20px 21px;
  }

  .novaDoctorMiniOverlay {
    padding: 14px;
  }
}

@media (max-width: 480px) {
  .novaDoctorMiniImage {
    aspect-ratio: 1 / 1.05;
  }

  .novaDoctorMiniBody h3 {
    font-size: 22px;
  }

  .novaDoctorMiniBody .doctorText {
    font-size: 12.5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .novaDoctorMiniCard,
  .novaDoctorMiniImage img,
  .novaDoctorMiniSparkle,
  .novaDoctorMiniLink,
  .novaDoctorMiniLink > svg {
    transition: none;
  }
}
