/* =========================================================
   NOVADENT PREMIUM WEBSITE — GLOBAL INTERACTION LAYER
   ========================================================= */

/* ---------- Smooth Website ---------- */

html {
  scroll-behavior: smooth;
}

body {
  overflow-x: hidden;
}


/* ---------- All Links ---------- */

a {
  transition:
    color 0.3s ease,
    background-color 0.3s ease,
    transform 0.3s ease,
    box-shadow 0.3s ease,
    border-color 0.3s ease;
}


/* ---------- Section Reveal ---------- */

.section,
.homeIntro,
.homeStats,
.treatments,
.doctors,
.testimonials,
.gallery,
.contact,
.about,
.pageSection {
  animation: novaSectionReveal 0.8s ease both;
}

@keyframes novaSectionReveal {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------- Images ---------- */

img {
  transition:
    transform 0.6s ease,
    filter 0.4s ease;
}

img:hover {
  transform: scale(1.035);
}


/* ---------- Image Containers ---------- */

.homeIntro img,
.doctorCard img,
.serviceCard img,
.gallery img,
.treatmentCard img {
  will-change: transform;
}


/* ---------- Premium Cards ---------- */

.doctorCard,
.serviceCard,
.treatmentCard,
.reviewCard,
.testimonialCard,
.galleryCard,
.infoCard {
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.doctorCard:hover,
.serviceCard:hover,
.treatmentCard:hover,
.reviewCard:hover,
.testimonialCard:hover,
.galleryCard:hover,
.infoCard:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.12);
}


/* ---------- Card Image Zoom ---------- */

.doctorCard:hover img,
.serviceCard:hover img,
.treatmentCard:hover img,
.galleryCard:hover img {
  transform: scale(1.07);
}


/* ---------- Buttons ---------- */

button,
.novaFooterCTAButton,
.homeIntro a,
.homeSmileBanner a {
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background-color 0.3s ease,
    color 0.3s ease;
}

button:hover,
.novaFooterCTAButton:hover,
.homeIntro a:hover,
.homeSmileBanner a:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.16);
}


/* ---------- Button Icon Animation ---------- */

a svg,
button svg {
  transition: transform 0.3s ease;
}

a:hover svg,
button:hover svg {
  transform: translateX(4px);
}


/* ---------- Premium Hero ---------- */

.hero,
.pageHero,
.aboutHero,
.treatmentsHero,
.doctorsHero,
.galleryHero,
.contactHero {
  position: relative;
  overflow: hidden;
}

.hero::after,
.pageHero::after,
.aboutHero::after,
.treatmentsHero::after,
.doctorsHero::after,
.galleryHero::after,
.contactHero::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;

  background:
    radial-gradient(
      circle at 85% 20%,
      rgba(255, 255, 255, 0.12),
      transparent 30%
    );
}


/* ---------- Hero Text Animation ---------- */

.hero h1,
.pageHero h1,
.aboutHero h1,
.treatmentsHero h1,
.doctorsHero h1,
.galleryHero h1,
.contactHero h1 {
  animation: novaHeroTitle 0.9s ease both;
}

.hero p,
.pageHero p,
.aboutHero p,
.treatmentsHero p,
.doctorsHero p,
.galleryHero p,
.contactHero p {
  animation: novaHeroText 1s 0.15s ease both;
}

@keyframes novaHeroTitle {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes novaHeroText {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------- Section Headings ---------- */

section h2 {
  transition:
    transform 0.3s ease,
    letter-spacing 0.3s ease;
}

section h2:hover {
  transform: translateY(-2px);
}


/* ---------- Stats ---------- */

.homeStats {
  position: relative;
  overflow: hidden;
}

.homeStats > * {
  transition:
    transform 0.3s ease;
}

.homeStats > *:hover {
  transform: translateY(-5px);
}


/* ---------- Doctor Cards ---------- */

.doctorCard {
  overflow: hidden;
}

.doctorCard:hover {
  transform: translateY(-10px);
}


/* ---------- Treatment Cards ---------- */

.serviceCard,
.treatmentCard {
  position: relative;
  overflow: hidden;
}

.serviceCard::before,
.treatmentCard::before {
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  top: -60px;
  right: -60px;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.10);

  transition:
    transform 0.5s ease;
}

.serviceCard:hover::before,
.treatmentCard:hover::before {
  transform: scale(2.5);
}


/* ---------- Gallery ---------- */

.gallery img {
  border-radius: inherit;
}

.gallery a,
.galleryCard {
  overflow: hidden;
}

.gallery a:hover img,
.galleryCard:hover img {
  transform: scale(1.08);
  filter: brightness(1.05);
}


/* ---------- Reviews ---------- */

.reviewCard,
.testimonialCard {
  position: relative;
}

.reviewCard:hover,
.testimonialCard:hover {
  transform: translateY(-7px);
}


/* ---------- Smile Banner ---------- */

.homeSmileBanner {
  position: relative;
  overflow: hidden;
}

.homeSmileBanner::before {
  content: "";
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      120deg,
      transparent,
      rgba(255,255,255,0.10),
      transparent
    );

  transform: translateX(-100%);
  transition: transform 0.8s ease;
}

.homeSmileBanner:hover::before {
  transform: translateX(100%);
}


/* ---------- Footer Links ---------- */

.novaFooter a {
  position: relative;
}

.novaFooter a:not(.novaFooterCTAButton)::after {
  content: "";

  position: absolute;
  left: 0;
  bottom: -4px;

  width: 0;
  height: 1px;

  background: currentColor;

  transition: width 0.3s ease;
}

.novaFooter a:hover::after {
  width: 100%;
}


/* ---------- CTA ---------- */

.novaFooterCTA {
  position: relative;
  overflow: hidden;
}

.novaFooterCTACard {
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.novaFooterCTACard:hover {
  transform: translateY(-5px);
  box-shadow:
    0 30px 70px rgba(0, 0, 0, 0.25);
}


/* ---------- Contact Icons ---------- */

.contact svg,
.infoCard svg {
  transition:
    transform 0.3s ease,
    opacity 0.3s ease;
}

.contact a:hover svg,
.infoCard:hover svg {
  transform: scale(1.12) rotate(-5deg);
}


/* ---------- Form Fields ---------- */

input,
textarea,
select {
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  transform: translateY(-1px);
  box-shadow:
    0 0 0 3px rgba(40, 130, 150, 0.10);
}


/* ---------- Navbar ---------- */

nav a {
  transition:
    color 0.25s ease,
    transform 0.25s ease;
}

nav a:hover {
  transform: translateY(-2px);
}


/* ---------- Accessibility ---------- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}


/* =========================================================
   MOBILE RESPONSIVE
   ========================================================= */

@media (max-width: 768px) {

  .doctorCard:hover,
  .serviceCard:hover,
  .treatmentCard:hover,
  .reviewCard:hover,
  .testimonialCard:hover,
  .galleryCard:hover,
  .infoCard:hover {
    transform: translateY(-4px);
  }

  img:hover {
