/* =========================
   CTA CARD
   ========================= */

.ndtCTACard {
  position: relative;
  overflow: hidden;

  min-height: 430px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  padding: 65px 50px;

  border-radius: 28px;

  background:
    linear-gradient(
      90deg,
      rgba(10, 48, 59, 0.88),
      rgba(24, 78, 90, 0.72)
    ),
    url("https://images.unsplash.com/photo-1609840114035-3c981b782dfe?auto=format&fit=crop&w=2000&q=90")
      center / cover no-repeat;

  box-shadow:
    0 30px 70px rgba(22, 72, 84, 0.22);

  text-align: center;

  isolation: isolate;

  animation: ndtCTAReveal 0.9s
    cubic-bezier(0.22, 1, 0.36, 1) both;
}


/* =========================
   BACKGROUND GLOW
   ========================= */

.ndtCTACard::before {
  content: "";

  position: absolute;

  width: 430px;
  height: 430px;

  right: -180px;
  top: -220px;

  border-radius: 50%;

  background: rgba(130, 209, 218, 0.16);

  pointer-events: none;
  z-index: -1;

  animation: ndtCTAGlow 7s ease-in-out infinite;
}

.ndtCTACard::after {
  content: "";

  position: absolute;

  width: 300px;
  height: 300px;

  left: -150px;
  bottom: -170px;

  border-radius: 50%;

  background: rgba(255, 255, 255, 0.08);

  pointer-events: none;
  z-index: -1;

  animation: ndtCTAGlowReverse 8s ease-in-out infinite;
}

@keyframes ndtCTAGlow {
  0%,
  100% {
    transform: translate(0, 0);
  }

  50% {
    transform: translate(-25px, 25px);
  }
}

@keyframes ndtCTAGlowReverse {
  0%,
  100% {
    transform: translate(0, 0);
  }

  50% {
    transform: translate(25px, -20px);
  }
}


