/* =========================================================
   GALLERY CARD
========================================================= */

.nova-gallery-pro-card {
  position: relative;
  display: block;
  width: 100%;
  height: 300px;
  min-height: 300px;
  padding: 0;
  margin: 0;
  border: 0;
  border-radius: 5px;
  overflow: hidden;
  background: #dce8e7;
  cursor: pointer;

  opacity: 0;
  transform: translateY(25px) scale(0.98);

  animation: novaGalleryCardIn 0.75s
    cubic-bezier(0.22, 1, 0.36, 1)
    forwards;

  transition:
    transform 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s ease;
}

.nova-gallery-pro-card:nth-child(1) {
  animation-delay: 0.05s;
}

.nova-gallery-pro-card:nth-child(2) {
  animation-delay: 0.10s;
}

.nova-gallery-pro-card:nth-child(3) {
  animation-delay: 0.15s;
}

.nova-gallery-pro-card:nth-child(4) {
  animation-delay: 0.20s;
}

.nova-gallery-pro-card:nth-child(5) {
  animation-delay: 0.25s;
}

.nova-gallery-pro-card:nth-child(6) {
  animation-delay: 0.30s;
}

.nova-gallery-pro-card:nth-child(7) {
  animation-delay: 0.35s;
}

.nova-gallery-pro-card:nth-child(8) {
  animation-delay: 0.40s;
}

@keyframes novaGalleryCardIn {
  0% {
    opacity: 0;
    transform: translateY(25px) scale(0.97);
  }

  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}


/* =========================================================
   IMAGE
========================================================= */

.nova-gallery-pro-card img {
  width: 100%;
  height: 100%;
  display: block;

  object-fit: cover;
  object-position: center;

  transform: scale(1.02);

  transition:
    transform 0.9s cubic-bezier(0.2, 0.7, 0.2, 1),
    filter 0.55s ease;
}


/* =========================================================
   HOVER
========================================================= */

.nova-gallery-pro-card:hover {
  transform: translateY(-7px);
  box-shadow:
    0 20px 45px rgba(23, 63, 69, 0.18);
}

.nova-gallery-pro-card:hover img {
  transform: scale(1.12);
  filter: brightness(0.62) saturate(0.9);
}


/* =========================================================
   OVERLAY
========================================================= */

.nova-gallery-pro-card::after {
  content: "";
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      180deg,
      rgba(10, 42, 48, 0.02) 20%,
      rgba(10, 42, 48, 0.78) 100%
    );

  opacity: 0;

  transition: opacity 0.45s ease;
  pointer-events: none;
}

.nova-gallery-pro-card:hover::after {
  opacity: 1;
}

.nova-gallery-pro-card-overlay {
  position: absolute;
  inset: auto 0 0 0;
  z-index: 2;

  padding: 25px 22px;

  opacity: 0;
  transform: translateY(15px);

  transition:
    opacity 0.45s ease,
    transform 0.45s ease;
}

.nova-gallery-pro-card:hover .nova-gallery-pro-card-overlay {
  opacity: 1;
  transform: translateY(0);
}

.nova-gallery-pro-card-overlay small {
