  opacity: 0;

  transform: translateY(20px);

  transition:
    opacity 0.45s ease,
    transform 0.45s ease;
}

.nova-gallery-pro-card:hover
.nova-gallery-pro-card-overlay {
  opacity: 1;

  transform: translateY(0);
}


/* TEXT */

.nova-gallery-pro-card-overlay div {
  transform: translateY(15px);
  opacity: 0;

  transition:
    transform 0.45s ease,
    opacity 0.45s ease;
}

.nova-gallery-pro-card:hover
.nova-gallery-pro-card-overlay div {
  transform: translateY(0);
  opacity: 1;
}


/* NUMBER */

.nova-gallery-pro-card-number {
