========================================================= */

.nova-gallery-grid-pro {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}


/* IMAGE CARD */

.nova-gallery-item-pro {
  position: relative;
  width: 100%;
  height: 290px;

  padding: 0;

  border: 1px solid rgba(52, 121, 130, 0.25);
  border-radius: 8px;

  overflow: hidden;

  background: #ffffff;
  cursor: pointer;

  opacity: 0;

  animation: galleryImageReveal 0.8s
    cubic-bezier(0.22, 1, 0.36, 1)
    forwards;

  animation-delay: var(--gallery-delay);

  transition:
    transform 0.4s ease,
    border-color 0.4s ease,
    box-shadow 0.4s ease;
}


/* LOAD ANIMATION */

@keyframes galleryImageReveal {
  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* IMAGE */

.nova-gallery-item-pro img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transform: scale(1);

  transition:
    transform 0.8s cubic-bezier(0.2, 0.7, 0.2, 1),
    filter 0.5s ease;
}


/* HOVER CARD */

.nova-gallery-item-pro:hover {
  transform: translateY(-6px);

  border-color: #347982;

  box-shadow:
    0 15px 35px rgba(23, 63, 69, 0.15);
}


/* IMAGE ZOOM */

.nova-gallery-item-pro:hover img {
  transform: scale(1.08);

  filter: brightness(0.75);
}


/* BORDER GLOW */

.nova-gallery-item-pro::before {
  content: "";

  position: absolute;
  inset: 0;

  z-index: 3;

  border: 1px solid transparent;
  border-radius: 8px;

  pointer-events: none;

  transition:
    border-color 0.4s ease,
    box-shadow 0.4s ease;
}

.nova-gallery-item-pro:hover::before {
  border-color: rgba(168, 220, 224, 0.7);

  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.18);
}


/* OVERLAY */

.nova-gallery-item-shade {
  position: absolute;
  inset: 0;

  z-index: 1;

  background:
    linear-gradient(
      180deg,
      transparent 40%,
      rgba(10, 42, 48, 0.72) 100%
    );

  opacity: 0;

  transition: opacity 0.4s ease;
}

.nova-gallery-item-pro:hover
.nova-gallery-item-shade {
  opacity: 1;
}


/* TEXT ANIMATION */

.nova-gallery-item-content {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;

  z-index: 2;

  padding: 20px;

  text-align: left;

  opacity: 0;

  transform: translateY(15px);

  transition:
    opacity 0.4s ease,
    transform 0.4s ease;
}

.nova-gallery-item-pro:hover
.nova-gallery-item-content {
  opacity: 1;
  transform: translateY(0);
}


/* NUMBER */

