/* =========================================================
   NOVADENT — PREMIUM SMILE BANNER
   Existing Home.jsx structure
   ========================================================= */

.homeSmileBanner {
  position: relative;

  width: min(1060px, calc(100% - 40px));
  min-height: 430px;

  margin: 65px auto;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;
  isolation: isolate;

  border: 1px solid rgba(126, 218, 215, 0.30);
  border-radius: 30px;

  background: #104a54;

  box-shadow:
    0 30px 70px rgba(7, 43, 55, 0.20),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);

  transition:
    transform 0.45s ease,
    box-shadow 0.45s ease;
}


/* =========================================================
   BACKGROUND IMAGE
   ========================================================= */

.homeSmileBanner .smileBannerImage {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  object-fit: cover;
  object-position: center;

  z-index: -3;

  transform: scale(1.03);

  filter:
    saturate(0.82)
    contrast(1.03);

  animation:
    novaSmileImageZoom
    12s
    ease-in-out
    infinite
    alternate;

  transition:
    transform 1s cubic-bezier(.2, .7, .2, 1),
    filter 0.7s ease;
}


/* =========================================================
   PREMIUM IMAGE OVERLAY
   ========================================================= */

.homeSmileBanner .homeSmileOverlay {
  position: absolute;
  inset: 0;

  z-index: -2;

  background:
    linear-gradient(
      90deg,
      rgba(5, 30, 42, 0.95) 0%,
      rgba(7, 48, 59, 0.88) 38%,
      rgba(8, 55, 64, 0.68) 68%,
      rgba(8, 55, 64, 0.45) 100%
    ),
    linear-gradient(
      180deg,
      rgba(5, 28, 40, 0.10) 0%,
      rgba(5, 28, 40, 0.55) 100%
    );

  pointer-events: none;
}


