/* =========================================================
   NOVADENT — PREMIUM ANIMATED STAT DIVIDERS
   ========================================================= */

/* Remove old static divider */
.homeStats .interactiveStat {
  position: relative;
  border-right: none;
  overflow: hidden;
}


/* ---------------------------------------------------------
   MAIN VERTICAL LINE
--------------------------------------------------------- */

.homeStats .interactiveStat:not(:last-child)::after {
  content: "";

  position: absolute;

  top: 0;
  right: 0;

  width: 1px;
  height: 100%;

  background: linear-gradient(
    to bottom,
    transparent 0%,
    rgba(255, 255, 255, 0.08) 15%,
    rgba(255, 255, 255, 0.18) 50%,
    rgba(255, 255, 255, 0.08) 85%,
    transparent 100%
  );

  transform-origin: top;
  transform: scaleY(0);

  animation: novaDividerReveal 1.2s cubic-bezier(.2, .7, .2, 1) forwards;

  pointer-events: none;
}


/* ---------------------------------------------------------
   MOVING GLOW ON THE LINE
--------------------------------------------------------- */

.homeStats .interactiveStat:not(:last-child)::before {
  content: "";

  position: absolute;

  top: -30px;
  right: -1px;

  width: 3px;
  height: 65px;

  border-radius: 999px;

  background: linear-gradient(
    to bottom,
    transparent,
    #72d8d3,
    transparent
  );

  filter: blur(1px);

  opacity: 0;

  animation:
    novaDividerGlow 3.5s ease-in-out infinite;

  pointer-events: none;
}


/* ---------------------------------------------------------
   DIFFERENT DELAY FOR EACH LINE
--------------------------------------------------------- */

.homeStats .interactiveStat:nth-child(2)::after {
  animation-delay: 0.15s;
}

.homeStats .interactiveStat:nth-child(3)::after {
  animation-delay: 0.30s;
}

.homeStats .interactiveStat:nth-child(4)::after {
  animation-delay: 0.45s;
}


.homeStats .interactiveStat:nth-child(2)::before {
  animation-delay: 0.8s;
}

.homeStats .interactiveStat:nth-child(3)::before {
  animation-delay: 1.5s;
}

.homeStats .interactiveStat:nth-child(4)::before {
  animation-delay: 2.2s;
}


/* ---------------------------------------------------------
   LINE REVEAL
--------------------------------------------------------- */

@keyframes novaDividerReveal {

  0% {
    transform: scaleY(0);
    opacity: 0;
  }

  60% {
    opacity: 1;
  }

  100% {
    transform: scaleY(1);
    opacity: 1;
  }
}


/* ---------------------------------------------------------
   GLOW TRAVELS DOWN THE LINE
--------------------------------------------------------- */

@keyframes novaDividerGlow {

  0% {
    top: -70px;
    opacity: 0;
  }

  15% {
    opacity: 0.9;
  }

  50% {
    opacity: 0.65;
  }

  85% {
    opacity: 0.9;
  }

  100% {
    top: calc(100% + 20px);
    opacity: 0;
  }
}


/* ---------------------------------------------------------
   HOVER — LINE BECOMES MORE VISIBLE
--------------------------------------------------------- */

.homeStats .interactiveStat:hover::after {
  background: linear-gradient(
    to bottom,
    transparent,
    rgba(114, 216, 211, 0.55),
    transparent
  );

  box-shadow:
    0 0 12px rgba(114, 216, 211, 0.22);
}


/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 768px) {

  .homeStats .homeStatsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  /* On mobile make horizontal dividers instead */
  .homeStats .interactiveStat:not(:last-child)::after {
    width: 100%;
    height: 1px;

    top: auto;
    right: 0;
    bottom: 0;

    transform-origin: left;
    transform: scaleX(0);

    animation:
      novaHorizontalDividerReveal
      1.1s
      cubic-bezier(.2, .7, .2, 1)
      forwards;
  }

  .homeStats .interactiveStat:not(:last-child)::before {
    width: 65px;
    height: 3px;

    top: auto;
    right: auto;
    left: -70px;
    bottom: -1px;

    animation:
      novaHorizontalDividerGlow
      3.5s
      ease-in-out
      infinite;
  }

}


/* ---------------------------------------------------------
   MOBILE LINE ANIMATION
--------------------------------------------------------- */

@keyframes novaHorizontalDividerReveal {

  0% {
    transform: scaleX(0);
    opacity: 0;
  }

  100% {
    transform: scaleX(1);
    opacity: 1;
  }
}


@keyframes novaHorizontalDividerGlow {

