========================================================= */

.novaHeroVideo {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center center;

  z-index: 0;

  background: #10191a;

  opacity: 0;

  transition:
    opacity 1.2s ease,
    transform 8s ease;
}

.novaHeroVideoReady {
  opacity: 1;
  transform: scale(1.015);
}

/* =========================================================
   FALLBACK
========================================================= */

.novaHeroFallback {
  position: absolute;
  inset: 0;

  z-index: 0;

  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(85, 157, 151, 0.38),
      transparent 45%
    ),
    linear-gradient(
      135deg,
      #142423,
      #07100f
    );
}

.novaHeroFallbackGlow {
  position: absolute;
  width: 420px;
  height: 420px;

  left: 50%;
  top: 50%;

  transform: translate(-50%, -50%);

  border-radius: 50%;

  background: rgba(125, 205, 196, 0.12);

  filter: blur(80px);
}

/* =========================================================
