  max-width: 1000px;

  margin-top: 25px;

  text-align: center;

  display: flex;

  flex-direction: column;

  align-items: center;
}

/* =========================================================
   EYEBROW
========================================================= */

.novaHeroEyebrow {
  display: flex;

  align-items: center;

  justify-content: center;

  gap: 14px;

  margin-bottom: 25px;

  color: rgba(255,255,255,0.88);

  font-size: 11px;

  font-weight: 700;

  letter-spacing: 0.32em;

  text-transform: uppercase;

  animation:
    novaHeroFadeUp
    0.9s
    0.15s
    both;
}

.novaHeroLine {
  display: block;

  width: 35px;

  height: 1px;

  background: rgba(255,255,255,0.65);
}

/* =========================================================
   TITLE
========================================================= */

.novaHeroTitle {
  margin: 0;

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size:
    clamp(58px, 8.2vw, 128px);

  line-height: 0.91;

  font-weight: 400;

  letter-spacing: -0.045em;

  text-align: center;

  overflow: hidden;
}

.novaHeroTitleLine {
  display: block;

  transform: translateY(110%);

  opacity: 0;

  animation:
    novaHeroLetterLine
    1s
    cubic-bezier(0.16, 1, 0.3, 1)
    forwards;
}

.novaHeroTitleLine:nth-child(1) {
  animation-delay: 0.25s;
}

.novaHeroTitleLine:nth-child(2) {
  animation-delay: 0.4s;
}

.novaHeroTitleLine:nth-child(3) {
  animation-delay: 0.55s;
}

.novaHeroTitleAccent {
  font-style: italic;

  color: #a8d9d2;
}

/* =========================================================
   DESCRIPTION
========================================================= */

.novaHeroDescription {
  max-width: 580px;

  margin:
    32px
    auto
    0;

  color: rgba(255,255,255,0.82);

  font-size:
    clamp(14px, 1.2vw, 18px);

  line-height: 1.75;

  font-weight: 400;
}

/* =========================================================
   ACTIONS
========================================================= */

.novaHeroActions {
  display: flex;

  align-items: center;

  justify-content: center;

  gap: 18px;

  margin-top: 34px;

  flex-wrap: wrap;
}

.novaHeroPrimary,
.novaHeroSecondary {
  min-height: 54px;

  padding:
    0
    25px;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 10px;

  text-decoration: none;

  font-size: 13px;

  font-weight: 700;

  letter-spacing: 0.02em;

  transition:
    transform 0.35s ease,
    background 0.35s ease,
    border-color 0.35s ease,
    color 0.35s ease;
}

.novaHeroPrimary {
  color: #10201f;

  background: #b9e1dc;

  border: 1px solid #b9e1dc;
}

.novaHeroPrimary:hover {
  transform: translateY(-4px);

  background: #ffffff;

  border-color: #ffffff;
}

.novaHeroSecondary {
  color: #ffffff;

  border: 1px solid rgba(255,255,255,0.55);

  background: rgba(255,255,255,0.04);

  backdrop-filter: blur(8px);
}

.novaHeroSecondary:hover {
  transform: translateY(-4px);

  background: rgba(255,255,255,0.12);

  border-color: #ffffff;
}

/* =========================================================
   GENERAL REVEAL
========================================================= */

.novaHeroReveal {
  opacity: 0;

  transform: translateY(35px);

  animation:
    novaHeroFadeUp
    0.9s
    0.75s
    cubic-bezier(0.16, 1, 0.3, 1)
    forwards;
}

.novaHeroDescription {
  animation-delay: 0.85s;
}

.novaHeroActions {
  animation-delay: 1.05s;
}

/* =========================================================
   SIDE TEXT
========================================================= */

.novaHeroSideText {
  position: absolute;

  z-index: 6;

  right: 24px;

  top: 50%;

  transform:
    translateY(-50%)
    rotate(90deg);

  transform-origin: center;

  color: rgba(255,255,255,0.55);

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 0.35em;

  white-space: nowrap;
}

/* =========================================================
   BOTTOM
========================================================= */

.novaHeroBottom {
  position: absolute;

  z-index: 7;

  left: 0;
  right: 0;
  bottom: 0;

  padding:
    25px
    clamp(24px, 7vw, 110px);

  display: flex;

  align-items: center;

  justify-content: space-between;

  color: rgba(255,255,255,0.72);

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 0.2em;

  text-transform: uppercase;
}

.novaHeroBottomLeft {
  display: flex;

  align-items: center;

  gap: 13px;
}

.novaHeroDot {
  width: 4px;
  height: 4px;

  border-radius: 50%;

  background: #b9e1dc;
}

/* =========================================================
   SCROLL
========================================================= */

.novaHeroScroll {
  display: flex;

  align-items: center;

  gap: 9px;
}

.novaHeroScrollArrow {
  animation:
    novaHeroScrollBounce
    1.7s
    ease-in-out
    infinite;
}

/* =========================================================
   ANIMATIONS
========================================================= */

@keyframes novaHeroFadeUp {
  from {
    opacity: 0;

    transform: translateY(35px);
  }

  to {
    opacity: 1;

    transform: translateY(0);
  }
}

@keyframes novaHeroLetterLine {
  from {
    opacity: 0;

    transform: translateY(110%);
  }

  to {
    opacity: 1;

    transform: translateY(0);
  }
}

@keyframes novaHeroScrollBounce {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(5px);
  }
}

/* =========================================================
   TABLET
========================================================= */

@media (max-width: 900px) {

  .novaHero {
    min-height: 92vh;
    height: 92vh;
  }

  .novaHeroContainer {
    padding:
      0
      35px;
  }

  .novaHeroTitle {
    font-size:
      clamp(54px, 10vw, 88px);
  }

  .novaHeroSideText {
    display: none;
  }

  .novaHeroBottom {
    padding:
      20px
      35px;
  }
