/* =========================================================
   NOVADENT — FINAL PREMIUM STORYTELLING HOME
   NOVADENT original palette retained: white + blue + teal
========================================================= */
:root{
  --nova-white:#ffffff;
  --nova-paper:#ffffff;
  --nova-blue:#0b2545;
  --nova-blue-2:#123d68;
  --nova-teal:#1f8a8a;
  --nova-teal-2:#146b6b;
  --nova-accent:#55b8b0;
  --nova-soft:#f5fafb;
  --nova-soft-2:#eef6f6;
  --nova-text:#183b56;
  --nova-muted:#64748b;
  --nova-line:#dce8eb;
  --nova-shadow:0 24px 65px rgba(11,37,69,.11);
  --nova-shadow-soft:0 12px 35px rgba(11,37,69,.07);--nova-forest:var(--nova-blue);--nova-forest-2:var(--nova-blue-2);--nova-sage-light:var(--nova-soft-2);--nova-gold:var(--nova-teal);--nova-gold-light:var(--nova-accent);--nova-ink:var(--nova-text);
}

html{scroll-padding-top:90px}
body{background:#fff!important;color:var(--nova-text)}
.homePage{background:#fff!important;overflow:clip}

/* ---------- shared story system ---------- */
.storySection{position:relative;padding:clamp(88px,9vw,132px) 0;background:#fff;overflow:hidden}
.storySection:nth-of-type(even){background:#fff}
.storyContainer{width:min(1240px,calc(100% - 64px));margin:0 auto;position:relative}
.storySplit{display:grid;grid-template-columns:minmax(0,1.03fr) minmax(0,.97fr);gap:clamp(48px,7vw,92px);align-items:center}

.storyMedia,.storyContent,.founderVisual,.founderContent,.clinicLargeImage,.clinicExperienceCopy,.sectionIntro,.principleCard,.editorialService,.editorialDoctor,.reviewIntro,.reviewCard{opacity:0;transform:translateY(42px);transition:opacity .85s cubic-bezier(.2,.75,.2,1),transform .85s cubic-bezier(.2,.75,.2,1);transition-delay:var(--delay,0ms)}
.reveal-left{transform:translateX(-48px)}
.reveal-right{transform:translateX(48px)}
[data-reveal].is-visible,.is-visible .storyMedia,.is-visible .storyContent,.is-visible .founderVisual,.is-visible .founderContent,.is-visible .clinicLargeImage,.is-visible .clinicExperienceCopy,.is-visible .sectionIntro,.is-visible .principleCard,.is-visible .editorialService,.is-visible .editorialDoctor,.is-visible .reviewIntro,.is-visible .reviewCard{opacity:1;transform:none}

.storyKicker{display:inline-flex;align-items:center;gap:9px;color:var(--nova-teal);font-size:10px;font-weight:900;letter-spacing:2.5px;line-height:1.2}
.storyKicker::before{content:"";width:30px;height:1px;background:currentColor}
.storyIndex{display:block;margin-top:9px;color:#91a0ae;font-size:9px;font-weight:800;letter-spacing:2px}
.storyContent h2,.sectionIntro h2,.founderContent h2,.reviewIntro h2,.appointmentStory h2{margin:18px 0 22px;color:var(--nova-blue);font-family:"Playfair Display",Georgia,serif;font-size:clamp(40px,5vw,70px);line-height:.99;letter-spacing:-2.2px;font-weight:600}
.storyContent h2 em,.sectionIntro h2 em,.founderContent h2 em,.reviewIntro h2 em,.appointmentStory h2 em{color:var(--nova-teal);font-style:italic;font-weight:500}
.storyLead{max-width:590px;color:var(--nova-blue);font-size:18px;font-weight:700;line-height:1.55}
.storyContent>p:not(.storyLead),.sectionIntro>p,.founderContent>p,.reviewIntro>p,.appointmentStory p{max-width:660px;color:var(--nova-muted);font-size:14px;line-height:1.9}

/* ---------- premium buttons ---------- */
.storyButton,.lightStoryButton{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:13px 21px;border:1px solid transparent;border-radius:999px;background:var(--nova-teal);color:#fff!important;font-size:11px;font-weight:900;letter-spacing:.25px;box-shadow:0 11px 28px rgba(31,138,138,.18);transition:transform .32s ease,box-shadow .32s ease,background .32s ease}
.storyButton:hover{transform:translateY(-4px);background:var(--nova-teal-2);box-shadow:0 17px 34px rgba(31,138,138,.25)}

/* ---------- welcome ---------- */
.storyImageFrame{position:relative;min-height:590px;overflow:hidden;border-radius:4px 30px 30px 4px;background:var(--nova-soft);box-shadow:var(--nova-shadow)}
.storyImageFrame::before{content:"";position:absolute;z-index:0;inset:18px -18px -18px 18px;border:1px solid rgba(31,138,138,.18);border-radius:4px 30px 30px 4px}
.storyImageFrame::after{content:"";position:absolute;z-index:1;inset:0;background:linear-gradient(180deg,transparent 52%,rgba(11,37,69,.48))}
.storyImageFrame img{position:relative;z-index:0;width:100%;height:590px;object-fit:cover;transition:transform 1s cubic-bezier(.2,.75,.2,1)}
.storyImageFrame:hover img{transform:scale(1.035)}
.storyVertical{position:absolute;z-index:3;top:26px;left:24px;color:#fff;font-size:9px;font-weight:900;letter-spacing:2.5px;writing-mode:vertical-rl;transform:rotate(180deg)}
.storyImageBadge{position:absolute;z-index:4;left:24px;bottom:24px;display:flex;align-items:center;gap:10px;padding:12px 16px;border:1px solid rgba(255,255,255,.35);border-radius:999px;background:rgba(11,37,69,.78);color:#fff;backdrop-filter:blur(12px);font-size:10px;font-weight:800}
.storyImageBadge svg{color:var(--nova-accent)}
.storyMiniGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:30px 0}
.storyMiniGrid div{padding:17px;border:1px solid var(--nova-line);border-radius:15px;background:#fff;box-shadow:var(--nova-shadow-soft);transition:transform .32s ease,box-shadow .32s ease,border-color .32s ease}
.storyMiniGrid div:hover{transform:translateY(-5px);border-color:rgba(31,138,138,.35);box-shadow:var(--nova-shadow)}
.storyMiniGrid strong{display:block;margin-bottom:6px;color:var(--nova-teal);font-size:10px;letter-spacing:1.5px}
.storyMiniGrid span{color:var(--nova-blue);font-size:11px;line-height:1.45;font-weight:800}

/* ---------- clinic story ---------- */
.centerIntro{text-align:center;max-width:800px;margin:0 auto 58px}
.centerIntro .storyKicker{justify-content:center}
.clinicExperienceGrid{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,.88fr);gap:clamp(40px,7vw,90px);align-items:center}
.clinicLargeImage{position:relative;min-height:570px;overflow:hidden;border-radius:28px;box-shadow:var(--nova-shadow);background:var(--nova-soft)}
.clinicLargeImage img{width:100%;height:570px;object-fit:cover;transition:transform 1s cubic-bezier(.2,.75,.2,1)}
.clinicLargeImage:hover img{transform:scale(1.035)}
.imageCaption{position:absolute;z-index:2;left:22px;right:22px;bottom:22px;display:grid;grid-template-columns:auto 1fr;column-gap:12px;align-items:center;padding:16px 18px;border:1px solid rgba(255,255,255,.3);border-radius:16px;background:rgba(11,37,69,.82);color:#fff;backdrop-filter:blur(12px)}
.imageCaption span{grid-row:1/3;color:var(--nova-accent);font-size:11px;font-weight:900}
.imageCaption strong{font-size:13px}.imageCaption small{font-size:10px;color:rgba(255,255,255,.68)}
.clinicExperienceCopy{display:flex;flex-direction:column;align-items:flex-start}
.experiencePoint{display:grid;grid-template-columns:43px 1fr;gap:14px;width:100%;padding:18px 0;border-bottom:1px solid var(--nova-line)}
.experiencePoint>span{width:36px;height:36px;display:grid;place-items:center;border-radius:50%;background:var(--nova-soft-2);color:var(--nova-teal);font-size:10px;font-weight:900}
.experiencePoint strong{color:var(--nova-blue);font-size:14px}.experiencePoint p{margin:4px 0 0;color:var(--nova-muted);font-size:12px;line-height:1.65}
.clinicExperienceCopy .storyButton{margin-top:27px}

/* ---------- founder + CR ---------- */
.founderStory{background:#fff!important}
.founderGrid{display:grid;grid-template-columns:minmax(0,.84fr) minmax(0,1.16fr);gap:clamp(48px,7vw,92px);align-items:center}
.founderImageFrame{position:relative;min-height:600px;overflow:hidden;border:1px solid var(--nova-line);border-radius:28px;background:var(--nova-soft);box-shadow:var(--nova-shadow)}
.founderImageFrame img{width:100%;height:600px;object-fit:cover;transition:transform .9s cubic-bezier(.2,.75,.2,1)}
.founderImageFrame:hover img{transform:scale(1.035)}
.founderSeal{position:absolute;right:20px;bottom:20px;display:flex;align-items:center;gap:10px;padding:13px 16px;border:1px solid rgba(255,255,255,.3);border-radius:15px;background:rgba(11,37,69,.88);color:#fff;backdrop-filter:blur(10px);box-shadow:0 16px 35px rgba(11,37,69,.18)}
.founderSeal svg{color:var(--nova-accent)}
.founderSeal span{font-size:9px;font-weight:900;letter-spacing:1.1px;line-height:1.4}
.founderDetails{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:27px 0}
.founderDetails div{padding:15px 17px;border:1px solid var(--nova-line);border-radius:14px;background:#fff;transition:transform .3s ease,box-shadow .3s ease,border-color .3s ease}
.founderDetails div:hover{transform:translateY(-4px);border-color:rgba(31,138,138,.3);box-shadow:var(--nova-shadow-soft)}
.founderDetails span{display:block;color:var(--nova-muted);font-size:8px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase}
.founderDetails strong{display:block;margin-top:5px;color:var(--nova-blue);font-size:12px}

.crInformationCard{margin-top:76px;padding:30px;border:1px solid var(--nova-line);border-radius:24px;background:#fff;box-shadow:var(--nova-shadow-soft);position:relative;overflow:hidden}
.crInformationCard::before{content:"";position:absolute;left:0;top:0;width:4px;height:100%;background:var(--nova-teal)}
.crHeader{display:flex;align-items:flex-end;justify-content:space-between;gap:25px;margin-bottom:22px}
.crHeader span{display:block;color:var(--nova-teal);font-size:9px;font-weight:900;letter-spacing:2px}
.crHeader h3{margin:7px 0 0;color:var(--nova-blue);font-family:"Playfair Display",Georgia,serif;font-size:28px}
.crBadge{padding:7px 11px;border:1px solid rgba(31,138,138,.2);border-radius:999px;color:var(--nova-teal);background:var(--nova-soft-2);font-size:8px;font-weight:900;letter-spacing:1.3px;white-space:nowrap}
.crGrid{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--nova-line);border-radius:16px;overflow:hidden}
.crGrid>div{padding:18px;border-right:1px solid var(--nova-line);background:#fff}
.crGrid>div:last-child{border-right:0}
.crGrid span{display:block;color:var(--nova-muted);font-size:8px;font-weight:900;letter-spacing:1.4px;text-transform:uppercase}
.crGrid strong{display:block;margin-top:7px;color:var(--nova-blue);font-size:12px;line-height:1.5}

/* ---------- philosophy ---------- */
.philosophyStory{background:var(--nova-soft)!important}
.principleGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}
.principleCard{position:relative;min-height:290px;padding:26px;border:1px solid var(--nova-line);border-radius:21px;background:#fff;box-shadow:var(--nova-shadow-soft);transition:transform .38s ease,box-shadow .38s ease,border-color .38s ease}
.principleCard:hover{transform:translateY(-9px)!important;box-shadow:var(--nova-shadow);border-color:rgba(31,138,138,.34)}
.principleNumber{color:#9aabb8;font-size:9px;font-weight:900;letter-spacing:1.7px}
.principleIcon{width:48px;height:48px;display:grid;place-items:center;margin:45px 0 22px;border-radius:50%;background:var(--nova-soft-2);color:var(--nova-teal);transition:transform .4s ease}
.principleCard:hover .principleIcon{transform:rotate(8deg) scale(1.08)}
.principleCard h3{margin-bottom:9px;color:var(--nova-blue);font-size:16px}.principleCard p{color:var(--nova-muted);font-size:11px;line-height:1.75}.principleArrow{position:absolute;right:22px;bottom:22px;color:var(--nova-teal)}

/* ---------- services ---------- */
.servicesStory{background:#fff}
.servicesIntro{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;margin-bottom:50px}
.editorialServiceGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.editorialService{overflow:hidden;border:1px solid var(--nova-line);border-radius:22px;background:#fff;box-shadow:var(--nova-shadow-soft);transition:transform .4s ease,box-shadow .4s ease,border-color .4s ease}
.editorialService:hover{transform:translateY(-9px)!important;box-shadow:var(--nova-shadow);border-color:rgba(31,138,138,.28)}
.editorialServiceImage{position:relative;height:260px;overflow:hidden}.editorialServiceImage img{width:100%;height:100%;object-fit:cover;transition:transform .8s cubic-bezier(.2,.75,.2,1)}.editorialService:hover .editorialServiceImage img{transform:scale(1.08)}
.editorialServiceImage::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(11,37,69,.5))}
.editorialServiceImage>span{position:absolute;z-index:2;top:15px;left:15px;color:#fff;font-size:10px;font-weight:900;letter-spacing:1.5px}
.editorialImageArrow{position:absolute;z-index:3;right:14px;top:14px;width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:rgba(255,255,255,.9);color:var(--nova-blue);transition:transform .3s ease}.editorialService:hover .editorialImageArrow{transform:rotate(45deg)}
