/* =========================================================
   NOVADENT CINEMATIC HERO
========================================================= */

.novaHero {
  position: relative;
  width: 100%;
  min-height: 100svh;
  height: 100svh;
  overflow: hidden;
  isolation: isolate;
  background: #0b2633;
}

/* ---------------------------------------------------------
   VIDEO
--------------------------------------------------------- */

.novaHeroMedia {
  position: absolute;
  inset: 0;
  z-index: -3;
  overflow: hidden;
}

.novaHeroVideo {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center center;
}

/* ---------------------------------------------------------
   VIDEO OVERLAYS
--------------------------------------------------------- */

.novaHeroOverlay {
  position: absolute;
  inset: 0;
  background: rgba(5, 28, 39, 0.48);
  z-index: 1;
}

.novaHeroGradient {
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      180deg,
      rgba(5, 28, 39, 0.68) 0%,
      rgba(5, 28, 39, 0.20) 35%,
      rgba(5, 28, 39, 0.28) 65%,
      rgba(5, 28, 39, 0.82) 100%
    );
  pointer-events: none;
}

/* ---------------------------------------------------------
   HERO CONTENT
--------------------------------------------------------- */

.novaHeroContent {
  position: relative;
  z-index: 5;

  width: min(900px, calc(100% - 40px));
  min-height: 100%;
  margin: 0 auto;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  text-align: center;

  padding: 110px 0 100px;

  color: #ffffff;
}

/* ---------------------------------------------------------
   EYEBROW
--------------------------------------------------------- */

.novaHeroEyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;

  margin-bottom: 24px;

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;

  color: rgba(255, 255, 255, 0.92);

  animation: novaHeroFadeDown 0.9s ease both;
}

.novaHeroEyebrowLine {
  width: 34px;
  height: 1px;

  background: rgba(255, 255, 255, 0.7);
}

/* ---------------------------------------------------------
   TITLE
--------------------------------------------------------- */

.novaHeroTitle {
  max-width: 850px;
  margin: 0;

  font-size: clamp(48px, 7vw, 94px);
  line-height: 0.98;
  font-weight: 600;
  letter-spacing: -0.045em;

  color: #ffffff;

  text-shadow:
    0 3px 25px rgba(0, 0, 0, 0.25);

  animation: novaHeroTitleReveal 1s 0.12s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.novaHeroTitle span {
  display: block;

  color: #7ed8d0;

  font-style: italic;
  font-weight: 400;

  margin-top: 8px;
}

/* ---------------------------------------------------------
   DESCRIPTION
--------------------------------------------------------- */

.novaHeroDescription {
  max-width: 650px;

  margin: 28px auto 0;

  font-size: 16px;
  line-height: 1.8;
  font-weight: 400;

  color: rgba(255, 255, 255, 0.88);

  text-shadow:
    0 2px 12px rgba(0, 0, 0, 0.25);

  animation: novaHeroFadeUp 0.9s 0.35s ease both;
}

/* ---------------------------------------------------------
   BUTTONS
--------------------------------------------------------- */

.novaHeroActions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;

  margin-top: 34px;

  animation: novaHeroFadeUp 0.9s 0.5s ease both;
}

.novaHeroPrimary,
.novaHeroSecondary {
  min-height: 54px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;

  padding: 0 25px;

  border-radius: 999px;

  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.02em;

  text-decoration: none;

  transition:
    transform 0.3s ease,
    background 0.3s ease,
    color 0.3s ease,
    border-color 0.3s ease,
    box-shadow 0.3s ease;
}

.novaHeroPrimary {
  color: #123846;
  background: #ffffff;

  box-shadow:
    0 14px 35px rgba(0, 0, 0, 0.18);
}

.novaHeroPrimary:hover {
  transform: translateY(-3px);

  background: #7ed8d0;

  color: #123846;

  box-shadow:
    0 18px 40px rgba(0, 0, 0, 0.24);
}

.novaHeroSecondary {
  color: #ffffff;

  border: 1px solid rgba(255, 255, 255, 0.55);

  background: rgba(255, 255, 255, 0.08);

  backdrop-filter: blur(8px);
}

.novaHeroSecondary:hover {
  transform: translateY(-3px);

  border-color: #ffffff;

  background: rgba(255, 255, 255, 0.16);
}

/* ---------------------------------------------------------
   TRUST INFO
--------------------------------------------------------- */

.novaHeroTrust {
  display: flex;
  align-items: center;
  justify-content: center;

  margin-top: 54px;

  animation: novaHeroFadeUp 0.9s 0.68s ease both;
}

.novaHeroTrustItem {
  display: flex;
  flex-direction: column;
  align-items: center;

  min-width: 125px;
}

.novaHeroTrustItem strong {
  font-size: 14px;
  font-weight: 700;

  color: #ffffff;
}

.novaHeroTrustItem span {
  margin-top: 4px;

  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;

  color: rgba(255, 255, 255, 0.68);
}

.novaHeroTrustDivider {
  width: 1px;
  height: 30px;

  margin: 0 18px;

  background: rgba(255, 255, 255, 0.3);
}

/* ---------------------------------------------------------
   SIDE LABEL
--------------------------------------------------------- */

.novaHeroSideLabel {
  position: absolute;

  right: 28px;
  top: 50%;

  z-index: 6;

  display: flex;
  align-items: center;
  gap: 12px;

  transform: translateY(-50%) rotate(90deg);

  transform-origin: center;

  color: rgba(255, 255, 255, 0.65);

  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.25em;
}

.novaHeroSideLine {
  display: block;

  width: 38px;
  height: 1px;

  background: rgba(255, 255, 255, 0.5);
}

/* ---------------------------------------------------------
   SCROLL INDICATOR
--------------------------------------------------------- */

.novaHeroScroll {
  position: absolute;

  left: 50%;
  bottom: 24px;

  z-index: 6;

  transform: translateX(-50%);

  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;

  color: rgba(255, 255, 255, 0.72);

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.25em;
}

.novaHeroScrollLine {
  width: 1px;
  height: 34px;

  background: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.8),
    transparent
  );

  animation: novaHeroScrollPulse 1.8s ease-in-out infinite;
}

/* ---------------------------------------------------------
   ANIMATIONS
--------------------------------------------------------- */

@keyframes novaHeroFadeDown {
  from {
    opacity: 0;
    transform: translateY(-18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes novaHeroFadeUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes novaHeroTitleReveal {
  from {
    opacity: 0;
    transform: translateY(45px);
    filter: blur(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes novaHeroScrollPulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scaleY(0.7);
    transform-origin: top;
  }

  50% {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: top;
  }
}

/* ---------------------------------------------------------
   TABLET
--------------------------------------------------------- */

@media (max-width: 900px) {

  .novaHeroSideLabel {
    display: none;
  }

  .novaHeroTitle {
    font-size: clamp(46px, 8vw, 72px);
  }

  .novaHeroDescription {
    max-width: 590px;
  }
}

/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 640px) {

  .novaHero {
    min-height: 100svh;
    height: 100svh;
  }

  .novaHeroContent {
    width: min(100% - 30px, 520px);

    padding:
      90px 0
      95px;
  }

  .novaHeroEyebrow {
    gap: 8px;

    margin-bottom: 18px;

    font-size: 8px;
    letter-spacing: 0.18em;
  }

  .novaHeroEyebrowLine {
    width: 22px;
  }

  .novaHeroTitle {
    font-size: clamp(43px, 13vw, 62px);
    line-height: 0.98;
    letter-spacing: -0.045em;
  }

  .novaHeroTitle span {
    margin-top: 6px;
  }

  .novaHeroDescription {
    margin-top: 22px;

    font-size: 13px;
    line-height: 1.7;
  }

  .novaHeroActions {
    width: 100%;

    flex-direction: column;

    margin-top: 27px;
    gap: 10px;
  }

  .novaHeroPrimary,
  .novaHeroSecondary {
    width: min(100%, 290px);

    min-height: 50px;

    padding: 0 20px;

    font-size: 12px;
  }

  .novaHeroTrust {
    width: 100%;

    margin-top: 35px;
  }

  .novaHeroTrustItem {
    min-width: auto;
    flex: 1;
  }

  .novaHeroTrustItem strong {
    font-size: 12px;
  }

  .novaHeroTrustItem span {
    font-size: 7px;
    line-height: 1.4;
    letter-spacing: 0.08em;
  }

  .novaHeroTrustDivider {
    height: 25px;

    margin: 0 8px;
  }

  .novaHeroScroll {
    bottom: 16px;

    font-size: 7px;
  }

  .novaHeroScrollLine {
    height: 25px;
  }
}

/* ---------------------------------------------------------
   SMALL MOBILE
--------------------------------------------------------- */

@media (max-width: 390px) {

  .novaHeroContent {
    padding-top: 82px;
  }

  .novaHeroTitle {
    font-size: 40px;
  }

  .novaHeroDescription {
    font-size: 12px;
  }

  .novaHeroTrust {
    margin-top: 28px;
  }

  .novaHeroTrustItem span {
    font-size: 6px;
  }
}

/* ---------------------------------------------------------
   REDUCED MOTION
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

  .novaHeroEyebrow,
  .novaHeroTitle,
  .novaHeroDescription,
  .novaHeroActions,
  .novaHeroTrust,
  .novaHeroScrollLine {
    animation: none;
  }

  .novaHeroPrimary,
  .novaHeroSecondary {
    transition: none;
  }
}
/* =========================================
   HERO → WELCOME SECTION SPACING
   ========================================= */

.homeIntro {
  position: relative;
  padding-top: 120px !important;
  padding-bottom: 120px !important;
  background: #ffffff !important;
  margin-top: 0;
}

.homeIntro .section-container {
  position: relative;
  z-index: 2;
}

/* Extra breathing space after cinematic hero */
.novaHero + .homeIntro {
  margin-top: 0;
  border-top: 1px solid rgba(31, 138, 138, 0.08);
}

/* Mobile */
