    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
  }

  .premiumHome [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}
/* =========================================================
   NOVADENT — CLEAN PREMIUM STORY SYSTEM
   White / Navy / Teal
   Consistent spacing + typography + RiverSmile-style reveal
   ========================================================= */

:root {
  --nova-navy: #09284d;
  --nova-navy-deep: #061f3d;
  --nova-teal: #159da2;
  --nova-teal-light: #dff5f5;
  --nova-text: #183557;
  --nova-muted: #61758f;
  --nova-line: #e3ebf0;
  --nova-soft: #f6fafb;
  --nova-white: #ffffff;

  --nova-container: 1180px;
  --nova-section-space: 88px;
  --nova-radius: 20px;

  --nova-ease: cubic-bezier(0.22, 1, 0.36, 1);
}


/* =========================================================
   BASE
   ========================================================= */

html {
  scroll-behavior: smooth;
}

.homePage {
  width: 100%;
  overflow: hidden;
  background: var(--nova-white);
  color: var(--nova-text);
}

.homePage *,
.novaHero * {
  box-sizing: border-box;
}

.homePage img {
  display: block;
  max-width: 100%;
}

.storyContainer {
  width: min(var(--nova-container), calc(100% - 48px));
  margin: 0 auto;
}


/* =========================================================
   COMMON STORY SECTION
   ========================================================= */

.storySection {
  position: relative;
  padding: var(--nova-section-space) 0;
  background: var(--nova-white);
}

.storySection + .storySection {
  margin-top: 0;
}

.welcomeStory,
.founderStory,
.doctorsStory {
  background: var(--nova-white);
}

.clinicStory,
.philosophyStory,
.servicesStory,
.reviewStory {
  background: var(--nova-soft);
}


/* =========================================================
   COMMON TYPOGRAPHY
   ========================================================= */

.storyKicker {
  display: block;
  margin-bottom: 12px;
  color: var(--nova-teal);
  font-size: 12px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.storyIndex {
  display: block;
  margin-bottom: 20px;
  color: #8b9aad;
  font-size: 10px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.storySection h2 {
  margin: 0;
  max-width: 780px;
  color: var(--nova-navy);
  font-size: clamp(42px, 4.3vw, 64px);
  line-height: 0.98;
  letter-spacing: -0.045em;
  font-weight: 500;
}

.storySection h2 em {
  color: var(--nova-teal);
  font-weight: 500;
}

.storySection p {
  color: var(--nova-muted);
  font-size: 16px;
  line-height: 1.75;
}

.storyLead {
  margin: 24px 0 12px;
  color: var(--nova-teal) !important;
  font-size: 18px !important;
  line-height: 1.6 !important;
  font-weight: 700;
}

.centerIntro {
  max-width: 760px;
  margin: 0 auto 50px;
  text-align: center;
}

.centerIntro h2 {
  margin-left: auto;
  margin-right: auto;
}

.centerIntro p {
  max-width: 650px;
  margin: 22px auto 0;
}


/* =========================================================
   RIVERSMILE-STYLE REVEAL ANIMATION
   ========================================================= */

[data-reveal] {
  opacity: 0;
  transform: translateY(34px);
  transition:
    opacity 0.8s var(--nova-ease),
    transform 0.8s var(--nova-ease);
  transition-delay: var(--delay, 0ms);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}

.reveal-left {
  transform: translateX(-45px);
}

.reveal-right {
  transform: translateX(45px);
}

.reveal-left.is-visible,
.reveal-right.is-visible {
  transform: translateX(0);
}


/* Image movement — subtle, not excessive */
.storyImageFrame img,
.clinicLargeImage img,
.founderImageFrame img,
.editorialServiceImage img,
.editorialDoctorImage img {
  transition:
    transform 1s var(--nova-ease),
    filter 0.7s ease;
}

.storyImageFrame:hover img,
.clinicLargeImage:hover img,
.founderImageFrame:hover img,
.editorialService:hover .editorialServiceImage img,
.editorialDoctor:hover .editorialDoctorImage img {
  transform: scale(1.035);
}


/* =========================================================
   HERO
   ========================================================= */

.novaHero {
  position: relative;
  min-height: 100svh;
  width: 100%;
  overflow: hidden;
  isolation: isolate;
  background: #071f3b;
}

.novaHeroMedia,
.novaHeroVideo {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.novaHeroVideo {
  display: block;
  object-fit: cover;
  object-position: center;
}

.novaHeroOverlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: rgba(4, 28, 53, 0.48);
}

.novaHeroGradient {
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      180deg,
      rgba(4, 25, 48, 0.28) 0%,
      rgba(4, 25, 48, 0.18) 35%,
      rgba(4, 25, 48, 0.65) 100%
    );
}
.novaHeroContent {
  position: relative;
  z-index: 5;
  min-height: 84vh;
  width: min(1000px, calc(100% - 48px));
  margin: 0 auto;
  padding: 80px 0 55px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #fff;
}

.novaHeroEyebrow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  margin-bottom: 18px;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2em;
}

.novaHeroEyebrowLine {
  width: 38px;
  height: 1px;
  background: rgba(255, 255, 255, 0.65);
}

.novaHeroTitle {
  max-width: 850px;
  margin: 0 auto;
  color: #fff;
  font-size: clamp(44px, 5.5vw, 76px);
  line-height: 0.98;
  letter-spacing: -0.045em;
  font-weight: 600;
  text-align: center;
  animation: novaHeroTitleIn 1.1s var(--nova-ease) both;
}

.novaHeroTitle span {
  display: block;
  color: #d9f7ff;
  font-style: italic;
}

.novaHeroDescription {
  max-width: 620px;
  margin: 18px auto 0;
  color: rgba(255, 255, 255, 0.88);
  font-size: 16px;
  line-height: 1.55;
  text-align: center;
  animation: novaHeroTextIn 1s 0.15s var(--nova-ease) both;
}

.novaHeroActions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 22px;
  animation: novaHeroTextIn 1s 0.25s var(--nova-ease) both;
}

.novaHeroPrimary,
.novaHeroSecondary {
  min-height: 50px;
  padding: 0 22px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  transition:
    transform 0.35s var(--nova-ease),
    background 0.35s ease,
    border-color 0.35s ease;
}

.novaHeroPrimary {
  color: #fff;
  background: var(--nova-teal);
}

.novaHeroSecondary {
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.6);
  background: rgba(255, 255, 255, 0.05);
}

.novaHeroPrimary:hover,
.novaHeroSecondary:hover {
  transform: translateY(-3px);
}

.novaHeroSecondary:hover {
  background: rgba(255, 255, 255, 0.12);
}

.novaHeroTrust {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 28px;
  margin-top: 22px;
  animation: novaHeroTextIn 1s 0.35s var(--nova-ease) both;
}

.novaHeroTrustItem {
  display: flex;
  flex-direction: column;
  gap: 5px;
  text-align: center;
  align-items: center;
}

.novaHeroTrustItem strong {
  color: #fff;
  font-size: 15px;
}

.novaHeroTrustItem span {
  color: rgba(255, 255, 255, 0.68);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.novaHeroTrustDivider {
  width: 1px;
  height: 30px;
  background: rgba(255, 255, 255, 0.3);
}

.novaHeroScroll,
.novaHeroSideLabel {
  position: absolute;
  z-index: 6;
  color: rgba(255, 255, 255, 0.8);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.2em;
}

.novaHeroScroll {
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}

.novaHeroScrollLine {
  width: 1px;
  height: 25px;
  background: rgba(255, 255, 255, 0.55);
}

.novaHeroSideLabel {
  right: 24px;
  top: 50%;
  transform: translateY(-50%) rotate(90deg);
  display: flex;
  align-items: center;
  gap: 12px;
}

.novaHeroSideLine {
  width: 36px;
  height: 1px;
  background: rgba(255, 255, 255, 0.5);
}

@keyframes novaHeroTitleIn {
  from {
    opacity: 0;
    transform: translateY(35px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes novaHeroTextIn {
  from {
    opacity: 0;
    transform: translateY(22px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .novaHeroContent {
    min-height: 78vh;
    width: calc(100% - 32px);
    padding: 65px 0 45px;
  }

  .novaHeroTitle {
    font-size: clamp(38px, 10vw, 58px);
  }

  .novaHeroDescription {
    max-width: 92%;
    font-size: 14px;
    margin-top: 15px;
  }

  .novaHeroActions {
    margin-top: 18px;
    flex-direction: column;
    gap: 8px;
  }

  .novaHeroTrust {
    margin-top: 18px;
    gap: 16px;
  }

  .novaHeroTrustDivider {
    height: 25px;
  }
}
/* =========================================================
   WELCOME
   ========================================================= */

.storySplit {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 72px;
  align-items: center;
}

.storyMedia {
  min-width: 0;
}

.storyImageFrame {
  position: relative;
  height: 570px;
  overflow: hidden;
  border-radius: 22px;
  background: #edf4f5;
}

.storyImageFrame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.storyVertical {
  position: absolute;
  left: 22px;
  top: 26px;

  writing-mode: vertical-rl;
  transform: rotate(180deg);

  color: rgba(255,255,255,0.9);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.storyImageBadge {
  position: absolute;
  left: 22px;
  bottom: 22px;

  display: inline-flex;
  align-items: center;
