  height: 510px;
  overflow: hidden;
  border-radius: 20px;
}

.clinicLargeImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.imageCaption {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 22px;

  display: flex;
  align-items: center;
  gap: 12px;

  padding: 16px 18px;
  border-radius: 13px;

  color: #fff;
  background: rgba(5, 31, 58, 0.88);
}

.imageCaption span {
