  text-decoration: none;

  font-size: 11px;
  font-weight: 800;
}

.editorialServiceBody > a:hover,
.editorialDoctorBody > a:hover {
  color: var(--nova-teal);
}


/* =========================================================
   DOCTORS
   ========================================================= */

.doctorsStory {
