  object-fit: cover;
}

.editorialDoctorBody {
  padding: 22px;
}

.editorialDoctorBody h3 {
  font-size: 27px;
}

.editorialDoctorBody p {
  margin: 0;
  font-size: 14px;
}

.editorialDoctorBody small {
