  margin-top: 10px;
  color: #8090a2;
  font-size: 10px;
  font-weight: 700;
}


/* =========================================================
   REVIEWS
   ========================================================= */

.reviewStory {
  padding-top: 76px;
  padding-bottom: 76px;
}

.reviewGrid {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
  gap: 70px;
  align-items: center;
}

.reviewIntro h2 {
  max-width: 500px;
}

.reviewIntro > p {
  max-width: 480px;
}

.reviewStars {
  margin: 30px 0 20px;
  color: var(--nova-teal);
  font-size: 16px;
  letter-spacing: 4px;
}

.reviewCard {
  position: relative;
  min-height: 330px;
  padding: 52px 45px 35px;

