  border-radius: 20px;

  color: #fff;
  background: var(--nova-navy);

  box-shadow: 0 25px 65px rgba(9,40,77,0.14);
}

.reviewQuote {
  position: absolute;
  top: 16px;
  left: 30px;

  color: rgba(92,211,210,0.55);
  font-family: Georgia, serif;
