  align-items: center;
  gap: 12px;
  margin-top: 30px;
}

.reviewAuthor > div {
  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  border-radius: 50%;
  color: #fff;
  background: var(--nova-teal);

  font-size: 10px;
  font-weight: 800;
}

.reviewAuthor span {
