  align-items: center;
  justify-content: flex-end;
  gap: 14px;
  margin-top: 20px;
}

.reviewControls > button {
  width: 34px;
  height: 34px;

  display: grid;
  place-items: center;

  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 50%;

  color: #fff;
  background: transparent;
  cursor: pointer;
}

.reviewControls > div {
  display: flex;
  align-items: center;
  gap: 5px;
}

.reviewControls > div button {
  width: 7px;
  height: 7px;
  padding: 0;

  border: 0;
  border-radius: 50%;

  background: rgba(255,255,255,0.3);
  cursor: pointer;
}

.reviewControls > div button.active {
  width: 20px;
  border-radius: 10px;
  background: #62d5d4;
}


/* =========================================================
   APPOINTMENT CTA
   ========================================================= */

.appointmentStory {
  padding: 72px 0;
  background: var(--nova-navy-deep);
  color: #fff;
}

.appointmentStoryInner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 50px;
}

.lightKicker {
  color: #65d7d5;
}

.lightIndex {
  color: rgba(255,255,255,0.45);
}

.appointmentStory h2 {
  max-width: 730px;
  color: #fff;
}

.appointmentStory h2 em {
  color: #65d7d5;
}

.appointmentStory p {
  max-width: 600px;
  margin-bottom: 0;
  color: rgba(255,255,255,0.65);
}

.appointmentActions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  flex-shrink: 0;
}

.lightStoryButton {
  min-height: 52px;
  padding: 0 20px;

  display: inline-flex;
  align-items: center;
  gap: 9px;

  border-radius: 12px;
  color: #fff;
  background: var(--nova-teal);

  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
}

.textLightLink {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  color: rgba(255,255,255,0.75);
  text-decoration: none;

  font-size: 11px;
  font-weight: 700;
