/* =========================================================
   MOBILE / TABLET
   ========================================================= */

@media (max-width: 1050px) {

  :root {
    --nova-section-space: 72px;
  }

  .storySplit,
  .clinicExperienceGrid,
  .founderGrid,
  .reviewGrid {
    gap: 42px;
  }

  .storyImageFrame {
    height: 500px;
  }

  .founderImageFrame {
    height: 500px;
  }

  .clinicLargeImage {
    height: 450px;
  }

  .editorialDoctorImage {
    height: 330px;
  }

  .editorialServiceImage {
    height: 220px;
  }

  .storySection h2 {
    font-size: clamp(38px, 5vw, 54px);
  }
}


@media (max-width: 820px) {

  :root {
    --nova-section-space: 62px;
  }

  .storyContainer {
    width: min(100% - 32px, 680px);
  }

  .novaHeroContent {
    width: calc(100% - 32px);
    padding: 110px 0 90px;
  }

  .novaHeroTitle {
    font-size: clamp(50px, 10vw, 76px);
  }

  .novaHeroDescription {
    font-size: 15px;
    max-width: 600px;
  }

  .novaHeroTrust {
    gap: 16px;
    margin-top: 35px;
  }

  .storySplit,
  .clinicExperienceGrid,
  .founderGrid,
  .reviewGrid {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .storyImageFrame,
  .founderImageFrame {
    height: 500px;
  }

  .clinicLargeImage {
    height: 430px;
