/* =========================================
   NOVADENT - PREMIUM STATS
========================================= */

.premiumStats {
  width: 100%;
  padding: 52px 20px;
  background: #ffffff;
}

.premiumStats .statsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  border-top: 1px solid #e3edef;
  border-bottom: 1px solid #e3edef;
}

.premiumStats .statsGrid > div {
  position: relative;
  min-width: 0;
  padding: 28px 20px;
  text-align: center;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  opacity: 0;
  transform: translateY(18px);

  animation: statsReveal 0.7s ease forwards;
}

.premiumStats .statsGrid > div:nth-child(1) {
  animation-delay: 0.05s;
}

.premiumStats .statsGrid > div:nth-child(2) {
  animation-delay: 0.15s;
}

.premiumStats .statsGrid > div:nth-child(3) {
  animation-delay: 0.25s;
}

.premiumStats .statsGrid > div:nth-child(4) {
  animation-delay: 0.35s;
}


/* separators */

.premiumStats .statsGrid > div:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 25%;
  right: 0;
  width: 1px;
  height: 50%;
  background: #e0eaed;
}


/* icons */

.premiumStats .statsGrid svg {
  width: 19px;
  height: 19px;
  margin-bottom: 11px;
  color: #55b8b0;
}


/* numbers */

.premiumStats .statsGrid strong {
  display: block;
  margin: 0;

  font-size: 34px;
  line-height: 1;
  font-weight: 650;
  letter-spacing: -0.8px;

  color: #083246;
}


/* labels */

.premiumStats .statsGrid span {
  display: block;
  margin-top: 9px;

  font-size: 11px;
  line-height: 1.4;
  font-weight: 600;

  letter-spacing: 1px;
  text-transform: uppercase;

  color: #71828a;
}


/* hover */

.premiumStats .statsGrid > div {
  transition: transform 0.3s ease;
}

.premiumStats .statsGrid > div:hover {
  transform: translateY(-3px);
}

.premiumStats .statsGrid > div:hover strong {
  color: #55b8b0;
}


/* reveal */

@keyframes statsReveal {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


