  content: "";

  position: absolute;

  bottom: 0;
  right: -100%;

  width: 100%;
  height: 2px;

  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.65),
    transparent
  );

  animation: statBorderMoveReverse 3s linear infinite;
}

