/* ==========================================
   NOVADENT GLOBAL PREMIUM ANIMATIONS
========================================== */

[data-reveal],
.serviceCard,
.doctorCard,
.galleryCard,
.reviewCard,
.premiumCard,
.storyCard {
  opacity: 0;
  transform: translateY(35px);
  transition:
    opacity 0.8s ease,
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
}

[data-reveal].is-visible,
.serviceCard.is-visible,
.doctorCard.is-visible,
.galleryCard.is-visible,
.reviewCard.is-visible,
.premiumCard.is-visible,
.storyCard.is-visible {
  opacity: 1;
  transform: translateY(0);
}


/* LEFT REVEAL */

.reveal-left {
  opacity: 0;
  transform: translateX(-50px);
  transition:
    opacity 0.85s ease,
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}

.reveal-left.is-visible {
  opacity: 1;
  transform: translateX(0);
}


/* RIGHT REVEAL */

.reveal-right {
  opacity: 0;
  transform: translateX(50px);
  transition:
    opacity 0.85s ease,
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}

.reveal-right.is-visible {
  opacity: 1;
  transform: translateX(0);
}


/* IMAGE REVEAL */

.imageReveal {
  overflow: hidden;
}

.imageReveal img {
  transform: scale(1.08);
  opacity: 0.7;
  transition:
    transform 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.9s ease;
}

.imageReveal.is-visible img {
  transform: scale(1);
  opacity: 1;
}


/* IMAGE HOVER */

.serviceCard img,
.doctorCard img,
.galleryCard img,
.storyCard img {
  transition:
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.serviceCard:hover img,
.doctorCard:hover img,
.galleryCard:hover img,
.storyCard:hover img {
  transform: scale(1.06);
}


/* CARD HOVER */

.serviceCard,
.doctorCard,
.galleryCard,
.reviewCard,
.storyCard {
  transition:
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.serviceCard:hover,
.doctorCard:hover,
.galleryCard:hover,
.reviewCard:hover,
.storyCard:hover {
  transform: translateY(-7px);
}


/* BUTTON */

a,
button {
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease;
}

button:hover,
a[class*="btn"]:hover,
a[class*="Button"]:hover {
  transform: translateY(-2px);
}


/* NAVBAR */

nav a {
  position: relative;
}

nav a::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -5px;

  width: 0;
  height: 2px;

  background: #1596a6;

  transform: translateX(-50%);
  transition: width 0.3s ease;
}

nav a:hover::after,
nav a.active::after {
  width: 70%;
}


/* STAGGER */

.serviceCard:nth-child(2),
.doctorCard:nth-child(2),
.galleryCard:nth-child(2),
.reviewCard:nth-child(2) {
  transition-delay: 100ms;
}

.serviceCard:nth-child(3),
.doctorCard:nth-child(3),
.galleryCard:nth-child(3),
.reviewCard:nth-child(3) {
  transition-delay: 200ms;
}

.serviceCard:nth-child(4),
.doctorCard:nth-child(4),
.galleryCard:nth-child(4),
.reviewCard:nth-child(4) {
  transition-delay: 300ms;
}

.serviceCard:nth-child(5),
.galleryCard:nth-child(5) {
  transition-delay: 400ms;
}

.serviceCard:nth-child(6),
.galleryCard:nth-child(6) {
  transition-delay: 500ms;
}


/* FORM ANIMATION */

input,
textarea,
select {
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

input:focus,
textarea:focus,
select:focus {
  transform: translateY(-1px);
  border-color: #1596a6 !important;
  box-shadow: 0 0 0 3px rgba(21, 150, 166, 0.1);
  outline: none;
}


/* REDUCE MOTION */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
/* ==========================================
   NOVADENT REVEAL ANIMATIONS
========================================== */

.reveal {
  opacity: 0;
  transition:
    opacity 0.8s ease,
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);

  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

/* From Bottom */
.reveal-up {
  transform: translateY(45px);
}

/* From Left */
.reveal-left {
  transform: translateX(-55px);
}

/* From Right */
.reveal-right {
  transform: translateX(55px);
}

/* From Top */
.reveal-down {
  transform: translateY(-45px);
}

/* Visible */
.reveal-visible {
  opacity: 1;
  transform: translate(0, 0);
}
.reveal {
  opacity: 0;
  transition:
    opacity 0.9s ease,
    transform 1s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

.reveal-up {
  transform: translateY(55px);
}

.reveal-left {
  transform: translateX(-65px);
}

.reveal-right {
  transform: translateX(65px);
}

.reveal-down {
  transform: translateY(-55px);
}

.reveal-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}


