.novaHero {
  position: relative;
  min-height: 100vh;
  overflow: hidden;
  isolation: isolate;
}

.novaHeroMedia {
  position: absolute;
  inset: 0;
  z-index: -3;
  overflow: hidden;
}

.novaHeroVideo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.03);
  animation: novaHeroVideoZoom 14s ease-in-out infinite alternate;
}

.novaHeroOverlay {
  position: absolute;
  inset: 0;
  background: rgba(3, 25, 38, 0.42);
  z-index: 1;
}

.novaHeroGradient {
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(
      90deg,
      rgba(3, 24, 36, 0.72) 0%,
      rgba(3, 24, 36, 0.36) 45%,
      rgba(3, 24, 36, 0.18) 100%
    ),
    linear-gradient(
      180deg,
      rgba(3, 24, 36, 0.35) 0%,
      transparent 35%,
      rgba(3, 24, 36, 0.48) 100%
    );
}

.novaHeroVignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  box-shadow: inset 0 0 180px rgba(0, 20, 30, 0.45);
}

.novaHeroTopLabel {
  position: absolute;
