  flex-direction: column;
  align-items: center;
  gap: 7px;

  transform: translateX(-50%);

  color: rgba(255, 255, 255, 0.65);

  font-size: 8px;
  letter-spacing: 0.24em;
}

.novaHeroScrollLine {
  width: 1px;
  height: 30px;
  background: linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.8),
    transparent
  );

  animation: novaHeroScrollLine 1.8s ease-in-out infinite;
}


/* =========================================================
   HERO ANIMATIONS
========================================================= */

@keyframes novaHeroFadeUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes novaHeroTitleReveal {
  from {
    opacity: 0;
    transform: translateY(35px);
    filter: blur(7px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes novaHeroVideoZoom {
  from {
    transform: scale(1.03);
  }

  to {
    transform: scale(1.1);
  }
}

@keyframes novaHeroPulse {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.8);
  }

  50% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes novaHeroScrollLine {
  0%,
  100% {
    opacity: 0.3;
    transform: scaleY(0.65);
    transform-origin: top;
  }

  50% {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: top;
  }
}


