/* =========================================================
   NOVADENT - WELCOME SECTION PREMIUM ENHANCEMENT
========================================================= */

.welcomeStory {
  position: relative;
  overflow: hidden;
}

.welcomeStory .storySplit {
  position: relative;
}

/* IMAGE */

.welcomeStory .storyMedia {
  opacity: 0;
  transform: translateX(-45px);
  transition:
    opacity 0.9s ease,
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

.welcomeStory .storyMedia.is-visible {
  opacity: 1;
  transform: translateX(0);
}

.storyImageFrame {
  position: relative;
  overflow: hidden;
  border-radius: 2px;
  isolation: isolate;
}

.storyImageFrame::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;

  background:
    linear-gradient(
      135deg,
      rgba(8, 47, 73, 0.16),
      transparent 45%
    ),
    linear-gradient(
      to top,
      rgba(0, 0, 0, 0.25),
      transparent 45%
    );
}

.storyImageFrame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;

  transition:
    transform 1s cubic-bezier(0.22, 1, 0.36, 1),
    filter 0.6s ease;
}

.storyImageFrame:hover img {
  transform: scale(1.055);
  filter: brightness(1.04);
}

/* IMAGE VERTICAL LABEL */

.storyVertical {
  position: absolute;
  left: 18px;
  top: 50%;
  z-index: 4;

  transform: translateY(-50%) rotate(-90deg);
  transform-origin: left center;

  color: rgba(255, 255, 255, 0.82);

  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.22em;

  white-space: nowrap;
}

/* IMAGE BADGE */

.storyImageBadge {
  position: absolute;
  left: 22px;
  bottom: 22px;
  z-index: 5;

  display: inline-flex;
  align-items: center;
  gap: 9px;

  padding: 10px 14px;

  color: #ffffff;
  background: rgba(8, 47, 73, 0.78);

  border: 1px solid rgba(255, 255, 255, 0.22);

  backdrop-filter: blur(10px);

  font-size: 10px;
  letter-spacing: 0.08em;

  transition:
    transform 0.35s ease,
    background 0.35s ease;
}

.storyImageFrame:hover .storyImageBadge {
  transform: translateY(-5px);
  background: rgba(8, 47, 73, 0.9);
}


/* CONTENT */

.welcomeStory .storyContent {
  opacity: 0;
  transform: translateX(45px);

  transition:
    opacity 0.9s ease 0.12s,
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.12s;
}

.welcomeStory .storyContent.is-visible {
  opacity: 1;
  transform: translateX(0);
}

/* KICKER */

.welcomeStory .storyKicker {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.welcomeStory .storyKicker::before {
  content: "";
  width: 28px;
  height: 1px;

  background: currentColor;

  transition:
    width 0.5s ease;
}

.welcomeStory .storyContent:hover .storyKicker::before {
  width: 45px;
}


/* HEADING */

.welcomeStory h2 {
  transition: transform 0.5s ease;
}

.welcomeStory .storyContent:hover h2 {
  transform: translateX(3px);
}

.welcomeStory h2 em {
  transition: color 0.35s ease;
}


/* LEAD TEXT */

.welcomeStory .storyLead {
  position: relative;
}

.welcomeStory .storyLead::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 5px;

  width: 2px;
  height: calc(100% - 10px);

  background: #0f6b8f;
  opacity: 0.7;
}


/* MINI GRID */

.welcomeStory .storyMiniGrid {
  margin-top: 30px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.welcomeStory .storyMiniGrid > div {
  position: relative;

  padding: 17px 14px;

  background: rgba(8, 47, 73, 0.035);

  border: 1px solid rgba(8, 47, 73, 0.12);

  overflow: hidden;

  transition:
    transform 0.35s ease,
    border-color 0.35s ease,
    background 0.35s ease;
}

.welcomeStory .storyMiniGrid > div::before {
  content: "";

  position: absolute;
  left: 0;
  bottom: 0;

  width: 0;
  height: 2px;

  background: #0f6b8f;

  transition: width 0.4s ease;
}

.welcomeStory .storyMiniGrid > div:hover {
  transform: translateY(-5px);

  border-color: rgba(15, 107, 143, 0.35);

  background: rgba(15, 107, 143, 0.06);
}

.welcomeStory .storyMiniGrid > div:hover::before {
  width: 100%;
}

.welcomeStory .storyMiniGrid strong {
  display: block;

  margin-bottom: 7px;

  color: #0f6b8f;

  font-size: 12px;
  letter-spacing: 0.1em;
