========================================================= */

.premiumHome .welcomeStory {
  position: relative;
  overflow: hidden;
  background: #ffffff;
}

.premiumHome .welcomeStory::before {
  content: "";
  position: absolute;
  width: 320px;
  height: 320px;
  right: -160px;
  top: 80px;
  border-radius: 50%;
  background: rgba(8, 47, 73, 0.035);
  pointer-events: none;
}

.premiumHome .welcomeStory .storyContainer {
  position: relative;
  z-index: 1;
}

/* IMAGE */

.premiumHome .welcomeStory .storyImageFrame {
  position: relative;
  overflow: hidden;
  border-radius: 22px;
  background: #eef5f7;
  box-shadow: 0 22px 55px rgba(8, 47, 73, 0.12);
}

.premiumHome .welcomeStory .storyImageFrame::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      135deg,
      rgba(8, 47, 73, 0.08),
      transparent 55%
    );
