}

.premiumHome .welcomeStory .storyImageFrame:hover img {
  transform: scale(1.055);
  filter: saturate(1.04);
}

/* IMAGE BADGE */

.premiumHome .welcomeStory .storyImageBadge {
  position: absolute;
  left: 20px;
  bottom: 20px;
  z-index: 3;

