/* SIDE LABEL */

.novaHeroSideLabel {
  position: absolute;

  right: 22px;
  top: 50%;

  z-index: 7;

  display: flex;

  gap: 11px;

  color:
    rgba(255,255,255,0.58);

  font-size: 8px;

  font-weight: 800;

  letter-spacing: 0.20em;

  transform:
    translateY(-50%)
    rotate(90deg);
}

/* INDICATORS */

.novaHeroIndicators {
  position: absolute;

  right: 25px;
  bottom: 125px;

  z-index: 10;

  display: flex;

  flex-direction: column;

  gap: 8px;
}

.novaHeroIndicators button {
  width: 25px;
  height: 2px;

  padding: 0;

  border: 0;

  background:
