  cursor: pointer;

  overflow: hidden;

  transition:
    width 0.3s ease;
}

.novaHeroIndicators button span {
  display: block;

  width: 0;
  height: 100%;

  background: #d9f7ff;
}

.novaHeroIndicators button.active {
  width: 45px;
}

.novaHeroIndicators button.active span {
  width: 100%;

  animation:
    novaIndicatorProgress
    5s
    linear both;
}

/* SCROLL */

.novaHeroScroll {
  position: absolute;

  left: 50%;
  bottom: 5px;

  z-index: 9;

  display: flex;

  flex-direction: column;

  align-items: center;

  gap: 4px;

  color:
