  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.18em;

  transform:
    translateX(-50%);
}

/* ANIMATIONS */

@keyframes novaHeroVideoZoom {
  from {
    transform: scale(1.04);
  }

  to {
    transform: scale(1.08);
  }
}

@keyframes novaHeroTopIn {
  from {
    opacity: 0;

    transform:
      translate(-50%, -15px);
  }

  to {
    opacity: 1;

    transform:
      translate(-50%, 0);
  }
}

@keyframes novaTextEnter {
  from {
    opacity: 0;

    transform:
      translateY(65px);

    clip-path:
      inset(100% 0 0 0);
  }

  to {
    opacity: 1;

    transform:
      translateY(0);

    clip-path:
      inset(0 0 0 0);
  }
}

@keyframes novaTextExit {
  from {
    opacity: 1;

    transform:
      translateY(0);
  }

  to {
    opacity: 0;

    transform:
      translateY(-50px);

    clip-path:
      inset(0 0 100% 0);
  }
}

@keyframes novaIndicatorProgress {
  from {
    width: 0;
  }

  to {
    width: 100%;
  }
}

