/* =====================================================
   NOVADENT — RIVERMILES INSPIRED STATS
===================================================== */

.premiumStats {
  position: relative;
  padding: 105px 0 95px;
  background: #ffffff;
  overflow: hidden;
}

.premiumStats::before {
  content: "";
  position: absolute;
  top: 0;
  left: 7%;
  right: 7%;
  height: 1px;
  background: rgba(23, 63, 79, 0.12);
}

.statsGrid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  align-items: stretch;
}

/* Individual stat */

.statsGrid > div {
  position: relative;
  min-height: 210px;
  padding: 18px 38px 10px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-start;
  text-align: left;
  border-right: 1px solid rgba(23, 63, 79, 0.1);
  background: transparent;

  transition:
    transform 0.6s cubic-bezier(.2,.65,.2,1),
    background 0.5s ease;
}

.statsGrid > div:last-child {
  border-right: none;
}

/* Small number/icon */

.statsGrid svg {
  position: absolute;
  top: 18px;
  left: 38px;
  color: #0b8f91;
  stroke-width: 1.5;
  opacity: 0.9;

  transition:
    transform 0.5s cubic-bezier(.2,.65,.2,1),
    opacity 0.4s ease;
}

.statsGrid > div:hover svg {
  transform: translate(4px, -4px);
  opacity: 1;
}

/* Big number */

.statsGrid strong {
  display: block;
  margin: 0;

  color: #173f4f;
  font-size: clamp(48px, 5vw, 76px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.055em;

  transition:
    transform 0.55s cubic-bezier(.2,.65,.2,1),
    color 0.4s ease;
}

.statsGrid > div:hover strong {
  transform: translateX(5px);
  color: #0b8f91;
}

/* Label */

.statsGrid span {
  display: block;
  margin-top: 18px;

  color: #71858c;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

/* Bottom accent */

.statsGrid > div::after {
  content: "";
  position: absolute;
  left: 38px;
  bottom: 0;
  width: 28px;
  height: 2px;
  background: #0b8f91;

  transform: scaleX(1);
  transform-origin: left;

  transition:
    width 0.5s cubic-bezier(.2,.65,.2,1);
}

.statsGrid > div:hover::after {
  width: 58px;
}

/* =====================================================
   REVEAL
===================================================== */

.premiumStats[data-reveal] {
  opacity: 0;
  transform: translateY(35px);

  transition:
    opacity 0.9s ease,
    transform 0.9s cubic-bezier(.2,.65,.2,1);
}

.premiumStats[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* =====================================================
   STAGGER
===================================================== */

.statsGrid > div:nth-child(1) {
  transition-delay: 80ms;
}

.statsGrid > div:nth-child(2) {
  transition-delay: 160ms;
}

.statsGrid > div:nth-child(3) {
  transition-delay: 240ms;
}

.statsGrid > div:nth-child(4) {
  transition-delay: 320ms;
}

/* =====================================================
   TABLET
===================================================== */

@media (max-width: 900px) {

  .premiumStats {
    padding: 80px 0;
  }

  .statsGrid {
    grid-template-columns: repeat(2, 1fr);
    row-gap: 55px;
  }

  .statsGrid > div {
    min-height: 185px;
  }

  .statsGrid > div:nth-child(2) {
    border-right: none;
  }

  .statsGrid > div:nth-child(3),
  .statsGrid > div:nth-child(4) {
    border-top: 1px solid rgba(23, 63, 79, 0.1);
    padding-top: 35px;
  }

  .statsGrid > div:nth-child(3) {
    border-right: 1px solid rgba(23, 63, 79, 0.1);
  }
}

/* =====================================================
   MOBILE
===================================================== */

@media (max-width: 600px) {

  .premiumStats {
    padding: 65px 0 60px;
  }

  .premiumStats::before {
    left: 20px;
    right: 20px;
  }

  .statsGrid {
    grid-template-columns: 1fr 1fr;
    row-gap: 0;
  }

  .statsGrid > div {
    min-height: 155px;
    padding: 18px 18px 12px;
  }

  .statsGrid > div:nth-child(2) {
    border-right: none;
  }

  .statsGrid > div:nth-child(3),
  .statsGrid > div:nth-child(4) {
    border-top: 1px solid rgba(23, 63, 79, 0.1);
    padding-top: 28px;
  }

  .statsGrid > div:nth-child(3) {
    border-right: 1px solid rgba(23, 63, 79, 0.1);
  }

  .statsGrid svg {
    top: 18px;
    left: 18px;
    width: 17px;
    height: 17px;
  }

  .statsGrid strong {
    font-size: 40px;
  }

  .statsGrid span {
    margin-top: 12px;
    font-size: 8px;
    letter-spacing: 0.1em;
  }

  .statsGrid > div::after {
    left: 18px;
    width: 22px;
  }

  .statsGrid > div:hover::after {
    width: 42px;
  }
}

