.premiumTreatmentProcess {
  padding: 125px 0;
  background: #ffffff;
}

.premiumTreatmentProcessHeader {
  display: grid;
  grid-template-columns: 1fr 0.55fr;
  gap: 100px;
  align-items: end;
  margin-bottom: 70px;
}

.premiumTreatmentProcessHeader h2 {
  margin: 28px 0 0;
  color: var(--nova-navy);
  font-size: clamp(43px, 5vw, 70px);
  font-weight: 500;
  line-height: 0.98;
  letter-spacing: -0.05em;
}

.premiumTreatmentProcessHeader h2 em {
  display: block;
  color: var(--nova-teal);
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.premiumTreatmentProcessHeader > p {
  margin: 0;
  color: var(--nova-muted);
  font-size: 13px;
  line-height: 1.9;
}

.premiumTreatmentSteps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--nova-line);
  border-bottom: 1px solid var(--nova-line);
}

.premiumTreatmentStep {
  position: relative;
  min-height: 330px;
  padding: 35px 40px;
  border-right: 1px solid var(--nova-line);
  transition:
    background 0.4s ease,
    transform 0.4s ease;
}

.premiumTreatmentStep:last-child {
  border-right: none;
}

.premiumTreatmentStep:hover {
  background: #f7fafb;
  transform: translateY(-5px);
}

.premiumTreatmentStepTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.premiumTreatmentStepTop > span {
  color: var(--nova-teal);
  font-size: 11px;
  font-weight: 800;
}

.premiumTreatmentStepTop > div {
  color: var(--nova-teal);
}

.premiumTreatmentStep h3 {
  margin: 75px 0 15px;
  color: var(--nova-navy);
  font-size: 25px;
  font-weight: 600;
}

.premiumTreatmentStep p {
  max-width: 310px;
  margin: 0;
  color: var(--nova-muted);
  font-size: 12px;
  line-height: 1.8;
}

.premiumTreatmentStepArrow {
  position: absolute;
  right: 40px;
  bottom: 35px;
  color: var(--nova-navy);
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.premiumTreatmentStep:hover .premiumTreatmentStepArrow {
  transform: translate(4px,-4px);
  color: var(--nova-teal);
}


/* =========================================================
   FAQ
   ========================================================= */

.premiumTreatmentFAQ {
  padding: 125px 0;
  background: #f7fafb;
}

.premiumTreatmentFAQGrid {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 120px;
  align-items: start;
}

.premiumTreatmentFAQIntro h2 {
  margin: 28px 0 22px;
  color: var(--nova-navy);
  font-size: clamp(44px, 5vw, 70px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.05em;
}

.premiumTreatmentFAQIntro h2 em {
  display: block;
  color: var(--nova-teal);
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.premiumTreatmentFAQIntro p {
  max-width: 410px;
  margin: 0;
  color: var(--nova-muted);
  font-size: 13px;
  line-height: 1.9;
}

.premiumTreatmentOutlineButton {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 30px;
  padding-bottom: 8px;
  color: var(--nova-navy);
  border-bottom: 1px solid var(--nova-teal);
  text-decoration: none;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  transition:
    gap 0.35s ease,
    color 0.35s ease;
}

.premiumTreatmentOutlineButton:hover {
  gap: 18px;
  color: var(--nova-teal);
}

.premiumTreatmentFAQList {
  border-top: 1px solid var(--nova-line);
}

.premiumTreatmentFAQItem {
  border-bottom: 1px solid var(--nova-line);
}

.premiumTreatmentFAQItem button {
  width: 100%;
  display: grid;
  grid-template-columns: 45px 1fr 22px;
  gap: 15px;
  align-items: center;
  padding: 25px 0;
  border: none;
  background: transparent;
  color: var(--nova-navy);
  text-align: left;
  cursor: pointer;
}

.premiumTreatmentFAQNumber {
  color: var(--nova-teal);
  font-size: 9px;
  font-weight: 800;
}

.premiumTreatmentFAQQuestion {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.5;
}

.premiumTreatmentFAQItem button > svg {
  color: var(--nova-navy);
  transition:
    transform 0.35s ease,
    color 0.35s ease;
}

.premiumTreatmentFAQItem.is-open button > svg {
  transform: rotate(180deg);
  color: var(--nova-teal);
}

.premiumTreatmentFAQAnswer {
  display: grid;
  grid-template-rows: 0fr;
  transition:
    grid-template-rows 0.45s ease;
}

.premiumTreatmentFAQAnswer p {
  overflow: hidden;
  margin: 0;
  color: var(--nova-muted);
  font-size: 12px;
  line-height: 1.85;
  opacity: 0;
  transition:
    opacity 0.35s ease,
    padding 0.35s ease;
}

.premiumTreatmentFAQItem.is-open
.premiumTreatmentFAQAnswer {
  grid-template-rows: 1fr;
}

.premiumTreatmentFAQItem.is-open
.premiumTreatmentFAQAnswer p {
  padding: 0 0 25px 60px;
  opacity: 1;
}


/* =========================================================
   CTA
   ========================================================= */

.premiumTreatmentCTA {
  position: relative;
  min-height: 620px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--nova-deep);
  color: #ffffff;
}

.premiumTreatmentCTAImage {
  position: absolute;
  inset: 0;
}

.premiumTreatmentCTAImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  opacity: 0.48;
}

.premiumTreatmentCTAOverlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(16,47,60,0.94) 0%,
      rgba(16,47,60,0.72) 55%,
      rgba(16,47,60,0.4) 100%
    ),
    linear-gradient(
      180deg,
      rgba(16,47,60,0.35),
      rgba(16,47,60,0.65)
    );
}

.premiumTreatmentCTA .premiumTreatmentContainer {
  position: relative;
  z-index: 2;
}

.premiumTreatmentCTAContent {
  max-width: 720px;
}

.premiumTreatmentSectionLabelLight {
  color: #63c9c7;
}

.premiumTreatmentSectionLabelLight span:first-child {
  color: #ffffff;
}

.premiumTreatmentCTAContent h2 {
  margin: 30px 0 22px;
  color: #ffffff;
  font-size: clamp(50px, 6vw, 88px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.055em;
}

.premiumTreatmentCTAContent h2 em {
  display: block;
  color: rgba(255,255,255,0.65);
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
}

.premiumTreatmentCTAContent > p {
  max-width: 550px;
  margin: 0;
  color: rgba(255,255,255,0.72);
  font-size: 14px;
  line-height: 1.9;
}

.premiumTreatmentCTAButtons {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 35px;
}

.premiumTreatmentPrimaryButton,
.premiumTreatmentSecondaryButton {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  padding: 14px 18px;
  text-decoration: none;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  transition:
    transform 0.35s ease,
    background 0.35s ease,
    color 0.35s ease;
}

.premiumTreatmentPrimaryButton {
  color: #ffffff;
  background: var(--nova-teal);
}

.premiumTreatmentSecondaryButton {
  color: #ffffff;
  border: 1px solid rgba(255,255,255,0.3);
}

.premiumTreatmentPrimaryButton:hover,
.premiumTreatmentSecondaryButton:hover {
  transform: translateY(-3px);
}

.premiumTreatmentPrimaryButton:hover {
  background: var(--nova-teal-dark);
}

.premiumTreatmentSecondaryButton:hover {
  background: #ffffff;
  color: var(--nova-navy);
}


