/* =========================================================
   ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .premiumTreatmentHeroMedia img,
  .premiumTreatmentImageFrame img,
  .premiumTreatmentHeroButton,
  .premiumTreatmentLink,
  .premiumTreatmentStep,
  .premiumTreatmentFAQAnswer,
  .premiumTreatmentFAQAnswer p {
    animation: none !important;
    transition: none !important;
  }

}
/* =========================================================
   PREMIUM ALTERNATING LEFT / RIGHT REVEAL
   ========================================================= */

.premiumTreatmentItem {
  opacity: 0;
  transform: translateX(-100px);
  transition:
    opacity 1s cubic-bezier(.22,.61,.36,1),
    transform 1.1s cubic-bezier(.22,.61,.36,1);
  will-change: transform, opacity;
}

/* Even / Right-side cards */
.premiumTreatmentItem:nth-child(even) {
  transform: translateX(100px);
}

/* When visible */
.premiumTreatmentItem.is-visible {
  opacity: 1;
  transform: translateX(0);
}


/* =========================================================
   IMAGE + CONTENT REVEAL
   ========================================================= */

.premiumTreatmentItem .premiumTreatmentVisual {
  opacity: 0;
  transform: scale(.97);
  transition:
    opacity .9s ease .15s,
    transform 1.1s cubic-bezier(.22,.61,.36,1) .15s;
}

.premiumTreatmentItem .premiumTreatmentContent {
  opacity: 0;
  transform: translateY(35px);
  transition:
    opacity .8s ease .3s,
    transform .9s cubic-bezier(.22,.61,.36,1) .3s;
}

.premiumTreatmentItem.is-visible .premiumTreatmentVisual {
  opacity: 1;
  transform: scale(1);
}

.premiumTreatmentItem.is-visible .premiumTreatmentContent {
  opacity: 1;
  transform: translateY(0);
}


/* =========================================================
   STAGGER CONTENT
   ========================================================= */

.premiumTreatmentItem:nth-child(1) {
  transition-delay: 0ms;
}

.premiumTreatmentItem:nth-child(2) {
  transition-delay: 80ms;
}

.premiumTreatmentItem:nth-child(3) {
  transition-delay: 0ms;
}

.premiumTreatmentItem:nth-child(4) {
  transition-delay: 80ms;
}

.premiumTreatmentItem:nth-child(5) {
  transition-delay: 0ms;
}

.premiumTreatmentItem:nth-child(6) {
  transition-delay: 80ms;
}


/* =========================================================
   PREMIUM IMAGE MOTION
   ========================================================= */

.premiumTreatmentImageFrame {
  overflow: hidden;
}

.premiumTreatmentImageFrame img {
  transform: scale(1.08);
  transition:
    transform 1.5s cubic-bezier(.16,1,.3,1),
    filter 1s ease;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentImageFrame img {
  transform: scale(1);
}

.premiumTreatmentItem:hover
.premiumTreatmentImageFrame img {
  transform: scale(1.055);
  filter: brightness(1.03) saturate(1.04);
}


/* =========================================================
   TEXT ELEMENTS ENTER AFTER CARD
   ========================================================= */

.premiumTreatmentContentTop,
.premiumTreatmentContent h3,
.premiumTreatmentRule,
.premiumTreatmentDescription,
.premiumTreatmentTags,
.premiumTreatmentLink {
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity .7s ease,
    transform .7s cubic-bezier(.22,.61,.36,1);
}

.premiumTreatmentItem.is-visible
.premiumTreatmentContentTop {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .25s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentContent h3 {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .35s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentRule {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .42s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentDescription {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .48s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentTags {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .55s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentLink {
  opacity: 1;
  transform: translateY(0);
  transition-delay: .65s;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .premiumTreatmentItem,
  .premiumTreatmentItem:nth-child(even) {
    transform: translateY(55px);
  }

  .premiumTreatmentItem.is-visible {
    transform: translateY(0);
  }

  .premiumTreatmentItem .premiumTreatmentVisual {
    transform: translateY(25px) scale(.98);
  }

  .premiumTreatmentItem.is-visible
  .premiumTreatmentVisual {
    transform: translateY(0) scale(1);
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .premiumTreatmentItem,
  .premiumTreatmentItem:nth-child(even),
  .premiumTreatmentItem .premiumTreatmentVisual,
  .premiumTreatmentItem .premiumTreatmentContent,
  .premiumTreatmentContentTop,
  .premiumTreatmentContent h3,
  .premiumTreatmentRule,
  .premiumTreatmentDescription,
  .premiumTreatmentTags,
  .premiumTreatmentLink {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }

}
/* =========================================================
   NOVADENT — LEFT / RIGHT CINEMATIC REVEAL
   NO BOTTOM / TOP MOVEMENT
   ========================================================= */

.premiumTreatmentItem {
  opacity: 0;
  transform: translateX(-120px) scale(0.97);
  transition:
    opacity 1s cubic-bezier(.22,.61,.36,1),
    transform 1.15s cubic-bezier(.22,.61,.36,1);
  will-change: transform, opacity;
}

/* 02, 04, 06 → RIGHT SIDE */
.premiumTreatmentItem:nth-child(even) {
  transform: translateX(120px) scale(0.97);
}

/* Final position */
.premiumTreatmentItem.is-visible {
  opacity: 1;
  transform: translateX(0) scale(1);
}


/* =========================================================
   IMAGE
   ========================================================= */

.premiumTreatmentItem .premiumTreatmentVisual {
  opacity: 0;
  transition:
    opacity 0.9s ease 0.12s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentVisual {
  opacity: 1;
}


/* =========================================================
   CONTENT
   ========================================================= */

.premiumTreatmentItem .premiumTreatmentContent {
  opacity: 0;
  transition:
    opacity 0.8s ease 0.25s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentContent {
  opacity: 1;
}


/* =========================================================
   IMAGE CINEMATIC ZOOM
   ========================================================= */

.premiumTreatmentImageFrame {
  overflow: hidden;
}

.premiumTreatmentImageFrame img {
  transform: scale(1.08);
  transition:
    transform 1.5s cubic-bezier(.16,1,.3,1),
    filter 1s ease;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentImageFrame img {
  transform: scale(1);
}

.premiumTreatmentItem:hover
.premiumTreatmentImageFrame img {
  transform: scale(1.055);
  filter: brightness(1.03) saturate(1.04);
}


/* =========================================================
   TEXT STAGGER — ONLY FADE
   NO VERTICAL MOVEMENT
   ========================================================= */

.premiumTreatmentContentTop,
.premiumTreatmentContent h3,
.premiumTreatmentRule,
.premiumTreatmentDescription,
.premiumTreatmentTags,
.premiumTreatmentLink {
  opacity: 0;
  transform: none !important;
  transition:
    opacity 0.65s ease;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentContentTop {
  opacity: 1;
  transition-delay: 0.25s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentContent h3 {
  opacity: 1;
  transition-delay: 0.35s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentRule {
  opacity: 1;
  transition-delay: 0.42s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentDescription {
  opacity: 1;
  transition-delay: 0.48s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentTags {
  opacity: 1;
  transition-delay: 0.55s;
}

.premiumTreatmentItem.is-visible
.premiumTreatmentLink {
  opacity: 1;
  transition-delay: 0.62s;
}


/* =========================================================
   MOBILE
   STILL LEFT / RIGHT — NO UP/DOWN
   ========================================================= */

@media (max-width: 700px) {

  .premiumTreatmentItem {
    transform: translateX(-55px) scale(0.98);
  }

  .premiumTreatmentItem:nth-child(even) {
    transform: translateX(55px) scale(0.98);
  }

  .premiumTreatmentItem.is-visible,
  .premiumTreatmentItem:nth-child(even).is-visible {
    transform: translateX(0) scale(1);
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .premiumTreatmentItem,
  .premiumTreatmentItem:nth-child(even),
  .premiumTreatmentItem .premiumTreatmentVisual,
  .premiumTreatmentItem .premiumTreatmentContent,
  .premiumTreatmentContentTop,
  .premiumTreatmentContent h3,
  .premiumTreatmentRule,
  .premiumTreatmentDescription,
  .premiumTreatmentTags,
  .premiumTreatmentLink {
    opacity: 1 !important;
