/* =========================================================
   NOVADENT — CINEMATIC RIVERSMILE-STYLE REVEAL SYSTEM
   ========================================================= */

:root {
  --nova-ease: cubic-bezier(.16, 1, .3, 1);
  --nova-ease-soft: cubic-bezier(.22, .61, .36, 1);
}


/* ---------------------------------------------------------
   BASE REVEAL
   --------------------------------------------------------- */

.novaReveal {
  opacity: 0;
  transform: translateY(55px);
  transition:
    opacity 1s var(--nova-ease),
    transform 1.15s var(--nova-ease);
}

.novaReveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}


/* ---------------------------------------------------------
   LEFT / RIGHT REVEALS
   --------------------------------------------------------- */

.novaRevealLeft {
  opacity: 0;
  transform: translateX(-90px);
  transition:
    opacity 1s var(--nova-ease),
    transform 1.15s var(--nova-ease);
}

.novaRevealRight {
  opacity: 0;
  transform: translateX(90px);
  transition:
    opacity 1s var(--nova-ease),
    transform 1.15s var(--nova-ease);
}

.novaRevealLeft.is-visible,
.novaRevealRight.is-visible {
  opacity: 1;
  transform: translateX(0);
}


/* ---------------------------------------------------------
   SCALE REVEAL
   --------------------------------------------------------- */

.novaRevealScale {
  opacity: 0;
  transform: scale(.92);
  transition:
    opacity 1s var(--nova-ease),
    transform 1.3s var(--nova-ease);
}

.novaRevealScale.is-visible {
  opacity: 1;
  transform: scale(1);
}


/* ---------------------------------------------------------
   IMAGE MASK REVEAL
   --------------------------------------------------------- */

.novaImageReveal {
  overflow: hidden;
  clip-path: inset(0 100% 0 0);
  transition:
    clip-path 1.35s var(--nova-ease);
}

.novaImageReveal.is-visible {
  clip-path: inset(0 0 0 0);
}

.novaImageReveal img {
  transform: scale(1.12);
  transition:
    transform 1.8s var(--nova-ease);
}

.novaImageReveal.is-visible img {
  transform: scale(1);
}


/* ---------------------------------------------------------
   RIGHT IMAGE MASK
   --------------------------------------------------------- */

.novaImageRevealRight {
  overflow: hidden;
  clip-path: inset(0 0 0 100%);
  transition:
    clip-path 1.35s var(--nova-ease);
}

.novaImageRevealRight.is-visible {
  clip-path: inset(0 0 0 0);
}

.novaImageRevealRight img {
  transform: scale(1.12);
  transition:
    transform 1.8s var(--nova-ease);
}

.novaImageRevealRight.is-visible img {
  transform: scale(1);
}


/* ---------------------------------------------------------
   TEXT STAGGER
   --------------------------------------------------------- */

.novaStagger > * {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity .85s var(--nova-ease),
    transform .95s var(--nova-ease);
}

.novaStagger.is-visible > *:nth-child(1) {
  transition-delay: 80ms;
}

.novaStagger.is-visible > *:nth-child(2) {
  transition-delay: 160ms;
}

.novaStagger.is-visible > *:nth-child(3) {
  transition-delay: 240ms;
}

.novaStagger.is-visible > *:nth-child(4) {
  transition-delay: 320ms;
}

.novaStagger.is-visible > *:nth-child(5) {
  transition-delay: 400ms;
}

.novaStagger.is-visible > * {
  opacity: 1;
  transform: translateY(0);
}


/* ---------------------------------------------------------
   CINEMATIC CARD REVEAL
   --------------------------------------------------------- */

.novaCardReveal {
  opacity: 0;
  transform:
    translateX(-100px)
    scale(.94);

  transition:
    opacity 1s var(--nova-ease),
    transform 1.2s var(--nova-ease);
}

.novaCardReveal:nth-child(even) {
  transform:
    translateX(100px)
    scale(.94);
}

.novaCardReveal.is-visible {
  opacity: 1;
  transform:
    translateX(0)
    scale(1);
}


/* ---------------------------------------------------------
   CARD STAGGER
   --------------------------------------------------------- */

.novaCardReveal:nth-child(1) {
  transition-delay: 50ms;
}

.novaCardReveal:nth-child(2) {
  transition-delay: 130ms;
}

.novaCardReveal:nth-child(3) {
  transition-delay: 210ms;
}

.novaCardReveal:nth-child(4) {
  transition-delay: 290ms;
}

.novaCardReveal:nth-child(5) {
  transition-delay: 370ms;
}

.novaCardReveal:nth-child(6) {
  transition-delay: 450ms;
}


/* ---------------------------------------------------------
   PREMIUM CARD HOVER
   --------------------------------------------------------- */

.novaAnimatedCard {
  position: relative;
  overflow: hidden;
  transition:
    transform .65s var(--nova-ease),
    box-shadow .65s ease;
}

.novaAnimatedCard:hover {
  transform: translateY(-8px);
  box-shadow:
    0 28px 65px rgba(23, 63, 79, .14);
}

.novaAnimatedCard img {
  transition:
    transform 1.2s var(--nova-ease),
    filter .8s ease;
}

.novaAnimatedCard:hover img {
  transform: scale(1.055);
  filter: brightness(1.03);
}


/* ---------------------------------------------------------
   IMAGE OVERLAY
   --------------------------------------------------------- */

.novaAnimatedCard::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;

  background:
    linear-gradient(
      180deg,
      rgba(23,63,79,0) 45%,
      rgba(23,63,79,.18) 100%
    );

  opacity: .7;

  transition:
    opacity .7s ease;
}

.novaAnimatedCard:hover::after {
  opacity: .45;
}


/* ---------------------------------------------------------
   FLOATING ELEMENT
   --------------------------------------------------------- */

.novaFloat {
  animation:
    novaFloatAnimation 5s ease-in-out infinite;
}

@keyframes novaFloatAnimation {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-8px);
  }

}


/* ---------------------------------------------------------
   LINE REVEAL
   --------------------------------------------------------- */

.novaLineReveal {
  position: relative;
  overflow: hidden;
}

.novaLineReveal::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;

  width: 100%;
  height: 1px;

  background: #0b8f91;

  transform:
    scaleX(0);

  transform-origin: left;

  transition:
    transform 1s var(--nova-ease);
}

.novaLineReveal.is-visible::after {
  transform: scaleX(1);
}


/* ---------------------------------------------------------
   NUMBER / BADGE
   --------------------------------------------------------- */

.novaNumberReveal {
  opacity: 0;
  transform: scale(.7);
  transition:
    opacity .7s ease,
    transform .8s var(--nova-ease);
}

.novaNumberReveal.is-visible {
  opacity: 1;
  transform: scale(1);
}


/* ---------------------------------------------------------
   BUTTON REVEAL
   --------------------------------------------------------- */

.novaButtonReveal {
  opacity: 0;
  transform: translateY(20px);
  transition:
    opacity .8s var(--nova-ease),
    transform .9s var(--nova-ease);
}

.novaButtonReveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}


/* ---------------------------------------------------------
   MOBILE
   --------------------------------------------------------- */

@media (max-width: 700px) {

  .novaRevealLeft {
    transform: translateX(-45px);
  }

  .novaRevealRight {
    transform: translateX(45px);
  }

  .novaCardReveal {
    transform:
      translateX(-45px)
      scale(.97);
  }

  .novaCardReveal:nth-child(even) {
    transform:
      translateX(45px)
      scale(.97);
  }

  .novaImageReveal,
  .novaImageRevealRight {
    clip-path: inset(0 0 100% 0);
  }

  .novaImageReveal.is-visible,
  .novaImageRevealRight.is-visible {
    clip-path: inset(0 0 0 0);
  }

}
