  gap: 4px;

  color: #0b8f91;

  margin-bottom: 28px;
}

.novaReviewCard > p {
  margin: 0;

  color: var(--nova-dark);

  font-size: 16px;

  line-height: 1.8;
}

.novaReviewPerson {
  position: absolute;

  left: 35px;
  right: 35px;
  bottom: 28px;

  display: flex;

  align-items: center;

  gap: 12px;

  padding-top: 18px;

  border-top:
    1px solid
    rgba(23,63,79,.1);
}

.novaReviewAvatar {
  width: 35px;
  height: 35px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #173f4f;

  color: #fff;

  font-size: 11px;

  font-weight: 800;
}

.novaReviewPerson strong {
  display: block;

  color: var(--nova-dark);

  font-size: 11px;
}

.novaReviewPerson span {
  display: block;

  margin-top: 3px;

  color: #71858c;

  font-size: 9px;
}


/* =========================================================
   APPOINTMENT CTA
========================================================= */

.novaAppointmentCTA {
  padding:
    110px
    0;

  background: #f7fafb;

  overflow: hidden;
}

.novaAppointmentGrid {
  display: grid;

  grid-template-columns:
    1fr
    1fr;

  min-height: 650px;

  background: #173f4f;
}

.novaAppointmentImage {
  position: relative;

  overflow: hidden;
}

.novaAppointmentImage img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transform: scale(1.1);

  transition:
    transform 1.7s var(--nova-motion-ease);
}

.novaAppointmentImage.is-visible img {
  transform: scale(1);
}

.novaAppointmentImageOverlay {
  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      180deg,
      rgba(23,63,79,.04),
      rgba(23,63,79,.72)
    );
}

.novaAppointmentImageText {
  position: absolute;

  left: 35px;
  bottom: 35px;

  color: #fff;
}

.novaAppointmentImageText span {
  display: block;

  margin-bottom: 10px;

  color: rgba(255,255,255,.7);

  font-size: 9px;

  font-weight: 800;

  letter-spacing: .15em;
}

.novaAppointmentImageText strong {
  display: block;

  font-size: 31px;

  line-height: 1.2;
}

.novaAppointmentContent {
  display: flex;

  flex-direction: column;

  justify-content: center;

  padding:
    70px;

  color: #fff;
}

.novaAppointmentContent .storyKicker {
  color: #77cacc;
}

.novaAppointmentContent .storyIndex {
  color: rgba(255,255,255,.5);
}

.novaAppointmentContent h2 {
  margin:
    18px
    0
    22px;

  color: #fff;

  font-size: clamp(
    38px,
    4vw,
    64px
  );

  line-height: 1.04;
}

.novaAppointmentContent h2 em {
  color: #77cacc;

  font-style: normal;
}

.novaAppointmentContent > p {
  max-width: 500px;

  margin: 0;

  color: rgba(255,255,255,.68);

  font-size: 14px;

  line-height: 1.85;
}

.novaAppointmentInfo {
  display: grid;

  grid-template-columns:
    repeat(3,1fr);

  gap: 20px;

  margin:
    38px
    0;

  padding:
    25px 0;

  border-top:
    1px solid
    rgba(255,255,255,.15);

  border-bottom:
    1px solid
    rgba(255,255,255,.15);
}

.novaAppointmentInfo small {
  display: block;

  margin-bottom: 6px;

  color: #77cacc;

  font-size: 8px;

  font-weight: 800;

  letter-spacing: .12em;
}

.novaAppointmentInfo strong,
.novaAppointmentInfo a {
  color: #fff;

  font-size: 11px;

  line-height: 1.5;

  text-decoration: none;
}

.novaAppointmentButtons {
  display: flex;

  flex-wrap: wrap;

  gap: 15px;
}

.novaAppointmentPrimary,
.novaAppointmentSecondary {
  display: inline-flex;

  align-items: center;

  justify-content: center;

  gap: 9px;

  min-height: 50px;

  padding:
    0
    22px;

  font-size: 10px;

  font-weight: 800;

  letter-spacing: .08em;

  text-decoration: none;

  transition:
    transform .4s var(--nova-motion-ease),
    gap .4s ease,
    background .4s ease;
}

.novaAppointmentPrimary {
  background: #fff;

  color: #173f4f;
}

.novaAppointmentSecondary {
  border:
    1px solid
    rgba(255,255,255,.3);

  color: #fff;
}

.novaAppointmentPrimary:hover,
.novaAppointmentSecondary:hover {
  transform: translateY(-4px);
  gap: 13px;
}

.novaAppointmentSecondary:hover {
  background:
    rgba(255,255,255,.08);
}


/* =========================================================
   BUTTON REVEAL
========================================================= */

.novaButtonReveal {
  opacity: 0;

  transform:
    translateY(25px);

  transition:
    opacity .85s var(--nova-motion-ease),
    transform .95s var(--nova-motion-ease);
}

.novaButtonReveal.is-visible {
  opacity: 1;

  transform:
    translateY(0);
}


/* =========================================================
   HOME TREATMENT COLLECTION
========================================================= */

.novaTreatmentCollection {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;

  margin-top: 60px;

  padding:
    22px
    0;

  border-top:
    1px solid
    rgba(23,63,79,.12);

  border-bottom:
    1px solid
    rgba(23,63,79,.12);
}

.novaTreatmentCollection > span {
  color: #71858c;

  font-size: 9px;

  font-weight: 800;

  letter-spacing: .13em;
}

.novaTreatmentCollection a {
  display: inline-flex;

  align-items: center;

  gap: 8px;

  color: var(--nova-dark);

  font-size: 10px;

  font-weight: 800;

  text-decoration: none;

  transition:
    gap .4s ease,
    color .4s ease;
}

.novaTreatmentCollection a:hover {
  gap: 14px;

  color: var(--nova-teal);
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 1000px) {

  .novaPhilosophyGrid {
    grid-template-columns:
      repeat(2,1fr);
  }

  .novaDoctorsGrid,
  .novaReviewsGrid {
    grid-template-columns:
      repeat(2,1fr);
  }

  .novaAppointmentGrid {
    grid-template-columns: 1fr;
  }

  .novaAppointmentImage {
    min-height: 500px;
  }

  .novaPhilosophyHeading,
  .novaDoctorsHeading,
  .novaReviewsHeading {
    grid-template-columns: 1fr;

    gap: 25px;
  }

}


@media (max-width: 900px) {

  .novaCinematicLeft {
    transform:
      translateX(-65px)
      scale(.98);
  }

  .novaCinematicRight {
    transform:
      translateX(65px)
      scale(.98);
  }

  .novaPhilosophySection,
  .novaDoctorsSection,
  .novaReviewsSection {
    padding:
      85px
      0;
  }

  .novaAppointmentCTA {
    padding:
      75px
      0;
  }

}


@media (max-width: 700px) {

  .novaCinematicLeft {
    transform:
      translateX(-45px)
      scale(.985);
  }

  .novaCinematicRight {
    transform:
      translateX(45px)
      scale(.985);
  }

  .novaCinematicScale {
    transform:
      scale(.94)
      translateY(20px);
  }

  .novaStagger > * {
    transform:
      translateY(22px);
  }


  /* Philosophy */

  .novaPhilosophySection {
    padding:
      70px
      0;
  }

  .novaPhilosophyGrid {
    grid-template-columns: 1fr;
  }

  .novaPhilosophyCard {
    min-height: 270px;
  }


  /* Doctors */

  .novaDoctorsSection {
    padding:
      70px
      0;
  }

  .novaDoctorsGrid {
    grid-template-columns: 1fr;
    gap: 45px;
  }

  .novaDoctorImage {
    height: 420px;
  }


  /* Reviews */

  .novaReviewsSection {
    padding:
      70px
      0;
  }

  .novaReviewsGrid {
    grid-template-columns: 1fr;
  }

  .novaReviewCard {
    min-height: 300px;
  }


  /* Appointment */

  .novaAppointmentCTA {
    padding:
      55px
      0;
  }

  .novaAppointmentImage {
    min-height: 390px;
  }

  .novaAppointmentContent {
    padding:
      45px
      25px;
  }

  .novaAppointmentContent h2 {
    font-size: 39px;
  }

  .novaAppointmentInfo {
    grid-template-columns: 1fr;

    gap: 16px;
  }

  .novaAppointmentButtons {
    flex-direction: column;
  }

  .novaAppointmentPrimary,
  .novaAppointmentSecondary {
    width: 100%;
  }


  /* Treatment */

  .novaTreatmentCollection {
    flex-direction: column;

    align-items: flex-start;
  }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

  .novaCinematicReveal,
  .novaCinematicLeft,
  .novaCinematicRight,
  .novaCinematicScale,
  .novaImageMask,
  .novaImageMaskRight,
  .novaStagger > *,
  .novaTreatmentStory,
  .novaStatReveal,
  .novaDoctorCard,
  .novaReviewCard,
  .novaButtonReveal {
    opacity: 1 !important;

    transform: none !important;

    clip-path: none !important;

    transition: none !important;
  }

}
