/* =========================================================
   NOVADENT — RIVERSMILE INSPIRED CINEMATIC HERO
   ========================================================= */

.novaHero {
  position: relative;
  width: 100%;
  height: 100svh;
  min-height: 720px;
  overflow: hidden;
  isolation: isolate;
  background: #071c27;
  color: #fff;
}

/* VIDEO */

.novaHeroMedia {
  position: absolute;
  inset: 0;
  z-index: -3;
  overflow: hidden;
}

.novaHeroVideo {
  position: absolute;
  inset: -2%;
  width: 104%;
  height: 104%;
  object-fit: cover;
  object-position: center;
  display: block;

  filter:
    brightness(.72)
    saturate(.86)
    contrast(1.03);

  animation: novaHeroVideoMotion 18s ease-in-out infinite alternate;
}

@keyframes novaHeroVideoMotion {
  from {
    transform: scale(1);
  }

  to {
    transform: scale(1.055);
  }
}

/* CINEMATIC OVERLAY */

.novaHeroOverlay {
  position: absolute;
  inset: 0;
  z-index: -2;

  background:
    linear-gradient(
      90deg,
      rgba(3, 19, 29, .78) 0%,
      rgba(3, 19, 29, .48) 40%,
      rgba(3, 19, 29, .20) 75%,
      rgba(3, 19, 29, .32) 100%
    ),
    linear-gradient(
      180deg,
      rgba(0,0,0,.28),
      transparent 38%,
      rgba(0,0,0,.58)
    );
}

.novaHeroGlow {
  position: absolute;
  width: 480px;
  height: 480px;
  left: 50%;
  top: 45%;
  transform: translate(-50%, -50%);
  border-radius: 50%;

  background: rgba(70, 205, 208, .10);
  filter: blur(80px);
  pointer-events: none;
}

/* TOP LABEL */

.novaHeroTopLabel {
  position: absolute;
  top: 32px;
  left: 50%;
  transform: translateX(-50%);

  display: flex;
  align-items: center;
  gap: 9px;

  z-index: 10;

  color: rgba(255,255,255,.82);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .22em;
  white-space: nowrap;
}

.novaHeroTopLabel svg {
  color: #8de1df;
}

/* MAIN CONTENT */

.novaHeroContent {
  position: relative;
  z-index: 5;

  width: min(1100px, calc(100% - 80px));
  min-height: 100svh;

  margin: 0 auto;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  padding: 100px 0 180px;

  text-align: center;
}

/* EYEBROW */

.novaHeroEyebrow {
  display: flex;
  align-items: center;
  gap: 15px;

  margin-bottom: 27px;

  color: #b7ecea;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .27em;
}

.novaHeroEyebrow span {
  width: 42px;
  height: 1px;
  background: rgba(255,255,255,.5);
}

/* TITLE */

.novaHeroText {
  max-width: 950px;
}

.novaHeroText h1 {
  margin: 0;

  font-family:
    "Playfair Display",
    Georgia,
    serif;

  font-size: clamp(58px, 8vw, 112px);
  font-weight: 400;
  line-height: .92;
  letter-spacing: -.055em;
}

.novaHeroText h1 span,
.novaHeroText h1 em {
  display: block;
}

.novaHeroText h1 em {
  margin-top: 7px;

  color: #a9e9e6;
  font-style: italic;
  font-weight: 400;
}

/* DESCRIPTION */

.novaHeroText p {
  max-width: 610px;

  margin: 30px auto 0;

  color: rgba(255,255,255,.82);

  font-size: 15px;
  line-height: 1.8;
}

/* BUTTONS */

.novaHeroActions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;

  margin-top: 31px;
}

.novaHeroPrimary,
.novaHeroSecondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;

  min-height: 52px;

  padding: 0 23px;

  text-decoration: none;

  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;

  transition:
    transform .4s ease,
    background .4s ease,
    border-color .4s ease,
    color .4s ease;
}

.novaHeroPrimary {
  color: #07313e;
  background: #fff;
}

.novaHeroPrimary:hover {
  transform: translateY(-4px);
  background: #9de3e0;
}

.novaHeroSecondary {
  color: #fff;
  border: 1px solid rgba(255,255,255,.5);
  background: rgba(255,255,255,.06);
  backdrop-filter: blur(10px);
}

.novaHeroSecondary:hover {
  transform: translateY(-4px);
  border-color: #9de3e0;
  color: #9de3e0;
}

/* TEXT ANIMATION */

.heroEnter {
  animation: novaHeroTextIn .9s cubic-bezier(.16,1,.3,1) both;
}

.heroExit {
  animation: novaHeroTextOut .45s ease both;
}

@keyframes novaHeroTextIn {
  from {
    opacity: 0;
    transform:
      translateY(55px);
    filter: blur(8px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
    filter: blur(0);
  }
}

@keyframes novaHeroTextOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }

  to {
    opacity: 0;
    transform: translateY(-25px);
  }
}

/* BOTTOM INFORMATION */

.novaHeroBottom {
  position: absolute;
  z-index: 8;

  left: 50%;
  bottom: 0;

  transform: translateX(-50%);

  width: min(1180px, calc(100% - 80px));

  display: grid;
  grid-template-columns:
    1fr
    1.2fr
    1fr
    auto;

  align-items: center;

  background: rgba(255,255,255,.97);
  color: #173f4f;

  border-top: 1px solid rgba(255,255,255,.2);
}

.novaHeroBottom > div {
  min-height: 92px;

  display: flex;
  flex-direction: column;
  justify-content: center;

  padding: 16px 24px;

  border-right: 1px solid rgba(23,63,79,.10);
}

.novaHeroBottom small {
  margin-bottom: 6px;

  color: #0b8f91;

  font-size: 8px;
  font-weight: 800;
  letter-spacing: .14em;
}

.novaHeroBottom strong,
.novaHeroBottom a {
  color: #173f4f;

  font-size: 12px;
  font-weight: 800;

  text-decoration: none;
}

.novaHeroBottom span {
  margin-top: 3px;

  color: #71858c;

  font-size: 9px;
}

.novaHeroBottomButton {
  min-height: 92px;

  display: flex;
  align-items: center;
  gap: 12px;

  padding: 0 25px;

  color: #fff;

  background: #173f4f;

  text-decoration: none;

  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;

  white-space: nowrap;

  transition: background .4s ease;
}

.novaHeroBottomButton:hover {
  background: #0b8f91;
}

/* SIDE LABEL */

.novaHeroSide {
  position: absolute;

  left: 25px;
  top: 50%;

  transform:
    translateY(-50%)
    rotate(-90deg);

  display: flex;
  gap: 22px;

  z-index: 8;

  color: rgba(255,255,255,.58);

  font-size: 7px;
  font-weight: 800;
  letter-spacing: .25em;
}

/* SCROLL */

.novaHeroScroll {
  position: absolute;

  right: 30px;
  bottom: 145px;

  z-index: 8;

  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;

  color: rgba(255,255,255,.75);

  font-size: 7px;
  font-weight: 800;
  letter-spacing: .18em;

  writing-mode: vertical-rl;
}

.novaHeroScroll svg {
  animation:
    novaScrollArrow
    1.8s
    ease-in-out
    infinite;
}

@keyframes novaScrollArrow {
  0%,100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(7px);
  }
}

/* COUNTER */

.novaHeroCounter {
  position: absolute;

  right: 30px;
  top: 50%;

  transform: translateY(-50%);

  z-index: 8;

  color: #fff;
}

.novaHeroCounter strong {
  font-family: Georgia, serif;
  font-size: 32px;
  font-weight: 400;
}

.novaHeroCounter span {
  color: rgba(255,255,255,.5);
  font-size: 9px;
}

/* =========================================================
   MOBILE
========================================================= */

