    transform 1.25s cubic-bezier(.16,1,.3,1) .12s;
}

.premiumHome .welcomeStory .novaWelcomeVisual.is-visible,
.premiumHome .welcomeStory .storyContent.is-visible {
  opacity: 1 !important;
  transform: translateX(0) !important;
}


/* =========================================================
   ALL CARDS — LEFT / RIGHT
   ========================================================= */

.premiumHome .principleCard,
.premiumHome .editorialService,
.premiumHome .editorialDoctor,
.premiumHome .premiumTreatmentItem,
.premiumHome .reviewCard {
  opacity: 0;
  transition:
    opacity 0.95s ease,
    transform 1.1s cubic-bezier(.16,1,.3,1);
}


/* ODD → LEFT */

.premiumHome .principleCard:nth-child(odd),
.premiumHome .editorialService:nth-child(odd),
.premiumHome .editorialDoctor:nth-child(odd),
.premiumHome .premiumTreatmentItem:nth-child(odd),
.premiumHome .reviewCard:nth-child(odd) {
  transform: translateX(-100px);
}


/* EVEN → RIGHT */

.premiumHome .principleCard:nth-child(even),
.premiumHome .editorialService:nth-child(even),
.premiumHome .editorialDoctor:nth-child(even),
.premiumHome .premiumTreatmentItem:nth-child(even),
.premiumHome .reviewCard:nth-child(even) {
  transform: translateX(100px);
}


/* ACTIVE */

.premiumHome .principleCard.is-visible,
.premiumHome .editorialService.is-visible,
.premiumHome .editorialDoctor.is-visible,
.premiumHome .premiumTreatmentItem.is-visible,
.premiumHome .reviewCard.is-visible {
  opacity: 1 !important;
  transform: translateX(0) !important;
}


/* =========================================================
   STAGGER
   ========================================================= */

.premiumHome .principleCard:nth-child(1),
.premiumHome .editorialService:nth-child(1),
.premiumHome .editorialDoctor:nth-child(1),
.premiumHome .premiumTreatmentItem:nth-child(1) {
  transition-delay: 0ms;
}

.premiumHome .principleCard:nth-child(2),
.premiumHome .editorialService:nth-child(2),
.premiumHome .editorialDoctor:nth-child(2),
.premiumHome .premiumTreatmentItem:nth-child(2) {
  transition-delay: 100ms;
}

.premiumHome .principleCard:nth-child(3),
.premiumHome .editorialService:nth-child(3),
.premiumHome .editorialDoctor:nth-child(3),
.premiumHome .premiumTreatmentItem:nth-child(3) {
  transition-delay: 200ms;
}

.premiumHome .principleCard:nth-child(4),
.premiumHome .editorialService:nth-child(4),
.premiumHome .editorialDoctor:nth-child(4),
.premiumHome .premiumTreatmentItem:nth-child(4) {
  transition-delay: 300ms;
}

.premiumHome .premiumTreatmentItem:nth-child(5) {
  transition-delay: 400ms;
}

.premiumHome .premiumTreatmentItem:nth-child(6) {
  transition-delay: 500ms;
}


/* =========================================================
   CARD IMAGE CINEMATIC REVEAL
   ========================================================= */

.premiumHome .editorialServiceImage,
.premiumHome .editorialDoctorImage,
.premiumHome .premiumTreatmentImageFrame,
.premiumHome .novaWelcomeMainImage,
.premiumHome .novaWelcomeSecondImage,
.premiumHome .founderEditorialImage {
  overflow: hidden;
}

.premiumHome .editorialServiceImage img,
.premiumHome .editorialDoctorImage img,
.premiumHome .premiumTreatmentImageFrame img,
.premiumHome .novaWelcomeMainImage img,
.premiumHome .novaWelcomeSecondImage img,
.premiumHome .founderEditorialImage img {
  transform: scale(1.10);
  transition:
    transform 1.5s cubic-bezier(.16,1,.3,1),
    filter 1s ease;
}

.premiumHome .editorialService.is-visible img,
.premiumHome .editorialDoctor.is-visible img,
.premiumHome .premiumTreatmentItem.is-visible img {
  transform: scale(1);
}

.premiumHome .editorialService:hover img,
.premiumHome .editorialDoctor:hover img,
.premiumHome .premiumTreatmentItem:hover img,
.premiumHome .novaWelcomeMainImage:hover img,
.premiumHome .novaWelcomeSecondImage:hover img {
  transform: scale(1.055);
  filter: brightness(1.04) saturate(1.05);
}


/* =========================================================
   CARD CONTENT REVEAL
   ========================================================= */

.premiumHome .editorialServiceBody,
.premiumHome .editorialDoctorBody,
.premiumHome .premiumTreatmentContent {
  opacity: 0;
  transform: translateY(25px);
  transition:
    opacity .75s ease .3s,
    transform .85s cubic-bezier(.16,1,.3,1) .3s;
}

.premiumHome .editorialService.is-visible .editorialServiceBody,
.premiumHome .editorialDoctor.is-visible .editorialDoctorBody,
.premiumHome .premiumTreatmentItem.is-visible .premiumTreatmentContent {
  opacity: 1;
  transform: translateY(0);
}


/* =========================================================
   CLINIC EXPERIENCE
   ========================================================= */

.premiumHome .novaExperienceGallery {
  opacity: 0;
  transform: translateX(-100px);
  transition:
    opacity 1s ease,
    transform 1.15s cubic-bezier(.16,1,.3,1);
}

.premiumHome .novaExperienceGallery.is-visible {
  opacity: 1 !important;
  transform: translateX(0) !important;
}

.premiumHome .novaExperienceContent {
  opacity: 1;
}

.premiumHome .novaExperienceItem {
  opacity: 0;
  transform: translateX(90px);
  transition:
    opacity .8s ease var(--delay, 0ms),
    transform 1s cubic-bezier(.16,1,.3,1) var(--delay, 0ms);
}

.premiumHome .novaExperienceItem.is-visible {
  opacity: 1 !important;
  transform: translateX(0) !important;
}


/* =========================================================
   FOUNDER
   ========================================================= */

.premiumHome .founderEditorialVisual {
  opacity: 0;
  transform: translateX(-100px);
  transition:
    opacity 1s ease,
    transform 1.2s cubic-bezier(.16,1,.3,1);
}

.premiumHome .founderEditorialVisual.is-visible {
  opacity: 1 !important;
  transform: translateX(0) !important;
}


/* =========================================================
   STATS
   ========================================================= */

.premiumHome .statsGrid > div {
  opacity: 0;
  transform: translateY(50px);
  transition:
    opacity .8s ease,
    transform .9s cubic-bezier(.16,1,.3,1);
}

.premiumHome .statsGrid > div:nth-child(1) {
  transition-delay: 0ms;
}

.premiumHome .statsGrid > div:nth-child(2) {
  transition-delay: 100ms;
}

.premiumHome .statsGrid > div:nth-child(3) {
  transition-delay: 200ms;
}

.premiumHome .statsGrid > div:nth-child(4) {
  transition-delay: 300ms;
}

.premiumHome .statsGrid.is-visible > div,
.premiumHome .premiumStats.is-visible .statsGrid > div {
  opacity: 1;
  transform: translateY(0);
}


/* =========================================================
   RUNNING TYPOGRAPHY
   ========================================================= */

.novaRunningText,
.heroRunningLine {
  overflow: hidden;
  width: 100%;
  white-space: nowrap;
}

.heroRunningLine {
  position: relative;
  padding: 15px 0;
  background: #0b2545;
  border-top: 1px solid rgba(255,255,255,.12);
  border-bottom: 1px solid rgba(255,255,255,.12);
}

.heroRunningTrack {
  display: flex;
  width: max-content;
  gap: 70px;
  animation: novaRunning 24s linear infinite;
  will-change: transform;
}

.heroRunningTrack span {
  flex-shrink: 0;
  color: rgba(255,255,255,.9);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .22em;
}

@keyframes novaRunning {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-50%);
  }
}


/* =========================================================
   SECTION TITLE MOVEMENT
   ========================================================= */

.premiumHome .storyKicker,
.premiumHome .storyIndex {
  display: inline-block;
  opacity: 0;
  transform: translateX(-25px);
  transition:
    opacity .7s ease,
    transform .8s cubic-bezier(.16,1,.3,1);
}

.premiumHome .sectionIntro.is-visible .storyKicker,
.premiumHome .sectionIntro.is-visible .storyIndex,
.premiumHome .reviewIntro.is-visible .storyKicker,
.premiumHome .reviewIntro.is-visible .storyIndex {
  opacity: 1;
  transform: translateX(0);
}


/* =========================================================
   HOVER — PREMIUM MOVEMENT
   ========================================================= */

.premiumHome .principleCard:hover,
.premiumHome .editorialService:hover,
.premiumHome .editorialDoctor:hover,
.premiumHome .reviewCard:hover {
  transform: translateY(-8px) !important;
}

.premiumHome .premiumTreatmentItem:hover {
  transform: translateX(5px) !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 768px) {

  .premiumHome .principleCard,
  .premiumHome .editorialService,
  .premiumHome .editorialDoctor,
  .premiumHome .premiumTreatmentItem,
  .premiumHome .reviewCard,
  .premiumHome .welcomeStory .novaWelcomeVisual,
  .premiumHome .welcomeStory .storyContent,
  .premiumHome .founderEditorialVisual,
  .premiumHome .novaExperienceGallery,
  .premiumHome .novaExperienceItem {
    transform: translateY(45px);
  }

  .premiumHome .principleCard.is-visible,
  .premiumHome .editorialService.is-visible,
  .premiumHome .editorialDoctor.is-visible,
  .premiumHome .premiumTreatmentItem.is-visible,
  .premiumHome .reviewCard.is-visible,
  .premiumHome .welcomeStory .novaWelcomeVisual.is-visible,
  .premiumHome .welcomeStory .storyContent.is-visible,
  .premiumHome .founderEditorialVisual.is-visible,
  .premiumHome .novaExperienceGallery.is-visible,
  .premiumHome .novaExperienceItem.is-visible {
    transform: translateY(0) !important;
  }

  .heroRunningTrack {
    gap: 40px;
    animation-duration: 18s;
  }
}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .premiumHome *,
  .premiumHome *::before,
  .premiumHome *::after {
    animation: none !important;
    transition: none !important;
  }

  .premiumHome [data-reveal],
  .premiumHome .principleCard,
  .premiumHome .editorialService,
  .premiumHome .editorialDoctor,
  .premiumHome .premiumTreatmentItem,
  .premiumHome .reviewCard,
  .premiumHome .sectionIntro,
  .premiumHome .reviewIntro {
    opacity: 1 !important;
    transform: none !important;
    clip-path: none !important;
  }
}
/* =========================================================
   NOVADENT DENTAL CARE
   CLEAN BASE STYLESHEET
   ========================================================= */

:root {
  --primary: #0b8f91;
  --primary-dark: #173f4f;
  --primary-soft: #eaf6f6;

  --text: #173f4f;
  --text-soft: #71858c;

  --white: #ffffff;
  --light: #f7fafb;
  --line: rgba(23, 63, 79, 0.12);

  --shadow: 0 20px 50px rgba(23, 63, 79, 0.10);
  --shadow-soft: 0 12px 30px rgba(23, 63, 79, 0.08);

  --container: 1240px;
  --radius: 8px;
}

/* =========================================================
   RESET
   ========================================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}

body {
  margin: 0;
  padding: 0;

  background: #ffffff;
  color: var(--text);

  font-family:
    "DM Sans",
    Arial,
    Helvetica,
    sans-serif;

  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body,
button,
input,
textarea,
select {
  font-family:
    "DM Sans",
    Arial,
    Helvetica,
    sans-serif;
}

img {
  max-width: 100%;
  display: block;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

h1,
h2,
h3,
h4,
h5,
h6,
p {
  margin-top: 0;
}

/* =========================================================
   COMMON CONTAINER
   ========================================================= */

.storyContainer,
.container,
.sectionContainer {
  width: min(var(--container), calc(100% - 48px));
  margin-left: auto;
  margin-right: auto;
}

/* =========================================================
   NAVBAR
   ========================================================= */

.novaNavbar {
  position: fixed;
  top: 0;
  left: 0;

  width: 100%;
  height: 82px;

  z-index: 1000;

  background: rgba(255, 255, 255, 0.96);

  border-bottom: 1px solid var(--line);

  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.novaNavbarInner {
  width: min(1280px, calc(100% - 48px));
  height: 100%;

  margin: 0 auto;

  display: flex;
  align-items: center;
  gap: 28px;
}

/* Brand */

.novaBrand {
  flex-shrink: 0;
}

.novaBrandText {
  display: flex;
  flex-direction: column;
}

.novaBrandText strong {
  color: var(--primary-dark);
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.novaBrandText span {
  margin-top: 2px;

  color: var(--primary);
  font-size: 8px;
  font-weight: 700;

  letter-spacing: 0.18em;
}

/* Navigation */

.novaNavigation {
  flex: 1;

  display: flex;
  justify-content: center;
  align-items: center;
}

.novaNavLinks {
  display: flex;
  align-items: center;
  gap: 4px;
}

.novaNavLink {
  position: relative;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 44px;
  padding: 0 14px;

  color: #536579;

  font-size: 12px;
  font-weight: 700;

  transition:
    color 0.25s ease,
    background 0.25s ease;
}

.novaNavLink:hover {
  color: var(--primary);
}

.novaNavLink.isActive {
  color: var(--primary-dark);
}

.novaNavLink.isActive::after {
  content: "";

  position: absolute;

  left: 12px;
  right: 12px;
  bottom: 4px;

  height: 2px;

  background: var(--primary);

  border-radius: 2px;
}

.novaDesktopCTA {
  flex-shrink: 0;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 42px;

  padding: 0 18px;

  color: #ffffff;
  background: var(--primary-dark);

  border-radius: 4px;

  font-size: 11px;
  font-weight: 800;

  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.novaDesktopCTA:hover {
  transform: translateY(-2px);
  background: var(--primary);
}

/* =========================================================
   MAIN
   ========================================================= */

main {
  margin: 0;
  padding: 0;
}

.homePage {
  margin: 0;
  padding: 0;

  overflow-x: hidden;

  background: #ffffff;
}

/* =========================================================
   HERO
   ========================================================= */

.novaHero {
  position: relative;

  width: 100%;
  height: 100vh;
  min-height: 680px;

  overflow: hidden;

  background: #102f3c;
}

.novaHeroVideo {
  position: absolute;

  inset: 0;

  width: 100%;
  height: 100%;

  object-fit: cover;

  z-index: 0;
}

.novaHeroOverlay {
  position: absolute;

  inset: 0;

  z-index: 1;

  background:
    linear-gradient(
      90deg,
      rgba(8, 32, 43, 0.78),
      rgba(8, 32, 43, 0.45),
      rgba(8, 32, 43, 0.25)
    );
}

.novaHeroGradient {
  position: absolute;

  left: 0;
  right: 0;
  bottom: 0;

  height: 35%;

  z-index: 2;

  background:
    linear-gradient(
      to top,
      rgba(5, 25, 34, 0.72),
      transparent
    );
}

.novaHeroContainer {
  position: relative;

  z-index: 5;

  width: min(1240px, calc(100% - 48px));
  height: 100%;

  margin: 0 auto;

  display: flex;
  align-items: center;
}

.novaHeroContent {
  max-width: 850px;

  color: #ffffff;
}

.novaHeroEyebrow {
  display: flex;
  align-items: center;
  gap: 10px;

  margin-bottom: 20px;

  color: rgba(255, 255, 255, 0.85);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.20em;
}

.novaHeroLine {
  width: 30px;
  height: 1px;

  background: var(--primary);
}

.novaHeroTitle {
  margin: 0;

  color: #ffffff;

  font-family:
    "Playfair Display",
    Georgia,
    serif;

  font-size: clamp(52px, 7vw, 100px);
  line-height: 0.96;

  font-weight: 500;

  letter-spacing: -0.045em;
}

.novaHeroAccent {
  color: #8ed4d4;
}

.novaHeroDescription {
  max-width: 570px;

  margin-top: 28px;

  color: rgba(255, 255, 255, 0.82);

  font-size: 15px;
  line-height: 1.75;
}

.novaHeroActions {
  display: flex;
  align-items: center;
  gap: 18px;

  margin-top: 30px;
}

.novaHeroPrimary {
  display: inline-flex;
  align-items: center;
  gap: 9px;

  min-height: 48px;

  padding: 0 20px;

  color: #ffffff;
  background: var(--primary);

  border-radius: 4px;

  font-size: 12px;
  font-weight: 800;

  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.novaHeroPrimary:hover {
  transform: translateY(-3px);
  background: #087c7e;
}

.novaHeroSecondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  color: #ffffff;

  font-size: 12px;
  font-weight: 800;

  transition:
    gap 0.3s ease,
    color 0.3s ease;
}

.novaHeroSecondary:hover {
  gap: 13px;
  color: #8ed4d4;
}

.novaHeroBottom {
  position: absolute;

  left: 0;
  right: 0;
  bottom: 0;

  z-index: 6;

  padding: 22px 0;

  color: rgba(255, 255, 255, 0.72);
}

.novaHeroBottomLeft {
  display: flex;
  gap: 25px;

  font-size: 9px;
  letter-spacing: 0.12em;
}

/* =========================================================
   RUNNING LINE
   ========================================================= */

.heroRunningLine {
  width: 100%;

  overflow: hidden;

  padding: 15px 0;

  background: var(--primary-dark);
}

.heroRunningTrack {
  display: flex;

  width: max-content;

  animation: novaRunning 25s linear infinite;
}

.heroRunningTrack span {
  flex-shrink: 0;

  padding: 0 35px;

  color: rgba(255, 255, 255, 0.92);

  font-size: 10px;
  font-weight: 700;

  letter-spacing: 0.20em;

  white-space: nowrap;
}

@keyframes novaRunning {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-50%);
  }
}

/* =========================================================
   COMMON STORY SECTION
   ========================================================= */

.storySection {
  position: relative;

  padding: 110px 0;

  background: #ffffff;
}

.storyKicker {
  display: block;

  margin-bottom: 12px;

  color: var(--primary);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.18em;
}

.storyIndex {
  display: block;

  margin-bottom: 20px;

  color: #9aa9ae;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 0.14em;
}

.storySection h2 {
  margin: 0;

  color: var(--primary-dark);

  font-family:
    "Playfair Display",
    Georgia,
    serif;

  font-size: clamp(36px, 4.5vw, 58px);

  line-height: 1.05;

  font-weight: 500;

  letter-spacing: -0.03em;
}

.storySection h2 em {
  color: var(--primary);

  font-style: italic;
}

.storyLead {
  margin-top: 22px;

  color: var(--text-soft);

  font-size: 16px;
  line-height: 1.8;
}

/* =========================================================
   WELCOME
   ========================================================= */

.welcomeStory {
  padding-top: 80px;
}

.storySplit {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 80px;

  align-items: center;
}

.novaWelcomeVisual {
  position: relative;
}

.novaWelcomeMainImage {
  position: relative;

  overflow: hidden;

  border-radius: 5px;

  box-shadow: var(--shadow);
}

.novaWelcomeMainImage img {
  width: 100%;
  height: 560px;

  object-fit: cover;

  transition: transform 0.8s ease;
}

.novaWelcomeMainImage:hover img {
  transform: scale(1.04);
}

.novaWelcomeSecondImage {
  position: absolute;

  right: -25px;
  bottom: -35px;

  width: 40%;

  overflow: hidden;

  border: 7px solid #ffffff;

  box-shadow: var(--shadow);
}

.novaWelcomeSecondImage img {
  width: 100%;
  height: 190px;

  object-fit: cover;

  transition: transform 0.7s ease;
}

.novaWelcomeSecondImage:hover img {
  transform: scale(1.06);
}

.storyContent {
  max-width: 600px;
}

.storyMiniGrid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 20px;

  margin-top: 35px;

  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.storyMiniGrid > div {
  padding: 22px 0;
}

.storyMiniGrid strong {
  display: block;

  color: var(--primary);

  font-size: 18px;
}

.storyMiniGrid span {
  display: block;

  margin-top: 6px;

  color: var(--text-soft);

  font-size: 10px;
  line-height: 1.5;
}

.storyButton {
  display: inline-flex;
  align-items: center;
  gap: 9px;

  margin-top: 28px;

  padding: 12px 18px;

  color: #ffffff;
  background: var(--primary-dark);

  border-radius: 4px;

  font-size: 11px;
  font-weight: 800;

  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.storyButton:hover {
  transform: translateY(-3px);
  background: var(--primary);
}

/* =========================================================
   CLINIC EXPERIENCE
   ========================================================= */

.clinicStory {
  background: #f8fbfb;
}

.sectionIntro {
  display: grid;

  grid-template-columns: 1fr 0.7fr;

  gap: 70px;

  align-items: end;
}

.sectionIntro > p {
  margin: 0;

  color: var(--text-soft);

  font-size: 14px;
  line-height: 1.8;
}

.novaExperienceStory {
  display: grid;

  grid-template-columns: 1.08fr 0.92fr;

  gap: 80px;

  margin-top: 70px;

  align-items: center;
}

.novaExperienceGallery {
  position: relative;

  min-height: 600px;
}

.novaExperienceMain {
  position: absolute;

  top: 0;
  left: 0;

  width: 78%;
  height: 500px;

  overflow: hidden;

  box-shadow: var(--shadow);
}

.novaExperienceMain img,
.novaExperienceFloating img,
.novaExperienceSmall img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition: transform 0.8s ease;
}

.novaExperienceMain:hover img,
.novaExperienceFloating:hover img,
.novaExperienceSmall:hover img {
  transform: scale(1.05);
}

.novaExperienceMainOverlay {
  position: absolute;

  left: 20px;
  right: 20px;
  bottom: 20px;

  display: flex;
  align-items: center;
  gap: 14px;

  padding: 14px 16px;

  background: rgba(255, 255, 255, 0.94);

  backdrop-filter: blur(10px);
}

.novaExperienceMainOverlay > span {
  color: var(--primary);

  font-size: 12px;
  font-weight: 800;
}

.novaExperienceMainOverlay strong {
  display: block;

  color: var(--primary-dark);

  font-size: 11px;

  letter-spacing: 0.10em;
}

.novaExperienceMainOverlay small {
  display: block;

  margin-top: 4px;

  color: var(--text-soft);

  font-size: 10px;
}

.novaExperienceFloating {
  position: absolute;

  top: 115px;
  right: 0;

  width: 40%;
  height: 245px;

  overflow: hidden;

  border: 7px solid #ffffff;

  box-shadow: var(--shadow);

  z-index: 3;
}

.novaExperienceFloating span {
  position: absolute;

  left: 12px;
  bottom: 12px;

  padding: 6px 9px;

  color: #ffffff;
  background: rgba(23, 63, 79, 0.88);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.10em;
}

.novaExperienceSmall {
  position: absolute;

  right: 8%;
  bottom: 0;

  width: 31%;
  height: 185px;

  overflow: hidden;

  border: 7px solid #ffffff;

  box-shadow: var(--shadow);

  z-index: 4;
}

.novaExperienceNumber {
  position: absolute;

  left: 0;
  bottom: 25px;

  display: flex;
  align-items: baseline;
  gap: 8px;
}

.novaExperienceNumber span {
  color: var(--primary-dark);

  font-size: 42px;
  font-weight: 700;
}

.novaExperienceNumber small {
  color: var(--primary);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.14em;
}

.novaExperienceContent {
  display: flex;
  flex-direction: column;
}

.novaExperienceItem {
  display: grid;

  grid-template-columns: 36px 1fr 20px;

  gap: 18px;

  padding: 25px 0;

  border-bottom: 1px solid var(--line);
}

.novaExperienceItemNumber {
  color: var(--primary);

  font-size: 11px;
  font-weight: 800;
}

.novaExperienceLabel {
  display: block;

  color: var(--primary);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.13em;
}

.novaExperienceItem h3 {
  margin: 8px 0;

  color: var(--primary-dark);

  font-size: 20px;
}

.novaExperienceItem p {
  margin: 0;

  color: var(--text-soft);

  font-size: 13px;
  line-height: 1.8;
}

.novaExperienceLink {
  display: inline-flex;
  align-items: center;
  gap: 9px;

  width: fit-content;

  margin-top: 28px;
  padding-bottom: 7px;

  color: var(--primary-dark);

  border-bottom: 1px solid var(--primary);

  font-size: 11px;
  font-weight: 800;

  transition: gap 0.3s ease;
}

.novaExperienceLink:hover {
  gap: 15px;
}

/* =========================================================
   FOUNDER
   ========================================================= */

.founderStory {
  background: #ffffff;
}

.founderEditorial {
  display: grid;

  grid-template-columns: 0.85fr 1.15fr;

  gap: 85px;

  align-items: center;
}

.founderEditorialVisual {
  position: relative;
}

.founderEditorialImage {
  position: relative;

  overflow: hidden;

  box-shadow: var(--shadow);
}

.founderEditorialImage img {
  width: 100%;
  height: 600px;

  object-fit: cover;

  transition: transform 0.9s ease;
}

.founderEditorialImage:hover img {
  transform: scale(1.04);
}

.founderImageOverlay {
  position: absolute;

  left: 20px;
  right: 20px;
  bottom: 20px;

  display: flex;
  align-items: center;
  gap: 14px;

  padding: 14px;

  background: rgba(255, 255, 255, 0.94);
}

.founderImageOverlay > span {
  color: var(--primary);

  font-size: 12px;
  font-weight: 800;
}

.founderImageOverlay strong {
  display: block;

  color: var(--primary-dark);

  font-size: 11px;
}

.founderImageOverlay small {
  display: block;

  margin-top: 4px;

  color: var(--text-soft);

  font-size: 10px;
}

.founderExperienceCard {
  position: absolute;

  right: -25px;
  bottom: -25px;

  width: 145px;
  height: 145px;

  display: flex;
  flex-direction: column;
  justify-content: center;

  padding: 20px;

  color: #ffffff;
  background: var(--primary-dark);

  box-shadow: var(--shadow);
}

.founderExperienceCard strong {
  font-size: 40px;
  line-height: 1;
}

.founderExperienceCard span {
  margin-top: 8px;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.12em;
}

.founderEditorialDetails {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 20px;

  margin: 30px 0;

  padding: 24px 0;

  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.founderEditorialDetails span,
.founderRegistrationGrid span {
  display: block;

  color: var(--primary);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.12em;
}

.founderEditorialDetails strong,
.founderRegistrationGrid strong {
  display: block;

  margin-top: 7px;

  color: var(--primary-dark);

  font-size: 12px;
  line-height: 1.5;
}

.founderEditorialContent > p:not(.storyLead) {
  color: var(--text-soft);

  font-size: 14px;
  line-height: 1.8;
}

.founderVision {
  margin-top: 28px;

  padding: 22px;

  background: var(--primary-soft);

  border-left: 3px solid var(--primary);
}

.founderVision > span {
  color: var(--primary);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.13em;
}

.founderVision p {
  margin: 9px 0 0;

  color: var(--primary-dark);

  font-size: 14px;
  line-height: 1.7;
}

/* Registration */

.founderRegistration {
  margin-top: 90px;

  padding: 35px;

  background: #f7fafb;

  border: 1px solid var(--line);
}

.founderRegistrationHeader {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 25px;
}

.founderRegistrationHeader > div > span {
  color: var(--primary);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.14em;
}

.founderRegistrationHeader h3 {
  margin: 8px 0 0;

  color: var(--primary-dark);

  font-size: 24px;
}

.crBadge {
  padding: 7px 10px;

  color: #8a6333;
  background: #f4eadc;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.10em;
}

.founderRegistrationGrid {
  display: grid;

  grid-template-columns: repeat(4, 1fr);

  gap: 25px;

  margin-top: 30px;
}

/* =========================================================
   STATS
   ========================================================= */

.premiumStats {
  padding: 65px 0;

  background: var(--primary-dark);

  color: #ffffff;
}

.statsGrid {
  display: grid;

  grid-template-columns: repeat(4, 1fr);
}

.statsGrid > div {
  min-height: 150px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  padding: 20px;

  border-right: 1px solid rgba(255, 255, 255, 0.12);

  text-align: center;
}

.statsGrid > div:last-child {
  border-right: none;
}

.statsGrid svg {
  margin-bottom: 12px;

  color: #8ed4d4;
}

.statsGrid strong {
  font-size: 40px;
  line-height: 1;
}

.statsGrid span {
  margin-top: 8px;

  color: rgba(255, 255, 255, 0.65);

  font-size: 9px;
  font-weight: 800;

  letter-spacing: 0.13em;
}

/* =========================================================
   PHILOSOPHY
   ========================================================= */

.philosophySection,
.premiumPhilosophy,
.philosophyStory {
  padding: 110px 0;

  background: #f8fbfb;
}

.philosophyGrid,
.premiumPhilosophyGrid,
.principlesGrid {
  display: grid;

  grid-template-columns: repeat(4, 1fr);

  margin-top: 55px;
}

.principleCard {
  padding: 30px;

  border-right: 1px solid var(--line);

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.principleCard:last-child {
  border-right: none;
}

.principleCard:hover {
  transform: translateY(-6px);
}

.principleCard h3 {
  margin: 18px 0 10px;

  color: var(--primary-dark);

  font-size: 18px;
}

.principleCard p {
  margin: 0;

  color: var(--text-soft);

  font-size: 13px;
  line-height: 1.75;
}

/* =========================================================
   TREATMENTS
   ========================================================= */

.premiumTreatmentEditorial {
  padding: 110px 0;

  background: #ffffff;
}

.premiumTreatmentEditorialHeader {
  display: grid;

  grid-template-columns: 1fr 0.65fr;

  gap: 70px;

  margin-bottom: 65px;
}

.premiumTreatmentEditorialHeader p {
  color: var(--text-soft);

  font-size: 14px;
  line-height: 1.8;
}

.premiumTreatmentList {
  display: flex;
  flex-direction: column;
}

.premiumTreatmentItem {
  display: grid;

  grid-template-columns: 1fr 1fr;

  gap: 70px;

  padding: 65px 0;

  border-top: 1px solid var(--line);

  align-items: center;
}

.premiumTreatmentItemReverse {
  direction: rtl;
}

.premiumTreatmentItemReverse > * {
  direction: ltr;
}

.premiumTreatmentImageFrame {
  position: relative;

  overflow: hidden;

  height: 480px;

  background: #eef4f5;
}

.premiumTreatmentImageFrame img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition: transform 0.9s ease;
}

.premiumTreatmentImageFrame:hover img {
  transform: scale(1.05);
}

.premiumTreatmentImageGradient {
  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      to top,
      rgba(10, 35, 45, 0.55),
      transparent 55%
    );

  pointer-events: none;
}

.premiumTreatmentNumber {
  position: absolute;

  left: 22px;
  top: 22px;

  color: #ffffff;

  font-size: 12px;
  font-weight: 800;
}

.premiumTreatmentContent h3 {
  margin: 12px 0 18px;

  color: var(--primary-dark);

  font-family:
    "Playfair Display",
    Georgia,
    serif;

  font-size: 42px;
  font-weight: 500;
}

.premiumTreatmentContent p {
  color: var(--text-soft);

  font-size: 14px;
  line-height: 1.8;
}

.premiumTreatmentTags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  margin-top: 22px;
}

.premiumTreatmentTags span {
  padding: 7px 9px;

  color: var(--primary-dark);
  background: var(--primary-soft);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.07em;
}

.premiumTreatmentContent a {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  margin-top: 25px;

  color: var(--primary);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.10em;
}

/* =========================================================
   DOCTORS
   ========================================================= */

.doctorsSection,
.teamSection {
  padding: 110px 0;

  background: #f8fbfb;
}

.doctorsSection .sectionContainer,
.teamSection .sectionContainer {
  width: min(var(--container), calc(100% - 48px));
  margin: auto;
}

.doctorsGrid,
.teamGrid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 25px;

  margin-top: 55px;
}

.doctorCard,
.premiumDoctorCard,
.teamCard {
  overflow: hidden;

  background: #ffffff;

  border: 1px solid var(--line);

  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;
}

.doctorCard:hover,
.premiumDoctorCard:hover,
.teamCard:hover {
  transform: translateY(-7px);

  box-shadow: var(--shadow);
}

.doctorCard img,
.premiumDoctorCard img,
.teamCard img {
  width: 100%;
  height: 390px;

  object-fit: cover;

  transition: transform 0.7s ease;
}

.doctorCard:hover img,
.premiumDoctorCard:hover img,
.teamCard:hover img {
  transform: scale(1.04);
}

.doctorCard > div,
.premiumDoctorCard > div,
.teamCard > div {
  padding: 24px;
}

.doctorCard h3,
.premiumDoctorCard h3,
.teamCard h3 {
  margin: 0;

  color: var(--primary-dark);

  font-size: 21px;
}

.doctorCard p,
.premiumDoctorCard p,
.teamCard p {
  margin: 7px 0 0;

  color: var(--text-soft);

  font-size: 12px;
  line-height: 1.6;
}

/* =========================================================
   REVIEWS
   ========================================================= */

.reviewsSection {
  padding: 110px 0;

  background: #ffffff;
}

.reviewsGrid,
.reviewGrid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 25px;

  margin-top: 55px;
}

.reviewCard {
  padding: 30px;

  background: #f8fbfb;

  border: 1px solid var(--line);

  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.reviewCard:hover {
  transform: translateY(-6px);

  box-shadow: var(--shadow-soft);
}

.reviewCard p {
  color: var(--text-soft);

  font-size: 14px;
  line-height: 1.8;
}

.reviewCard strong {
  display: block;

  margin-top: 20px;

  color: var(--primary-dark);

  font-size: 12px;
}

/* =========================================================
   APPOINTMENT
   ========================================================= */

.appointmentSection,
.premiumAppointment,
.appointmentCTA {
  padding: 110px 0;

  background: var(--primary-dark);

  color: #ffffff;
}

.appointmentSection .storyContainer,
.premiumAppointment .storyContainer,
.appointmentCTA .storyContainer {
  display: grid;

  grid-template-columns: 0.9fr 1.1fr;

  gap: 70px;

  align-items: center;
}

.appointmentSection h2,
.premiumAppointment h2,
.appointmentCTA h2 {
  color: #ffffff;
}

.appointmentSection p,
.premiumAppointment p,
.appointmentCTA p {
  color: rgba(255, 255, 255, 0.70);

  font-size: 14px;
  line-height: 1.8;
}

/* Forms */

.appointmentFormSection,
.contactFormSection {
  padding: 100px 0;

  background: #f8fbfb;
}

.appointmentForm,
.contactForm {
  padding: 35px;

  background: #ffffff;

  border: 1px solid var(--line);

  box-shadow: var(--shadow-soft);
}

.formRow,
.contactFormRow {
  display: grid;

  grid-template-columns: repeat(2, 1fr);

  gap: 20px;
}

.formGroup {
  margin-bottom: 20px;
}

.formGroup label {
  display: block;

  margin-bottom: 8px;

  color: var(--primary-dark);

  font-size: 10px;
  font-weight: 800;

  letter-spacing: 0.08em;
}

.formGroup input,
.formGroup textarea,
.formGroup select,
.appointmentForm input,
.appointmentForm textarea,
.appointmentForm select,
.contactForm input,
.contactForm textarea,
.contactForm select {
  width: 100%;

  padding: 13px 14px;

  color: var(--primary-dark);
  background: #ffffff;

  border: 1px solid rgba(23, 63, 79, 0.18);

  outline: none;

  border-radius: 3px;

  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

.formGroup input:focus,
.formGroup textarea:focus,
.formGroup select:focus,
.appointmentForm input:focus,
.appointmentForm textarea:focus,
.appointmentForm select:focus,
.contactForm input:focus,
.contactForm textarea:focus,
.contactForm select:focus {
  border-color: var(--primary);

  box-shadow:
    0 0 0 3px rgba(11, 143, 145, 0.10);
}

.formGroup textarea,
.appointmentForm textarea,
.contactForm textarea {
  min-height: 140px;

  resize: vertical;
}

.formSubmit,
.appointmentSubmit,
.contactSubmit {
  min-height: 48px;

  padding: 0 22px;

  color: #ffffff;
  background: var(--primary-dark);

  border: 0;
  border-radius: 4px;

  font-size: 11px;
  font-weight: 800;

  cursor: pointer;

  transition:
    transform 0.3s ease,
    background 0.3s ease;
}

.formSubmit:hover,
.appointmentSubmit:hover,
.contactSubmit:hover {
  transform: translateY(-2px);

  background: var(--primary);
}

/* =========================================================
   OTHER PAGES - COMMON HERO
   ========================================================= */

.aboutPage,
.novaAboutPage,
.novaDoctorsPage,
.novaTreatmentsPage,
.novaReviewsPage,
.novaAppointmentPage,
.novaContactPage,
.nova-gallery-page {
  background: #ffffff;
}

.aboutHero,
.novaAboutHero,
.novaDoctorsHero,
.novaTreatmentsHero,
.nova-gallery-hero,
.novaReviewsHero,
.novaAppointmentHero,
.novaContactHero {
  position: relative;

  min-height: 500px;

  display: flex;
  align-items: center;

  overflow: hidden;

  background: var(--primary-dark);

  color: #ffffff;
}

.aboutHero::before,
.novaAboutHero::before,
.novaDoctorsHero::before,
.novaTreatmentsHero::before,
.nova-gallery-hero::before,
.novaReviewsHero::before,
.novaAppointmentHero::before,
.novaContactHero::before {
  content: "";

  position: absolute;

  inset: 0;

  background:
    linear-gradient(
      90deg,
      rgba(8, 35, 47, 0.88),
      rgba(8, 35, 47, 0.55)
    );
}

.aboutHeroContent,
.novaAboutHeroContent,
.novaDoctorsHeroContent,
.novaTreatmentsHeroContent,
.nova-gallery-hero-content,
.novaReviewsHeroContent,
.novaAppointmentHeroContent,
.novaContactHeroContent {
  position: relative;

  z-index: 2;

  width: min(var(--container), calc(100% - 48px));

  margin: auto;
}

.aboutHero h1,
.novaAboutHero h1,
.novaDoctorsHero h1,
.novaTreatmentsHero h1,
.nova-gallery-hero h1,
.novaReviewsHero h1,
.novaAppointmentHero h1,
.novaContactHero h1 {
  margin: 0;

  color: #ffffff;

  font-family:
    "Playfair Display",
    Georgia,
    serif;

  font-size: clamp(48px, 6vw, 80px);

  font-weight: 500;

  line-height: 1;
}

.aboutHero p,
.novaAboutHero p,
.novaDoctorsHero p,
.novaTreatmentsHeroContent p,
.nova-gallery-hero p,
.novaReviewsHero p,
.novaAppointmentHero p,
.novaContactHero p {
  max-width: 600px;

  margin-top: 22px;

  color: rgba(255, 255, 255, 0.75);

  font-size: 15px;

  line-height: 1.8;
}

/* =========================================================
   GALLERY
   ========================================================= */

.nova-gallery-page {
  padding-bottom: 100px;
}

.nova-gallery-grid,
.galleryGrid {
  display: grid;

  grid-template-columns: repeat(3, 1fr);

  gap: 20px;

  width: min(var(--container), calc(100% - 48px));

  margin: 70px auto 0;
}

.nova-gallery-grid img,
.galleryGrid img {
  width: 100%;
  height: 350px;

  object-fit: cover;

  transition:
    transform 0.7s ease,
    filter 0.5s ease;
}

.nova-gallery-grid img:hover,
.galleryGrid img:hover {
  transform: scale(1.03);

  filter: brightness(1.04);
}

/* =========================================================
   FOOTER
   ========================================================= */

.novaFooter {
  padding: 75px 0 25px;

  background: #071d35;

  color: #ffffff;
}

.novaFooterContainer {
  width: min(var(--container), calc(100% - 48px));

  margin: 0 auto;
}

.novaFooterGrid {
  display: grid;

  grid-template-columns: 1.4fr repeat(3, 1fr);

  gap: 50px;
}

.novaFooter h3,
.novaFooter h4 {
  margin: 0 0 18px;

  color: #ffffff;

  font-size: 15px;
}

.novaFooter p,
.novaFooter li,
.novaFooter a {
  color: rgba(255, 255, 255, 0.62);

  font-size: 12px;
  line-height: 1.8;
}

.novaFooter a {
  transition: color 0.25s ease;
}

.novaFooter a:hover {
  color: #8ed4d4;
}

.novaFooterBottom {
  margin-top: 55px;

  padding-top: 20px;

  border-top: 1px solid rgba(255, 255, 255, 0.10);

  color: rgba(255, 255, 255, 0.45);

  font-size: 10px;
}

/* =========================================================
   RESPONSIVE — TABLET
   ========================================================= */

@media (max-width: 1000px) {

  .novaNavbarInner {
    width: min(100% - 32px, 900px);
  }

  .novaNavigation {
    display: none;
  }

  .storySplit,
  .novaExperienceStory,
  .founderEditorial {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .sectionIntro,
  .premiumTreatmentEditorialHeader {
    grid-template-columns: 1fr;
    gap: 25px;
  }

  .novaExperienceGallery {
    min-height: 500px;
  }

  .founderEditorialImage img {
    height: 520px;
  }

  .statsGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .statsGrid > div:nth-child(2) {
    border-right: none;
  }

  .statsGrid > div:nth-child(1),
  .statsGrid > div:nth-child(2) {
    border-bottom: 1px solid rgba(255,255,255,0.12);
  }

  .philosophyGrid,
  .premiumPhilosophyGrid,
  .principlesGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .principleCard:nth-child(2) {
    border-right: none;
  }

  .doctorsGrid,
  .teamGrid,
  .reviewsGrid,
  .reviewGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .appointmentSection .storyContainer,
  .premiumAppointment .storyContainer,
  .appointmentCTA .storyContainer {
    grid-template-columns: 1fr;
  }

  .novaFooterGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .novaNavbar {
    height: 70px;
