/* ALL PAGE STORY REVEAL */

[data-reveal] {
  opacity: 0;
  transform: translateY(60px);
  transition:
    opacity 1s cubic-bezier(.22,.61,.36,1),
    transform 1s cubic-bezier(.22,.61,.36,1);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}
/* CINEMATIC IMAGE REVEAL */

[data-image-reveal] {
  overflow: hidden;
}

[data-image-reveal] img {
  transform: scale(1.12);
  transition:
    transform 1.4s cubic-bezier(.22,.61,.36,1);
}

[data-image-reveal].is-visible img {
  transform: scale(1);
}
[data-from-left] {
  opacity: 0;
  transform: translateX(-90px);
  transition:
    opacity 1s ease,
    transform 1.15s cubic-bezier(.22,.61,.36,1);
}

[data-from-right] {
  opacity: 0;
  transform: translateX(90px);
  transition:
    opacity 1s ease,
    transform 1.15s cubic-bezier(.22,.61,.36,1);
}

[data-from-left].is-visible,
[data-from-right].is-visible {
  opacity: 1;
  transform: translateX(0);
}
/* =========================================================
   NOVADENT — FINAL CINEMATIC CARD REVEAL
========================================================= */

/* DEFAULT */
main [data-reveal] {
  opacity: 0;
  transform: translate3d(0, 40px, 0);
  transition:
    opacity 900ms cubic-bezier(.16, 1, .3, 1),
    transform 1000ms cubic-bezier(.16, 1, .3, 1);
  transition-delay: var(--delay, 0ms);
}

/* AFTER ANIMATION */
main [data-reveal].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}


/* =========================================================
   LEFT → RIGHT STORY REVEAL
========================================================= */

main [data-reveal].reveal-left,
main [data-reveal][data-direction="left"] {
  opacity: 0;
  transform: translate3d(-90px, 0, 0);
}

main [data-reveal].reveal-right,
main [data-reveal][data-direction="right"] {
  opacity: 0;
  transform: translate3d(90px, 0, 0);
}

main [data-reveal].reveal-left.is-visible,
main [data-reveal].reveal-right.is-visible,
main [data-reveal][data-direction="left"].is-visible,
main [data-reveal][data-direction="right"].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}


/* =========================================================
   TREATMENT CARDS
========================================================= */

.premiumTreatmentItem[data-reveal]:nth-child(odd) {
  opacity: 0;
  transform: translate3d(-90px, 0, 0);
}

.premiumTreatmentItem[data-reveal]:nth-child(even) {
  opacity: 0;
  transform: translate3d(90px, 0, 0);
}

.premiumTreatmentItem[data-reveal].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}

.premiumTreatmentItem:nth-child(1) {
  transition-delay: 0ms;
}

.premiumTreatmentItem:nth-child(2) {
  transition-delay: 100ms;
}

.premiumTreatmentItem:nth-child(3) {
  transition-delay: 180ms;
}

.premiumTreatmentItem:nth-child(4) {
  transition-delay: 260ms;
}

.premiumTreatmentItem:nth-child(5) {
  transition-delay: 340ms;
}

.premiumTreatmentItem:nth-child(6) {
  transition-delay: 420ms;
}


/* =========================================================
   DOCTOR CARDS
========================================================= */

.novaDoctorCard[data-reveal]:nth-child(odd),
.doctorCard[data-reveal]:nth-child(odd),
.editorialDoctor[data-reveal]:nth-child(odd) {
  opacity: 0;
  transform: translate3d(-70px, 0, 0);
}

.novaDoctorCard[data-reveal]:nth-child(even),
.doctorCard[data-reveal]:nth-child(even),
