}


/* =========================================================
   MAIN CARD ENTRY
   ========================================================= */

@keyframes reviewCardEnter {

  0% {
    opacity: 0;

    transform:
      translate3d(
        var(--review-enter-x),
        20px,
        0
      )
      scale(.985);
  }

  100% {
    opacity: 1;

    transform:
      translate3d(0, 0, 0)
      scale(1);
  }

}


/* =========================================================
   IMAGE AREA
   ========================================================= */

.reviewVisual {
  position: relative !important;

  min-height: 560px !important;

  overflow: hidden !important;

  background: #edf4f5 !important;
}


.reviewVisualImage {
  position: absolute !important;

  inset: 0 !important;

  overflow: hidden !important;

  clip-path: inset(
    0 100% 0 0
  ) !important;

  animation:
    reviewImageReveal
    1.15s
    cubic-bezier(.16,.72,.2,1)
    0.08s
    forwards !important;
}


.reviewVisualImage img {
  width: 100% !important;

  height: 100% !important;

  display: block !important;

  object-fit: cover !important;

  transform:
    scale(1.10)
    translateX(18px) !important;

  filter:
    saturate(.92)
    contrast(.97) !important;

  animation:
    reviewImageMove
    1.45s
    cubic-bezier(.16,.72,.2,1)
    0.08s
    forwards !important;
}


@keyframes reviewImageReveal {

  0% {
    clip-path:
      inset(0 100% 0 0);
  }

  100% {
    clip-path:
      inset(0 0 0 0);
  }

}


@keyframes reviewImageMove {

  0% {
    transform:
      scale(1.10)
      translateX(18px);
  }

  100% {
    transform:
      scale(1)
      translateX(0);
  }

}


