/* =========================================================
   NOVADENT REVIEWS — PREMIUM MOTION ONLY
   Does NOT change existing card layout
   ========================================================= */

.reviewCard {
  position: relative !important;
  overflow: hidden !important;

  /* keep existing layout */
  transform: translateY(0);
  opacity: 1;

  animation:
    novaReviewCardIn
    0.9s
    cubic-bezier(.22,.61,.36,1)
    both !important;

  will-change: transform, opacity;
}


/* Smooth entrance */
@keyframes novaReviewCardIn {
  0% {
    opacity: 0;
    transform: translateY(28px);
  }

  60% {
    opacity: 1;
    transform: translateY(-3px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------------------------------------------------------
   Quote animation
   --------------------------------------------------------- */

.reviewCard .reviewQuote {
  display: inline-block;

  opacity: 0;

  transform:
    translateY(18px)
    scale(.82);

  animation:
    novaReviewQuote
    .75s
    .18s
    cubic-bezier(.22,.61,.36,1)
    forwards;
}

@keyframes novaReviewQuote {
  0% {
    opacity: 0;
    transform:
      translateY(18px)
      scale(.82);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}


/* ---------------------------------------------------------
   Review text
   --------------------------------------------------------- */

.reviewCard blockquote {
  opacity: 0;

  transform: translateY(18px);

  animation:
    novaReviewText
    .8s
    .25s
    cubic-bezier(.22,.61,.36,1)
    forwards;
}

@keyframes novaReviewText {
  0% {
    opacity: 0;
    transform: translateY(18px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------------------------------------------------------
   Author
   --------------------------------------------------------- */

.reviewCard .reviewAuthor {
  opacity: 0;

  transform: translateY(16px);

  animation:
    novaReviewAuthor
    .75s
    .38s
    cubic-bezier(.22,.61,.36,1)
    forwards;
}

@keyframes novaReviewAuthor {
  0% {
    opacity: 0;
    transform: translateY(16px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------------------------------------------------------
   Initials — subtle premium movement
   --------------------------------------------------------- */

.reviewCard .reviewAuthorInitials {
  transition:
    transform .45s cubic-bezier(.22,.61,.36,1),
    box-shadow .45s ease;
}

.reviewCard .reviewAuthor:hover
.reviewAuthorInitials {
  transform: translateY(-3px);
}


/* ---------------------------------------------------------
   Controls
   --------------------------------------------------------- */

.reviewCard .reviewControls {
  opacity: 0;

  transform: translateY(12px);

  animation:
    novaReviewControls
    .7s
    .5s
    cubic-bezier(.22,.61,.36,1)
    forwards;
}

@keyframes novaReviewControls {
  0% {
    opacity: 0;
    transform: translateY(12px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ---------------------------------------------------------
   Arrow buttons
   --------------------------------------------------------- */

.reviewCard .reviewControls > button {
  transition:
    transform .3s ease,
    background-color .3s ease,
    color .3s ease;
}

.reviewCard .reviewControls > button:hover {
  transform: translateY(-3px);
}


/* ---------------------------------------------------------
   Dots
   --------------------------------------------------------- */

.reviewCard .reviewControls > div button {
  transition:
    transform .35s cubic-bezier(.22,.61,.36,1),
    width .35s ease,
    opacity .3s ease;
}

.reviewCard .reviewControls > div button:hover {
  transform: scale(1.25);
}

.reviewCard .reviewControls > div button.active {
  transform: scale(1.08);
}


/* ---------------------------------------------------------
   Card hover — VERY subtle
   Does NOT change layout
   --------------------------------------------------------- */

.reviewCard {
  transition:
    box-shadow .5s ease,
    background-color .5s ease;
}

.reviewCard:hover {
  box-shadow:
    0 22px 55px rgba(23, 63, 79, .10);
}


/* ---------------------------------------------------------
   Mobile
   --------------------------------------------------------- */

@media (max-width: 768px) {

  .reviewCard {
    animation-duration: .75s !important;
  }

  .reviewCard blockquote {
    animation-delay: .18s;
  }

  .reviewCard .reviewAuthor {
    animation-delay: .3s;
  }

  .reviewCard .reviewControls {
    animation-delay: .4s;
  }
}


/* ---------------------------------------------------------
   Accessibility
   --------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

  .reviewCard,
  .reviewCard .reviewQuote,
  .reviewCard blockquote,
  .reviewCard .reviewAuthor,
  .reviewCard .reviewControls {
    animation: none !important;
    opacity: 1 !important;
    transform: none !important;
  }
}
/* =========================================================
   NOVADENT — CLEAN FINAL PHILOSOPHY STORY MOTION
   FINAL OVERRIDE: replaces conflicting philosophy animation
   rules from earlier CSS sections without changing layout/content.
   ========================================================= */

.premiumHome .philosophyStory .principleCard[data-reveal] {
  opacity: 0 !important;
  transform: translate3d(-110px, 0, 0) !important;
  transition:
    opacity 900ms cubic-bezier(.22,1,.36,1),
    transform 1000ms cubic-bezier(.22,1,.36,1),
    box-shadow 350ms ease !important;
  transition-delay: 0ms !important;
  will-change: opacity, transform;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(even) {
  transform: translate3d(110px, 0, 0) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal].is-visible {
  opacity: 1 !important;
  transform: translate3d(0, 0, 0) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(1) {
  transition-delay: 0ms !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(2) {
  transition-delay: 110ms !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(3) {
  transition-delay: 220ms !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(4) {
  transition-delay: 330ms !important;
}

/* IMAGE: no zoom; it travels horizontally with the card. */
.premiumHome .philosophyStory .principleCard[data-reveal] .principleImage img {
  opacity: 1 !important;
  transform: translate3d(-45px, 0, 0) !important;
  transition:
    transform 1050ms cubic-bezier(.22,1,.36,1),
    filter 700ms ease !important;
  filter: brightness(.94) saturate(.96) !important;
  will-change: transform, filter;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(even) .principleImage img {
  transform: translate3d(45px, 0, 0) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal].is-visible .principleImage img {
  transform: translate3d(0, 0, 0) !important;
  filter: brightness(1) saturate(1.04) !important;
}

/* Image reveal line — directional, not a zoom. */
.premiumHome .philosophyStory .principleCard[data-reveal] .principleImage {
  clip-path: inset(0 14% 0 0) !important;
  transition: clip-path 1050ms cubic-bezier(.22,1,.36,1) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(even) .principleImage {
  clip-path: inset(0 0 0 14%) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal].is-visible .principleImage {
  clip-path: inset(0) !important;
}

/* Text enters opposite to the image. */
.premiumHome .philosophyStory .principleCard[data-reveal] .principleCardContent {
  opacity: 0 !important;
  transform: translate3d(45px, 0, 0) !important;
  transition:
    opacity 650ms cubic-bezier(.22,1,.36,1),
    transform 800ms cubic-bezier(.22,1,.36,1) !important;
  transition-delay: 180ms !important;
