}

.premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(even) .principleCardContent {
  transform: translate3d(-45px, 0, 0) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal].is-visible .principleCardContent {
  opacity: 1 !important;
  transform: translate3d(0, 0, 0) !important;
}

/* Keep existing card hover, but never turn it into an image zoom. */
.premiumHome .philosophyStory .principleCard[data-reveal].is-visible:hover {
  transform: translate3d(0, -7px, 0) !important;
}

.premiumHome .philosophyStory .principleCard[data-reveal]:hover .principleImage img {
  transform: translate3d(6px, 0, 0) !important;
  filter: brightness(1.04) saturate(1.07) !important;
}

@media (max-width: 1100px) {
  .premiumHome .philosophyStory .principleCard[data-reveal] {
    transform: translate3d(-80px, 0, 0) !important;
  }

  .premiumHome .philosophyStory .principleCard[data-reveal]:nth-child(even) {
    transform: translate3d(80px, 0, 0) !important;
  }
}

@media (max-width: 768px) {
