    clip-path: inset(0 0 8% 0) !important;
  }

  .premiumHome .philosophyStory .principleCard[data-reveal].is-visible .principleImage {
    clip-path: inset(0) !important;
  }

  .premiumHome .philosophyStory .principleCard[data-reveal] .principleCardContent,
