    transform: translate3d(0, 30px, 0) !important;
  }

  .premiumHome .philosophyStory .principleCard[data-reveal].is-visible .principleCardContent {
    transform: translate3d(0, 0, 0) !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .premiumHome .philosophyStory .principleCard[data-reveal],
  .premiumHome .philosophyStory .principleCard[data-reveal] .principleImage,
  .premiumHome .philosophyStory .principleCard[data-reveal] .principleImage img,
  .premiumHome .philosophyStory .principleCard[data-reveal] .principleCardContent {
    opacity: 1 !important;
    transform: none !important;
    clip-path: none !important;
    transition: none !important;
  }
}

/* ================================================================
   NOVADENT — PREMIUM EDITORIAL / RIVERSMILE-INSPIRED VISUAL LAYER
   Keep this block at the END of index.css so it wins over older rules.
   Hero component is intentionally untouched.
   ================================================================ */

:root{
