--------------------------------------------------------- */

.careStoryContent {
  min-width: 0;
  max-width: 560px;
}

.careStoryContent h2 {
  max-width: 560px;

  margin: 16px 0 24px;

  color: #0b2545;

  font-family: "Playfair Display", serif;

  font-size: clamp(40px, 4.5vw, 62px);

  font-weight: 500;

  line-height: 1;

  letter-spacing: -2px;
}

.careStoryContent h2 em {
  display: block;

  color: #1f8a8a;

  font-style: italic;

  font-weight: 500;
}

.careStoryIntro {
  max-width: 500px;

  margin: 0 0 32px;

  color: #64748b;

  font-size: 12px;

  line-height: 1.8;
}


/* ---------------------------------------------------------
   CARE POINTS
--------------------------------------------------------- */

.careStoryPoints {
  border-top: 1px solid #dce8eb;
}

.careStoryPoint {
  display: grid;

  grid-template-columns: 35px minmax(0,1fr);

  gap: 18px;

  padding: 17px 0;

  border-bottom: 1px solid #dce8eb;
}

.careStoryPoint > span {
  color: #aab8c3;

  font-family: "Playfair Display", serif;

  font-size: 18px;
}

.careStoryPoint h3 {
  margin: 0 0 5px;

  color: #0b2545;

  font-family: "Playfair Display", serif;

  font-size: 19px;

  font-weight: 500;
}

.careStoryPoint p {
  max-width: 430px;

  margin: 0;

  color: #64748b;

  font-size: 10px;

  line-height: 1.65;
}


/* ---------------------------------------------------------
   CTA
--------------------------------------------------------- */

.careStoryLink {
  display: inline-flex;

  align-items: center;

  gap: 10px;

  margin-top: 28px;

  color: #0b2545;

  font-size: 9px;

  font-weight: 800;

  letter-spacing: 1.5px;

  text-decoration: none;

  transition:
    color .25s ease,
    gap .25s ease;
}

.careStoryLink svg {
  color: #1f8a8a;

  transition:
    transform .25s ease;
}

.careStoryLink:hover {
  color: #1f8a8a;

  gap: 14px;
}

.careStoryLink:hover svg {
  transform: translate(3px,-3px);
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 950px) {

  .careStoryGrid {
    grid-template-columns: 1fr;
    gap: 55px;
  }

  .careStoryVisual {
    padding-right: 45px;
  }

  .careStoryMainImage {
    height: 500px;
  }

  .careStoryContent {
    max-width: 700px;
  }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 600px) {

  .careStoryGrid {
    gap: 40px;
  }

  .careStoryVisual {
    padding-right: 25px;
  }

  .careStoryMainImage {
    height: 390px;
  }

  .careStorySmallImage {
    width: 125px;
    height: 155px;

    right: 0;
    bottom: 28px;

    padding: 6px;
  }

  .careStoryNumber {
    left: -8px;
    top: 20px;

    padding: 10px 12px;
  }

  .careStoryNumber span {
