/* =========================================================
   CARE STORY — IMAGE POLISH + CINEMATIC REVEAL
========================================================= */

/* Main image stays clean and proportional */
.careStoryMainImage {
  position: relative;
  height: 540px;
  overflow: hidden;
  background: #eef6f6;
}

/* Soft cinematic overlay */
.careStoryMainImage::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(11, 37, 69, 0.08),
    transparent 45%
  );
  pointer-events: none;
}

/* Image starts slightly to the left */
.careStoryMainImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: center;
  transform: translateX(-45px);
  opacity: 0.82;

  transition:
    transform 1.15s cubic-bezier(.22,.61,.36,1),
    opacity 1s ease;
}

/* When section enters viewport */
.careStoryVisual.is-visible .careStoryMainImage img {
  transform: translateX(0);
  opacity: 1;
}


/* ---------------------------------------------------------
   SMALL IMAGE
--------------------------------------------------------- */

.careStorySmallImage {
  width: 175px;
  height: 220px;
  right: -5px;
  bottom: 42px;

  padding: 7px;

  background: #fff;

  box-shadow:
    0 18px 45px rgba(11, 37, 69, 0.13);

  overflow: hidden;
}

.careStorySmallImage img {
  width: 100%;
  height: 100%;
  display: block;

  object-fit: cover;

  transform: translateX(-30px);
  opacity: 0.75;

  transition:
    transform 1s cubic-bezier(.22,.61,.36,1) .18s,
    opacity .8s ease .18s;
}

.careStoryVisual.is-visible .careStorySmallImage img {
  transform: translateX(0);
  opacity: 1;
}


/* ---------------------------------------------------------
   NUMBER — SUBTLE FLOAT-IN
--------------------------------------------------------- */

.careStoryNumber {
  opacity: 0;
  transform: translateY(18px);

  transition:
    opacity .7s ease .35s,
    transform .7s cubic-bezier(.22,.61,.36,1) .35s;
}

.careStoryVisual.is-visible .careStoryNumber {
  opacity: 1;
  transform: translateY(0);
}


/* ---------------------------------------------------------
   CONTENT CINEMATIC REVEAL
--------------------------------------------------------- */

.careStoryContent {
  transform: translateY(25px);
  opacity: 0;

  transition:
    transform .85s cubic-bezier(.22,.61,.36,1),
    opacity .8s ease;
}

.careStoryContent.is-visible {
  transform: translateY(0);
  opacity: 1;
}


/* Text elements enter progressively */
.careStoryContent .miniLabel {
  opacity: 0;
  transform: translateY(12px);

  transition:
    opacity .5s ease .1s,
    transform .5s ease .1s;
}

.careStoryContent.is-visible .miniLabel {
  opacity: 1;
  transform: translateY(0);
}

.careStoryContent h2 {
  opacity: 0;
  transform: translateY(18px);

  transition:
    opacity .7s ease .18s,
    transform .7s cubic-bezier(.22,.61,.36,1) .18s;
}

.careStoryContent.is-visible h2 {
  opacity: 1;
  transform: translateY(0);
}

.careStoryIntro {
  opacity: 0;
  transform: translateY(15px);

  transition:
    opacity .65s ease .3s,
    transform .65s ease .3s;
}

.careStoryContent.is-visible .careStoryIntro {
  opacity: 1;
  transform: translateY(0);
}


/* ---------------------------------------------------------
   CARE POINTS
--------------------------------------------------------- */

.careStoryPoint {
  opacity: 0;
  transform: translateX(20px);

  transition:
    opacity .6s ease,
    transform .65s cubic-bezier(.22,.61,.36,1);
}

.careStoryContent.is-visible .careStoryPoint:nth-child(1) {
  opacity: 1;
  transform: translateX(0);
  transition-delay: .38s;
}

.careStoryContent.is-visible .careStoryPoint:nth-child(2) {
  opacity: 1;
  transform: translateX(0);
  transition-delay: .48s;
}

.careStoryContent.is-visible .careStoryPoint:nth-child(3) {
  opacity: 1;
  transform: translateX(0);
  transition-delay: .58s;
}


/* ---------------------------------------------------------
   IMAGE HOVER — SLIDE, NOT ZOOM
--------------------------------------------------------- */

.careStoryMainImage {
  cursor: pointer;
}

.careStoryMainImage img {
  transition:
    transform 1.15s cubic-bezier(.22,.61,.36,1),
    opacity 1s ease;
}

.careStoryMainImage:hover img {
  transform: translateX(7px);
}

.careStorySmallImage:hover img {
  transform: translateX(6px);
}


/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 600px) {

  .careStoryMainImage {
    height: 380px;
  }

  .careStoryMainImage img {
    transform: translateX(-28px);
  }

  .careStoryVisual.is-visible .careStoryMainImage img {
    transform: translateX(0);
  }

  .careStorySmallImage {
    width: 120px;
    height: 150px;
    right: 0;
    bottom: 25px;
    padding: 5px;
  }

  .careStoryNumber {
    left: -5px;
    top: 18px;
  }

  .careStoryMainImage:hover img,
  .careStorySmallImage:hover img {
    transform: none;
  }
}


/* ---------------------------------------------------------
   REDUCED MOTION
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

  .careStoryMainImage img,
  .careStorySmallImage img,
  .careStoryNumber,
  .careStoryContent,
  .careStoryContent h2,
  .careStoryContent .miniLabel,
  .careStoryIntro,
  .careStoryPoint {
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}
