/* MAIN VISUAL GRID */

.novaDifferenceGrid {
  display: grid;
  grid-template-columns: 1.3fr .8fr .8fr;
  grid-template-rows: 250px 250px;
  gap: 13px;
}

/* LARGE IMAGE */

.differenceVisual {
  position: relative;
  grid-row: span 2;
  min-height: 513px;
  overflow: hidden;
  background: #dce8eb;
}

.differenceVisual img,
.differenceImageSmall img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: filter .45s ease;
}

.differenceVisual:hover img,
.differenceImageSmall:hover img {
  filter: saturate(1.06) contrast(1.02);
}

.differenceVisual::after,
.differenceImageSmall::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    transparent 38%,
    rgba(6,26,49,.82)
  );
}

.differenceVisualOverlay {
  position: absolute;
  left: 24px;
  right: 24px;
  bottom: 23px;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  gap: 15px;
  color: #fff;
}

.differenceVisualNumber {
  color: rgba(255,255,255,.68);
  font-family: "Playfair Display", serif;
  font-size: 57px;
  line-height: .8;
}

.differenceVisualOverlay small {
  display: block;
