  margin: 6px 0 0;
  font-family: "Playfair Display", serif;
  font-size: 24px;
  line-height: 1.1;
  font-weight: 500;
}

/* CONTENT */

.differenceContent {
  position: relative;
  padding: 27px;
  background: #fff;
  border: 1px solid #dce8eb;
  transition:
    border-color .3s ease,
    transform .3s ease,
    box-shadow .3s ease;
}

.differenceContent:hover {
  border-color: var(--primary);
  transform: translateY(-3px);
  box-shadow: 0 12px 30px rgba(11,37,69,.07);
}

.differenceContentDark {
  background: var(--ink);
  border-color: var(--ink);
}

.differenceContentDark:hover {
  border-color: var(--primary);
}

.differenceNumber {
  position: absolute;
  top: 18px;
  right: 21px;
  color: #a6b7bb;
  font-family: "Playfair Display", serif;
  font-size: 24px;
}

.differenceIcon {
  display: flex;
  align-items: center;
