  max-width: 285px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}

.differenceContentDark p {
  color: rgba(255,255,255,.67);
}

.differenceArrow {
  position: absolute;
  right: 21px;
  bottom: 18px;
  color: var(--primary);
  font-size: 21px;
  transition: transform .3s ease;
}

.differenceContent:hover .differenceArrow {
  transform: translate(4px,-4px);
}

/* SMALL IMAGE */

.differenceImageSmall {
  position: relative;
  overflow: hidden;
}

.differenceImageLabel {
  position: absolute;
  left: 17px;
  bottom: 17px;
  z-index: 2;
  color: #fff;
}

