  font-size: 34px;
  line-height: 1;
}

.differenceImageLabel small {
  color: rgba(255,255,255,.8);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .17em;
}

/* BOTTOM BRAND LINE */

.differenceBottomLine {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid #dce8eb;
  color: #94a3b8;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
}

/* REVEAL */

.novaDifference [data-reveal] {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity .65s ease,
    transform .65s cubic-bezier(.2,.7,.2,1);
}

.novaDifference [data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

.novaDifferenceGrid > *:nth-child(2) {
  transition-delay: .1s;
}

.novaDifferenceGrid > *:nth-child(3) {
  transition-delay: .18s;
}

.novaDifferenceGrid > *:nth-child(4) {
  transition-delay: .26s;
}

.differenceBottomLine {
  transition-delay: .34s !important;
}

/* TABLET */

@media (max-width: 950px) {
  .novaDifference {
    padding: 70px 0 !important;
  }

  .novaDifference .differenceIntro {
    grid-template-columns: 1fr;
    gap: 22px;
  }

  .novaDifferenceGrid {
