  }

}
/* =========================================================
   SMILE JOURNEY — CINEMATIC IMAGE FLY-IN
   JSX UNCHANGED
   ========================================================= */

.smileJourneyItem {
  overflow: visible;
}

.smileJourneyImage {
  opacity: 0;
  will-change: transform, opacity, filter;

  transition:
    opacity 0.8s ease,
    transform 1.15s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.8s ease;
}


/* 01 — LEFT SIDE */

.smileJourneyItem:nth-child(1)
.smileJourneyImage {
  transform:
    translate3d(-180px, 35px, 0)
    rotate(-4deg)
    scale(0.90);

  filter: blur(4px);
}


/* 02 — RIGHT SIDE */

.smileJourneyItem:nth-child(2)
.smileJourneyImage {
  transform:
    translate3d(180px, 35px, 0)
    rotate(4deg)
    scale(0.90);

  filter: blur(4px);
}


/* 03 — LEFT SIDE */

.smileJourneyItem:nth-child(3)
.smileJourneyImage {
  transform:
    translate3d(-180px, 35px, 0)
    rotate(-4deg)
    scale(0.90);

  filter: blur(4px);
}


/* =========================================================
   FINAL POSITION
   ========================================================= */

.smileJourneyItem.is-visible
.smileJourneyImage {
  opacity: 1;

  transform:
    translate3d(0, 0, 0)
    rotate(0deg)
    scale(1);

  filter: blur(0);
}


/* =========================================================
   STAGGERED ARRIVAL
   ========================================================= */

.smileJourneyItem:nth-child(1)
.smileJourneyImage {
  transition-delay: 0.05s;
}

.smileJourneyItem:nth-child(2)
.smileJourneyImage {
  transition-delay: 0.18s;
}

.smileJourneyItem:nth-child(3)
.smileJourneyImage {
  transition-delay: 0.31s;
}


/* =========================================================
   IMAGE ITSELF
   ========================================================= */

.smileJourneyImage img {
  transform: scale(1.06);

  transition:
    transform 1.3s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.7s ease;
}

.smileJourneyItem.is-visible
.smileJourneyImage img {
  transform: scale(1);
}


/* =========================================================
   META + TEXT ARRIVE AFTER IMAGE
   ========================================================= */

.smileJourneyItem .smileJourneyMeta {
  opacity: 0;
  transform: translateY(14px);

  transition:
    opacity 0.6s ease,
    transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.smileJourneyItem .smileJourneyCopy {
  opacity: 0;
  transform: translateY(16px);

  transition:
    opacity 0.65s ease,
    transform 0.65s cubic-bezier(0.16, 1, 0.3, 1);
}


.smileJourneyItem.is-visible
.smileJourneyMeta {
  opacity: 1;
  transform: translateY(0);

  transition-delay: 0.55s;
}


.smileJourneyItem.is-visible
.smileJourneyCopy {
  opacity: 1;
  transform: translateY(0);

  transition-delay: 0.68s;
}


/* =========================================================
   HOVER
   ========================================================= */

.smileJourneyItem:hover
.smileJourneyImage {
  transform:
    translate3d(0, -5px, 0)
    rotate(0deg)
    scale(1.01);
}

.smileJourneyItem:hover
.smileJourneyImage img {
  transform: scale(1.035);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 680px) {

  .smileJourneyItem:nth-child(1)
  .smileJourneyImage,
  .smileJourneyItem:nth-child(3)
  .smileJourneyImage {
    transform:
      translate3d(-90px, 25px, 0)
      rotate(-2deg)
      scale(0.94);

    filter: blur(3px);
  }

  .smileJourneyItem:nth-child(2)
  .smileJourneyImage {
    transform:
      translate3d(90px, 25px, 0)
      rotate(2deg)
      scale(0.94);

    filter: blur(3px);
  }

  .smileJourneyItem.is-visible
  .smileJourneyImage {
    transform:
      translate3d(0, 0, 0)
      rotate(0deg)
      scale(1);

    filter: blur(0);
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .smileJourneyImage,
  .smileJourneyImage img,
  .smileJourneyMeta,
  .smileJourneyCopy {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
    transition: none !important;
  }

}
