  overflow: hidden;

  background: var(--soft-bg);

  border: 1px solid var(--border);

  box-shadow:
    0 30px 80px rgba(11, 37, 69, 0.12);
}

.philosophyImageFrame img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transform: scale(1.035);

  transition:
    transform 1.5s cubic-bezier(0.16, 1, 0.3, 1),
    filter 1s ease;
}

.philosophyMainVisual:hover
.philosophyImageFrame img {
  transform: scale(1.07);
}

.philosophyImageShade {
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      180deg,
      rgba(6, 26, 49, 0.02) 40%,
      rgba(6, 26, 49, 0.62) 100%
    );

  pointer-events: none;
}


/* image label */

.philosophyImageLabel {
  position: absolute;

  left: 30px;
  bottom: 28px;

  z-index: 4;

  display: flex;
  align-items: center;
  gap: 14px;

  color: #ffffff;
}

.philosophyImageLabel span {
  font-family: "Playfair Display", serif;
  font-size: 50px;
  line-height: 1;
}

.philosophyImageLabel div {
  width: 42px;
  height: 1px;

  background: rgba(255, 255, 255, 0.55);
}

.philosophyImageLabel small {
  font-size: 9px;
  letter-spacing: 0.18em;
}


/* corner labels */

.philosophyCorner {
  position: absolute;

  z-index: 5;

  color: rgba(255, 255, 255, 0.82);

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.philosophyCornerTop {
  top: 24px;
  left: 26px;
}

.philosophyCornerBottom {
  right: 25px;
  bottom: 25px;

  writing-mode: vertical-rl;

  transform: rotate(180deg);
}


/* =========================================================
   CONTENT
   ========================================================= */

.philosophyStoryContent {
  position: relative;

  min-height: 680px;

  padding: 52px 48px;

  display: flex;
  flex-direction: column;
  justify-content: space-between;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.96),
      rgba(239, 247, 247, 0.78)
    );

  border: 1px solid var(--border);

  box-shadow:
    0 18px 55px rgba(11, 37, 69, 0.06);
}

.philosophyStoryContent::before {
  content: "";

  position: absolute;
  top: -1px;
  right: -1px;

  width: 100px;
  height: 100px;

  border-top: 1px solid var(--primary);
  border-right: 1px solid var(--primary);

  opacity: 0.45;
}

.philosophySmallLabel {
  display: block;

  margin-bottom: 34px;

  color: var(--primary);

  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.philosophyContentTop h3 {
  max-width: 510px;

  margin: 0 0 22px;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: clamp(38px, 4vw, 58px);
  line-height: 1.02;

  font-weight: 500;

  letter-spacing: -0.04em;
}

.philosophyContentTop h3 em {
  color: var(--primary);

  font-style: italic;
  font-weight: 400;
}

.philosophyContentTop > p {
  max-width: 460px;

  margin: 0;

  color: var(--muted);

  font-size: 13px;
  line-height: 1.9;
}


/* =========================================================
   PRINCIPLES
   ========================================================= */

.philosophyPrincipleList {
  margin-top: 55px;

  border-top: 1px solid var(--border);
}

.philosophyPrinciple {
  display: grid;

  grid-template-columns: 38px minmax(0, 1fr) 24px;

  align-items: center;

  gap: 15px;

  min-height: 72px;

  border-bottom: 1px solid var(--border);

  transition:
    padding 0.35s ease,
    background 0.35s ease;
}

.philosophyPrinciple:hover {
  padding-left: 12px;

  background:
    linear-gradient(
      90deg,
      rgba(85, 184, 176, 0.08),
      transparent
    );
}

.philosophyPrinciple > span {
  color: var(--primary);

  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.philosophyPrinciple h4 {
  margin: 0 0 3px;

  color: var(--ink);

  font-size: 12px;
  font-weight: 700;
}

.philosophyPrinciple p {
  margin: 0;

  color: var(--muted);

  font-size: 10px;
  line-height: 1.5;
}

.philosophyPrinciple b {
  color: var(--primary);

  font-size: 17px;
  font-weight: 400;

  transition:
    transform 0.35s ease;
}

.philosophyPrinciple:hover b {
  transform:
    translate(4px, -4px);
}


/* =========================================================
   BOTTOM IMAGE STRIP
   ========================================================= */

.philosophyBottom {
  position: relative;

  display: grid;
  grid-template-columns: 210px minmax(0, 1fr) 100px;

  align-items: center;

  min-height: 155px;

  margin-top: 24px;

  overflow: hidden;

  border: 1px solid var(--border);

  background: #ffffff;
}

.philosophyBottomImage {
  height: 155px;

  overflow: hidden;
}

.philosophyBottomImage img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  transition:
    transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.philosophyBottom:hover
.philosophyBottomImage img {
  transform: scale(1.07);
}

.philosophyBottomText {
  padding: 25px 35px;
}

.philosophyBottomText span {
  display: block;

  margin-bottom: 12px;

  color: var(--primary);

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.philosophyBottomText p {
  max-width: 560px;

  margin: 0;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: clamp(20px, 2.3vw, 30px);
  line-height: 1.15;
}

.philosophyBottomNumber {
  color: rgba(31, 138, 138, 0.16);

  font-family: "Playfair Display", serif;

  font-size: 80px;
  line-height: 1;

  text-align: center;
}


/* =========================================================
   FOOTER
   ========================================================= */

.philosophyFooter {
  display: grid;

  grid-template-columns: 1fr auto 1fr;

  align-items: center;

  gap: 30px;

  padding-top: 28px;

  color: #8b9aa5;

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
}

.philosophyFooter > span:last-child {
  text-align: right;
}

.philosophyProgress {
  display: flex;
  align-items: center;
  gap: 10px;
}

.philosophyProgress b {
  color: var(--primary);

  font-size: 8px;
}

.philosophyProgress i {
  width: 28px;
  height: 1px;

  background: var(--border);
}


/* =========================================================
   SCROLL REVEAL
   ========================================================= */

.philosophyCinematic [data-reveal] {
  opacity: 0;

  transform:
    translateY(45px)
    scale(0.985);

  transition:
    opacity 0.8s ease,
    transform 1s cubic-bezier(0.16, 1, 0.3, 1);
}


/* header */

.philosophyCinematic
.philosophyTop.is-visible {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  transition-delay: 0.05s;
}


/* MAIN IMAGE — flies from left */

.philosophyCinematic
.philosophyMainVisual {
  opacity: 0;

  transform:
    translate3d(-150px, 45px, 0)
    rotate(-3deg)
    scale(0.93);

  filter: blur(4px);

  transition:
    opacity 0.8s ease,
    transform 1.25s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.9s ease;
}

.philosophyCinematic
.philosophyMainVisual.is-visible {
  opacity: 1;

  transform:
    translate3d(0, 0, 0)
    rotate(0)
    scale(1);

  filter: blur(0);

  transition-delay: 0.12s;
}


/* RIGHT CONTENT — arrives after image */

.philosophyCinematic
.philosophyStoryContent.is-visible {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  transition-delay: 0.3s;
}


/* bottom strip */

.philosophyCinematic
.philosophyBottom.is-visible {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  transition-delay: 0.45s;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1000px) {

  .philosophyCinematic {
    padding: 95px 0 65px;
  }

  .philosophyTop {
    grid-template-columns: 1fr;

    gap: 28px;

    margin-bottom: 55px;
  }

  .philosophyIntro {
    max-width: 500px;
  }

  .philosophyStory {
    grid-template-columns: 1fr;
  }

  .philosophyMainVisual {
    min-height: 560px;
  }

  .philosophyStoryContent {
    min-height: auto;
  }

  .philosophyBottom {
    grid-template-columns: 170px minmax(0, 1fr) 80px;
  }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

  .philosophyCinematic {
    padding: 75px 0 50px;
  }

  .philosophyTitleBlock h2 {
    font-size: clamp(42px, 12vw, 58px);

    line-height: 0.98;
  }

  .philosophyIndex {
    position: static;

    margin-top: 15px;
  }

  .philosophyIntro {
    padding-left: 20px;
  }

  .philosophyIntro p {
    font-size: 12px;
    line-height: 1.8;
  }

  .philosophyStory {
    gap: 14px;
  }

  .philosophyMainVisual {
    min-height: 430px;
  }

  .philosophyImageFrame {
    position: absolute;
  }

  .philosophyImageLabel {
    left: 20px;
    bottom: 20px;
  }

  .philosophyImageLabel span {
    font-size: 38px;
  }

  .philosophyCorner {
    font-size: 7px;
  }

  .philosophyStoryContent {
    padding: 30px 22px;
  }

  .philosophySmallLabel {
    margin-bottom: 25px;
  }

  .philosophyContentTop h3 {
    font-size: 36px;
  }

  .philosophyContentTop > p {
    font-size: 12px;
    line-height: 1.8;
  }

  .philosophyPrincipleList {
    margin-top: 35px;
  }

  .philosophyPrinciple {
    grid-template-columns: 28px minmax(0, 1fr) 18px;

    min-height: 70px;

    gap: 9px;
  }

  .philosophyPrinciple p {
    font-size: 9px;
  }

  .philosophyBottom {
    grid-template-columns: 100px minmax(0, 1fr);

    min-height: 120px;
  }

  .philosophyBottomImage {
    height: 120px;
  }

  .philosophyBottomText {
    padding: 18px;
  }

  .philosophyBottomText p {
    font-size: 19px;
  }

  .philosophyBottomNumber {
    display: none;
  }

  .philosophyFooter {
    grid-template-columns: 1fr;

    gap: 14px;

    text-align: left;
  }

  .philosophyFooter > span:last-child {
    text-align: left;
  }

  .philosophyProgress {
    order: 3;
  }

  /* smaller flying distance on mobile */

  .philosophyCinematic
  .philosophyMainVisual {
    transform:
      translate3d(-90px, 35px, 0)
      rotate(-3deg)
      scale(0.94);

    filter: blur(3px);
  }

  .philosophyCinematic
  .philosophyMainVisual.is-visible {
    transform:
      translate3d(0, 0, 0)
      rotate(0)
      scale(1);

    filter: blur(0);
  }

}


/* =========================================================
   ACCESSIBILITY
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .philosophyOrb,
  .philosophyCinematic [data-reveal],
  .philosophyCinematic
  .philosophyMainVisual,
  .philosophyImageFrame img,
  .philosophyBottomImage img,
  .philosophyPrinciple,
  .philosophyPrinciple b {
    animation: none !important;

    transition: none !important;

    transform: none !important;
    filter: none !important;
  }

}
/* =========================================================
   NOVADENT — OUR PHILOSOPHY
   UNIQUE CINEMATIC EDITORIAL SECTION
   ========================================================= */

.philosophyNew {
  position: relative;
  padding: 125px 0 95px;
  overflow: hidden;

  background:
    radial-gradient(
      circle at 8% 25%,
      rgba(85, 184, 176, 0.11),
      transparent 26%
    ),
    radial-gradient(
      circle at 92% 80%,
      rgba(31, 138, 138, 0.08),
      transparent 28%
    ),
    #ffffff;
}


/* =========================================================
   BACKGROUND GLOW
   ========================================================= */

.philosophyNewGlow {
  position: absolute;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(45px);
  opacity: 0.45;
  animation: philosophyGlowMove 10s ease-in-out infinite;
}

.philosophyGlowOne {
  left: -250px;
  top: 10%;

  background:
    radial-gradient(
      circle,
      rgba(85, 184, 176, 0.15),
      transparent 70%
    );
}

.philosophyGlowTwo {
  right: -250px;
  bottom: 5%;

  background:
    radial-gradient(
      circle,
      rgba(31, 138, 138, 0.12),
      transparent 70%
    );

  animation-delay: -5s;
}

@keyframes philosophyGlowMove {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }

  50% {
    transform: translate3d(35px, -25px, 0);
  }
}


/* =========================================================
   INNER
   ========================================================= */

.philosophyNewInner {
  position: relative;
  z-index: 2;
}


/* =========================================================
   HEADER
   ========================================================= */

.philosophyNewHeader {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.65fr);
  gap: 90px;
  align-items: end;

  margin-bottom: 72px;
}

.philosophyNewHeading {
  position: relative;
}

.philosophyNewLabel {
  display: flex;
  align-items: center;
  gap: 12px;

  margin-bottom: 20px;

  color: var(--primary);

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
}

.philosophyNewLabel span {
  width: 42px;
  height: 1px;
  background: var(--primary);
}

.philosophyNewIndex {
  position: absolute;
  top: 3px;
  right: 0;

  color: #9aa9b3;

  font-size: 9px;
  letter-spacing: 0.16em;
}

.philosophyNewHeading h2 {
  max-width: 850px;

  margin: 0;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: clamp(54px, 7vw, 96px);
  font-weight: 500;
  line-height: 0.94;

  letter-spacing: -0.06em;
}

.philosophyNewHeading h2 em {
  color: var(--primary);
  font-style: italic;
  font-weight: 400;
}

.philosophyNewIntro {
  position: relative;
  padding-left: 28px;
}

.philosophyNewIntro::before {
  content: "";

  position: absolute;
  left: 0;
  top: 0;

  width: 1px;
  height: 100%;

  background:
    linear-gradient(
      to bottom,
      var(--primary),
      transparent
    );
}

.philosophyNewIntro span {
  display: block;

  margin-bottom: 17px;

  color: var(--ink);

  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
}

.philosophyNewIntro p {
  max-width: 370px;

  margin: 0;

  color: var(--muted);

  font-size: 13px;
  line-height: 1.9;
}


/* =========================================================
   BIG STATEMENT
   ========================================================= */

.philosophyStatement {
  position: relative;

  max-width: 1060px;

  margin: 0 auto 85px;

  padding: 0 80px;

  text-align: center;
}

.philosophyQuoteMark {
  display: block;

  height: 52px;

  color: rgba(31, 138, 138, 0.18);

  font-family: "Playfair Display", serif;

  font-size: 100px;
  line-height: 0.8;
}

.philosophyStatement p {
  max-width: 900px;

  margin: 0 auto;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: clamp(27px, 3.3vw, 45px);
  line-height: 1.25;

  font-weight: 400;

  letter-spacing: -0.025em;
}

.philosophyStatementLine {
  display: block;

  width: 70px;
  height: 1px;

  margin: 30px auto 17px;

  background: var(--primary);
}

.philosophyStatement small {
  color: #8b9aa5;

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
}


/* =========================================================
   VALUES GRID
   ========================================================= */

.philosophyValues {
  display: grid;

  grid-template-columns: repeat(4, 1fr);

  border-top: 1px solid var(--border);
  border-left: 1px solid var(--border);
}


/* =========================================================
   VALUE ITEM
   ========================================================= */

.philosophyValue {
  position: relative;

  min-height: 430px;

  padding: 28px 27px 30px;

  overflow: hidden;

  background: rgba(255, 255, 255, 0.78);

  border-right: 1px solid var(--border);
  border-bottom: 1px solid var(--border);

  transition:
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    background 0.45s ease,
    box-shadow 0.45s ease;
}

.philosophyValue:hover {
  z-index: 3;

  transform:
    translateY(-10px);

  background: #ffffff;

  box-shadow:
    0 25px 60px rgba(11, 37, 69, 0.12);
}


/* top */

.philosophyValueTop {
  display: flex;
  justify-content: space-between;
  align-items: center;

  color: #8b9aa5;

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.17em;
}

.philosophyValueTop span:first-child {
  color: var(--primary);
}


/* large background number */

.philosophyValueNumber,
.philosophyValueIcon {
  position: absolute;

  right: -8px;
  top: 55px;

  color: rgba(31, 138, 138, 0.07);

  font-family: "Playfair Display", serif;

  font-size: 145px;

  line-height: 1;

  pointer-events: none;

  transition:
    transform 0.6s ease,
    color 0.6s ease;
}

.philosophyValue:hover
.philosophyValueNumber {
  transform:
    translate(-10px, -10px)
    scale(1.04);

  color: rgba(31, 138, 138, 0.11);
}

.philosophyValueIcon span {
  display: none;
}


/* content */

.philosophyValue h3 {
  position: relative;
  z-index: 2;

  max-width: 230px;

  margin: 175px 0 18px;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: clamp(27px, 2.3vw, 36px);
  line-height: 1.04;

  font-weight: 500;

  letter-spacing: -0.035em;
}

.philosophyValue h3 em {
  color: var(--primary);

  font-style: italic;
  font-weight: 400;
}

.philosophyValue p {
  position: relative;
  z-index: 2;

  max-width: 245px;

  margin: 0;

  color: var(--muted);

  font-size: 11px;
  line-height: 1.75;
}


/* arrow */

.philosophyValueArrow {
  position: absolute;

  right: 25px;
  bottom: 26px;

  width: 34px;
  height: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: 1px solid var(--border);

  color: var(--primary);

  font-size: 16px;

  transition:
    transform 0.4s ease,
    background 0.4s ease,
    color 0.4s ease;
}

.philosophyValue:hover
.philosophyValueArrow {
  transform:
    translate(4px, -4px);

  background: var(--primary);

  color: #ffffff;
}


/* dark first panel */

.philosophyValueDark {
  background: var(--ink);
}

.philosophyValueDark:hover {
  background: var(--ink-dark);
}

.philosophyValueDark .philosophyValueTop {
  color: rgba(255, 255, 255, 0.5);
}

.philosophyValueDark .philosophyValueTop span:first-child {
  color: var(--accent);
}

.philosophyValueDark h3 {
  color: #ffffff;
}

.philosophyValueDark p {
  color: rgba(255, 255, 255, 0.62);
}

.philosophyValueDark
.philosophyValueNumber {
  color: rgba(255, 255, 255, 0.055);
}

.philosophyValueDark
.philosophyValueArrow {
  border-color: rgba(255, 255, 255, 0.18);
  color: var(--accent);
}


/* accent panel */

.philosophyValueAccent {
  background:
    linear-gradient(
      145deg,
      var(--light-teal),
      #ffffff
    );
}

.philosophyValueAccent
.philosophyValueNumber {
  color: rgba(31, 138, 138, 0.11);
}


/* =========================================================
   BOTTOM CINEMATIC LINE
   ========================================================= */

.philosophyNewFooter {
  display: grid;

  grid-template-columns: 150px minmax(80px, 1fr) auto minmax(80px, 1fr) 150px;

  align-items: center;

  gap: 18px;

  margin-top: 45px;

  padding-top: 25px;

  border-top: 1px solid var(--border);
}

.philosophyFooterWord {
  display: flex;
  align-items: center;
  gap: 9px;

  color: #8b9aa5;

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.16em;
}

.philosophyFooterWord b {
  color: var(--primary);
}

.philosophyFooterRight {
  justify-content: flex-end;
}

.philosophyFooterLine {
  height: 1px;

  background:
    linear-gradient(
      90deg,
      transparent,
      var(--border)
    );
}

.philosophyNewFooter p {
  margin: 0;

  white-space: nowrap;

  color: var(--ink);

  font-family: "Playfair Display", serif;

  font-size: 17px;
}

.philosophyNewFooter p em {
  color: var(--primary);
  font-style: italic;
}


/* =========================================================
   REVEAL ANIMATION
   Existing IntersectionObserver is reused
   ========================================================= */

.philosophyNew [data-reveal] {
  opacity: 0;

  transform:
    translateY(45px)
    scale(0.985);

  transition:
    opacity 0.8s ease,
    transform 1s cubic-bezier(0.16, 1, 0.3, 1);
}

.philosophyNew [data-reveal].is-visible {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);
}

.philosophyNewHeader.is-visible {
  transition-delay: 0.05s;
}

.philosophyStatement.is-visible {
  transition-delay: 0.18s;
}

.philosophyValue:nth-child(1).is-visible {
  transition-delay: 0.10s;
}

.philosophyValue:nth-child(2).is-visible {
  transition-delay: 0.18s;
