/* ---------------------------------------------------------
   CINEMATIC REVEAL
   --------------------------------------------------------- */

.treatmentCard[data-reveal] {
  opacity: 0;

  transform:
    translateY(25px)
    scale(0.97);

  filter: blur(2px);

  transition:
    opacity 0.65s ease,
    transform 0.75s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.65s ease,
    box-shadow 0.4s ease,
    border-color 0.3s ease;
}

.treatmentCard[data-reveal].is-visible {
  opacity: 1;

  transform:
    translateY(0)
    scale(1);

  filter: blur(0);
}

.treatmentCard:nth-child(1).is-visible {
  transition-delay: 0.04s;
}

.treatmentCard:nth-child(2).is-visible {
  transition-delay: 0.12s;
}

.treatmentCard:nth-child(3).is-visible {
  transition-delay: 0.20s;
}

.treatmentCard:nth-child(4).is-visible {
  transition-delay: 0.28s;
}

.treatmentCard:nth-child(5).is-visible {
