/* =========================================================
   NOVADENT — CINEMATIC STORYTELLING SYSTEM
   Existing JSX / content preserved
   ========================================================= */

/* ---------- GLOBAL STORY REVEAL ---------- */

[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 45px, 0);
  filter: blur(5px);
  transition:
    opacity 0.9s cubic-bezier(0.16, 1, 0.3, 1),
    transform 1s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.9s ease;
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  filter: blur(0);
}

/* ---------- STORY CHILDREN ---------- */

[data-reveal].is-visible h1,
[data-reveal].is-visible h2,
[data-reveal].is-visible h3 {
  animation: novaTextRise 0.85s cubic-bezier(0.16, 1, 0.3, 1) both;
}

[data-reveal].is-visible p {
  animation: novaTextRise 0.75s 0.12s cubic-bezier(0.16, 1, 0.3, 1) both;
}

[data-reveal].is-visible .miniLabel,
[data-reveal].is-visible .storyIndex,
[data-reveal].is-visible .differenceSectionLabel,
[data-reveal].is-visible .novaPhilosophyLabel {
  animation: novaLabelReveal 0.65s 0.05s ease both;
}

@keyframes novaTextRise {
  from {
    opacity: 0;
    transform: translate3d(0, 24px, 0);
    filter: blur(4px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

@keyframes novaLabelReveal {
  from {
    opacity: 0;
    transform: translate3d(-18px, 0, 0);
    letter-spacing: 0.2em;
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    letter-spacing: normal;
  }
}


/* =========================================================
   TREATMENTS — COMPACT PREMIUM CINEMATIC
   ========================================================= */

.ndtTreatments {
  position: relative;
  overflow: hidden;
}

/* Heading */

.ndtTreatments .ndtHeading {
  margin-bottom: 34px !important;
}

.ndtTreatments .ndtHeading h2 {
  max-width: 680px !important;
  margin: 0 !important;

  font-size: clamp(32px, 3.2vw, 43px) !important;
  line-height: 0.98 !important;
  letter-spacing: -0.035em !important;

  transform-origin: left center;
}

.ndtTreatments .ndtHeading > p {
  max-width: 460px !important;
  margin-top: 12px !important;

  font-size: 11px !important;
  line-height: 1.65 !important;
}

/* Heading cinematic entrance */

.ndtTreatments .ndtHeading.is-visible h2 {
  animation:
    novaTreatmentHeading 1s
    cubic-bezier(0.16, 1, 0.3, 1)
    both;
}

.ndtTreatments .ndtHeading.is-visible > p {
  animation:
    novaTextRise 0.8s 0.18s
    cubic-bezier(0.16, 1, 0.3, 1)
    both;
}

@keyframes novaTreatmentHeading {
  from {
    opacity: 0;
    transform: translate3d(0, 35px, 0) scale(0.97);
    filter: blur(8px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: blur(0);
  }
}


/* =========================================================
   3 COLUMN DESKTOP
   ========================================================= */

.ndtTreatments .ndtCards {
  display: grid !important;

  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 18px !important;

  width: 100% !important;
}


/* =========================================================
   TREATMENT CARD
   ========================================================= */

.ndtTreatments .ndtCard {
  position: relative;

  display: flex !important;
  flex-direction: column !important;

  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;

  height: 390px !important;
  min-height: 390px !important;

  overflow: hidden !important;

  opacity: 0;
  transform:
    translate3d(0, 55px, 0)
    scale(0.965);

  filter: blur(5px);

  transition:
    opacity 0.85s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.95s cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 0.45s ease;
}


/* Cards appear one by one */

.ndtTreatments .ndtCard:nth-child(1) {
  transition-delay: 0.05s;
}

.ndtTreatments .ndtCard:nth-child(2) {
  transition-delay: 0.15s;
}

.ndtTreatments .ndtCard:nth-child(3) {
  transition-delay: 0.25s;
}

.ndtTreatments .ndtCard:nth-child(4) {
  transition-delay: 0.35s;
}

.ndtTreatments .ndtCard:nth-child(5) {
  transition-delay: 0.45s;
}

.ndtTreatments .ndtCard:nth-child(6) {
  transition-delay: 0.55s;
}

.ndtTreatments .ndtCard.is-visible {
  opacity: 1;
  transform:
    translate3d(0, 0, 0)
    scale(1);

  filter: blur(0);
}


/* =========================================================
   CARD IMAGE — CINEMATIC CAMERA EFFECT
   ========================================================= */

.ndtTreatments .ndtCardImage {
  position: relative;

  width: 100% !important;

  height: 178px !important;
  min-height: 178px !important;

  flex: 0 0 178px !important;

  overflow: hidden !important;
}

.ndtTreatments .ndtCardImage img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transform:
    scale(1.12)
    translate3d(0, 10px, 0);

  filter: saturate(0.82);

  transition:
    transform 1.25s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.8s ease;
}

.ndtTreatments .ndtCard.is-visible .ndtCardImage img {
  transform:
    scale(1)
    translate3d(0, 0, 0);

  filter: saturate(1);
}


/* Hover camera movement */

.ndtTreatments .ndtCard:hover .ndtCardImage img {
  transform:
    scale(1.075)
    translate3d(0, -3px, 0);
}


/* Overlay */

.ndtTreatments .ndtImageOverlay {
  opacity: 0.25;

  transition:
    opacity 0.5s ease;
}

.ndtTreatments .ndtCard:hover .ndtImageOverlay {
  opacity: 0.5;
}


/* =========================================================
   IMAGE META — STAGGER
   ========================================================= */

.ndtTreatments .ndtCardNumber,
.ndtTreatments .ndtCardCategory,
.ndtTreatments .ndtCardDuration,
.ndtTreatments .ndtImageBottom {
  opacity: 0;

  transform: translate3d(0, 12px, 0);

  transition:
    opacity 0.55s ease,
    transform 0.65s cubic-bezier(0.16, 1, 0.3, 1);
}

.ndtTreatments .ndtCard.is-visible .ndtCardNumber {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.45s;
}

.ndtTreatments .ndtCard.is-visible .ndtCardCategory {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.52s;
}

.ndtTreatments .ndtCard.is-visible .ndtCardDuration {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.58s;
}

.ndtTreatments .ndtCard.is-visible .ndtImageBottom {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.64s;
}


/* =========================================================
   CARD BODY
   ========================================================= */

.ndtTreatments .ndtCardBody {
  padding: 16px 17px !important;
}

.ndtTreatments .ndtCardTitle {
  opacity: 0;
  transform: translate3d(0, 16px, 0);

  transition:
    opacity 0.6s ease,
    transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.ndtTreatments .ndtCard.is-visible .ndtCardTitle {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.48s;
}

.ndtTreatments .ndtCardTitle h3 {
  font-size: 20px !important;
  line-height: 1.05 !important;
}


/* Description */

.ndtTreatments .ndtCardBody > p {
  opacity: 0;

  transform: translate3d(0, 13px, 0);

  font-size: 10px !important;
  line-height: 1.55 !important;

  margin-top: 8px !important;

  transition:
    opacity 0.55s ease,
    transform 0.65s cubic-bezier(0.16, 1, 0.3, 1);
}

.ndtTreatments .ndtCard.is-visible .ndtCardBody > p {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.58s;
}


/* Tags */

.ndtTreatments .ndtTags {
  opacity: 0;

  transform: translate3d(0, 10px, 0);

  padding-top: 8px !important;
  gap: 4px !important;

  transition:
    opacity 0.5s ease,
    transform 0.55s ease;
}

.ndtTreatments .ndtCard.is-visible .ndtTags {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.68s;
}

.ndtTreatments .ndtTags span {
  padding: 4px 7px !important;
  font-size: 6.5px !important;
}


/* Link */

.ndtTreatments .ndtCardLink {
  opacity: 0;

  transform: translate3d(0, 8px, 0);

  margin-top: 8px !important;

  font-size: 7.5px !important;

  transition:
    opacity 0.5s ease,
    transform 0.55s ease;
}

.ndtTreatments .ndtCard.is-visible .ndtCardLink {
  opacity: 1;
  transform: translate3d(0, 0, 0);
  transition-delay: 0.76s;
}


/* =========================================================
   CARD HOVER — PREMIUM
   ========================================================= */

.ndtTreatments .ndtCard:hover {
  transform:
    translate3d(0, -8px, 0)
    scale(1.012);

  box-shadow:
    0 24px 55px rgba(11, 37, 69, 0.16);
}

.ndtTreatments .ndtImageArrow {
  transition:
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.ndtTreatments .ndtCard:hover .ndtImageArrow {
  transform:
    translate3d(4px, -4px, 0);
}


