}

.cinematicReviewImage {
  position: relative;
  overflow: hidden;
}

.cinematicReviewImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scale(1.06);
  transition: transform 1.2s cubic-bezier(.16,1,.3,1);
}

.cinematicReviewFeature:hover
