    width .35s ease,
    background .35s ease;
}

.cinematicReviewControls > div button.active {
  width: 42px;
  background: var(--primary);
}

/* =========================================================
   APPOINTMENT — CINEMATIC FINAL SECTION
========================================================= */

.cinematicAppointment {
  position: relative;
  isolation: isolate;
  min-height: 510px;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding: 90px 5%;
  background:
    radial-gradient(
      circle at 78% 30%,
      rgba(85, 184, 176, 0.28),
      transparent 32%
    ),
    linear-gradient(
      120deg,
      #061a31 0%,
      #0b2545 52%,
      #103f52 100%
    );
}

.cinematicAppointmentAmbient {
  position: absolute;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.cinematicAppointmentAmbient span {
  position: absolute;
  display: block;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 50%;
  animation: novaAppointmentOrbit 18s linear infinite;
}

.cinematicAppointmentAmbient span:nth-child(1) {
  width: 420px;
  height: 420px;
  right: -100px;
  top: -120px;
}

.cinematicAppointmentAmbient span:nth-child(2) {
  width: 620px;
  height: 620px;
  right: -190px;
  top: -220px;
  animation-duration: 24s;
}

.cinematicAppointmentAmbient span:nth-child(3) {
  width: 820px;
  height: 820px;
  right: -290px;
  top: -320px;
  animation-duration: 30s;
}

@keyframes novaAppointmentOrbit {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

.cinematicAppointmentInner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1320px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr) auto;
  gap: clamp(24px, 4vw, 48px);
  align-items: center;
}

.cinematicAppointmentNumber {
  align-self: start;
  padding-top: 5px;
  color: rgba(255, 255, 255, 0.45);
  font-family: "Playfair Display", Georgia, serif;
  font-size: 64px;
  line-height: 1;
}

.cinematicAppointment .lightKicker,
.cinematicAppointment .lightIndex {
  display: inline-block;
  color: rgba(255, 255, 255, 0.78) !important;
  font-size: 10px;
  letter-spacing: 0.16em;
}

.cinematicAppointment .lightIndex {
  margin-left: 18px;
}

.cinematicAppointmentCopy {
  min-width: 0;
}

.cinematicAppointmentCopy h2 {
  max-width: 800px;
  margin: 22px 0;
  color: #ffffff;
  font-family: "Playfair Display", Georgia, serif;
  font-size: clamp(38px, 5vw, 70px);
  line-height: 1.08;
  letter-spacing: -0.035em;
  font-weight: 500;
}

.cinematicAppointmentCopy h2 em {
  color: #a8e0d3;
  font-style: italic;
}

.cinematicAppointmentCopy p {
  max-width: 500px;
  margin: 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 14px;
  line-height: 1.85;
}

.cinematicAppointmentActions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 22px;
}

.cinematicAppointment .lightStoryButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 20px;
  border: 1px solid #ffffff;
  background: #ffffff;
  color: #0b2545;
  text-decoration: none;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  transition: transform 0.3s ease, background 0.3s ease,
    border-color 0.3s ease;
}

.cinematicAppointment .lightStoryButton:hover {
  transform: translateY(-3px);
  background: #a8e0d3;
  border-color: #a8e0d3;
}

.cinematicAppointment .textLightLink {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #ffffff;
  text-decoration: none;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  transition: gap 0.3s ease, color 0.3s ease;
}

.cinematicAppointment .textLightLink:hover {
  gap: 13px;
  color: #a8e0d3;
}

/* TABLET */
@media (max-width: 1000px) {
  .cinematicAppointment {
    padding: 75px 5%;
  }

  .cinematicAppointmentInner {
    grid-template-columns: 48px minmax(0, 1fr);
    gap: 24px;
  }

  .cinematicAppointmentActions {
    grid-column: 2;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 22px;
  }
}

/* MOBILE */
@media (max-width: 600px) {
  .cinematicAppointment {
    min-height: auto;
    padding: 64px 22px;
  }

  .cinematicAppointmentInner {
    grid-template-columns: minmax(0, 1fr);
    gap: 22px;
  }

  .cinematicAppointmentNumber {
    font-size: 48px;
  }

  .cinematicAppointment .lightIndex {
    display: block;
    margin: 12px 0 0;
  }

  .cinematicAppointmentCopy h2 {
    margin: 22px 0 18px;
    font-size: clamp(36px, 9vw, 48px);
