    font-size: 14px;
  }

  .cinematicAppointmentActions {
    grid-column: auto;
    align-items: stretch;
    gap: 20px;
  }

  .cinematicAppointment .lightStoryButton {
    width: 100%;
    min-height: 54px;
  }

  .cinematicAppointmentAmbient span:nth-child(3) {
    right: -500px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cinematicAppointmentAmbient span {
    animation: none;
  }

  .cinematicAppointment .lightStoryButton,
  .cinematicAppointment .textLightLink {
    transition: none;
  }
}

