/* =========================================================
   NOVADENT — STORY PROGRESS PREMIUM FINISH
========================================================= */

.novaStoryProgress {
  position: fixed;
  right: 24px;
  top: 50%;
  z-index: 900;
  transform: translateY(-50%);
}

/* Vertical track */
.novaStoryProgressTrack {
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 6px;
  width: 1px;
  background: rgba(11, 37, 69, 0.12);
}

/* Items */
.novaStoryProgressItems {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 17px;
}

/* Button */
.novaStoryProgressItems button {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 105px;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
  text-align: left;
}

/* Number dot */
.novaStoryProgressItems button span {
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 13px;
  height: 13px;
  border: 1px solid rgba(31, 138, 138, 0.32);
  border-radius: 50%;
  background: #fff;
  color: var(--muted);
  font-size: 6px;
  font-weight: 800;
  transition:
    width 0.35s ease,
    height 0.35s ease,
    background 0.35s ease,
    border-color 0.35s ease,
    color 0.35s ease,
    box-shadow 0.35s ease;
}

/* Label */
.novaStoryProgressItems button small {
  opacity: 0.45;
  color: var(--ink);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.12em;
  white-space: nowrap;
  transform: translateX(-3px);
  transition:
    opacity 0.35s ease,
    color 0.35s ease,
    transform 0.35s ease;
}

/* Hover */
.novaStoryProgressItems button:hover span {
  border-color: var(--primary);
  color: var(--primary);
}

.novaStoryProgressItems button:hover small {
  opacity: 0.85;
  color: var(--primary);
  transform: translateX(0);
}

/* Active */
.novaStoryProgressItems button.is-active span {
  width: 17px;
  height: 17px;
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  box-shadow:
    0 0 0 5px rgba(31, 138, 138, 0.08),
    0 0 18px rgba(31, 138, 138, 0.18);
}

.novaStoryProgressItems button.is-active small {
  opacity: 1;
  color: var(--primary);
  transform: translateX(2px);
}

/* Smaller screens */
@media (max-width: 900px) {
  .novaStoryProgress {
    right: 12px;
  }

  .novaStoryProgressItems button {
    min-width: auto;
  }

  .novaStoryProgressItems button small {
    display: none;
  }
}

/* Mobile */
@media (max-width: 600px) {
  .novaStoryProgress {
    display: none;
  }
}
