  transition:
    transform 1.2s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.8s ease;
  will-change: transform;
}

.premiumHome .cinematicTreatmentFeatured:hover
.cinematicTreatmentFeaturedImage img {
  transform: scale(1.075);
  filter: saturate(1.05) contrast(1.03);
}

.premiumHome .cinematicTreatmentImageShade {
  transition: opacity 0.6s ease;
}

.premiumHome .cinematicTreatmentFeatured:hover
.cinematicTreatmentImageShade {
  opacity: 0.72;
}

/* Number movement */

.premiumHome .cinematicTreatmentNumber {
  transition:
    transform 0.65s cubic-bezier(0.16, 1, 0.3, 1),
    letter-spacing 0.5s ease;
}

.premiumHome .cinematicTreatmentFeatured:hover
.cinematicTreatmentNumber {
  transform: translateY(-5px);
  letter-spacing: 0.12em;
}

/* Arrow */

.premiumHome .cinematicTreatmentArrow {
  transition:
    transform 0.55s cubic-bezier(0.16, 1, 0.3, 1),
    background 0.4s ease;
}

.premiumHome .cinematicTreatmentArrow svg {
  transition: transform 0.55s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicTreatmentFeatured:hover
.cinematicTreatmentArrow {
  transform: translate(-5px, -5px);
}

.premiumHome .cinematicTreatmentFeatured:hover
.cinematicTreatmentArrow svg {
  transform: translate(3px, -3px);
}

/* ---------------------------------------------------------
   TREATMENT ROWS
--------------------------------------------------------- */

.premiumHome .cinematicTreatmentRow {
  position: relative;
  transition:
    transform 0.6s cubic-bezier(0.16, 1, 0.3, 1),
    padding-left 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicTreatmentRow:hover {
  transform: translateX(7px);
}

.premiumHome .cinematicTreatmentRowImage {
  overflow: hidden;
}

.premiumHome .cinematicTreatmentRowImage img {
  transform: scale(1.02);
  transition:
    transform 0.9s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.6s ease;
}

.premiumHome .cinematicTreatmentRow:hover
.cinematicTreatmentRowImage img {
  transform: scale(1.1);
  filter: saturate(1.06);
}

.premiumHome .cinematicTreatmentRowImage > span {
  transition:
    transform 0.45s ease,
    letter-spacing 0.45s ease;
}

.premiumHome .cinematicTreatmentRow:hover
.cinematicTreatmentRowImage > span {
  transform: translateY(-4px);
  letter-spacing: 0.12em;
}

.premiumHome .cinematicTreatmentRowArrow {
  transition:
    transform 0.5s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.4s ease;
}

.premiumHome .cinematicTreatmentRowArrow svg {
  transition: transform 0.5s ease;
}

.premiumHome .cinematicTreatmentRow:hover
.cinematicTreatmentRowArrow {
  transform: translate(-4px, -4px);
}

.premiumHome .cinematicTreatmentRow:hover
.cinematicTreatmentRowArrow svg {
  transform: translate(3px, -3px);
}

/* ---------------------------------------------------------
   TREATMENT FOOTER PROGRESS
--------------------------------------------------------- */

.premiumHome .cinematicTreatmentProgress i {
  transform-origin: left center;
  transition:
    transform 0.55s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.4s ease;
}

.premiumHome .cinematicTreatmentProgress i:hover {
  transform: scaleX(1.35);
}

/* ---------------------------------------------------------
   DOCTORS
--------------------------------------------------------- */

.premiumHome .cinematicDoctor {
  transition:
    transform 0.75s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicDoctor:hover {
  transform: translateY(-8px);
}

.premiumHome .cinematicDoctorPortrait {
  overflow: hidden;
}

.premiumHome .cinematicDoctorPortrait img {
  transform: scale(1.015);
  transition:
    transform 1.1s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.7s ease;
}

.premiumHome .cinematicDoctor:hover
.cinematicDoctorPortrait img {
  transform: scale(1.065);
  filter: saturate(1.04) contrast(1.03);
}

.premiumHome .cinematicDoctorPortraitShade {
  transition: opacity 0.6s ease;
}

.premiumHome .cinematicDoctor:hover
.cinematicDoctorPortraitShade {
  opacity: 0.5;
}

.premiumHome .cinematicDoctorNumber,
.premiumHome .cinematicDoctorExperience {
  transition:
    transform 0.55s cubic-bezier(0.16, 1, 0.3, 1),
    letter-spacing 0.45s ease;
}

.premiumHome .cinematicDoctor:hover
.cinematicDoctorNumber {
  transform: translateY(-5px);
}

.premiumHome .cinematicDoctor:hover
.cinematicDoctorExperience {
  transform: translateX(-5px);
  letter-spacing: 0.08em;
}

.premiumHome .cinematicDoctorInfo h3 {
  transition:
    transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicDoctor:hover
.cinematicDoctorInfo h3 {
  transform: translateX(5px);
}

.premiumHome .cinematicDoctorInfo a {
  transition:
    gap 0.45s ease,
    opacity 0.4s ease;
}

.premiumHome .cinematicDoctorInfo a svg {
  transition:
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicDoctorInfo a:hover svg {
  transform: translate(4px, -4px);
}

/* ---------------------------------------------------------
   REVIEWS
--------------------------------------------------------- */

.premiumHome .cinematicReviewFeature {
  overflow: hidden;
}

.premiumHome .cinematicReviewImage {
  overflow: hidden;
}

.premiumHome .cinematicReviewImage img {
  transform: scale(1.02);
  transition:
    transform 1.2s cubic-bezier(0.16, 1, 0.3, 1),
    filter 0.7s ease;
}

.premiumHome .cinematicReviewFeature:hover
.cinematicReviewImage img {
  transform: scale(1.065);
  filter: saturate(1.04);
}

.premiumHome .cinematicReviewImage > span {
  transition:
    transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .cinematicReviewFeature:hover
.cinematicReviewImage > span {
  transform: translate(-4px, -4px);
}

/* Review slide */

.premiumHome .reviewSlideNext {
  animation: novaReviewNext 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .reviewSlidePrev {
  animation: novaReviewPrev 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes novaReviewNext {
  from {
    opacity: 0;
    transform: translateX(34px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes novaReviewPrev {
  from {
    opacity: 0;
    transform: translateX(-34px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Review controls */

.premiumHome .cinematicReviewControls button {
  transition:
    transform 0.35s ease,
    opacity 0.35s ease,
    background 0.35s ease;
}

.premiumHome .cinematicReviewControls button:hover {
  transform: translateY(-3px);
}

.premiumHome .cinematicReviewControls > div button {
  transform: scale(0.85);
}

.premiumHome .cinematicReviewControls > div button.active {
  transform: scale(1);
}

/* ---------------------------------------------------------
   APPOINTMENT CTA
--------------------------------------------------------- */

.premiumHome .cinematicAppointment {
  position: relative;
  overflow: hidden;
}

.premiumHome .cinematicAppointment::before {
  content: "";
  position: absolute;
  inset: -30%;
  pointer-events: none;
  background:
    radial-gradient(
      circle at 25% 40%,
      rgba(255, 255, 255, 0.08),
      transparent 28%
    ),
    radial-gradient(
      circle at 75% 65%,
      rgba(255, 255, 255, 0.06),
      transparent 25%
    );
  animation: novaAppointmentGlow 10s ease-in-out infinite alternate;
}

@keyframes novaAppointmentGlow {
  0% {
    transform: translate3d(-2%, 0, 0) scale(1);
  }

  100% {
    transform: translate3d(2%, -2%, 0) scale(1.05);
  }
}

.premiumHome .cinematicAppointmentCopy,
.premiumHome .cinematicAppointmentActions,
.premiumHome .cinematicAppointmentNumber {
  position: relative;
  z-index: 2;
}

.premiumHome .lightStoryButton {
  transition:
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    gap 0.4s ease;
}

.premiumHome .lightStoryButton:hover {
  transform: translateY(-4px);
}

.premiumHome .lightStoryButton svg:last-child {
  transition:
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .lightStoryButton:hover svg:last-child {
  transform: translateX(5px);
}

.premiumHome .textLightLink svg {
  transition:
    transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

.premiumHome .textLightLink:hover svg {
  transform: translate(4px, -4px);
}

/* ---------------------------------------------------------
   STORY PROGRESS
--------------------------------------------------------- */

.premiumHome .novaStoryProgressItems button {
  transition:
    transform 0.35s ease,
    opacity 0.35s ease;
}

.premiumHome .novaStoryProgressItems button:hover {
  transform: translateX(-4px);
}

.premiumHome .novaStoryProgressItems button span {
  transition:
    transform 0.35s ease,
    letter-spacing 0.35s ease;
}

.premiumHome .novaStoryProgressItems button.is-active span {
  transform: scale(1.08);
  letter-spacing: 0.08em;
}

/* ---------------------------------------------------------
   IMAGE MICRO-MOTION
--------------------------------------------------------- */

.premiumHome .cinematicTreatmentFeaturedImage,
.premiumHome .cinematicTreatmentRowImage,
.premiumHome .cinematicDoctorPortrait,
.premiumHome .cinematicReviewImage {
  isolation: isolate;
}

/* ---------------------------------------------------------
   ACCESSIBILITY
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

  .premiumHome *,
  .premiumHome *::before,
  .premiumHome *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .premiumHome [data-reveal] {
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 768px) {

  .premiumHome [data-reveal] {
    transform: translateY(22px);
  }

  .premiumHome .cinematicTreatmentFeatured:hover,
  .premiumHome .cinematicDoctor:hover {
    transform: translateY(-3px);
  }

  .premiumHome .cinematicTreatmentRow:hover {
    transform: translateX(3px);
  }

  .premiumHome .cinematicTreatmentFeatured:hover
  .cinematicTreatmentFeaturedImage img {
    transform: scale(1.04);
  }

  .premiumHome .cinematicTreatmentRow:hover
  .cinematicTreatmentRowImage img {
    transform: scale(1.045);
  }

  .premiumHome .cinematicDoctor:hover
  .cinematicDoctorPortrait img {
    transform: scale(1.04);
  }

  .premiumHome .cinematicReviewFeature:hover
  .cinematicReviewImage img {
    transform: scale(1.035);
  }

  .premiumHome .cinematicAppointment::before {
    animation-duration: 14s;
  }
}
