  filter: saturate(1);
}

.novaDoctorImageOverlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgba(7, 31, 54, 0.05) 0%,
      rgba(7, 31, 54, 0) 45%,
      rgba(7, 31, 54, 0.2) 100%
    );
  pointer-events: none;
}

.novaDoctorImageNumber {
  position: absolute;
