  letter-spacing: -0.035em;
}

.novaDoctorSpeciality {
  margin: 25px 0 0;
  color: #758591;
  font-size: 17px;
}

.novaDoctorDescription {
  max-width: 500px;
  margin: 34px 0 42px;
  color: #7a8994;
  font-size: 15px;
  line-height: 1.8;
}

.novaDoctorMeta {
  display: flex;
  gap: 55px;
  padding: 28px 0;
  border-top: 1px solid #d9e2e4;
  border-bottom: 1px solid #d9e2e4;
}

.novaDoctorMeta div {
  display: flex;
  flex-direction: column;
