  transform: translateY(35px);
  transition:
    opacity 0.9s ease,
    transform 0.9s cubic-bezier(.2,.7,.2,1);
}

.novaDoctorsSection.is-visible[data-reveal] .novaDoctorsHeading {
  opacity: 1;
  transform: translateY(0);
}

.novaDoctorsSection.is-visible[data-reveal] .novaDoctorsIntro {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 0.15s;
}

.novaDoctorsSection.is-visible[data-reveal] .novaDoctorFeature {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 0.28s;
}


