/* Final frontend QA pass: safe responsive defaults, focus visibility and media stability. */
:where(img, video, iframe, canvas, svg) { max-width: 100%; }
img { height: auto; }
:where(input, select, textarea, button) { font: inherit; }
:where(button, a, input, select, textarea, summary, [tabindex]:not([tabindex="-1"])):focus-visible {
  outline: 3px solid #168a8a;
  outline-offset: 3px;
}
:where(button, input, select, textarea) { min-width: 0; }
:where(input, select, textarea) { max-width: 100%; }
html { scroll-padding-top: 90px; }
body { overflow-wrap: anywhere; }
@media (max-width: 760px) {
  html { scroll-padding-top: 72px; }
  :where(.container, .section-container, .page-container) { max-width: 100%; }
  :where(button, .btn, a.button, input[type="submit"]) { touch-action: manipulation; }
  :where(input, select, textarea) { font-size: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

/* NOVADENT motion upgrade — additive, reduced-motion aware */
@keyframes novaHeroContentIn { from { opacity: 0; transform: translate3d(0,22px,0); } to { opacity: 1; transform: translate3d(0,0,0); } }
@keyframes novaHeroMediaIn { from { opacity: .72; transform: scale(1.035) translate3d(18px,0,0); } to { opacity: 1; transform: scale(1) translate3d(0,0,0); } }
.novaHeroContent { animation: novaHeroContentIn .8s cubic-bezier(.2,.7,.2,1) both; }
.novaHeroMedia, .novaHeroVideo { animation: novaHeroMediaIn 1.15s ease-out both; }
.novaHeroActions a, .novaDesktopCTA, .novaMobileAppointment, .novaMobileBar a, button { transition: transform .22s ease, box-shadow .22s ease, background-color .22s ease, color .22s ease, border-color .22s ease; }
.novaHeroActions a:hover, .novaDesktopCTA:hover, .novaMobileAppointment:hover { transform: translateY(-3px); box-shadow: 0 12px 28px rgba(12,48,56,.18); }
.novaNavigation a { transition: color .2s ease, background-color .2s ease, transform .2s ease; }
.novaNavigation a:hover { transform: translateY(-1px); }
.novaNavbar { transition: background-color .25s ease, box-shadow .25s ease, backdrop-filter .25s ease; }
body:has(.novaNavbar) .novaNavbar { position: sticky; top: 0; z-index: 1000; }
/* Service and feature cards: subtle lift without changing layout. */
:where(.service-card, .serviceCard, .novaServiceCard, .treatment-card, .treatmentCard, .doctor-card, .doctorCard, .testimonial-card, .review-card, .nova-gallery-item-pro) { transition: transform .28s cubic-bezier(.2,.7,.2,1), box-shadow .28s ease, border-color .28s ease; }
:where(.service-card, .serviceCard, .novaServiceCard, .treatment-card, .treatmentCard, .doctor-card, .doctorCard, .testimonial-card, .review-card, .nova-gallery-item-pro):hover { transform: translateY(-5px); box-shadow: 0 16px 38px rgba(15,54,67,.12); }
:where(.service-card, .serviceCard, .novaServiceCard, .treatment-card, .treatmentCard, .doctor-card, .doctorCard, .testimonial-card, .review-card, .nova-gallery-item-pro) img { transition: transform .45s cubic-bezier(.2,.7,.2,1), filter .35s ease; }
:where(.service-card, .serviceCard, .novaServiceCard, .treatment-card, .treatmentCard, .doctor-card, .doctorCard, .testimonial-card, .review-card, .nova-gallery-item-pro):hover img { transform: scale(1.035); }
/* General reveal hooks support existing data-reveal markup and the Reveal component. */
.reveal { opacity: 0; transform: translate3d(0,18px,0); transition: opacity .65s ease, transform .65s cubic-bezier(.2,.7,.2,1); transition-delay: var(--reveal-delay, 0ms); }
.reveal-visible { opacity: 1; transform: translate3d(0,0,0); }
:where([data-reveal], [data-about-reveal]) { transition: opacity .65s ease, transform .65s cubic-bezier(.2,.7,.2,1); }
:where(img, .galleryImage, .nova-gallery-item-pro) { overflow: clip; }
.nova-gallery img { transition: transform .5s cubic-bezier(.2,.7,.2,1), filter .35s ease; }
.nova-gallery a:hover img, .nova-gallery button:hover img { transform: scale(1.045); }
@media (max-width: 760px) { .novaHeroContent, .novaHeroMedia, .novaHeroVideo { animation-duration: .65s; } :where(.service-card, .serviceCard, .novaServiceCard, .treatment-card, .treatmentCard, .doctor-card, .doctorCard, .testimonial-card, .review-card):hover { transform: none; } }
@media (prefers-reduced-motion: reduce) { .novaHeroContent, .novaHeroMedia, .novaHeroVideo { animation: none !important; } .reveal { opacity: 1; transform: none; transition: none; } }
